    DIMS = [('COUNTRY', ['KOR', 'USA', 'TWN']), ('BOP_ACCOUNTING_ENTRY', ['A_NFA_T', 'L_NIL_T', 'NETCD_T', 'CD_T']),
            ('INDICATOR', ['CAB', 'D_F', 'O_F', 'P_F', 'P_F5']), ('UNIT', ['USD']), ('FREQUENCY', ['Q'])]
