        self.assertIs(saved['obce'], prev); self.assertEqual(zd.META['ok']['obce'], 'cached')
        self.assertIs(zd.META['ok']['obce_tw'], False); self.assertEqual(zd.META['ok']['obce_hk'], 'cached')
