        self.assertEqual([zd._tdw_rz(x) for x in (1.997, 0.996, 1.994, 2.0, -1.996, 1.0, -0.999, 2.004, 0.4449, None, 'x')],
                         [1.99, 0.99, 1.99, 2.0, -1.99, 1.0, -0.99, 2.0, 0.44, None, None])
