            for broken in (None, {'rows': 'x', 'v': 2}):
                zd._W_LOG[0] = broken; zd._W_LOG[1] = None; zd.META['notes'].clear(); zd.META['errors'].clear()
                out, bd = zd.build_daily_w2({'swiat-dzien': wd})
