    @classmethod
    def zip_bytes(cls, csv_text, name='BTCUSDT-metrics-2026-09-24.csv'):
        import io, zipfile
        b = io.BytesIO()
        with zipfile.ZipFile(b, 'w') as z:
            z.writestr(name, csv_text)
