        self.assertEqual(zd._ix_merge([['2026-09-22', 1.0], ['2026-09-24', 2.0], ['x'], ['2026-09-23', None]], [['2026-09-24', 2.5], ['2026-09-25', 3.0]], 3),
                         [['2026-09-22', 1.0], ['2026-09-24', 2.5], ['2026-09-25', 3.0]])
