    F1_OWNER = 'edgar/data/1535264/0001535264-26-000053.txt'   # to samo zgłoszenie pod CIK osoby zgłaszającej
    # odpowiedź magazynu na brak pliku (dzień bez indeksu) i strona blokady (nagranie 26.09.2026, skrócone)
