        self.assertNotIn("R['bledy']", src[a:b]); self.assertEqual(src[a:b].count(' get('), 1, 'jedno miejsce zapytania (pętla po 2 funduszach), bez ponawiania')
        self.assertEqual([t for t, _, _ in self.k.EM_FUNDS], ['IBIT', 'ETHA'])
