    def test_przebieg_glowny(self):
        saved = {}
        stubs = [mock.patch.object(zd, n, side_effect=RuntimeError('offline')) for n in dir(zd) if n.startswith('build_') and n != 'build_nastroj' and callable(getattr(zd, n))]
        env = {k: '' for k in ('SOSOVALUE_KEY', 'COINGECKO_KEY', 'FINNHUB_KEY', 'TWELVEDATA_KEY', 'COINMARKETCAP_KEY', 'EIA_KEY', 'BLS_KEY', 'BEA_KEY', 'SITE_URL', 'CACHE_DIR')}
        env['FRED_KEY'] = 'TAJNY-FRED-139'
        ok = {k: True for k in zd.NS_KEYS}
        young = {'at': _iso(10), 'ok': ok, 'd': []}
        mid_bad = {'at': _iso(90), 'ok': dict(ok, sb=False), 'd': []}
        mid_ok = {'at': _iso(90), 'ok': ok, 'd': []}
        old = {'at': _iso(7 * 60), 'ok': ok, 'd': []}
        built = {'at': zd.NOW, 'ok': ok, 'd': []}
        [p.start() for p in stubs]
        try:
            def run(prev, build, fu=None):
                calls = []
                def prv(name):
                    return prev if name == 'nastroj' else fu if name == 'fundusze' else None
                with mock.patch.dict(os.environ, env, clear=False), mock.patch.object(zd, 'save', lambda n, o: saved.__setitem__(n, o) or zd.SAVED.__setitem__(n, o)), \
                     mock.patch.object(zd, 'previous', prv), \
                     mock.patch.object(zd, 'build_nastroj', side_effect=(lambda k, S, p: calls.append((k, dict(S), p)) or build) if not isinstance(build, Exception) else build):
                    zd.main()
                return calls
            self.assertEqual(run(young, AssertionError('nie powinien budować')), []); self.assertIs(saved['nastroj'], young); self.assertEqual(zd.META['ok']['nastroj'], 'cached')
            self.assertEqual(run(mid_ok, AssertionError('nie powinien budować')), []); self.assertEqual(zd.META['ok']['nastroj'], 'cached', '90 min, komplet — z pamięci')
            fu = {'at': _iso(30), 'f': {}}
            c = run(mid_bad, built, fu)
            self.assertEqual(len(c), 1, 'brak składnika sprzed 90 min — ponowienie'); self.assertEqual(c[0][0], 'TAJNY-FRED-139'); self.assertIs(c[0][2], mid_bad)
            self.assertIs(c[0][1].get('fundusze'), fu, 'fundusze z tego przebiegu (zapisane wcześniej w main)'); self.assertIs(zd.META['ok']['nastroj'], True)
            self.assertEqual(len(run(old, built)), 1); self.assertIs(saved['nastroj'], built)
            run(old, dict(built, ok=dict(ok, vix=False))); self.assertIs(zd.META['ok']['nastroj'], False, 'składnik bez liczby = źródło bez pełnej odpowiedzi')
            saved.clear()
            run(old, RuntimeError('offline')); self.assertIs(saved['nastroj'], old, 'awaria — poprzedni plik'); self.assertIs(zd.META['ok']['nastroj'], False)
            self.assertIn('Nastroje: offline', zd.META['errors'])
            saved.clear()
            run(None, RuntimeError('offline')); self.assertNotIn('nastroj', saved, 'bez poprzedniego pliku i bez danych — nic')
        finally:
            [p.stop() for p in stubs]

    def test_kod_kontrola_strona_i_zaslepki(self):
        root = os.path.dirname(os.path.abspath(__file__))
        src = open(zd.__file__, encoding='utf-8').read()
        a = src.index('# ===================== v139: NASTROJE RYNKÓW'); b = src.index('\ndef parse_deriv(', a)
        blok = src[a:b]
        self.assertIn('def build_nastroj(', blok); self.assertNotIn('os.environ', blok, 'klucz tylko z przebiegu głównego')
        self.assertLess(src.index('def build_fred('), a, 'blok zaraz po FRED')
        self.assertEqual(sorted(zd.FRED_SERIES), ['DTWEXBGS', 'RRPONTSYD', 'WALCL', 'WDTGAL', 'WFASECL1', 'WMTSECL1', 'WSEFINOL', 'WSEFINTL1'], 'fred.json — same serie Fed (v293, audyt G2: TGA jako stan na środę WDTGAL)')
        self.assertEqual(zd.NS_SERIES, (('vix', 'VIXCLS'), ('hy', 'BAMLH0A0HYM2'), ('spx', 'SP500')))
        head = src[:src.index("FRED = 'https://api.stlouisfed.org")]
        self.assertIn('VIXCLS i BAMLH0A0HYM2 — wskazane wprost w zadaniu właściciela', head)
        self.assertIn('SP500 — do potwierdzenia przez właściciela', head, 'zgoda na SP500 nie jest udawana')
        self.assertNotIn('zgoda właściciela 27.09 na', src, 'bez przypisywania właścicielowi zgody, której zadanie nie zawiera')
        self.assertIn('SP500 — w zadaniu nie ma tej serii', blok); self.assertIn('DO POTWIERDZENIA', blok)
        self.assertEqual((zd.NS_WIN, zd.NS_WIN_MIN, zd.NS_MIN, zd.NS_STALE_D, zd.NS_HIST_D, zd.NS_EVERY, zd.NS_RETRY, zd.NS_KEEP_H, zd.NS_RET, zd.NS_MA),
                         (252, 240, 3, 5, 45, 360, 60, 36, 20, {'vix': 50, 'spx': 125}))
        m = src.index('def main():'); m0 = src.index("prev_ns = previous('nastroj')")
        self.assertTrue(m < src.index("if prev_fu: save('fundusze', prev_fu)") < m0 < src.index("_CR_LOG[0] = previous('krypto-dziennik')"), 'po funduszach, przed trendami')
        self.assertIn("META['errors'].append(mask(f'{NS_LABEL}: {e}')); META['ok']['nastroj'] = False", src); self.assertEqual(zd.NS_LABEL, 'Nastroje')
        me = open(__file__, encoding='utf-8').read()
        tup = zd.re.compile(r"for (?:f|fn) in\s*\(\s*('build_\w+'(?:\s*,\s*'build_\w+')*)\s*\)", zd.re.S)
        lists = [x.group(1) for x in tup.finditer(me) if "'build_wieloryby'" in x.group(1)]
        self.assertGreaterEqual(len(lists), 18); self.assertEqual([s[:60] for s in lists if "'build_nastroj'" not in s], [], 'każda krotka zaślepek zna build_nastroj')
        i = me.index('def test_meta_is_always_written'); j = me.index('\n    def ', i + 1)
        self.assertIn("'Indeksy', 'Nastroje', 'Rynki'", me[i:j], 'etykieta błędów meta')
        k = open(os.path.join(root, 'narzedzia', 'kontrola.py'), encoding='utf-8').read()
        PL = eval(zd.re.search(r'^PLIKI = (\[.*\])$', k, zd.re.M).group(1)); LM = eval(zd.re.search(r'^LIMIT_MIN = (\{[^}]*\})', k, zd.re.M).group(1))
        self.assertIn('nastroj', PL); self.assertEqual(LM['nastroj'], 12 * 60, 'plik co 6 h: dwa przebiegi bez nowego pliku = uwaga')
        h = open(os.path.join(root, 'index.html'), encoding='utf-8').read()
        self.assertEqual(h.count('<section class="panel pcard fg" id="g-fg" hidden></section>'), 1); self.assertEqual(h.count('<section class="panel fg" id="c-fg" hidden></section>'), 1)
        self.assertIn("srvJSON('nastroj')", h); self.assertIn('const EXTRA136=', h)
        wf = open(os.path.join(root, '.github', 'workflows', 'strona.yml'), encoding='utf-8').read()
        self.assertIn('FRED_KEY: ${{ secrets.FRED_KEY }}', wf, 'ten sam sekret — bez nowego')


