        self.ev.clear()
        self._build(f3, now=T1 + datetime.timedelta(hours=6), fail={'sopr': 429, 'cm': 500})
        self.assertEqual([u for u in self._gets() if 'bitcoin-data' in u], [], 'po 3 próbach tej doby — koniec')

