        US = {f'{zd.RWE_SPIKO}/share-classes': [{'symbol': 'SAFO', 'currency': 'USD'}]}
        g2, _p = _rwe169_net(over=US)
        self.assertIsNone(zd.rwe_spiko(lambda: 5.0, None, get=g2)['fx'], 'same klasy USD — bez kursu')

