# ===================== v187: IKONA STRONY =====================
class IkonaStronyV187(unittest.TestCase):
    """v187: ikona w karcie przeglądarki — img/favicon.svg (logo z nagłówka, kolory ciemnego motywu), PNG 32 i 180 px, wpis w licencjach."""

    def test_pliki(self):
        d = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'img')
        svg = open(os.path.join(d, 'favicon.svg'), encoding='utf-8').read()
        self.assertIn('M16 3 27 9.5v13L16 29 5 22.5v-13z', svg); self.assertIn('M5 9.5 16 16l11-6.5M16 16v13', svg)
        self.assertIn('stroke="#0A84FF"', svg); self.assertIn('stroke="#64D2FF"', svg); self.assertLess(len(svg), 1000)
        import struct
        for n, w in (('favicon-32.png', 32), ('apple-touch-icon.png', 180)):
            b = open(os.path.join(d, n), 'rb').read()
            self.assertEqual(b[:8], bytes.fromhex('89504e470d0a1a0a'), n)
            self.assertEqual(struct.unpack('>II', b[16:24]), (w, w), n)
            self.assertLess(len(b), 20_000, n)
        self.assertIn('img/favicon.svg, img/favicon-32.png, img/apple-touch-icon.png — ikona strony', open(os.path.join(d, 'LICENCJE.txt'), encoding='utf-8').read())


# ===================== v190: POPRAWKI PO PRZEGLĄDZIE v184–v189 =====================
class PoPrzegladzieV190(unittest.TestCase):
    """v190: cmc.json — wartości „sprzed doby” z tej samej odpowiedzi (zmiany 24 h z jednej migawki); kontrola — najdłuższy udany przebieg w 24 h."""

    def test_cmc_wczoraj(self):
        base = {'status': {'error_code': 0}, 'data': {'btc_dominance': 59.0, 'eth_dominance': 11.3, 'btc_dominance_yesterday': 58.6, 'eth_dominance_yesterday': 11.4,
                'last_updated': '2026-10-05T18:44:59.999Z', 'quote': {'USD': {'total_market_cap': 2.915e12, 'total_market_cap_yesterday': 2.91e12,
                                                                              'total_volume_24h': 8.59e10}}}}
        with mock.patch.object(zd, 'get_json', lambda url, headers=None: base):
            o = zd.build_cmc('k')
        self.assertEqual((o['btc_dom_y'], o['eth_dom_y'], o['total_mcap_y']), (58.6, 11.4, 2.91e12))
        for k in ('btc_dominance_yesterday', 'eth_dominance_yesterday'):
            del base['data'][k]
        del base['data']['quote']['USD']['total_market_cap_yesterday']
        with mock.patch.object(zd, 'get_json', lambda url, headers=None: base):
            o = zd.build_cmc('k')
        self.assertEqual((o['btc_dom_y'], o['eth_dom_y'], o['total_mcap_y']), (None, None, None), 'brak pól — brak, nie zero')

    def test_kontrola_najdluzszy_przebieg(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('kontrola_v190', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        k = importlib.util.module_from_spec(spec); spec.loader.exec_module(k)
        NOW = datetime.datetime(2026, 10, 5, 21, 0, tzinfo=datetime.timezone.utc)
        f = lambda m: (NOW - datetime.timedelta(minutes=m)).strftime('%Y-%m-%dT%H:%M:%SZ')  # noqa: E731
        runs = [{'id': 1, 'name': 'Strona i dane', 'status': 'completed', 'conclusion': 'success', 'run_started_at': f(60), 'updated_at': f(45.5)},
                {'id': 2, 'name': 'Strona i dane', 'status': 'completed', 'conclusion': 'success', 'run_started_at': f(30), 'updated_at': f(27)},
                {'id': 3, 'name': 'Strona i dane', 'status': 'completed', 'conclusion': 'cancelled', 'run_started_at': f(100), 'updated_at': f(50)},
                {'id': 4, 'name': 'Strona i dane', 'status': 'completed', 'conclusion': 'success', 'run_started_at': f(25 * 60), 'updated_at': f(25 * 60 - 40)},
                {'id': 5, 'name': 'Strona i dane', 'status': 'completed', 'conclusion': 'success', 'run_started_at': f(10), 'updated_at': 'zły'}]
        with mock.patch.object(k, 'NOW', NOW):
            A, b, u = k.przebiegi_ocena(runs, NOW)
        self.assertEqual(A['najdluzszy_min'], 14.5, 'tylko udane z 24 h; anulowany (czekanie w awarii) i starszy niż doba — pominięte; zły czas — pominięty')
        R = {'at': NOW.isoformat(), 'wynik': 'OK', 'uwagi': [], 'bledy': [], 'strona': {'ok': True, 'http': 200, 'ms': 1},
             'meta': {'at': f(5), 'wiek_min': 5, 'zrodla': 76, 'bez_odpowiedzi': [], 'errors': [], 'notes': []}, 'pliki': {}, 'swiezosc': [], 'zgodnosc': {},
             'actions': A}
        md = k.raport_md(R)
        self.assertIn('- Najdłuższy udany przebieg w 24 h: 14,5 min (od startu do końca, z czekaniem na maszyny; limit zadania budowy 25 min).', md)
        A['najdluzszy_min'] = 21.0
        self.assertIn('21,0 min (od startu do końca, z czekaniem na maszyny; limit zadania budowy 25 min) ⚠️ blisko limitu.', k.raport_md(R))
        A['najdluzszy_min'] = None
        self.assertNotIn('Najdłuższy udany przebieg', k.raport_md(R))
        self.assertTrue(md.startswith('# Kontrola strony — ') and '**Wynik: OK**' in md)


# ===================== v192: FUNDUSZE ETF — SZCZEGÓŁY PRZY NOWYM DNIU DANYCH ALBO CO 6 H =====================
class EtfFunduszeRzadziejV192(unittest.TestCase):
    """v192: lista i szczegóły funduszy (1 + N zapytań po ok. 7 s) tylko przy nowym dniu danych albo co 6 h; niepełna lista — znowu w następnym
    przebiegu; Hongkong co 6 h. 05.10: część „etf” 479 s z 686 s przebiegu. Bez sieci."""
    NOW = datetime.datetime(2026, 10, 5, 21, 0, tzinfo=datetime.timezone.utc)

    def setUp(self):
        zd.META['errors'].clear(); zd.META['ok'].clear(); zd.META['notes'].clear()
        self.enterContext(mock.patch.object(zd, '_now_utc', lambda: self.NOW))
        self.enterContext(mock.patch.object(zd, 'ETF_SYMS', ['btc']))
        self.enterContext(mock.patch.object(zd, 'get_json', lambda url, headers=None: {'bitcoin': {'usd_market_cap': 1.7e12}}))

    def _run(self, prev, last='2026-10-02', zly=None):
        calls = []
        funds = {'btc': [{'ticker': 'IBIT', 'name': 'a'}, {'ticker': 'FBTC', 'name': 'b'}]}
        snaps = {'IBIT': {'net_assets': 6.7e10, 'cum_inflow': 6.5e10, 'net_inflow': 7.1e7, 'sponsor_fee': 0.0025},   # v194: 71 + 29 = 100 = przepływ dnia
                 'FBTC': {'net_assets': 1.5e10, 'cum_inflow': 1.1e10, 'net_inflow': 2.9e7, 'sponsor_fee': 0}}
        base = _soso_factory({'btc': _rows(['2026-10-01', last]), 'eth': _rows(['2026-10-01', last])}, funds, snaps)   # v194: Hongkong BTC i ETH (czas części tylko dla kompletu)

        def soso(path, key, _retry=True):
            calls.append(path)
            if zly and zly in path:
                raise RuntimeError('HTTP 500')
            return base(path, key)
        with mock.patch.object(zd, 'soso', soso):
            out = zd.build_etf('k', 'c', prev)
        return out, calls

    def _prev(self, h_funds=1.0, asof='2026-10-02', h_hk=1.0):
        f = lambda h: (self.NOW - datetime.timedelta(hours=h)).isoformat()  # noqa: E731
        return {'assets': {'btc': {'asof': asof, 'day': [], 'd1': 100.0, 'cum': 5000.0, 'funds_at': f(h_funds),   # v194: te same liczby dnia
                                   'funds': [{'t': 'IBIT', 'n': 'a', 'cty': 'us', 'aum': 67000.0, 'cum': 65000.0, 'd1': 150.0, 'fee': 0.25, 'prem': None}]}},
                'hk': {'btc': {'sym': 'BTC', 'asof': asof, 'v': zd.ETF_HK_V}}, 'hk_at': f(h_hk)}   # v293c: wpis HK w bieżącym zapisie (starszy nie jest przenoszony)

    def test_pierwszy_przebieg_pelny(self):
        out, calls = self._run(None)
        self.assertEqual(sum('/market-snapshot' in c for c in calls), 2); self.assertTrue(any(c.startswith('/etfs?') for c in calls))
        self.assertEqual(out['assets']['btc']['funds_at'], zd.NOW); self.assertEqual(out['hk_at'], zd.NOW)
        self.assertEqual([f['t'] for f in out['assets']['btc']['funds']], ['IBIT', 'FBTC'])

    def test_ten_sam_dzien_lista_mloda_bez_zapytan(self):
        prev = self._prev()
        out, calls = self._run(prev)
        self.assertEqual(calls, ['/etfs/summary-history?symbol=BTC&country_code=US&limit=60'], 'tylko zestawienie USA — bez listy, szczegółów i Hongkongu')
        a = out['assets']['btc']
        self.assertEqual((a['funds'], a['funds_at']), (prev['assets']['btc']['funds'], prev['assets']['btc']['funds_at']))
        self.assertEqual((out['hk'], out['hk_at']), (prev['hk'], prev['hk_at']))
        self.assertIsNot(a['funds'], prev['assets']['btc']['funds'], 'kopia — poprzedni plik bez zmian w miejscu')
        self.assertEqual(a['asof'], '2026-10-02'); self.assertAlmostEqual(a['d1'], 100.0)

    def test_nowy_dzien_albo_stara_lista_albo_brak_czasu_pelne(self):
        for prev, why in ((self._prev(asof='2026-10-01'), 'nowy dzień danych'), (self._prev(h_funds=7), 'lista starsza niż 6 h'),
                          (dict(self._prev(), assets={'btc': dict(self._prev()['assets']['btc'], funds_at=None)}), 'bez czasu listy (stary plik)')):
            out, calls = self._run(prev)
            self.assertEqual(sum('/market-snapshot' in c for c in calls), 2, why)
            self.assertEqual(out['assets']['btc']['funds_at'], zd.NOW, why)
        out, calls = self._run(self._prev(h_hk=7))
        self.assertTrue(any('country_code=HK' in c for c in calls), 'Hongkong starszy niż 6 h — pobrany')

    def test_niepelna_lista_bez_czasu(self):
        out, calls = self._run(None, zly='/FBTC/')
        a = out['assets']['btc']
        self.assertEqual([f['t'] for f in a['funds']], ['IBIT']); self.assertNotIn('funds_at', a, 'niepełna lista — następny przebieg pobiera znowu')
        self.assertTrue(any('SoSoValue FBTC' in e for e in zd.META['errors']))
        self.assertEqual(zd.ETF_FUNDS_EVERY, 6 * 60)


# ===================== v193: WIELORYBY — PRZELEW MIĘDZY DWIEMA GIEŁDAMI Z LISTY (POLE x) =====================
class WhMiedzyGieldamiV193(unittest.TestCase):
    """v193: przelew między dwiema giełdami z listy = dwa wiersze (out/in) z polem x — giełdą po drugiej stronie (strona: jeden wiersz „⇄ A → B”);
    przelew z portfelem spoza listy — bez x; wewnętrzny (ta sama giełda) — pominięty jak dotąd; sumy dobowe bez zmian. Bez sieci."""
    T = WielorybyV105.T
    B1, X = WielorybyV105.B1, WielorybyV105.X
    BY1, BF1 = WielorybyEthV112.BY1, WielorybyEthV112.BF1
    _w = staticmethod(WielorybyV105._w)
    _h = staticmethod(WielorybyV105._h)
    _log = WielorybyV105._log
    _tx = WielorybyEthV112._tx

    def setUp(self):
        zd.META['errors'].clear(); zd.META['notes'].clear()
        self.W = {w['addr']: w['exch'] for w in zd.wh_portfele()}

    def test_usdt_usdc(self):
        L = [self._log(zd.WH_USDT, self.B1, self.BY1, 19_899_999.5, tx='0x' + 'c7' * 32, li=7),   # Binance → Bybit (jak 05.10)
             self._log(zd.WH_USDT, self.X, self.B1, 2_000_000, tx='0x' + '01' * 32),               # z zewnątrz na Binance
             self._log(zd.WH_USDC, self.BY1, self.X, 3_000_000, tx='0x' + '02' * 32)]              # z Bybit na zewnątrz
        rows = sorted(zd.wh_dekoduj(L, self.W).values(), key=lambda r: (r['tx'], r['dir']))
        self.assertEqual([(r['tx'][:4], r['dir'], r['exch'], r.get('x')) for r in rows],
                         [('0x01', 'in', 'Binance', None), ('0x02', 'out', 'Bybit', None), ('0xc7', 'in', 'Bybit', 'Binance'), ('0xc7', 'out', 'Binance', 'Bybit')])
        self.assertTrue(all('x' not in r for r in rows if r['tx'][:4] != '0xc7'), 'portfel spoza listy — pola x nie ma (nie opisujemy)')
        dob, kl = zd.wh_dobowe({}, {}, [dict(r, t='2026-10-05T12:21:00+00:00') for r in rows])
        d = dob['2026-10-05']
        self.assertEqual((d['Binance']['USDT']['out'], d['Bybit']['USDT']['in'], d['Binance']['USDT']['in']), (19899999.5, 19899999.5, 2000000.0), 'sumy dobowe per giełda jak dotąd')

    def test_eth(self):
        T = [self._tx(self.BY1, self.BF1, 1000.0, h='0x' + '04' * 32), self._tx(self.X, self.B1, 500.0, h='0x' + '05' * 32)]
        rows = sorted(zd.wh_eth_dekoduj(T, self.W, 2500.0).values(), key=lambda r: (r['tx'], r['dir']))
        self.assertEqual([(r['tx'][:4], r['dir'], r['exch'], r.get('x')) for r in rows],
                         [('0x04', 'in', 'Bitfinex', 'Bybit'), ('0x04', 'out', 'Bybit', 'Bitfinex'), ('0x05', 'in', 'Binance', None)])

    def test_polacz_zachowuje_x(self):
        r = {'t': '2026-10-05T12:21:00+00:00', 'token': 'USDT', 'amt': 1e7, 'usd': 1e7, 'dir': 'out', 'exch': 'Binance', 'x': 'Bybit', 'tx': '0x' + 'aa' * 32, 'blk': 500, 'li': 3}
        self.assertEqual(zd.wh_polacz([r], [], 100)[0].get('x'), 'Bybit', 'wiersz z poprzedniego pliku zachowuje x')


# ===================== v194: PO PRZEGLĄDZIE v190–v192 — ETF (te same liczby dnia, suma funduszy, błąd monety, Hongkong), KONTROLA =====================
class PoPrzegladzieV194(unittest.TestCase):
    """v194: lista funduszy ponownie tylko przy tym samym zestawieniu dnia i z sumą zgodną z przepływem dnia; błąd monety = poprzedni wpis
    (historia dni zostaje); Hongkong z czasem tylko dla kompletu; kontrola — czas samego zadania budowy. Bez sieci."""
    NOW = datetime.datetime(2026, 10, 5, 21, 0, tzinfo=datetime.timezone.utc)

    def setUp(self):
        zd.META['errors'].clear(); zd.META['ok'].clear(); zd.META['notes'].clear()
        self.enterContext(mock.patch.object(zd, '_now_utc', lambda: self.NOW))
        self.enterContext(mock.patch.object(zd, 'ETF_SYMS', ['btc', 'eth']))
        self.enterContext(mock.patch.object(zd, 'get_json', lambda url, headers=None: {'bitcoin': {'usd_market_cap': 1.7e12}, 'ethereum': {'usd_market_cap': 4e11}}))

    def _run(self, prev, hist=None, snaps=None, zle=()):
        calls = []
        funds = {'btc': [{'ticker': 'IBIT', 'name': 'a'}, {'ticker': 'FBTC', 'name': 'b'}], 'eth': [{'ticker': 'ETHA', 'name': 'c'}]}
        S = {'IBIT': {'net_assets': 6.7e10, 'cum_inflow': 6.5e10, 'net_inflow': 7.1e7, 'sponsor_fee': 0.0025},
             'FBTC': {'net_assets': 1.5e10, 'cum_inflow': 1.1e10, 'net_inflow': 2.9e7, 'sponsor_fee': 0},
             'ETHA': {'net_assets': 1.2e10, 'cum_inflow': 1.0e10, 'net_inflow': 1.0e8, 'sponsor_fee': 0.0025}}
        S.update(snaps or {})
        H = hist or {'btc': _rows(['2026-10-01', '2026-10-02']), 'eth': _rows(['2026-10-01', '2026-10-02'])}
        H.setdefault('btc', []); H.setdefault('eth', [])
        base = _soso_factory(H, funds, S)

        def soso(path, key, _retry=True):
            calls.append(path)
            for z in zle:
                if z in path:
                    raise RuntimeError('HTTP 500')
            if 'country_code=HK' in path:
                return _rows(['2026-10-02'], inflow=5.0)
            return base(path, key)
        with mock.patch.object(zd, 'soso', soso):
            out = zd.build_etf('k', 'c', prev)
        return out, calls

    def _prev(self, d1=100.0, cum=5000.0, asof='2026-10-02', h=1.0):
        f = (self.NOW - datetime.timedelta(hours=h)).isoformat()
        day = [[zd.ts('2026-08-%02d' % i), 1.0] for i in range(3, 29)] + [[zd.ts('2026-10-01'), 100.0], [zd.ts('2026-10-02'), d1]]
        fu = [{'t': 'IBIT', 'n': 'a', 'cty': 'us', 'aum': 67000.0, 'cum': 65000.0, 'd1': 71.0, 'fee': 0.25, 'prem': None},
              {'t': 'FBTC', 'n': 'b', 'cty': 'us', 'aum': 15000.0, 'cum': 11000.0, 'd1': 29.0, 'fee': 0.25, 'prem': None}]
        return {'assets': {'btc': {'sym': 'BTC', 'asof': asof, 'day': day, 'd1': d1, 'cum': cum, 'funds_at': f, 'funds': fu},
                           'eth': {'sym': 'ETH', 'asof': asof, 'day': day, 'd1': 100.0, 'cum': 5000.0, 'funds_at': f,
                                   'funds': [{'t': 'ETHA', 'n': 'c', 'cty': 'us', 'aum': 12000.0, 'cum': 10000.0, 'd1': 100.0, 'fee': 0.25, 'prem': None}]}},
                'hk': {'btc': {'sym': 'BTC', 'asof': asof, 'day': day[-3:], 'v': zd.ETF_HK_V}, 'eth': {'sym': 'ETH', 'asof': asof, 'day': day[-3:], 'v': zd.ETF_HK_V}}, 'hk_at': f}   # v293c: bieżący zapis HK

    def test_te_same_liczby_dnia_bez_listy(self):
        out, calls = self._run(self._prev())
        self.assertFalse(any('/market-snapshot' in c or c.startswith('/etfs?') for c in calls), 'te same liczby dnia, lista młoda — bez listy')
        self.assertEqual(out['assets']['btc']['funds_at'], self._prev()['assets']['btc']['funds_at'])

    def test_poprawka_liczb_dnia_pobiera_liste(self):
        for prev, why in ((self._prev(d1=90.0), 'przepływ dnia poprawiony przez źródło'), (self._prev(cum=4990.0), 'suma od startu poprawiona'),
                          (dict(self._prev(), assets={'btc': {k: v for k, v in self._prev()['assets']['btc'].items() if k != 'd1'}, 'eth': self._prev()['assets']['eth']}), 'stary plik bez d1')):
            zd.META['notes'].clear()
            out, calls = self._run(prev)
            self.assertEqual(sum('/market-snapshot' in c and ('IBIT' in c or 'FBTC' in c) for c in calls), 2, why)
            self.assertEqual(out['assets']['btc']['funds_at'], zd.NOW, why + ' — suma funduszy 71 + 29 = 100 = przepływ dnia')

    def test_suma_funduszy_niezgodna_bez_czasu(self):
        out, calls = self._run(None, snaps={'IBIT': {'net_assets': 6.7e10, 'cum_inflow': 6.5e10, 'net_inflow': 1.6e8, 'sponsor_fee': 0.0025}})
        a = out['assets']['btc']
        self.assertNotIn('funds_at', a, 'suma 160 + 29 ≠ 100 — szczegóły funduszy z innego dnia; następny przebieg pobiera znowu')
        self.assertTrue(any('SoSoValue BTC: lista funduszy niezgodna z przepływem dnia' in n for n in zd.META['notes']), zd.META['notes'])
        self.assertEqual(out['assets']['eth']['funds_at'], zd.NOW, 'ETH zgodne (100 = 100)')
        out, _ = self._run(None, snaps={'FBTC': {'net_assets': 1.5e10, 'cum_inflow': 1.1e10, 'net_inflow': None, 'sponsor_fee': 0}})
        self.assertNotIn('funds_at', out['assets']['btc'], 'fundusz bez przepływu — suma nieznana, bez czasu')
        out, _ = self._run(None, snaps={'IBIT': {'net_assets': 6.7e10, 'cum_inflow': 6.5e10, 'net_inflow': 7.102e7, 'sponsor_fee': 0.0025}})
        self.assertEqual(out['assets']['btc']['funds_at'], zd.NOW, 'różnica 0,02 mln — w tolerancji 0,05 mln (v199)')

    def test_blad_monety_poprzedni_wpis(self):
        prev = self._prev()
        out, calls = self._run(prev, hist={'btc': _rows(['2026-10-01', '2026-10-02'])}, zle=('symbol=ETH&country_code=US',))
        e = out['assets']['eth']
        self.assertEqual((e['asof'], len(e['day']), e['funds'][0]['t']), ('2026-10-02', 28, 'ETHA'), 'poprzedni wpis z historią 28 dni, nie brak monety')
        self.assertTrue(any('SoSoValue ETH: HTTP 500' in x for x in zd.META['errors'])); self.assertTrue(any('SoSoValue ETH: poprzednie dane z 2026-10-02' in n for n in zd.META['notes']))
        self.assertIsNot(e, prev['assets']['eth'], 'kopia')
        with self.assertRaises(RuntimeError):
            self._run(prev, zle=('summary-history?symbol=BTC&country_code=US', 'summary-history?symbol=ETH&country_code=US'))

    def test_blad_listy_nie_kasuje_monety(self):
        out, calls = self._run(self._prev(d1=90.0), zle=('/etfs?symbol=BTC',))
        a = out['assets']['btc']
        self.assertEqual((a['asof'], a['d1']), ('2026-10-02', 100.0), 'moneta z nowym zestawieniem')
        self.assertEqual([f['t'] for f in a['funds']], ['IBIT', 'FBTC'], 'ten sam dzień — poprzednia lista'); self.assertNotIn('funds_at', a)
        self.assertTrue(any('SoSoValue BTC: lista funduszy — HTTP 500' in x for x in zd.META['errors']))
        out, _ = self._run(self._prev(asof='2026-10-01'), zle=('/etfs?symbol=BTC',))
        self.assertEqual(out['assets']['btc']['funds'], [], 'inny dzień — bez listy (nie stare liczby przy nowym dniu)')

    def test_hongkong_komplet(self):
        prev = self._prev(h=7)
        out, calls = self._run(prev, zle=('symbol=ETH&country_code=HK',))
        self.assertEqual(out['hk']['eth'], prev['hk']['eth'], 'ETH bez odpowiedzi — poprzedni wpis'); self.assertEqual(out['hk']['btc']['asof'], '2026-10-02')
        self.assertNotIn('hk_at', out, 'bez kompletu — bez czasu, następny przebieg pobiera znowu')
        out, _ = self._run(prev)
        self.assertEqual(out['hk_at'], zd.NOW)

    def test_kontrola_czas_zadania_budowy(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('kontrola_v194', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        k = importlib.util.module_from_spec(spec); spec.loader.exec_module(k)
        NOW = self.NOW
        f = lambda m: (NOW - datetime.timedelta(minutes=m)).strftime('%Y-%m-%dT%H:%M:%SZ')  # noqa: E731
        runs = [{'id': 1, 'name': 'Strona i dane', 'status': 'completed', 'conclusion': 'success', 'run_started_at': f(60), 'updated_at': f(36)},
                {'id': 2, 'name': 'Strona i dane', 'status': 'completed', 'conclusion': 'success', 'run_started_at': f(30), 'updated_at': f(27)},
                {'id': 3, 'name': 'Strona i dane', 'status': 'completed', 'conclusion': 'cancelled', 'run_started_at': f(100), 'updated_at': f(50)},
                {'id': 4, 'name': 'Strona i dane', 'status': 'completed', 'conclusion': 'success', 'run_started_at': f(25 * 60), 'updated_at': f(25 * 60 - 40)},
                {'id': 5, 'name': 'Strona i dane', 'status': 'completed', 'conclusion': 'success', 'run_started_at': f(200), 'updated_at': f(186)},
                {'id': 6, 'name': 'Zegar zapasowy', 'status': 'completed', 'conclusion': 'success', 'run_started_at': f(300), 'updated_at': f(200)},
                {'id': 7, 'name': 'Strona i dane', 'status': 'completed', 'conclusion': 'success', 'run_started_at': 'zły', 'updated_at': f(5)}]
        self.assertEqual(k.najdluzsze_udane(runs, NOW, 3), [1, 5, 2], 'udane „Strona” z 24 h, malejąco wg czasu; anulowane, starsze, inne zadania i zły czas — pominięte')
        J = [{'name': 'zbuduj', 'started_at': '2026-10-05T20:00:20Z', 'completed_at': '2026-10-05T20:13:38Z'}, {'name': 'opublikuj', 'started_at': '2026-10-05T20:13:40Z', 'completed_at': '2026-10-05T20:24:00Z'}]
        self.assertAlmostEqual(k.zadanie_min(J, 'zbuduj'), 13.3, places=6)
        self.assertIsNone(k.zadanie_min(J, 'brak')); self.assertIsNone(k.zadanie_min([{'name': 'zbuduj', 'started_at': None, 'completed_at': 'x'}], 'zbuduj')); self.assertIsNone(k.zadanie_min(None, 'zbuduj'))
        A = {'przebiegi_24h': 5, 'wg_wyniku': {'success': 5}, 'najdluzszy_min': 24.0, 'budowa_max_min': 13.3, 'porazki': []}
        R = {'at': NOW.isoformat(), 'wynik': 'OK', 'uwagi': [], 'bledy': [], 'strona': {'ok': True, 'http': 200, 'ms': 1},
             'meta': {'at': f(5), 'wiek_min': 5, 'zrodla': 76, 'bez_odpowiedzi': [], 'errors': [], 'notes': []}, 'pliki': {}, 'swiezosc': [], 'zgodnosc': {}, 'actions': A}
        md = k.raport_md(R)
        self.assertIn('- Najdłuższy udany przebieg w 24 h: 24,0 min (od startu do końca, z czekaniem na maszyny); samo zadanie budowy najdłużej 13,3 min z limitu 25 min.', md)
        A['budowa_max_min'] = 21.5
        self.assertIn('samo zadanie budowy najdłużej 21,5 min z limitu 25 min ⚠️ blisko limitu.', k.raport_md(R))
        del A['budowa_max_min']
        self.assertIn('24,0 min (od startu do końca, z czekaniem na maszyny; limit zadania budowy 25 min) ⚠️ blisko limitu.', k.raport_md(R), 'bez czasu zadań — jak w v190')
        with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'), encoding='utf-8') as fh:
            src = fh.read()
        i = src.index('# 4. przebiegi Actions'); j = src.index('# 5. v115', i)
        self.assertIn("budowa_kandydaci(runs, NOW)", src[i:j]); self.assertIn("zadanie_min(json.loads(b3).get('jobs', []), 'zbuduj')", src[i:j])   # v199
        self.assertTrue(md.startswith('# Kontrola strony — ') and '**Wynik: OK**' in md, 'nagłówek i wynik bez zmian (czyta je zadanie w chmurze)')


# ===================== v195: CENY ETF-ÓW REGIONÓW — ZAMKNIĘCIE SESJI Z PLIKU NOTOWAŃ (ŚWIECA WSTĘPNA ALBO BRAK) =====================
class CenyZamknieciaV195(unittest.TestCase):
    """v195: zamknięcie sesji z notowania (czas ≥ 16:00, teraz ≥ 16:15) zastępuje wstępną świecę albo dopisuje brakującą, gdy poprzednie
    zamknięcie notowania = poprzednia świeca (≤ 0,05%); obrót nieznany = None. Liczby z 05.10. Bez sieci."""
    T = 1791230400   # 2026-10-05 20:00 UTC = 16:00 w Nowym Jorku (zamknięcie sesji)

    def setUp(self):
        zd.META['notes'].clear(); zd.META['errors'].clear()

    def _q(self):
        h = lambda c, v: [[d, c, v] for d in ('2026-09-24', '2026-09-25', '2026-09-28', '2026-09-29', '2026-09-30')]  # noqa: E731 — v199: historia obrotu
        return {'SPY': {'asof': '2026-10-05', 'd': h(760.0, 50_000_000) + [['2026-10-01', 763.99, 47708100], ['2026-10-02', 769.64, 46306400], ['2026-10-05', 774.94, 36114284]]},   # v203: prawdziwy obrót
                'ASEA': {'asof': '2026-10-02', 'd': h(20.9, 20_000) + [['2026-10-01', 20.9, 14900], ['2026-10-02', 20.95, 30300]]},
                'EZA': {'asof': '2026-10-05', 'd': h(63.0, 100_000) + [['2026-10-02', 63.19, 62200], ['2026-10-05', 63.11, 70616]]},   # v203: prawdziwy obrót
                'EWC': {'asof': '2026-10-05', 'd': h(58.0, 1_500_000) + [['2026-10-02', 58.72, 1192200], ['2026-10-05', 58.75, 50563]]},   # v203: obrót 3% — wstępna
                'EWJ': {'asof': '2026-10-05', 'd': h(98.0, 5_000_000) + [['2026-10-02', 98.92, 7328800], ['2026-10-05', 99.3, 3071843]]},
                'INDA': {'asof': '2026-10-05', 'd': h(46.0, 4_500_000) + [['2026-10-02', 46.52, 4323400], ['2026-10-05', 46.55, 3032335]]}}

    def _dz(self, at='2026-10-05T21:33:18+00:00', **over):   # v205: at — czas pobrania pliku notowań
        q = {'SPY': {'c': 774.83, 'pc': 769.64, 'dp': 0.6743, 't': self.T}, 'ASEA': {'c': 21.095, 'pc': 20.95, 'dp': 0.6921, 't': self.T},
             'EZA': {'c': 63.17, 'pc': 63.19, 'dp': -0.0317, 't': self.T}, 'EWJ': {'c': 99.3, 'pc': 98.92, 'dp': 0.3841, 't': self.T},
             'INDA': {'c': 46.57, 'pc': 46.52, 'dp': 0.1075, 't': self.T}, 'EWC': {'c': 58.78, 'pc': 58.72, 'dp': 0.1022, 't': self.T}}   # v199: INDA z pełnym obrotem — bez podmiany
        for k, v in over.items():
            q[k] = dict(q[k], **v)
        return {'at': at, 'q': q}

    def test_wstepne_i_brakujaca(self):
        q = self._q()
        self.assertEqual(zd._zamkniecia_z_notowan(q, self._dz()), 5)
        self.assertEqual(q['SPY']['d'][-1], ['2026-10-05', 774.83, None], 'v204: zamknięcie oficjalne (świeca wstępna 774,94 mimo obrotu 72% mediany)')
        self.assertEqual(q['EZA']['d'][-1], ['2026-10-05', 63.17, None]); self.assertEqual(q['EWC']['d'][-1], ['2026-10-05', 58.78, None])
        self.assertEqual((q['ASEA']['d'][-1], q['ASEA']['asof'], len(q['ASEA']['d'])), (['2026-10-05', 21.095, None], '2026-10-05', 8), 'ASEA: dopisana świeca 05.10')
        self.assertEqual(q['INDA']['d'][-1], ['2026-10-05', 46.57, None], 'v204: INDA 46,57 = zamknięcie oficjalne (świeca 46,55 była wstępna)')
        self.assertEqual(q['EWJ']['d'][-1], ['2026-10-05', 99.3, 3071843], 'świeca równa zamknięciu (ostateczna) — bez zmian')
        self.assertEqual(q['SPY']['d'][-2], ['2026-10-02', 769.64, 46306400], 'starsze świece bez zmian')
        self.assertTrue(any('zamknięcie sesji z pliku notowań dziennych' in n and 'ASEA, EWC, EZA, INDA, SPY' in n for n in zd.META['notes']), zd.META['notes'])
        zd.META['notes'].clear()
        self.assertEqual(zd._zamkniecia_z_notowan(q, self._dz(at='2026-10-05T22:35:00+00:00')), 0, 'drugi raz — nic do zmiany')
        self.assertEqual(zd.META['notes'], [])

    def test_bez_zmian(self):
        for dz, why in ((self._dz(at='2026-10-05T19:30:00+00:00', ASEA={'t': self.T - 1800}), 'plik pobrany 15:30 — sesja w toku (v205: czas pobrania)'),
                        (self._dz(at='2026-10-05T20:10:00+00:00'), 'plik pobrany 16:10 — przed 16:15'),
                        (self._dz(ASEA={'pc': 20.5}), 'inne poprzednie zamknięcie (dywidenda, korekta) — bez zmian'),
                        (self._dz(ASEA={'c': None}), 'brak ceny'),
                        (self._dz(ASEA={'c': True}), 'nie liczba'),
                        (self._dz(ASEA={'t': 'x'}), 'zły czas'),
                        (self._dz(ASEA={'t': self.T - 3 * 86400, 'c': 20.95, 'pc': 20.9}), 'notowanie z 02.10 — świeca równa (v199: zgodne poprzednie zamknięcie)')):
            q = self._q()
            zd._zamkniecia_z_notowan(q, dz)
            self.assertEqual(q['ASEA']['d'][-1], ['2026-10-02', 20.95, 30300], why)
        q = self._q()
        self.assertEqual(zd._zamkniecia_z_notowan(q, None), 0, 'bez pliku notowań')
        self.assertEqual(zd._zamkniecia_z_notowan(q, {'q': 'x'}), 0)

    def test_w_build_prices(self):
        q = self._q()
        with mock.patch.object(zd, 'DAY_SYMS', ['SPY', 'ASEA', 'EZA', 'EWJ', 'INDA']), mock.patch.object(zd, 'td_batch', lambda syms, key: (q, [])), \
                mock.patch.object(zd, 'TD_MIN_CANDLES', 2), mock.patch.object(zd, 'TD_MIN_SYMBOLS', 4), \
                mock.patch.object(zd, '_ny_now', lambda: datetime.datetime(2026, 10, 5, 17, 33)), mock.patch.dict(zd.SAVED, {'dzis': self._dz()}):
            o = zd.build_prices('k')
        self.assertEqual(o['asof'], '2026-10-05', 'wszystkie fundusze z tą samą ostatnią sesją — region bez „—”')
        self.assertEqual(o['q']['ASEA']['d'][-1], ['2026-10-05', 21.095, None])


# ===================== v196: KONTROLA RWA — TRWAŁY BRAK WARTOŚCI SPOZA LISTY PRZY MAŁYM WPŁYWIE = INFORMACJA =====================
class KontrolaRwaTrwalyBrakV196(unittest.TestCase):
    """v196: brak wartości produktów spoza listy (hidden_valued < 20): ⚠️ przez 3 dni od najmłodszego „brak od”, potem ℹ️, gdy „bez bieżącej
    wyceny” ≤ 5% sumy; większy udział albo nowy brak — znowu ⚠️. Liczby z 06.10. Bez sieci."""

    def setUp(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('kontrola_v196', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        self.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(self.k)

    def _j(self, brak='2026-10-05', sv=435036774, cv=26687749609, hv_n=0):
        hv = {'apollo': [95406791.04, '2026-09-27', 0, 10, brak], 'raac': [113538717.0, '2026-09-27', 0, 10, brak], 'stary': [1.0, '2026-09-01', 0, 3, '2026-09-20'],
              'zly': [1.0, '2026-09-27', 0, 1, 'x'], 'bez': [1.0, '2026-09-27', 0, 1]}
        return {'hist': [], 'chk': {}, 'ok': {'list': True, 'hidden': True}, 'n': {'hidden_valued': hv_n, 'kept': 0}, 'hv': hv,
                'seg': {'all': {'v': cv}}, 'stale': {'n': 13, 'nf': 0, 'ng': 13, 'v': sv, 'gone': '2026-10-05'}}

    def test_brak_od(self):
        self.assertEqual(self.k.rwa_brak_od(self._j()), '2026-10-05', 'najmłodszy poprawny „brak od”')
        self.assertIsNone(self.k.rwa_brak_od({'hv': {'a': [1.0, 'x', 0, 1]}})); self.assertIsNone(self.k.rwa_brak_od(None)); self.assertIsNone(self.k.rwa_brak_od({'hv': 'x'}))

    def test_trzy_dni_uwaga_potem_informacja(self):
        U = datetime.timezone.utc
        Z = self.k.rwa_porownanie(self._j(), datetime.datetime(2026, 10, 6, 1, 15, tzinfo=U))
        self.assertEqual(Z['status'], '⚠️'); self.assertIn('tylko 0 (próg 20)', Z['uwagi'][0])
        Z = self.k.rwa_porownanie(self._j(), datetime.datetime(2026, 10, 7, 23, 0, tzinfo=U))
        self.assertEqual(Z['status'], '⚠️', '2 dni — jeszcze uwaga')
        Z = self.k.rwa_porownanie(self._j(), datetime.datetime(2026, 10, 8, 1, 15, tzinfo=U))
        self.assertEqual((Z['status'], Z['uwagi']), ('✅', []), '3 dni, 1,6% bez bieżącej wyceny — bez uwagi')
        self.assertIn('ℹ️ produkty spoza listy z wartością 0 (próg 20) — źródło nie podaje ich wartości od 2026-10-05 (3 dni, stan trwały); bez bieżącej wyceny 1,6% sumy — bez uwagi', Z['opis'])
        Z = self.k.rwa_porownanie(self._j(sv=2e9, cv=26e9), datetime.datetime(2026, 10, 9, 1, 15, tzinfo=U))
        self.assertEqual(Z['status'], '⚠️', '7,1% bez bieżącej wyceny — nadal uwaga'); self.assertIn('tylko 0 (próg 20)', Z['uwagi'][0])
        Z = self.k.rwa_porownanie(self._j(brak='2026-10-09'), datetime.datetime(2026, 10, 9, 6, 0, tzinfo=U))
        self.assertEqual(Z['status'], '⚠️', 'nowy brak (młodszy „brak od”) — znowu uwaga')
        Z = self.k.rwa_porownanie(dict(self._j(), ok={'list': True, 'hidden': False}), datetime.datetime(2026, 10, 9, 1, 15, tzinfo=U))
        self.assertTrue(any('pobranie wartości produktów spoza głównej listy przerwane' in u for u in Z['uwagi']), 'przerwane pobranie — uwaga jak dotąd')
        self.assertEqual(self.k.rwa_porownanie(self._j(hv_n=25), datetime.datetime(2026, 10, 6, 1, 15, tzinfo=U))['status'], '✅', '25 z wartością — bez uwagi')


# ===================== v197: TAJWAN — PONOWNY ODCZYT OSTATNICH SESJI (POPRAWKI GIEŁDY PO PIERWSZEJ PUBLIKACJI) =====================
class TwPoprawkiV197(unittest.TestCase):
    """v197: dni z ostatnich 3 dni kalendarzowych pobierane ponownie najwyżej co 3 godz.; zmiana = nowy wiersz + notatka; brak odpowiedzi albo
    „No Data!” — poprzednie liczby (dzień nie staje się „bez sesji”); USD bez nowego kursu tylko przy tej samej liczbie zagranicy. Bez sieci."""

    def setUp(self):
        zd.META['errors'].clear(); zd.META['notes'].clear(); zd._RUN_T0[0] = None; zd._BACK_LATE_NOTE[0] = False
        self.enterContext(mock.patch.object(zd.time, 'sleep', lambda s: None))
        self.enterContext(mock.patch.object(zd, 'TW_BACK_MAX', 0))   # bez historii wstecz — tylko ostatnie dni

    @staticmethod
    def tw(date, fx, it='-5,293,160,007'):
        return {'stat': 'OK', 'date': date.replace('-', ''), 'data': [
            ['Dealers (Proprietary)', '1', '1', '1,415,360,504'], ['Dealers (Hedge)', '1', '1', '9,533,137,013'],
            ['Securities Investment Trust Companies', '1', '1', it],
            ['Foreign Investors include Mainland Area Investors(Foreign Dealers excluded)', '1', '1', fx],
            ['Foreign Dealers', '0', '0', '0'], ['Total', '1', '1', '77,551,945,755']]}

    def _run(self, prev, now, answers, rates=None):
        asked = []

        def gj(url, headers=None, timeout=30):
            if 'DEXTAUS' in url:
                return {'observations': rates or []}
            day = url.split('dayDate=')[1][:8]; iso = f'{day[:4]}-{day[4:6]}-{day[6:]}'; asked.append(iso)
            a = answers.get(iso)
            if isinstance(a, Exception):
                raise a
            return a if a is not None else {'stat': 'No Data!'}
        with mock.patch.object(zd, 'NOW', now), mock.patch.object(zd, '_now_utc', lambda: datetime.datetime.fromisoformat(now)), \
                mock.patch.object(zd, 'get_json', gj):
            return zd.twse_part(prev, 'KLUCZ'), asked

    def _prev(self, chk=None):
        p = {'d': [['2026-09-29', -63201.3, 1416.9, -16402.6, -78187.0, -1975.0, '2026-09-29'], ['2026-09-30', 29636.0, 7781.2, 1240.1, 38657.2, 926.1, '2026-09-30'],
                   ['2026-10-01', 21937.3, 5656.6, 1659.0, 29252.9, 685.2, '2026-10-01'], ['2026-10-02', 2621.8, 4909.6, 2026.1, 9557.5, 81.9, '2026-10-02'],
                   ['2026-10-05', 71896.6, -6394.7, 10948.1, 76450.0, 2246.1, '2026-10-02']], 'empty': ['2026-09-28']}   # 28.09 — święto (Dzień Nauczyciela)
        p['chk'] = {'2026-09-29': '2026-10-01T00:00:00+00:00', '2026-09-30': '2026-10-02T00:00:00+00:00', '2026-10-01': '2026-10-03T00:00:00+00:00',
                    '2026-10-02': '2026-10-04T00:00:00+00:00'} if chk is None else chk   # v198: starsze dni już czytane ponownie
        return p

    def test_ponowny_odczyt_poprawia_liczby(self):
        out, asked = self._run(self._prev(), '2026-10-06T00:00:00+00:00', {'2026-10-05': self.tw('2026-10-05', '71,896,608,245')})
        self.assertEqual(asked, ['2026-10-05'], '08:00 w Tajpej: dziś jeszcze bez sesji; 05.10 (1 dzień) — ponownie; 02.10 (4 dni) — nie')
        r = {x[0]: x for x in out['d']}['2026-10-05']
        self.assertEqual(r[:5], ['2026-10-05', 71896.6, -5293.2, 10948.5, 77551.9], 'liczby giełdy z ponownego odczytu')
        self.assertEqual(r[5:], [2246.1, '2026-10-02'], 'ta sama liczba zagranicy — przeliczenie na USD zostaje (bez nowego kursu)')
        self.assertEqual(out['chk']['2026-10-05'], '2026-10-06T00:00:00+00:00')   # v198: starsze dni mają chk z _prev
        self.assertTrue(any('TWSE: poprawione liczby sesji przy ponownym odczycie — 2026-10-05' in n for n in zd.META['notes']), zd.META['notes'])
        self.assertEqual(zd.META['errors'], [])
        zd.META['notes'].clear()
        out2, asked = self._run(out, '2026-10-06T01:00:00+00:00', {})
        self.assertEqual(asked, [], 'godzinę później — bez ponownego odczytu')
        out3, asked = self._run(out2, '2026-10-06T03:30:00+00:00', {'2026-10-05': self.tw('2026-10-05', '71,896,608,245')})
        self.assertEqual(asked, ['2026-10-05'], 'po 3 godz. — znowu'); self.assertFalse(any('poprawione' in n for n in zd.META['notes']), 'te same liczby — bez notatki')
        out4, asked = self._run(out3, '2026-10-09T09:00:00+00:00', {'2026-10-06': self.tw('2026-10-06', '1,000,000,000'), '2026-10-07': self.tw('2026-10-07', '2,000,000,000'),
                                                                    '2026-10-08': self.tw('2026-10-08', '3,000,000,000'), '2026-10-09': self.tw('2026-10-09', '4,000,000,000')})
        self.assertNotIn('2026-10-05', asked, '4 dni po sesji — już nie')

    def test_zmiana_zagranicy_bez_kursu_bez_usd_i_brak_odpowiedzi(self):
        out, _ = self._run(self._prev(), '2026-10-06T00:00:00+00:00', {'2026-10-05': self.tw('2026-10-05', '70,000,000,000')})
        r = {x[0]: x for x in out['d']}['2026-10-05']
        self.assertEqual((r[1], r[5:]), (70000.0, [None, None]), 'inna liczba zagranicy, brak kursu — brak przeliczenia, nie stara liczba')
        out, _ = self._run(self._prev(), '2026-10-06T00:00:00+00:00', {'2026-10-05': self.tw('2026-10-05', '70,000,000,000')},
                           rates=[{'date': '2026-10-02', 'value': '32.0'}])
        self.assertEqual({x[0]: x for x in out['d']}['2026-10-05'][5:], [2187.5, '2026-10-02'], 'z kursem — nowe przeliczenie')
        for ans, why in ((None, '„No Data!”'), (RuntimeError('HTTP 500'), 'błąd')):
            zd.META['notes'].clear(); zd.META['errors'].clear()
            out, _ = self._run(self._prev(), '2026-10-06T00:00:00+00:00', {'2026-10-05': ans})
            self.assertEqual({x[0]: x for x in out['d']}['2026-10-05'][:5], ['2026-10-05', 71896.6, -6394.7, 10948.1, 76450.0], why + ' — poprzednie liczby')
            self.assertNotIn('2026-10-05', out['empty'], why + ' — dzień z danymi nie staje się „bez sesji”')
            self.assertEqual(zd.META['errors'], [], why + ' — notatka, nie błąd')
            self.assertTrue(any('TWSE ponowny odczyt: 1 dni bez odpowiedzi' in n for n in zd.META['notes']), zd.META['notes'])
            self.assertNotIn('2026-10-05', out.get('chk', {}), 'bez udanego odczytu — bez czasu; następny przebieg próbuje znowu')

    def test_stary_chk_przyciety(self):
        c = dict(self._prev()['chk'], **{'2026-10-05': '2026-10-05T23:00:00+00:00', '2026-09-01': '2026-09-01T09:00:00+00:00', 'x': 5})
        out, _ = self._run(self._prev(chk=c), '2026-10-06T00:00:00+00:00', {})
        self.assertEqual(out['chk'], dict(self._prev()['chk'], **{'2026-10-05': '2026-10-05T23:00:00+00:00'}),
                         'młody odczyt bez ponownego zapytania; dni spoza pliku i złe wpisy — usunięte')


# ===================== v198: TAJWAN — JEDNORAZOWY PONOWNY ODCZYT DNI BEZ CHK (DO 14 DNI) =====================
class TwJednorazowoV198(TwPoprawkiV197):
    """v198: dzień bez chk (nigdy nie czytany ponownie) do 14 dni — jeden ponowny odczyt; potem zwykła reguła 3 dni; chk trzymane do 15 dni."""

    def test_dni_bez_chk_raz(self):
        P = self._prev(chk={})
        ans = {d: self.tw(d, '1,000,000,000') for d in ('2026-09-29', '2026-09-30', '2026-10-01', '2026-10-02', '2026-10-05')}
        out, asked = self._run(P, '2026-10-06T00:00:00+00:00', ans)
        self.assertEqual(asked, ['2026-09-29', '2026-09-30', '2026-10-01', '2026-10-02', '2026-10-05'], 'wszystkie dni bez chk do 14 dni')
        self.assertEqual(sorted(out['chk']), ['2026-09-29', '2026-09-30', '2026-10-01', '2026-10-02', '2026-10-05'])
        out2, asked = self._run(out, '2026-10-06T04:00:00+00:00', ans)
        self.assertEqual(asked, ['2026-10-05'], 'po odczycie — tylko ostatnie 3 dni (co 3 godz.)')
        out3, asked = self._run(out2, '2026-10-10T04:00:00+00:00', dict(ans, **{d: self.tw(d, '1,000,000,000') for d in ('2026-10-06', '2026-10-07', '2026-10-08', '2026-10-09')}))
        self.assertFalse({'2026-09-29', '2026-09-30', '2026-10-01', '2026-10-02'} & set(asked), 'dni z chk starsze niż 3 dni — nie')
        self.assertIn('2026-09-29', out3['chk'], 'chk trzymane do 15 dni (11 dni po sesji — jeszcze jest)')
        old = dict(P, d=[['2026-09-15', 1.0, 0, 0, 0, None, None]] + P['d'])
        _, asked = self._run(old, '2026-10-06T00:00:00+00:00', ans)
        self.assertNotIn('2026-09-15', asked, 'dzień starszy niż 14 dni — bez ponownego odczytu')


# ===================== v199: PO PRZEGLĄDZIE v193–v196 — RWA (ZAPIS Z ZAMIENNIKIEM), ETF, CENY, KONTROLA =====================
class PoPrzegladzieV199(unittest.TestCase):
    """v199: zapis produktu z zamiennikiem w konfiguracji zostaje także w dniu bez danych zamiennika (potem wraca do sum); ETF — tolerancja
    0,05 mln i poprzedni wpis tylko do 3 dni od najnowszej monety; ceny — podmiana tylko świecy wstępnej (mały obrót); kontrola — czasy zadania
    budowy także dla przebiegów > 20 min. Bez sieci."""

    def test_rwa_zapis_z_zamiennikiem_i_powrot(self):
        t = PoPrzegladzieV175('test_stan_produktow_i_zapis_po_31_dniach'); t.setUp()
        try:
            r = RwaV133('test_bramka_odswiezenia_i_proby'); P, H = r._parsed(), r._hid()
            em = zd.rwe_blok(t._rd(), None, t.NOW, oc={'v': 1, 'px': {'zloto': dict(_RWE169_GOLD)}})
            prev = {'at': '2026-10-04T23:00:00+00:00', 'seg': {}, 'hist': [], 'ok': {'list': True, 'hidden': True}, 'ph': {},
                    'hv': {s: [v, '2026-09-27', 0, 2, None] for s, v in H.items() if v}}
            H2 = dict(H, spiko=None)
            prev2 = dict(prev, hv=dict(prev['hv'], spiko=[2625000000.0, '2026-08-20', 0, 5, '2026-08-25']))
            J1 = zd.rwa_build(P, H2, prev2, t.NOW, em=em)
            self.assertIn('spiko', J1['issuer']['used'], 'dzień 1: Spiko w sumach z danych emitenta')
            J2 = zd.rwa_build(P, H2, J1, t.NOW)                                  # przebieg bez danych emitenta
            self.assertIn('spiko', J2['hv'], 'zapis zostaje mimo braku zamiennika tego dnia')
            J3 = zd.rwa_build(P, H2, J2, t.NOW, em=em)                           # dane emitenta wracają
            self.assertIn('spiko', J3['issuer']['used'], 'Spiko wraca do sum (dotąd: zapis usunięty — poza sumą na zawsze)')
            self.assertGreater(J3['seg']['all']['v'], J2['seg']['all']['v'] + 1e9, 'suma z Spiko wyższa o ponad 1 mld USD')
        finally:
            t.doCleanups()

    def test_etf_tolerancja_i_wiek_poprzedniego_wpisu(self):
        t = PoPrzegladzieV194('test_suma_funduszy_niezgodna_bez_czasu'); t.setUp()
