# ===================== v207: PAMIĘĆ AWARII CZĘŚCI AUTOMATU + OCENA W KONTROLI =====================
class PamiecAwariiV207(unittest.TestCase):
    """v207: zbieracz pamięta w meta.json, od kiedy część nie działa (seria nieudanych przebiegów) i kiedy się naprawiła (wpis 48 h po naprawie);
    kontrola: seria ≥ 3 h = uwaga, ≥ 48 h = BŁĄD z tym, co zrobić; naprawione w 24 h = informacja; dopisek przy odrzuconym kluczu i limicie."""

    def setUp(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('kontrola_v207', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        self.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(self.k)

    @staticmethod
    def _t(h):
        return (datetime.datetime(2026, 10, 6, 4, 0, tzinfo=datetime.timezone.utc) + datetime.timedelta(hours=h)).isoformat()

    def test_seria_naprawa_i_nowa_seria(self):
        t = self._t
        a = zd.awarie({}, {'tic': False, 'fred': True, 'oecd': 'cached'}, t(0))
        self.assertEqual(a, {'tic': {'od': t(0), 'ost': t(0), 'n': 1, 'do': None}}, 'tylko ok False zaczyna serię')
        a = zd.awarie(a, {'tic': False}, t(1))
        self.assertEqual(a['tic'], {'od': t(0), 'ost': t(1), 'n': 2, 'do': None})
        a = zd.awarie(a, {'fred': True}, t(2))
        self.assertEqual(a['tic']['do'], None, 'część nieobecna w przebiegu — seria bez zmian')
        a = zd.awarie(a, {'tic': 'cached'}, t(3))
        self.assertEqual(a['tic'], {'od': t(0), 'ost': t(1), 'n': 2, 'do': None}, "v211: 'cached' (bez zapytania — czeka na ponowienie) nie kończy serii")
        a = zd.awarie(a, {'tic': True}, t(3))
        self.assertEqual(a['tic'], {'od': t(0), 'ost': t(1), 'n': 2, 'do': t(3)}, 'tylko True kończy serię (naprawa)')
        b = zd.awarie(a, {'tic': True}, t(4))
        self.assertEqual(b['tic']['do'], t(3), 'naprawiona — data naprawy bez zmian')
        b = zd.awarie(a, {'tic': False}, t(5))
        self.assertEqual(b['tic'], {'od': t(5), 'ost': t(5), 'n': 1, 'do': None, 'prev': [t(0), t(3), 2]}, 'awaria po naprawie = nowa seria; v211: poprzednia zostaje')
        self.assertEqual(zd.awarie(a, {'tic': True}, t(3 + 48)), a, '48 h po naprawie — wpis jeszcze jest')
        self.assertEqual(zd.awarie(a, {'tic': True}, t(3 + 48.1)), {}, 'ponad 48 h po naprawie — wpis znika')

    def test_nieobecna_zle_wpisy_i_limit(self):
        t = self._t
        a = {'stara': {'od': t(-200), 'ost': t(-169), 'n': 5, 'do': None}, 'mloda': {'od': t(-200), 'ost': t(-167), 'n': 5, 'do': None}}
        o = zd.awarie(a, {}, t(0))
        self.assertEqual((o['stara']['do'], o['stara']['zn'], o['mloda']['zn']), (t(0), True, True), 'v211: nieobecna > 6 h od ostatniej awarii — seria zamknięta jako „zniknęła”')
        self.assertEqual(sorted(zd.awarie(a, {'stara': False}, t(0))), ['mloda', 'stara'], 'obecna z błędem — seria trwa mimo wieku')
        zle = {'a': {'od': t(0), 'ost': t(-1), 'n': 1, 'do': None}, 'b': {'od': t(-1), 'ost': t(0), 'n': 0, 'do': None},
               'c': {'od': t(-1), 'ost': t(0), 'n': True, 'do': None}, 'd': {'od': 'x', 'ost': t(0), 'n': 1, 'do': None},
               'e': {'od': t(-2), 'ost': t(-1), 'n': 1, 'do': 'x'}, 'f': {'od': t(-2), 'ost': t(-1), 'n': 1, 'do': t(-1.5)},
               'g': {'od': t(-2), 'ost': t(1), 'n': 1, 'do': None}, 'h': {'od': '2026-10-06T03:00:00', 'ost': t(0), 'n': 1, 'do': None}, 'i': 'x', 5: {}}
        self.assertEqual(zd.awarie(zle, {}, t(0)), {}, 'złe wpisy pominięte (kolejność, liczba, czas bez strefy, naprawa przed awarią, przyszłość)')
        self.assertEqual(zd.awarie(None, None, t(0)), {}); self.assertEqual(zd.awarie('x', {'a': None, 'b': 0}, t(0)), {}, 'tylko False = awaria')
        with self.assertRaises(ValueError):
            zd.awarie({}, {'a': False}, '2026-10-06T04:00:00')
        duzo = {f'c{i:03d}': {'od': t(-10), 'ost': t(-10 + i / 100), 'n': 1, 'do': None} for i in range(120)}
        out = zd.awarie(duzo, {}, t(0))
        self.assertEqual(len(out), zd.AW_MAX); self.assertIn('c119', out); self.assertNotIn('c019', out, 'zostają najmłodsze wg ostatniej awarii')
        self.assertEqual((zd.AW_PO_NAPRAWIE_H, zd.AW_NIEOBECNA_H, zd.AW_MAX), (48, 6, 100))

    def test_main_zapisuje_awarie_przed_meta(self):
        import inspect
        src = inspect.getsource(zd.main)
        i, j = src.index("META['awarie'] = awarie("), src.index("save('meta', META)")
        self.assertLess(i, j, 'pamięć awarii liczona przed zapisem meta.json')
        self.assertIn("META['awarie'] = awarie(pm.get('awarie'), META['ok'], NOW)", src); self.assertIn("pm = previous('meta') or {}", src)

    def test_kontrola_ocena(self):
        k, t = self.k, self._t
        now = datetime.datetime(2026, 10, 6, 4, 0, tzinfo=datetime.timezone.utc)
        self.assertIsNone(k.awarie_ocena({}, now)); self.assertIsNone(k.awarie_ocena({'awarie': []}, now)); self.assertIsNone(k.awarie_ocena(None, now))
        Z = k.awarie_ocena({'awarie': {}}, now)
        self.assertEqual(Z, {'trwa': [], 'naprawione': [], 'zniknely': [], 'uwagi': [], 'bledy': []})
        aw = {'krotka': {'od': t(-2), 'ost': t(-0.2), 'n': 12, 'do': None}, 'tic': {'od': t(-5), 'ost': t(-0.1), 'n': 30, 'do': None},
              'oecd': {'od': t(-50), 'ost': t(-0.1), 'n': 290, 'do': None}, 'fred': {'od': t(-10), 'ost': t(-8), 'n': 13, 'do': t(-7.9)},
              'bis': {'od': t(-40), 'ost': t(-30), 'n': 60, 'do': t(-25)}, 'zly': {'od': t(-1), 'ost': t(0), 'n': 0, 'do': None}, 'x': 'y'}
        Z = k.awarie_ocena({'awarie': aw}, now)
        self.assertEqual([x['czesc'] for x in Z['trwa']], ['krotka', 'oecd', 'tic']); self.assertEqual([x['czesc'] for x in Z['naprawione']], ['fred'])
        self.assertEqual(len(Z['bledy']), 1); self.assertEqual(len(Z['uwagi']), 1)
        self.assertEqual(Z['bledy'][0], 'część automatu „oecd” nie działa od 04.10.2026, 04:00 (2 dni 2 godz., nieudanych przebiegów z rzędu: 290) — automat '
                                        'nie naprawił tego sam; ' + k.PORADA_3D + ' (zadanie: „napraw część oecd”)')
        self.assertEqual(Z['uwagi'][0], 'część automatu „tic” nie działa od 06.10.2026, 01:00 (5 godz., nieudanych przebiegów z rzędu: 30) — automat ponawia '
                                        'sam; dane tej części mają swój wiek na stronie')
        self.assertEqual(Z['naprawione'][0]['h'], 2.1)
        self.assertEqual((k.AW_UWAGA_H, k.AW_BLAD_H, k.AW_INFO_H), (3, 24, 24))   # v385: BŁĄD od doby (było 48 h)

    def test_rodzaj_bledu(self):
        r = self.k.awaria_rodzaj
        for e in ('EODHD — klucz odrzucony albo plan bez indeksów (każda próba: HTTP 401/403)', 'Turcja: klucz EVDS_KEY odrzucony',
                  'Coinalyze: HTTP 403 — klucz odrzucony albo blokada', 'CoinGecko: HTTP Error 401: Unauthorized', 'BEA: Invalid API UserId — invalid api key'):
            self.assertIn('odrzucony klucz', r(e), e)
        for e in ('Twelve Data: You have run out of API credits for the current minute', 'OECD: HTTP Error 429: Too Many Requests',
                  'Coinalyze: limit zapytań (HTTP 429, Retry-After 30)', 'EODHD: HTTP Error 402: Payment Required'):
            self.assertIn('limit darmowego planu', r(e), e)
        for e in ('TWSE: timed out', 'trendy: KeyError x', 'CM: 401 dni historii', 'HTTP Error 500: Internal Server Error'):
            self.assertEqual(r(e), '', e)

    def test_raport_i_wpiecie(self):
        k = self.k
        with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'), encoding='utf-8') as f:
            src = f.read()
        self.assertIn("R['uwagi'].append('błąd zbieracza: ' + str(e)[:160] + awaria_rodzaj(e))", src)
        self.assertIn("aw = awarie_ocena(m)", src)
        R = {'at': '2026-10-06T06:20:00+00:00', 'wynik': 'OK', 'strona': {'ok': True, 'http': 200, 'ms': 500}, 'meta': {'at': '2026-10-06T06:13:00+00:00', 'wiek_min': 7,
             'zrodla': 76, 'bez_odpowiedzi': [], 'errors': [], 'notes': []}, 'pliki': {}, 'actions': {}, 'swiezosc': [], 'uwagi': [], 'bledy': []}
        self.assertNotIn('Awarie części automatu', k.raport_md(R), 'zbieracz sprzed v207 — bez linii')
        R['awarie'] = {'trwa': [], 'naprawione': [], 'uwagi': [], 'bledy': []}
        self.assertIn('- Awarie części automatu (24 h): brak.', k.raport_md(R))
        R['awarie'] = {'trwa': [{'czesc': 'tic', 'od': '2026-10-06T01:00:00+00:00', 'ost': '2026-10-06T06:10:00+00:00', 'n': 30, 'do': None, 'h': 5.3}],
                       'naprawione': [{'czesc': 'fred', 'od': '2026-10-05T22:00:00+00:00', 'ost': '2026-10-06T00:00:00+00:00', 'n': 13, 'do': '2026-10-06T00:10:00+00:00', 'h': 2.2}],
                       'uwagi': ['x'], 'bledy': []}
        md = k.raport_md(R)
        self.assertIn('- Awarie części automatu — trwają: tic od 06.10.2026, 03:00 (5 godz., nieudanych przebiegów: 30) ⚠️.', md)
        self.assertIn('- Naprawiły się same (24 h): fred 06.10.2026, 00:00 – 06.10.2026, 02:10 (2 godz., nieudanych przebiegów: 13) ℹ️.', md)
        self.assertIn('# Kontrola strony — 06.10.2026, 08:20 (czas polski)', md); self.assertIn('**Wynik: OK**', md)
        R['awarie']['trwa'][0]['h'] = 1.5
        self.assertIn('tic od 06.10.2026, 03:00 (1 godz., nieudanych przebiegów: 30) ℹ️.', k.raport_md(R), 'krótka seria — informacja')
        R['awarie']['trwa'][0]['h'] = 50.0
        self.assertIn('(2 dni 2 godz., nieudanych przebiegów: 30) ⚠️.', k.raport_md(R), 'v461: awaria części dłuższa niż doba = ⚠️ (❌ tylko przy awarii strony)')

    def test_kontrola_calosc_z_awariami(self):
        """Cała kontrola na zaślepionej sieci: meta.json z polem awarie — uwaga i błąd trafiają do wyniku, dopisek przy błędzie klucza."""
        k = self.k
        NOW = datetime.datetime(2026, 10, 6, 6, 20, tzinfo=datetime.timezone.utc)
        meta = {'at': (NOW - datetime.timedelta(minutes=7)).isoformat(), 'ok': {'tic': False, 'oecd': False}, 'notes': [],
                'errors': ['EODHD — klucz odrzucony albo plan bez indeksów (każda próba: HTTP 401/403)'],
                'awarie': {'tic': {'od': (NOW - datetime.timedelta(hours=5)).isoformat(), 'ost': (NOW - datetime.timedelta(minutes=7)).isoformat(), 'n': 30, 'do': None},
                           'oecd': {'od': (NOW - datetime.timedelta(hours=60)).isoformat(), 'ost': (NOW - datetime.timedelta(minutes=7)).isoformat(), 'n': 350, 'do': None}}}

        class Resp:
            def __init__(self, b):
                self.b, self.status = b, 200

            def read(self):
                return self.b

            def __enter__(self):
                return self

            def __exit__(self, *a):
                return False

        def urlopen(req, timeout=None):
            url = req.full_url
            if '/data/meta.json?' in url:
                return Resp(json.dumps(meta).encode())
            raise k.urllib.error.URLError('brak sieci w teście')
        import tempfile
        d = tempfile.mkdtemp(prefix='k207-')
        with mock.patch.object(k, 'NOW', NOW), mock.patch.object(k, 'OUT_DIR', d), mock.patch.object(k, 'ARCH_DIR', os.path.join(d, 'brak')), \
                mock.patch.object(k.time, 'sleep', lambda s: None), mock.patch.object(k.urllib.request, 'urlopen', urlopen):
            R = k.kontrola()
        self.assertEqual(R['wynik'], 'BŁĄD')
        self.assertTrue(any('„oecd” nie działa od 03.10.2026, 20:20 (2 dni 11 godz.' in b and 'napraw część oecd' in b for b in R['zewnetrzne']), R['zewnetrzne'])
        self.assertEqual([b for b in R['bledy'] if 'oecd' in b], [], 'v461: awaria źródła nie jest BŁĘDEM; BŁĄD tylko z braku strony w tym teście')
        self.assertTrue(any('„tic” nie działa od 06.10.2026, 03:20 (4 godz.' in u for u in R['uwagi']), 'v211: do ostatniego przebiegu (7 min przed kontrolą)')
        self.assertTrue(any(u.startswith('błąd zbieracza: EODHD') and 'odrzucony klucz' in u for u in R['uwagi']), R['uwagi'])
        md = k.raport_md(R)
        self.assertIn('- Awarie części automatu — trwają: oecd od 03.10.2026, 20:20 (2 dni 11 godz., nieudanych przebiegów: 350) ⚠️; tic od 06.10.2026, 03:20 (4 godz., nieudanych przebiegów: 30) ⚠️.', md)


# ===================== v208: TRENDY — POSTĘP NAUKI SYGNAŁÓW (pg w dziennikach) =====================
class PostepNaukiV208(unittest.TestCase):
    """v208: pole pg dzienników — dni z sygnałem każdej linii (te same pary i granica dojrzałości co punkty kontrolne), najbliższy punkt kontrolny
    bez oceny, szacunek terminu od 10 dni z sygnałem i 2 tygodni dziennika."""

    def test_pg_liczenie_i_szacunek(self):
        d = lambda s: datetime.date.fromisoformat(s)
        L = {'all': [('2026-09-28', 1, 'BTC', 1), ('2026-09-28', 0, 'ETH', -1), ('2026-09-29', 1, 'BTC', 1)], 'p': [], 'e': [('2026-09-30', 1, 'X', 1)]}
        names = [('p', 'p'), ('e', 'e'), ('all', 'all')]
        LA = dict(L, all=L['all'] + [('2026-10-03', 1, 'BTC', 1)])
        pg = zd._td_pg(L, LA, names, (100, 200, 400), {}, '2026-09-28', d('2026-10-06'), 5)
        self.assertEqual(pg, {'do': '2026-10-01', 'l': {'p': [0, 100, None, 0], 'e': [1, 100, None, 1], 'all': [3, 100, None, 2]}},
                         'dni bez powtórzeń, także młodsze niż 5 dni (03.10); za mało na szacunek')
        self.assertEqual(zd._td_pg(L, None, names, (100,), {}, '2026-09-28', d('2026-10-06'), 5)['l']['all'][0], 2, 'bez par „wszystkie” — dojrzałe')
        L2 = {'all': [('2026-09-%02d' % (1 + i), 1, 'BTC', 1) for i in range(20)]}
        pg = zd._td_pg(L2, L2, [('all', 'all')], (100, 200, 400), {}, '2026-09-01', d('2026-09-25'), 5)
        self.assertEqual(pg['l']['all'], [20, 100, '2026-12-14', 20], '20 dni z sygnałem w 20 dniach: 80 dni + 5 dojrzewania od granicy 20.09 → 14.12 (tempo n/dni)')
        cp = {'all': [[100, 60, 100, 50.0, 60.0, 60.0, 40.0, 70.0, 'none', '2026-12-01', 'x']]}
        self.assertEqual(zd._td_pg(L2, L2, [('all', 'all')], (100, 200, 400), cp, '2026-09-01', d('2026-09-25'), 5)['l']['all'][1], 200, 'po zapisanej ocenie — następny punkt')
        cp['all'] += [[200] + [0] * 10, [400] + [0] * 10]
        self.assertEqual(zd._td_pg(L2, L2, [('all', 'all')], (100, 200, 400), cp, '2026-09-01', d('2026-09-25'), 5)['l']['all'], [20, None, None, 20], 'wszystkie zapisane')
        pg = zd._td_pg(L2, L2, [('all', 'all')], (100, 200, 400), {}, '2026-09-15', d('2026-09-25'), 5)
        self.assertEqual(pg['l']['all'][2], None, 'dziennik krótszy niż 2 tygodnie — bez szacunku')
        self.assertEqual(zd._td_pg(None, None, [('x', 'x')], (100,), None, '2026-10-05', d('2026-10-06'), 4), {'do': '2026-10-02', 'l': {'x': [0, 100, None, 0]}})
        self.assertEqual((zd.TD_PG_EST_N, zd.TD_PG_EST_D), (10, 14))

    def test_dzienniki_maja_pg_zgodne_z_punktami_kontrolnymi(self):
        U = datetime.timezone.utc
        rows = []
        for i in range(40):
            day = (datetime.date(2026, 9, 28) + datetime.timedelta(days=i)).isoformat()
            rows.append([day, 'BTC', 2, 'obs', 'p+t+', '%sT06:30:00Z' % day, 0.5])
            rows.append([day, 'ETH', 0, 'quiet', 'p0', '%sT06:30:00Z' % day, -0.2])
        log = {'v': zd.TD_VC2, 'since': zd.TD_SINCE_CR2, 'rows': rows, 'cp': {}}
        out = zd._td_cr_log(log, [], [], datetime.datetime(2026, 11, 7, 12, 0, tzinfo=U))
        self.assertEqual(out['pg']['do'], '2026-11-02')
        self.assertEqual(out['pg']['l']['all'][:2], [40, 100], '40 dni z sygnałem i wynikiem (28.09–06.11), w tym 36 dojrzałych (do 02.11)')
        self.assertEqual(out['pg']['l']['all'][2], '2027-01-10', 'szacunek z dojrzałych: 36 w 36 dniach — 64 dni dalej + 5 dojrzewania')
        self.assertEqual(sorted(out['pg']['l']), sorted(k for _, k in zd.TD_RULES_CR2), 'wszystkie 7 linii')
        self.assertEqual(out['pg']['l']['e'], [0, 100, None, 0], 'linia bez sygnału — 0')
        w = {'v': zd.TD_VW2, 'since': zd.TD_SINCE_W2, 'rows': [], 'cp': {}}
        ow = zd._tdw_log(w, [], [], datetime.datetime(2026, 10, 6, 12, 0, tzinfo=U))
        self.assertEqual(ow['pg'], {'do': '2026-10-02', 'l': {k[0] + '.' + k[1]: [0, 100, None, 0] for k in zd.TD_RULES_W2}}, 'świat: nazwy jak w cp, start 05.10')
        self.assertTrue(zd._td_cr_valid(out) and zd._tdw_valid(ow), 'dzienniki z pg nadal poprawne')


# ===================== v209: KONTROLA — PODAŻ STABLECOINÓW I RENTOWNOŚĆ 10L USA (porównania krzyżowe) =====================
class KontrolaPorownaniaV209(unittest.TestCase):
    """v209: stablecoiny — DefiLlama vs CoinMarketCap z plików strony, odchylenie od mediany (kolumna stab_gap_pct); 10L USA — plik strony vs H.15
    z tych samych dni; brak FRED = informacja, nie uwaga. Liczby z 06.10."""

    def setUp(self):
        import importlib.util, tempfile
        spec = importlib.util.spec_from_file_location('kontrola_v209', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        self.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(self.k)
        self.tmp = tempfile.mkdtemp(prefix='k209-')

    KR = {'at': '2026-10-06T04:08:00+00:00', 'stabh': {'asof': '2026-10-06', 'cur': 312656934980}}
    CMC = {'at': '2026-10-06T04:30:00+00:00', 'stable_mcap': 285470694106.04}

    def test_stab_porownanie(self):
        k = self.k
        s = k.stab_porownanie(self.KR, self.CMC)
        self.assertEqual(s, {'a': 312656934980.0, 'b': 285470694106.04, 'roznica_pct': 9.523, 'odstep_h': 0.4, 'data': '2026-10-06'})
        self.assertIsNone(k.stab_porownanie({'stabh': {}}, self.CMC)); self.assertIsNone(k.stab_porownanie(self.KR, {'stable_mcap': 0}))
        self.assertIsNone(k.stab_porownanie(None, None)); self.assertIsNone(k.stab_porownanie({'stabh': {'cur': True}}, self.CMC))
        s = k.stab_porownanie(dict(self.KR, at='2026-10-05T20:00:00+00:00'), self.CMC)
        self.assertEqual((s['roznica_pct'], s['odstep_h']), (None, 8.5), 'pliki z różnych chwil — bez porównania')
        self.assertIsNone(k.stab_porownanie(dict(self.KR, at='zły'), self.CMC)['roznica_pct'])
        self.assertIsNone(k.stab_porownanie(dict(self.KR, at='2026-10-06T04:08:00'), self.CMC)['roznica_pct'], 'czas bez strefy — bez porównania')
        rows = {'2026-09-%02d' % d: {'stab': 9.4 + (d % 3) * 0.05} for d in range(20, 30)}
        self.assertEqual(k.mediana_ocena(rows, 'stab', 9.52, '2026-10-06', k.STAB_ZOLTE, None)[0], '✅')
        self.assertEqual(k.mediana_ocena(rows, 'stab', 12.0, '2026-10-06', k.STAB_ZOLTE, None)[0], '⚠️')
        self.assertEqual(k.mediana_ocena({}, 'stab', 9.52, '2026-10-06', k.STAB_ZOLTE, None)[0], 'ℹ️', 'bez historii — informacja')
        p = os.path.join(self.tmp, 'zgodnosc.csv')
        k.zgodnosc_zapisz(p, {'2026-10-05': {'cap': 4.3, 'tga': 3.0}, '2026-10-06': {'cap': 4.27, 'stab': 9.523}})
        with open(p, encoding='utf-8') as f:
            self.assertEqual(f.read(), 'date,cap_gap_pct,tga_gap_pct,stab_gap_pct,cmc_gap_pct\n2026-10-05,4.300,3.000,,\n2026-10-06,4.270,,9.523,\n')   # v277: + cmc
        self.assertEqual(k.zgodnosc_csv(p), {'2026-10-05': {'cap': 4.3, 'tga': 3.0}, '2026-10-06': {'cap': 4.27, 'stab': 9.523}})
        with open(p, 'w', encoding='utf-8') as f:
            f.write('date,cap_gap_pct,tga_gap_pct\n2026-10-05,4.300,3.000\n')
        self.assertEqual(k.zgodnosc_csv(p), {'2026-10-05': {'cap': 4.3, 'tga': 3.0}}, 'stary plik (3 kolumny) czytany jak dotąd')

    def test_ust(self):
        k = self.k
        csv_txt = 'observation_date,DGS10\n2026-09-21,4.96\n2026-09-24,5.18\n2026-09-25,5.17\n2026-09-28,5.24\n2026-09-29,.\n2026-09-30,5.29\nzły,1\n2026-10-01,x\n2026-10-02,5.28\n'
        F = k.ust_fred_csv(csv_txt)
        self.assertEqual(F, {'2026-09-21': 4.96, '2026-09-24': 5.18, '2026-09-25': 5.17, '2026-09-28': 5.24, '2026-09-30': 5.29, '2026-10-02': 5.28})
        self.assertEqual(k.ust_fred_csv(None), {}); self.assertEqual(k.ust_fred_csv('<html>'), {})
        ust = [['2026-09-%02d' % d, 5.0] for d in range(1, 20)] + [['2026-09-24', 5.18], ['2026-09-25', 5.17], ['2026-09-28', 5.24], ['2026-09-29', 5.26],
                                                                    ['2026-09-30', 5.29], ['2026-10-01', 5.24], ['2026-10-02', 5.28], ['2026-10-05', 5.31]]
        u = k.ust_porownanie({'ust': ust}, F)
        self.assertEqual(u, {'porownane': 5, 'do': '2026-10-02', 'roznice': []}, '06.10: wspólne daty równe co do setnej; 05.10 jeszcze bez H.15')
        u = k.ust_porownanie({'ust': ust[:-2] + [['2026-10-02', 5.31], ['2026-10-05', 5.31]]}, F)
        self.assertEqual(u['roznice'], [['2026-10-02', 5.31, 5.28, 0.03]])
        self.assertEqual(k.ust_porownanie({'ust': ust[:-2] + [['2026-10-02', 5.30]]}, F)['roznice'], [], 'dokładnie próg 0,02 — bez uwagi')
        self.assertIsNone(k.ust_porownanie({}, F)); self.assertIsNone(k.ust_porownanie({'ust': ust}, None))
        self.assertEqual(k.ust_porownanie({'ust': [['x', True], 'y', ['2026-10-02', 5.28]]}, F), {'porownane': 1, 'do': '2026-10-02', 'roznice': []})
        self.assertEqual((k.UST_PROG, k.UST_DNI, k.STAB_ZOLTE, k.STAB_MAX_H), (0.02, 10, 2.0, 6.0))
        self.assertTrue(k.UST_FRED.startswith('https://fred.stlouisfed.org/graph/fredgraph.csv?id=DGS10&cosd='))

    def test_raport(self):
        k = self.k
        R = {'at': '2026-10-06T06:20:00+00:00', 'wynik': 'OK', 'strona': {'ok': True, 'http': 200, 'ms': 500}, 'meta': {'at': '2026-10-06T06:13:00+00:00', 'wiek_min': 7,
             'zrodla': 76, 'bez_odpowiedzi': [], 'errors': [], 'notes': []}, 'pliki': {}, 'actions': {}, 'swiezosc': [], 'uwagi': [], 'bledy': [],
             'zgodnosc': {'stablecoiny': {'a': 312656934980.0, 'b': 285470694106.04, 'roznica_pct': 9.523, 'odstep_h': 0.4, 'data': '2026-10-06', 'status': 'ℹ️',
                                          'mediana_pct': None, 'dni': 0, 'opis': 'historia 0 z 7 dni — bez oceny'},
                          'ust10': {'porownane': 5, 'do': '2026-10-02', 'roznice': []}}}
        md = k.raport_md(R)
        self.assertIn('- Podaż stablecoinów, dwa źródła: 312.7 vs 285.5 mld USD — różnica dziś +9.52% — ℹ️ historia 0 z 7 dni — bez oceny.', md)   # v245c
        self.assertIn('- Rentowność 10L USA (Skarb USA vs H.15, te same dni): porównane 5 dat (do 2026-10-02), różnice > 0.02 pkt proc.: 0 ✅.', md)
        R['zgodnosc']['stablecoiny'].update(roznica_pct=None, odstep_h=8.5)
        self.assertIn('- Podaż stablecoinów, dwa źródła: pliki pobrane w odstępie 8.5 h — bez porównania ℹ️.', k.raport_md(R))
        R['zgodnosc']['ust10'] = {'porownane': 5, 'do': '2026-10-02', 'roznice': [['2026-10-02', 5.31, 5.28, 0.03]]}
        self.assertIn('różnice > 0.02 pkt proc.: 1 ⚠️ — 2026-10-02: 5.31 vs 5.28.', k.raport_md(R))
        R['zgodnosc']['ust10'] = {'brak': 'HTTP 503'}
        self.assertIn('- Rentowność 10L USA (Skarb USA vs H.15): brak odczytu H.15 (HTTP 503) ℹ️.', k.raport_md(R))
        R['zgodnosc']['ust10'] = {'porownane': 0, 'do': None, 'roznice': []}
        self.assertIn('- Rentowność 10L USA (Skarb USA vs H.15): brak wspólnych dat ℹ️.', k.raport_md(R))
        del R['zgodnosc']['stablecoiny'], R['zgodnosc']['ust10']
        md = k.raport_md(R)
        self.assertNotIn('Podaż stablecoinów', md); self.assertNotIn('Rentowność 10L', md)

    def test_kontrola_calosc(self):
        """Cała kontrola na zaślepionej sieci: pliki strony z liczbami stablecoinów i rentowności; FRED odpowiada albo nie — brak FRED bez uwagi."""
        import io, tempfile
        k = self.k
        NOW = datetime.datetime(2026, 10, 6, 6, 20, tzinfo=datetime.timezone.utc)
        fred = {'ok': True}
        csv_txt = 'observation_date,DGS10\n2026-10-01,5.24\n2026-10-02,5.28\n'
        files = {'krypto': self.KR, 'cmc': self.CMC, 'rynki': {'at': NOW.isoformat(), 'ust': [['2026-10-01', 5.24], ['2026-10-02', 5.33], ['2026-10-05', 5.31]]},
                 'meta': {'at': (NOW - datetime.timedelta(minutes=7)).isoformat(), 'ok': {}, 'errors': [], 'notes': []}}

        class Resp:
            def __init__(self, b):
                self.b, self.status = b, 200

            def read(self):
                return self.b

            def __enter__(self):
                return self

            def __exit__(self, *a):
                return False
        calls = []

        def urlopen(req, timeout=None):
            url = req.full_url; calls.append(url)
            if url.startswith('https://fred.stlouisfed.org/'):
                if fred['ok']:
                    return Resp(csv_txt.encode())
                raise k.urllib.error.URLError('HTTP 503')
            for n, j in files.items():
                if f'/data/{n}.json?' in url:
                    return Resp(json.dumps(j).encode())
            raise k.urllib.error.URLError('brak sieci w teście')

        def run():
            d = tempfile.mkdtemp(prefix='k209c-', dir=self.tmp)
            with mock.patch.object(k, 'NOW', NOW), mock.patch.object(k, 'OUT_DIR', d), mock.patch.object(k, 'ARCH_DIR', os.path.join(d, 'brak')), \
                    mock.patch.object(k.time, 'sleep', lambda s: None), mock.patch.object(k.urllib.request, 'urlopen', urlopen):
                R = k.kontrola()
            with open(os.path.join(d, 'zgodnosc.csv'), encoding='utf-8') as f:
                return R, f.read()
        R, csv_out = run()
        self.assertEqual(R['zgodnosc']['stablecoiny']['roznica_pct'], 9.523); self.assertEqual(R['zgodnosc']['stablecoiny']['status'], 'ℹ️')
        self.assertIn(',9.523,\n', csv_out, 'różnica zapisana do historii')   # v277: + pusta kolumna cmc
        self.assertEqual(R['zgodnosc']['ust10'], {'porownane': 2, 'do': '2026-10-02', 'roznice': [['2026-10-02', 5.33, 5.28, 0.05]], 'zrodlo': 'FRED'}, 'v211: wydawca niedostępny — zapas')
        self.assertTrue(any(u.startswith('rentowność 10L USA: plik strony vs H.15 różnią się') and '2026-10-02: 5.33 vs 5.28' in u for u in R['uwagi']), R['uwagi'])
        self.assertTrue(any('fredgraph.csv?id=DGS10&cosd=2026-09-15' in c for c in calls), calls)
        self.assertIn('cmc', k.PLIKI); self.assertEqual(k.LIMIT_MIN['cmc'], 90, 'cmc.json co przebieg — wiek jak meta'); self.assertEqual(R['pliki']['cmc']['http'], 200)
        fred['ok'] = False
        R, _ = run()
        self.assertEqual(R['zgodnosc']['ust10'], {'brak': 'Fed: <urlopen error brak sieci w teście>; FRED: <urlopen error HTTP 503>'})
        self.assertFalse(any('10L' in u or 'H.15' in u for u in R['uwagi']), 'brak FRED — bez uwagi')


# ===================== v211: POPRAWKI PO PRZEGLĄDZIE v207–v208 + H.15 U WYDAWCY =====================
class PoPrzegladzieV211(unittest.TestCase):
    """v211: tylko True kończy serię awarii ('cached' = czeka na ponowienie); część nieobecna > 6 h — „zniknęła”, nie BŁĄD; poprzednia seria
    zostaje (prev); czas serii do ostatniego przebiegu; części „czeka na publikację” tylko informacją; „(24 h): brak” i pamięć od; dopisek z pełnej
    treści błędu; pg z dniami dojrzałymi; H.15 u wydawcy z zapasem FRED."""

    def setUp(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('kontrola_v211', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        self.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(self.k)

    @staticmethod
    def _t(h):
        return (datetime.datetime(2026, 10, 6, 4, 0, tzinfo=datetime.timezone.utc) + datetime.timedelta(hours=h)).isoformat()

    def test_trwala_awaria_z_cached_nie_jest_naprawa(self):
        """Wzór części ze stanem z pliku (stres, rwa): False przy próbie, 'cached' między próbami — 3 doby; seria rośnie, BŁĄD po 48 h."""
        t, a = self._t, {}
        for h in range(0, 72):
            a = zd.awarie(a, {'stres': False if h % 6 == 0 else 'cached'}, t(h))
        self.assertEqual((a['stres']['od'], a['stres']['n'], a['stres']['do']), (t(0), 12, None))
        Z = self.k.awarie_ocena({'at': t(71), 'awarie': a}, datetime.datetime(2026, 10, 9, 4, 0, tzinfo=datetime.timezone.utc))
        self.assertEqual(len(Z['bledy']), 1); self.assertIn('„stres” nie działa od 06.10.2026, 06:00 (2 dni 23 godz.', Z['bledy'][0]); self.assertEqual(Z['naprawione'], [])

    def test_znikniecie_i_poprzednia_seria(self):
        t = self._t
        a = zd.awarie({}, {'fed': False}, t(0)); a = zd.awarie(a, {'fed': False}, t(2))
        self.assertIsNone(zd.awarie(a, {'x': True}, t(8))['fed']['do'], 'dokładnie 6 h nieobecności — jeszcze trwa')
        a = zd.awarie(a, {'x': True}, t(8.5))
        self.assertEqual(a['fed'], {'od': t(0), 'ost': t(2), 'n': 2, 'do': t(8.5), 'zn': True}, 'wyłączona część: ponad 6 h nieobecności — zamknięta jako „zniknęła”')
        Z = self.k.awarie_ocena({'at': t(9), 'awarie': a}, datetime.datetime(2026, 10, 6, 13, 30, tzinfo=datetime.timezone.utc))
        self.assertEqual(([x['czesc'] for x in Z['zniknely']], Z['bledy'], Z['uwagi'], Z['naprawione']), (['fed'], [], [], []), 'bez BŁĘDU i bez „naprawy”')
        md = self.k.raport_md({'at': t(9.5), 'wynik': 'OK', 'meta': {}, 'awarie': Z, 'uwagi': [], 'bledy': []})
        self.assertIn('- Zniknęły z przebiegów (24 h; część wyłączona albo zmieniona — nie awaria): fed — ostatnia nieudana próba 06.10.2026, 08:00 (nieudanych przebiegów: 2) ℹ️.', md)
        b = zd.awarie(a, {'fed': False}, t(10))
        self.assertNotIn('prev', b['fed'], 'seria „zniknęła” nie udaje naprawionej')
        # noc: 22:00–02:00 awaria, naprawa; rano jedna awaria — nocna zostaje w prev i w raporcie
        n0 = {'cftc': {'od': t(-6), 'ost': t(-2.2), 'n': 24, 'do': t(-2)}}
        b = zd.awarie(n0, {'cftc': False}, t(-1))
        self.assertEqual(b['cftc']['prev'], [t(-6), t(-2), 24])
        b = zd.awarie(b, {'cftc': True}, t(-0.8))
        Z = self.k.awarie_ocena({'at': t(0.3), 'awarie': b}, datetime.datetime(2026, 10, 6, 4, 27, tzinfo=datetime.timezone.utc))
        self.assertEqual([(x['od'], x['do'], x['n']) for x in Z['naprawione']], [(t(-6), t(-2), 24), (t(-1), t(-0.8), 1)], 'obie serie w „naprawionych”')
        c = zd.awarie(b, {'cftc': False}, t(0))
        self.assertEqual(c['cftc']['prev'], [t(-6), t(-2), 24], 'zostaje dłuższa z dwóch zamkniętych')
        self.assertNotIn('prev', zd.awarie(c, {'cftc': False}, t(46.1))['cftc'], 'prev znika 48 h po swoim końcu')
        zle = {'q': {'od': t(-3), 'ost': t(-2), 'n': 1, 'do': None, 'prev': [t(-1), t(-0.5), 1]}, 'r': {'od': t(-3), 'ost': t(-2), 'n': 1, 'do': None, 'prev': ['x', t(-4), 1]}}
        o = zd.awarie(zle, {'q': False, 'r': False}, t(0))
        self.assertTrue('prev' not in o['q'] and 'prev' not in o['r'], 'zła albo późniejsza od serii „prev” pominięta')

    def test_czeka_na_publikacje_tylko_informacja(self):
        t = self._t
        aw = {k: {'od': t(-100), 'ost': t(-0.1), 'n': 500, 'do': None} for k in ('jpx', 'ici', 'wycena_bg')}
        Z = self.k.awarie_ocena({'at': t(0), 'awarie': aw}, datetime.datetime(2026, 10, 6, 4, 10, tzinfo=datetime.timezone.utc))
