# ===================== v216: TRENDY — REGUŁY „W CIENIU” (rejestracja z góry 06.10) =====================
class RegulyWCieniuV216(unittest.TestCase):
    """v216: kandydaci z głosów składników (zgodność dwóch albo |N| ≥ r), te same wiersze i punkty kontrolne co reguły główne, surowszy próg
    (Bonferroni 11 / 10 linii × 3 oceny); pola cs i pgs dziennika; reguły główne bez zmian."""

    def test_glosy_i_pary_krypto(self):
        G = zd._td_sh_glos
        self.assertEqual((G({'p': 1, 't': 1}, 1, ('p', 't')), G({'p': 1, 't': -1}, 0, ('p', 't')), G({'p': 0, 't': 1}, 1, ('p', 't'))), (1, 0, 0))
        self.assertEqual((G({}, 3, 3), G({}, -3, 3), G({}, 2, 3), G({}, True, 2), G({}, None, 2)), (1, -1, 0, 0, 0))
        rows = [['2026-09-28', 'BTC', 3, 'obs', 'p+t+e0s+h0', 'x', 0.5], ['2026-09-28', 'ETH', -2, 'obs', 'p-t0e-s0h0', 'x', -0.3],
                ['2026-09-29', 'BTC', 1, 'obs', 'p+t+e-s-h0', 'x', -0.2], ['2026-09-29', 'SOL', 0, 'x', 'p+t+', 'x', 0], ['2026-09-30', 'ADA', 2, 'obs', 'p+h+', 'x', None]]
        L = zd._td_sh_pairs_cr({'rows': rows}, '2026-09-28')
        self.assertEqual(L['pt'], [('2026-09-28', 1, 'BTC', 1), ('2026-09-29', 0, 'BTC', 1)], 'p i t zgodne; y = 0 i brak y pominięte')
        self.assertEqual(L['es'], [('2026-09-29', 1, 'BTC', -1)], 'e i s zgodne w dół, cena spadła — trafienie')
        self.assertEqual(L['n3'], [('2026-09-28', 1, 'BTC', 1)]); self.assertEqual(L['ph'], [])
        self.assertEqual([k for k, _ in zd.TD_SH_CR], ['pt', 'ph', 'es', 'n3']); self.assertEqual([k for k, _, _ in zd.TD_SH_W], ['eq.pf', 'eq.fo'])   # v221: eq.n2 usunięty

    def test_prog_surowszy_i_dziennik(self):
        self.assertGreater(zd.TD_CR_ZLS, zd.TD_CR_ZL); self.assertGreater(zd.TD_W_ZLS, zd.TD_W_ZL)
        self.assertAlmostEqual(zd.TD_CR_ZLS, statistics.NormalDist().inv_cdf(1 - 0.025 / 33), places=6)
        self.assertAlmostEqual(zd.TD_W_ZLS, statistics.NormalDist().inv_cdf(1 - 0.025 / 27), places=6)   # v221: 9 linii × 3
        U = datetime.timezone.utc
        rows = []
        for i in range(110):
            day = (datetime.date(2026, 9, 28) + datetime.timedelta(days=i)).isoformat()
            rows.append([day, 'BTC', 3, 'obs', 'p+t+e0s+h0', '%sT06:30:00Z' % day, 0.5 if i % 4 else -0.4])
            rows.append([day, 'ETH', 0, 'quiet', 'p0', '%sT06:30:00Z' % day, -0.1])
        log = {'v': zd.TD_VC2, 'since': zd.TD_SINCE_CR2, 'rows': rows, 'cp': {}}
        out = zd._td_cr_log(log, [], [], datetime.datetime(2027, 1, 20, 12, 0, tzinfo=U))
        self.assertEqual(sorted(out['cs']), ['n3', 'pt'], 'kandydaci ze 100 dniami z sygnałem — ocena zapisana')
        c = out['cs']['pt'][0]
        self.assertEqual((c[0], c[1], c[2]), (100, 75, 100)); self.assertEqual(c[9], '2027-01-05')
        self.assertEqual(out['cp']['all'][0][:3], [100, 75, 100], 'reguła główna — ta sama liczba trafień')
        self.assertLess(c[6], out['cp']['all'][0][6], 'surowszy próg — szerszy zakres (dolna granica niżej)')
        self.assertEqual(out['pgs']['l']['pt'][:2], [110, 200], '110 dni z sygnałem; ocena 100 zapisana — następny punkt 200')
        self.assertEqual(out['pgs']['l']['es'], [0, 100, None, 0])
        again = zd._td_cr_log(dict(out, rows=out['rows'] + []), [], [], datetime.datetime(2027, 1, 21, 12, 0, tzinfo=U))
        self.assertEqual(again['cs']['pt'][0], c, 'ocena zamrożona — nie liczona od nowa')
        w = zd._tdw_log({'v': zd.TD_VW2, 'since': zd.TD_SINCE_W2, 'rows': [], 'cp': {}}, [], [], datetime.datetime(2026, 10, 6, 12, 0, tzinfo=U))
        self.assertEqual((w.get('cs'), sorted(w['pgs']['l'])), ({}, ['eq.fo', 'eq.pf']))   # v221: eq.n2 usunięty
        self.assertTrue(zd._td_cr_valid(out) and zd._tdw_valid(w))


# ===================== v217: FUNDUSZE ETF — ODRZUCANIE WIERSZY Z BŁĘDEM PLIKU ŹRÓDŁA =====================
class FunduszeCzyszczenieV217(unittest.TestCase):
    """v217: wiersz z aktywami (NAV × jednostki) ponad 2× od mediany sąsiednich dni odrzucony (EWZ 05.10: NAV 0,001328); podział jednostek
    zostaje; krótka historia bez oceny; fundusz iShares z odrzuconym świeżym dniem — uzupełnienie pełnym plikiem."""

    H = [['2026-09-%02d' % d, 36.0 + d / 10, 232600000] for d in range(14, 31) if datetime.date(2026, 9, d).weekday() < 5]

    def test_ewz_z_0510(self):
        h = self.H + [['2026-10-01', 37.119924, 233800000], ['2026-10-02', 38.109913, 235300000], ['2026-10-05', 0.001328, 238426920]]
        keep, bad = zd._fund_clean(h)
        self.assertEqual(bad, ['2026-10-05']); self.assertEqual(keep[-1][0], '2026-10-02')
        h2 = h + [['2026-10-06', 42.9, 238426920]]
        keep, bad = zd._fund_clean(h2)
        self.assertEqual(bad, ['2026-10-05'], 'wiersz w środku też odrzucony; następny dzień (prawdziwy NAV) zostaje'); self.assertEqual(keep[-1][0], '2026-10-06')

    def test_podzial_i_krotka_historia(self):
        h = self.H + [['2026-10-01', 18.6, 465200000], ['2026-10-02', 18.7, 466000000]]   # podział 2:1 — aktywa bez zmian
        self.assertEqual(zd._fund_clean(h)[1], [], 'podział jednostek zostaje')
        self.assertEqual(zd._fund_clean([['2026-10-01', 1.0, 10], ['2026-10-02', 1000.0, 10]]), ([['2026-10-01', 1.0, 10], ['2026-10-02', 1000.0, 10]], []), 'mniej niż 3 sąsiednie dni — bez oceny')
        self.assertEqual(zd._fund_clean(None), ([], [])); self.assertEqual(zd._fund_clean([['x', 1]]), ([], []))
        big = self.H + [['2026-10-01', 37.2 * 2.2, 232600000]]
        self.assertEqual(zd._fund_clean(big)[1], ['2026-10-01'], 'aktywa ×2,2 w dobę — błąd pliku'); self.assertEqual(zd._fund_clean(self.H + [['2026-10-01', 37.2 * 1.9, 232600000]])[1], [])
        self.assertEqual((zd.FUND_TNA_X, zd.FUND_TNA_OKNO), (2.0, 10))

    def test_wpiecie(self):
        import inspect
        src = inspect.getsource(zd.build_fundusze)
        self.assertIn('bad = _fund_clean(h)[1]', src); self.assertIn("bad = _fund_clean(out['f'][t]['h'])[1]", src)   # v221: wykrycie, historia surowa
        self.assertIn("p['bf_need'] = True", src.split('bad = _fund_clean(h)[1]')[1][:700], 'świeży zły dzień iShares — próba pełnym plikiem')


# ===================== v218: KONTROLA — WIEK LIST PORTFELI GIEŁD Z RAPORTÓW MIESIĘCZNYCH =====================
class KontrolaListyPortfeliV218(unittest.TestCase):
    """v218: listy OKX, Bybit, KuCoin (wieloryby.json → gieldy) starsze niż 45 dni — uwaga z tym, co zrobić; wiersz w raporcie."""

    def setUp(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('kontrola_v218', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        self.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(self.k)

    G = {'gieldy': {'Binance': {'since': '2022-11'}, 'OKX': {'since': '2026-09-08'}, 'Bybit': {'since': '2026-08-26'}, 'KuCoin': {'since': '2026-08-31'}, 'Bitfinex': {'since': '2022-11'}}}

    def test_ocena(self):
        k = self.k
        U = datetime.timezone.utc
        o = k.wh_listy_ocena(self.G, datetime.datetime(2026, 10, 6, 6, 20, tzinfo=U))
        self.assertEqual(o, {'wszystkie': [('OKX', '2026-09-08', 28), ('Bybit', '2026-08-26', 41), ('KuCoin', '2026-08-31', 36)], 'stare': []})
        o = k.wh_listy_ocena(self.G, datetime.datetime(2026, 10, 11, 6, 20, tzinfo=U))
        self.assertEqual(o['stare'], [('Bybit', '2026-08-26', 46)], 'Bybit po 45 dniach — uwaga; listy stałe (Binance, Bitfinex) bez oceny')
        self.assertIsNone(k.wh_listy_ocena(None)); self.assertIsNone(k.wh_listy_ocena({'gieldy': 'x'}))
        self.assertEqual(k.wh_listy_ocena({'gieldy': {'OKX': {'since': '2026-02-30'}, 'Bybit': 'x'}})['wszystkie'], [], 'zła data i zły wpis pominięte')
        self.assertEqual((k.WH_LISTY_MIES, k.WH_LISTY_DNI), (('OKX', 'Bybit', 'KuCoin'), 45))

    def test_raport_i_wpiecie(self):
        k = self.k
        with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'), encoding='utf-8') as f:
            src = f.read()
        self.assertIn("wl = wh_listy_ocena(files.get('wieloryby'))", src)
        R = {'at': '2026-10-11T06:20:00+00:00', 'wynik': 'UWAGA', 'meta': {}, 'uwagi': [], 'bledy': [],
             'zgodnosc': {'wh_listy': {'wszystkie': [('OKX', '2026-09-08', 33), ('Bybit', '2026-08-26', 46), ('KuCoin', '2026-08-31', 41)], 'stare': [('Bybit', '2026-08-26', 46)]}}}
        self.assertIn('- Listy portfeli giełd z raportów miesięcznych (wiek): OKX 33 dni, Bybit 46 dni ⚠️, KuCoin 41 dni.', k.raport_md(R))
        R['zgodnosc']['wh_listy'] = {'wszystkie': [('OKX', '2026-09-08', 28)], 'stare': []}
        self.assertIn('- Listy portfeli giełd z raportów miesięcznych (wiek): OKX 28 dni ✅.', k.raport_md(R))


# ===================== v219: POPRAWKI PO PRZEGLĄDZIE v213–v215 (kontrola) =====================
class PoPrzegladzieV219(unittest.TestCase):
    """v219: podpowiedź Pages tylko, gdy każda porażka bieżącej serii to publikacja Pages (osobny początek błędu); tekst o weekendach."""

    def setUp(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('kontrola_v219', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        self.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(self.k)

    def test_pages_tylko_dla_biezacej_serii(self):
        k = self.k
        U = datetime.timezone.utc
        NOW = datetime.datetime(2026, 10, 6, 6, 20, tzinfo=U)

        def r(i, m, c):
            return {'id': i, 'name': 'Strona i dane', 'status': 'completed', 'conclusion': c,
                    'run_started_at': (NOW - datetime.timedelta(minutes=m)).isoformat(), 'updated_at': (NOW - datetime.timedelta(minutes=m - 5)).isoformat()}
        tlo = [r(100 + i, 400 + 10 * i, 'success') for i in range(25)]
        PG = 'opublikuj / publikacja na GitHub Pages (zwykle chwilowa awaria po stronie GitHuba)'
        runs = [r(1, 10, 'failure'), r(2, 20, 'failure'), r(3, 30, 'success')] + tlo
        A, b, u = k.przebiegi_ocena(runs, NOW, {1: PG, 2: PG})
        self.assertTrue(b[0].startswith('automat nie działa (publikacja GitHub Pages): 2 nieudane przebiegi'), b)
        self.assertTrue(k.co_zrobic(b)[0].startswith('Ostatnie przebiegi padły na publikacji strony'))
        A, b, u = k.przebiegi_ocena(runs, NOW, {1: 'zbuduj / zbieraj dane', 2: PG})
        self.assertTrue(b[0].startswith('automat nie działa: 2 nieudane'), 'najnowsza porażka nie jest publikacją — zwykły błąd')
        self.assertTrue(k.co_zrobic(b)[0].startswith('Ostatnie przebiegi automatu kończą się błędem'))
        mix = [r(1, 10, 'failure'), r(2, 20, 'success'), r(3, 200, 'failure'), r(4, 210, 'failure')] + tlo
        A, b, u = k.przebiegi_ocena(mix, NOW, {1: 'zbuduj / zbieraj dane', 3: PG, 4: PG})
        self.assertTrue(b[0].startswith('automat nie działa: 3 nieudane'), 'stare porażki Pages + nowa porażka zbieracza — bez rady „poczekaj”')
        self.assertFalse(k.co_zrobic(b)[0].startswith('Ostatnie przebiegi padły na publikacji'))
        A, b, u = k.przebiegi_ocena(runs, NOW, {})
        self.assertTrue(b[0].startswith('automat nie działa: 2'), 'bez opisu kroków — zwykły błąd')

    def test_tekst_o_weekendach(self):
        h = self.k.co_zrobic(['TIC (miesięcznie): dane z 2026-06 — 160 d 0 h temu (próg 150 d)'])[0]
        self.assertIn('weekendy już odliczone', h); self.assertNotIn('dni bez sesji', h)


# ===================== v220: FUNDUSZE — JEDNA PRÓBA UZUPEŁNIENIA NA ODRZUCONY DZIEŃ =====================
class FunduszeBezPetliV220(unittest.TestCase):
    """v220: odrzucony świeży dzień — jedna próba uzupełnienia pełnym plikiem; ten sam dzień ponownie (pełny plik z tym samym błędem) — bez kolejnej."""

    def test_jedna_proba(self):
        """v223: próba zużyta dopiero po pobraniu pełnego pliku (_fund_bf_zapisz) — nieudane pobranie nie zamyka drogi do poprawki."""
        p = {'h': [['2026-10-02', 38.1, 235300000], ['2026-10-06', 42.9, 238426920]]}
        self.assertTrue(zd._fund_bf_odrz(p, ['2026-10-05'])); self.assertEqual((p.get('bf_odrz'), p['bf_czeka']), (None, ['2026-10-05']))
        self.assertTrue(zd._fund_bf_odrz(p, ['2026-10-05']), 'plik jeszcze nie pobrany — próba nadal przed nami')
        zd._fund_bf_zapisz(p); self.assertEqual((p['bf_odrz'], 'bf_czeka' in p), (['2026-10-05'], False))
        self.assertFalse(zd._fund_bf_odrz(p, ['2026-10-05']), 'ten sam dzień po pobraniu pliku — bez pętli')
        self.assertTrue(zd._fund_bf_odrz(p, ['2026-10-05', '2026-10-06'])); self.assertEqual(p['bf_czeka'], ['2026-10-06'])
        zd._fund_bf_zapisz(p); self.assertEqual(p['bf_odrz'], ['2026-10-05', '2026-10-06'])
        self.assertFalse(zd._fund_bf_odrz(p, ['2026-08-01']), 'dzień sprzed ponad 10 sesji — bez uzupełnienia')
        self.assertFalse(zd._fund_bf_odrz({'h': []}, ['2026-10-05'])); self.assertFalse(zd._fund_bf_odrz({'h': [['x', 1, 1]]}, ['2026-10-05']))
        q = {'h': [['2026-12-31', 1.0, 1]], 'bf_odrz': ['2026-12-%02d' % d for d in range(1, 31)]}
        self.assertTrue(zd._fund_bf_odrz(q, ['2026-12-31'])); zd._fund_bf_zapisz(q); self.assertEqual(len(q['bf_odrz']), 20, 'zapis prób — ostatnie 20 dat')

    def test_wpiecie(self):
        import inspect
        src = inspect.getsource(zd.build_fundusze)
        self.assertIn("if _fund_bf_odrz(p, bad):", src)
        self.assertNotIn("any(_bdays(_d(b), _d(p['h'][-1][0])) <= FUND_TNA_OKNO for b in bad if _d(b))", src, 'dawny warunek v217 (pętla) usunięty')


# ===================== v221: POPRAWKI PO PRZEGLĄDZIE v216–v219 =====================
class PoPrzegladzieV221(unittest.TestCase):
    """v221: historia funduszy surowa (zły wiersz przerywa łańcuch — przepływ i zwrot obu dni = brak, nie dwa dni na jednym); cena tygodniowa
    TRENDÓW bez pojedynczego złego wiersza; Pages — 5 najnowszych porażek serii; eq.n2 usunięty."""

    def test_przeplywy_nie_lacza_dwoch_dni(self):
        h = [['2026-09-29', 36.39653, 232600000], ['2026-09-30', 37.127677, 232600000], ['2026-10-01', 37.119924, 233800000],
             ['2026-10-02', 38.109913, 235300000], ['2026-10-05', 0.001328, 238426920], ['2026-10-06', 42.9, 238426920]]
        fl = zd.fund_flows(h)
        self.assertNotIn('2026-10-05', fl); self.assertNotIn('2026-10-06', fl, 'zły wiersz przerywa łańcuch — 06.10 to brak, nie przepływ dwóch dni')
        self.assertAlmostEqual(fl['2026-10-02'], (235300000 - 233800000) * 38.109913 / 1e6)
        d, px, ret = zd._td_fund_px(zd._fund_rows(h))
        self.assertEqual(ret[-2:], [None, None], 'zwroty 05.10 i 06.10 — brak')
        import inspect
        src = inspect.getsource(zd.build_fundusze)
        self.assertIn("p['h'] = h", src); self.assertIn('bad = _fund_clean(h)[1]', src); self.assertNotIn("p['h'], bad = _fund_clean(h)", src)
        self.assertIn("bad = _fund_clean(out['f'][t]['h'])[1]", src)

    def test_cena_tygodniowa_bez_zlego_wiersza(self):
        h = [['2026-09-%02d' % d, 36.0 + d / 10, 232600000] for d in range(14, 31) if datetime.date(2026, 9, d).weekday() < 5]
        h += [['2026-10-01', 37.1, 233800000], ['2026-10-02', 38.1, 235300000], ['2026-10-05', 0.001328, 238426920]]
        zd.META['notes'] = []
        keep = zd._fund_px_rows('EWZ', h)
        self.assertEqual(keep[-1][0], '2026-10-02'); self.assertEqual(len(keep), len(h) - 1)
        self.assertTrue(any(n.startswith('trendy EWZ: wiersz 2026-10-05 pominięty w cenie tygodniowej') for n in zd.META['notes']), zd.META['notes'])
        import inspect
        self.assertIn("_fund_px_rows(t, _fund_rows((fu.get(t) or {}).get('h')))", inspect.getsource(zd._tr_prices))

    def test_trwaly_skok_nadal_ucina(self):
        """v221: od pewnego dnia NAV o połowę na stałe (bez zmiany jednostek) — to nie pojedynczy zły wiersz: cena tygodniowa ucięta jak w v93."""
        days = [d for d in (datetime.date(2025, 9, 1) + datetime.timedelta(days=i) for i in range(390)) if d.weekday() < 5][-280:]
        h = [[d.isoformat(), (200.0 + 0.01 * i) * (0.5 if i >= len(days) - 10 else 1.0), 600] for i, d in enumerate(days)]
        self.assertEqual(zd._fund_clean(h)[1], [], 'trwały skok — żaden wiersz nie odstaje od sąsiadów')
        with mock.patch.object(zd, '_now_utc', return_value=datetime.datetime(2026, 9, 25, 10, 0, tzinfo=datetime.timezone.utc)):
            zd.META['notes'].clear()
            out = zd.build_trendy({'fundusze': {'f': {'XLK': {'h': h}}}})
        self.assertNotIn('fp_tech', {r['id'] for r in out['p']}); self.assertTrue(any(n.startswith('trendy XLK: skok NAV bez podziału') for n in zd.META['notes']))

    def test_kandydaci_swiata_po_poprawce(self):
        self.assertEqual([k for k, _, _ in zd.TD_SH_W], ['eq.pf', 'eq.fo'])
        self.assertAlmostEqual(zd.TD_W_ZLS, statistics.NormalDist().inv_cdf(1 - 0.025 / 27), places=6)

    def test_pages_dluga_seria(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('kontrola_v221', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        k = importlib.util.module_from_spec(spec); spec.loader.exec_module(k)
        U = datetime.timezone.utc
        NOW = datetime.datetime(2026, 10, 6, 6, 20, tzinfo=U)

        def r(i, m, c):
            return {'id': i, 'name': 'Strona i dane', 'status': 'completed', 'conclusion': c,
                    'run_started_at': (NOW - datetime.timedelta(minutes=m)).isoformat(), 'updated_at': (NOW - datetime.timedelta(minutes=m - 5)).isoformat()}
        PG = 'opublikuj / publikacja na GitHub Pages (zwykle chwilowa awaria po stronie GitHuba)'
        runs = [r(i, 10 * i, 'failure') for i in range(1, 8)] + [r(100 + i, 100 + 10 * i, 'success') for i in range(25)]
        A, b, u = k.przebiegi_ocena(runs, NOW, {i: PG for i in range(1, 6)})
        self.assertTrue(b[0].startswith('automat nie działa (publikacja GitHub Pages): 7 nieudanych'), b)


# ===================== v222: LICZNIK ZUŻYCIA DARMOWYCH PLANÓW =====================
class LicznikZuzyciaV222(unittest.TestCase):
    """v222: zbieracz liczy zapytania do planów z limitem (CoinGecko z kluczem, CoinMarketCap, Twelve Data — kredyty = symbole), narastająco
    między przebiegami (doba i miesiąc UTC); raport dostawcy CoinMarketCap najwyżej raz na 6 h."""

    def setUp(self):
        zd._ZUZ.clear()

    def tearDown(self):
        zd._ZUZ.clear()

    def test_licz(self):
        L = zd._zuz_licz
        L('https://api.coingecko.com/api/v3/global', {'x-cg-demo-api-key': 'k'})
        L('https://api.coingecko.com/api/v3/global', {'X-CG-DEMO-API-KEY': 'k'})
        L('https://api.coingecko.com/api/v3/simple/price?ids=ethereum', None)        # bez klucza — nie z planu
        L('https://api.coingecko.com/api/v3/global', {'x-cg-demo-api-key': ''})       # pusty klucz — nie z planu
        L('https://pro-api.coinmarketcap.com/v1/global-metrics/quotes/latest', {'X-CMC_PRO_API_KEY': 'k'})
        L('https://api.twelvedata.com/time_series?symbol=SPY,QQQ,EWJ&interval=1day&apikey=k')
        L('https://api.twelvedata.com/time_series?symbol=SPY&apikey=k')
        L('https://api.twelvedata.com/time_series?apikey=k')
        L('https://example.com/x?symbol=A,B', None); L(None, None); L('::', {'x': 1}); L('https://api.coingecko.com/x', 'zle')
        self.assertEqual(zd._ZUZ, {'cg': 2, 'cmc': 1, 'td': 5})

    def test_get_liczy(self):
        class R:
            status = 200

            def read(self):
                return b'{}'

            def __enter__(self):
                return self

            def __exit__(self, *a):
                return False
        with mock.patch.object(zd.urllib.request, 'urlopen', return_value=R()):
            zd.get('https://api.twelvedata.com/time_series?symbol=SPY,QQQ&apikey=k')
            zd.get_json('https://pro-api.coinmarketcap.com/v1/global-metrics/quotes/latest', {'X-CMC_PRO_API_KEY': 'k'})
            zd.get_bytes('https://api.coingecko.com/api/v3/x', {'x-cg-demo-api-key': 'k'})
            zd.get('https://stablecoins.llama.fi/stablecoins')
        self.assertEqual(zd._ZUZ, {'td': 2, 'cmc': 1, 'cg': 1})

    def test_narastajaco(self):
        z = zd.zuzycie
        a = z(None, {'cg': 4, 'cmc': 1, 'td': 7}, '2026-10-06T07:30:00+00:00')
        self.assertEqual(a['cg'], {'od': '2026-10-06T07:30:00+00:00', 'd': '2026-10-06', 'n': 4, 'm': '2026-10', 'nm': 4})
        self.assertEqual((a['cmc']['n'], a['td']['n'], sorted(a)), (1, 7, ['cg', 'cmc', 'fmp', 'td']))   # v295: + FMP
        b = z(a, {'cg': 1}, '2026-10-06T07:40:00+00:00')
        self.assertEqual((b['cg']['n'], b['cg']['nm'], b['cmc']['n'], b['td']['nm'], b['cg']['od']), (5, 5, 1, 7, '2026-10-06T07:30:00+00:00'))
        c = z(b, {'cg': 2}, '2026-10-07T00:00:05+00:00')   # nowa doba UTC
        self.assertEqual((c['cg']['n'], c['cg']['dp'], c['cg']['nm']), (2, ['2026-10-06', 5], 7))
        self.assertEqual((c['td']['n'], c['td']['dp'], c['td']['nm']), (0, ['2026-10-06', 7], 7))
        e = z(c, {'cg': 3}, '2026-11-01T00:00:05+00:00')   # nowy miesiąc
        self.assertEqual((e['cg']['n'], e['cg']['nm'], e['cg']['dp'], e['cg']['mp']), (3, 3, ['2026-10-07', 2], ['2026-10', 7]))
        f = z(e, {}, '2026-11-01T00:10:05+00:00')
        self.assertEqual((f['cg']['n'], f['cg']['dp'], f['cg']['mp']), (3, ['2026-10-07', 2], ['2026-10', 7]), 'poprzednia doba i miesiąc przechodzą dalej')
        g = z({'cg': {'od': 'x', 'd': '2026-11-01', 'n': True, 'nm': -3, 'dp': ['2026-10-31', 'x']}, 'td': 'x'}, {'cg': 1, 'td': 2.5},
              '2026-11-01T01:00:00+00:00')
        self.assertEqual(g['cg'], {'od': '2026-11-01T01:00:00+00:00', 'd': '2026-11-01', 'n': 1, 'm': '2026-11', 'nm': 1}, 'złe pola — od zera')
        self.assertEqual(g['td']['n'], 0, 'ułamek z przebiegu nie jest liczbą zapytań')
        h = z(a, {}, '2026-10-06T07:50:00+00:00', {'cmc': {'at': 'x', 'blad': 'HTTP 401'}})
        self.assertEqual(h['cmc']['dost'], {'at': 'x', 'blad': 'HTTP 401'}); self.assertNotIn('dost', h['cg'])

    def test_dost_cmc(self):
        P = {'cmc': {'dost': {'at': '2026-10-06T07:10:00+00:00', 'mies': [100, 9900, 10000]}}}
        with mock.patch.object(zd, 'cmc_key_info', side_effect=AssertionError('bez zapytania')):
            self.assertIs(zd._zuz_dost_cmc(P, 'k', '2026-10-06T11:50:00+00:00'), P['cmc']['dost'], 'ten sam blok 6 h — poprzedni raport')
            self.assertIsNone(zd._zuz_dost_cmc(P, '', '2026-10-06T12:00:00+00:00'), 'bez klucza — bez raportu')
        with mock.patch.object(zd, 'cmc_key_info', return_value={'at': 'n'}) as ki:
            self.assertEqual(zd._zuz_dost_cmc(P, 'k', '2026-10-06T12:00:00+00:00'), {'at': 'n'}); ki.assert_called_once_with('k')
            self.assertEqual(zd._zuz_dost_cmc(None, 'k', '2026-10-06T12:00:00+00:00'), {'at': 'n'})
            self.assertEqual(zd._zuz_dost_cmc({'cmc': {'dost': {'at': 'zly'}}}, 'k', '2026-10-06T12:00:00+00:00'), {'at': 'n'})
        old = list(zd.SECRETS)
        try:
            zd.SECRETS[:] = ['sekret']
            with mock.patch.object(zd, 'cmc_key_info', side_effect=RuntimeError('HTTP 401 sekret')):
                r = zd._zuz_dost_cmc(P, 'k', '2026-10-07T00:00:00+00:00')
        finally:
            zd.SECRETS[:] = old
        self.assertEqual(r, {'at': '2026-10-07T00:00:00+00:00', 'blad': 'HTTP 401 ***'}, 'nieudana próba zapisana bez klucza — bez ponawiania w bloku')
        self.assertEqual((zd._zuz_blok('2026-10-06T05:59:59+00:00'), zd._zuz_blok('2026-10-06T06:00:00+00:00'), zd._zuz_blok(None)),
                         ('2026-10-06/0', '2026-10-06/1', None))

    def test_key_info(self):
        J = {'status': {'error_code': 0}, 'data': {'plan': {'credit_limit_daily': 333, 'credit_limit_monthly': 10000,
             'credit_limit_monthly_reset_timestamp': '2026-11-01T00:00:00.000Z'},
             'usage': {'current_day': {'credits_used': 150, 'credits_left': 183}, 'current_month': {'credits_used': 880, 'credits_left': 9120.0}}}}
        with mock.patch.object(zd, 'get_json', return_value=J) as g:
            o = zd.cmc_key_info('k')
        self.assertEqual((o['dz'], o['mies'], o['reset_m']), ([150, 183, 333], [880, 9120, 10000], '2026-11-01T00:00:00.000Z'))
        self.assertTrue(g.call_args[0][0].endswith('/v1/key/info')); self.assertEqual(g.call_args[0][1]['X-CMC_PRO_API_KEY'], 'k')
        with mock.patch.object(zd, 'get_json', return_value={'status': {'error_code': 1002, 'error_message': 'bad key'}}):
            self.assertRaises(RuntimeError, zd.cmc_key_info, 'k')
        with mock.patch.object(zd, 'get_json', return_value={'status': {}, 'data': {'plan': 'x', 'usage': {'current_day': {'credits_used': True}}}}):
            self.assertRaises(RuntimeError, zd.cmc_key_info, 'k')   # bez żadnej liczby — błąd, nie zera

    def test_wpiecie(self):
        import inspect
        src = inspect.getsource(zd.main)
        self.assertIn('_ZUZ.clear()', src)
        self.assertIn("META['zuzycie'] = zuzycie(pz, dict(_ZUZ), NOW, {'cmc': dc} if dc else None)", src)
        self.assertLess(src.index('dc = _zuz_dost_cmc('), src.index("META['zuzycie'] = zuzycie("), 'raport dostawcy przed licznikiem — samo zapytanie też się liczy')
        self.assertLess(src.index("META['zuzycie'] = zuzycie("), src.index("save('meta', META)"))
        self.assertLess(src.index('    pm = {}\n'), src.index("pm = previous('meta') or {}"), 'pm istnieje, nawet gdy odczyt poprzedniego stanu zawiedzie')
        for f in (zd.get, zd.get_bytes):
            self.assertIn('_zuz_licz(url, headers)', inspect.getsource(f))


class KontrolaZuzycieV222(unittest.TestCase):
    """v222: kontrola — zużycie planów z prognozą na miesiąc, ⚠️ od 80% prognozy, ❌ przy wyczerpaniu (z podpowiedzią „Co zrobić”)."""

    def setUp(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('kontrola_v222', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        self.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(self.k)

    @staticmethod
    def M(at, **z):
        return {'at': at, 'zuzycie': z}

    def test_miesiac(self):
        k = self.k
        q = lambda nm, od='2026-10-06T07:30:00+00:00', m='2026-10': {'od': od, 'd': '2026-10-07', 'n': 10, 'm': m, 'nm': nm}  # noqa: E731
        o = k.zuzycie_ocena(self.M('2026-10-07T07:30:00+00:00', cg=q(176)))
        self.assertEqual(o['plany'], [{'k': 'cg', 'znak': '✅', 'tekst': 'CoinGecko (Demo) — zapytań w tym miesiącu (od 06.10.2026, 09:30): 176, '
                                       'prognoza na miesiąc ok. 5 456 z limitu 10 000 (55%)'}])
        self.assertEqual((o['uwagi'], o['bledy']), ([], []))
        o = k.zuzycie_ocena(self.M('2026-10-07T07:30:00+00:00', cg=q(300)))   # 300 × 31 = 9 300
        self.assertEqual(o['plany'][0]['znak'], '⚠️'); self.assertIn('zapas maleje', o['uwagi'][0])
        self.assertIn('zapas maleje; ' + k.PORADA_3D + ' (zadanie: „zmniejsz liczbę zapytań do CoinGecko”)', o['uwagi'][0])
        o = k.zuzycie_ocena(self.M('2026-10-07T07:30:00+00:00', cg=q(400)))   # 12 400
        self.assertIn('ponad limit', o['uwagi'][0]); self.assertEqual(o['bledy'], [])
        o = k.zuzycie_ocena(self.M('2026-10-30T07:30:00+00:00', cg=q(9600, od='2026-09-01T00:00:00+00:00')))
        self.assertEqual(o['plany'][0]['znak'], '❌')
        self.assertEqual(o['bledy'], ['limit planu CoinGecko (Demo) prawie wyczerpany: 9 600 z 10 000 zapytań w tym miesiącu (licznik automatu)'])
        self.assertNotIn('(od ', o['plany'][0]['tekst'], 'licznik sprzed początku miesiąca — bez „od”')
        o = k.zuzycie_ocena(self.M('2026-10-06T20:00:00+00:00', cg=q(90)))
        self.assertTrue(o['plany'][0]['tekst'].endswith(': 90 (prognoza po pierwszej dobie liczenia)')); self.assertEqual(o['uwagi'], [])
        o = k.zuzycie_ocena(self.M('2026-11-01T06:20:00+00:00', cg=q(7000)))
        self.assertEqual(o['plany'][0], {'k': 'cg', 'tekst': 'CoinGecko (Demo) — brak licznika w tym miesiącu', 'znak': 'ℹ️'})
        o = k.zuzycie_ocena(self.M('2026-02-02T00:00:00+00:00', cg=q(100, od='2026-02-01T00:00:00+00:00', m='2026-02')))
        self.assertIn('ok. 2 800 z limitu', o['plany'][0]['tekst'], 'luty — 28 dni')

    def test_doba(self):
        k = self.k
        q = lambda dp, od='2026-10-05T07:30:00+00:00': {'od': od, 'd': '2026-10-07', 'n': 84, 'm': '2026-10', 'nm': 1000, 'dp': dp}  # noqa: E731
        o = k.zuzycie_ocena(self.M('2026-10-07T06:20:00+00:00', td=q(['2026-10-06', 336])))
        self.assertEqual(o['plany'], [{'k': 'td', 'znak': '✅', 'tekst': 'Twelve Data (Basic) — kredytów wczoraj (doba UTC): 336 z limitu 800 (42%); '
                                       'w bieżącej dobie (od północy UTC): 84'}])
        o = k.zuzycie_ocena(self.M('2026-10-07T06:20:00+00:00', td=q(['2026-10-06', 700])))
        self.assertEqual((o['plany'][0]['znak'], len(o['uwagi']), o['bledy']), ('⚠️', 1, []))
        o = k.zuzycie_ocena(self.M('2026-10-07T06:20:00+00:00', td=q(['2026-10-06', 812])))
        self.assertEqual(o['plany'][0]['znak'], '❌')
        self.assertEqual(o['bledy'], ['limit planu Twelve Data (Basic) wyczerpany wczoraj: 812 z 800 kredytów (licznik automatu) — część notowań mogła nie przyjść'])
        o = k.zuzycie_ocena(self.M('2026-10-07T06:20:00+00:00', td=q(['2026-10-06', 336], od='2026-10-06T07:30:00+00:00')))
        self.assertIn('kredytów wczoraj: brak pełnej doby licznika', o['plany'][0]['tekst'], 'doba startu licznika niepełna')
        o = k.zuzycie_ocena(self.M('2026-10-07T06:20:00+00:00', td=q(['2026-10-05', 336])))
        self.assertIn('brak pełnej doby licznika', o['plany'][0]['tekst'], 'doba sprzed przerwy w przebiegach to nie „wczoraj”')

    def test_dostawca(self):
        k = self.k
        q = {'od': '2026-10-01T00:00:00+00:00', 'd': '2026-10-07', 'n': 40, 'm': '2026-10', 'nm': 900,
             'dost': {'at': '2026-10-07T06:00:05+00:00', 'dz': [150, 183, 333], 'mies': [930, 9070, 10000]}}
        o = k.zuzycie_ocena(self.M('2026-10-07T06:20:00+00:00', cmc=q))
        self.assertTrue(o['plany'][0]['tekst'].endswith('; według dostawcy w miesiącu: 930 z 10 000 (9%, stan 07.10.2026, 08:00)'))
        self.assertEqual((o['plany'][0]['znak'], o['uwagi'], o['bledy']), ('✅', [], []))
        o = k.zuzycie_ocena(self.M('2026-10-07T06:20:00+00:00', cmc=dict(q, dost={'at': '2026-10-07T06:00:05+00:00', 'dz': [None] * 3, 'mies': [9600, 400, None]})))
        self.assertEqual(o['plany'][0]['znak'], '❌'); self.assertIn('według dostawcy', o['bledy'][-1], 'limit z sumy: zużyte + zostało')
        o = k.zuzycie_ocena(self.M('2026-10-07T06:20:00+00:00', cmc=dict(q, dost={'at': '2026-10-07T06:00:05+00:00', 'blad': 'HTTP Error 403: Forbidden'})))
        self.assertTrue(o['plany'][0]['tekst'].endswith('; raport dostawcy niedostępny (HTTP Error 403: Forbidden)')); self.assertEqual(o['bledy'], [])
        o = k.zuzycie_ocena(self.M('2026-10-07T06:20:00+00:00', cmc=dict(q, dost={'at': '2026-10-07T06:00:05+00:00', 'dz': [340, 0, 333], 'mies': 'x'})))
        self.assertEqual(o['plany'][0]['znak'], '⚠️'); self.assertIn('dzienny limit wyczerpany', o['uwagi'][-1])

    def test_raport_i_wpiecie(self):
        k = self.k
        with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'), encoding='utf-8') as f:
            src = f.read()
        self.assertIn('zu = zuzycie_ocena(m)', src)
        R = {'at': '2026-10-07T06:20:00+00:00', 'wynik': 'UWAGA', 'meta': {}, 'uwagi': ['x'], 'bledy': [],
             'zuzycie': {'plany': [{'k': 'cg', 'tekst': 'A', 'znak': '✅'}, {'k': 'td', 'tekst': 'B', 'znak': '⚠️'}], 'uwagi': [], 'bledy': []}}
        self.assertIn('\n- Zużycie darmowych planów (licznik automatu — dolna granica): A ✅; B ⚠️.\n', k.raport_md(R))
        R['zuzycie'] = {'plany': [], 'uwagi': [], 'bledy': []}
        self.assertNotIn('Zużycie darmowych planów', k.raport_md(R))
        h = k.co_zrobic(['limit planu Twelve Data (Basic) wyczerpany wczoraj: 812 z 800 kredytów (licznik automatu) — część notowań mogła nie przyjść'])
        self.assertEqual(len(h), 1); self.assertIn(k.PORADA_3D_W, h[0])
        self.assertIsNone(k.zuzycie_ocena({'at': '2026-10-07T06:20:00+00:00'})); self.assertIsNone(k.zuzycie_ocena(None))
        self.assertIsNone(k.zuzycie_ocena({'at': 'x', 'zuzycie': {}}))
        self.assertEqual(k.zuzycie_ocena({'at': '2026-10-07T06:20:00+00:00', 'zuzycie': {'cg': 'x', 'td': {'od': 'zly'}}}), {'plany': [], 'uwagi': [], 'bledy': []})


# ===================== v223: FUNDUSZE PO PRZEGLĄDZIE v220–v221 =====================
class PoPrzegladzieV223(unittest.TestCase):
    """v223: zły wiersz pliku decyduje o braku (para dni = brak; suma grupy bez niego — dokładna); aktywa grupy z ostatniego poprawnego wiersza;
    próba uzupełnienia zużyta dopiero po pobraniu pliku; granice 0,5–2× zostają; notatki tylko o świeżych złych wierszach; limit planu od dostawcy."""

    H = [['2026-09-%02d' % d, 36.0 + d / 10, 232600000 + 100000 * d] for d in range(14, 31) if datetime.date(2026, 9, d).weekday() < 5]

    @staticmethod
    def mk(rows):
        return {'h': rows}

    def test_dwa_zle_wiersze_i_jednostki(self):
        h = self.H + [['2026-10-01', 37.1, 233800000], ['2026-10-02', 38.1, 235300000], ['2026-10-05', 0.001328, 238400000],
                      ['2026-10-06', 0.001402, 239100000], ['2026-10-07', 41.0, 239500000]]
        self.assertEqual(zd._fund_clean(h)[1], ['2026-10-05', '2026-10-06'])
        fl = zd.fund_flows(h)
        for d in ('2026-10-05', '2026-10-06', '2026-10-07'):
            self.assertNotIn(d, fl, d + ' — para ze złym wierszem to brak, nie przepływ ≈ 0')
        self.assertIn('2026-10-02', fl)
        d, px, ret = zd._td_fund_px(zd._fund_rows(h))
        self.assertEqual(ret[-3:], [None, None, None], 'zwroty dni ze złymi wierszami i dnia po nich — brak (nie zwrot z dwóch złych NAV)')
        self.assertTrue(zd._isnum(ret[-4]))
        h2 = self.H + [['2026-10-01', 37.1, 233800000], ['2026-10-02', 37.2, 233800000 * 2.5], ['2026-10-05', 37.3, 233900000]]
        fl2 = zd.fund_flows(h2)
        self.assertNotIn('2026-10-02', fl2); self.assertNotIn('2026-10-05', fl2, 'jednostki ×2,5 jednego dnia — brak, nie ±13 500 mln USD')

    def test_grupa_bez_zlego_wiersza_i_aktywa(self):
        days = ['2026-09-%02d' % d for d in (14, 15, 16, 17, 18, 21, 22, 23, 24, 25)]
        a = [[d, 50.0, 1000 + 10 * i] for i, d in enumerate(days)]
        b = [[d, 20.0, 500 + 5 * i] for i, d in enumerate(days)]
        b[6] = [days[6], 0.001, 530]                                       # zły wiersz B 22.09
        ds, v, aum = zd.fund_group({'A': self.mk(a), 'B': self.mk(b)}, ('A', 'B'))
        self.assertNotIn('2026-09-22', ds, 'dzień ze złym wierszem B — jak inny kalendarz: przepływy do następnego wspólnego dnia')
        self.assertAlmostEqual(v[ds.index('2026-09-23')], (20 * 50.0 + 10 * 20.0) / 1e6, msg='suma przez dwa dni — dokładna (A 22+23, B 21→23)')
        self.assertAlmostEqual(v[ds.index('2026-09-24')], (10 * 50.0 + 5 * 20.0) / 1e6)
        b2 = [r[:] for r in b]; b2[6] = [days[6], 20.0, 530]; b2[-1] = [days[-1], 0.001, 545]   # zły NAJNOWSZY wiersz B
        ds, v, aum = zd.fund_group({'A': self.mk(a), 'B': self.mk(b2)}, ('A', 'B'))
        self.assertAlmostEqual(aum, (50.0 * 1090 + 20.0 * 540) / 1e6, msg='aktywa B z 24.09 (ostatni poprawny), nie z błędnego 25.09')
        self.assertEqual(ds[-1], '2026-09-24')
        dl = [d.isoformat() for d in (datetime.date(2026, 8, 3) + datetime.timedelta(days=i) for i in range(45)) if d.weekday() < 5][:30]
        a3 = [[d, 50.0, 1000 + 10 * i] for i, d in enumerate(dl)]
        b3 = [[d, 20.0 if i < 15 else 36.0, 500 + 5 * i] for i, d in enumerate(dl)]   # trwały skok NAV ×1,8 bez wyjaśnienia (fund_split = 0)
        self.assertEqual(zd._fund_clean(b3)[1], [], 'aktywa ×1,9 — poniżej progu 2×, nie „zły wiersz”')
        ds, v, _ = zd.fund_group({'A': self.mk(a3), 'B': self.mk(b3)}, ('A', 'B'))
        self.assertIsNone(v[ds.index(dl[15])], 'skok bez wyjaśnienia u B — brak całej grupy tego dnia, nie przepływ samego A')
        self.assertTrue(all(zd._isnum(x) for x in v[ds.index(dl[16]):]) and all(zd._isnum(x) for x in v[:ds.index(dl[15])]), 'pozostałe dni liczone')

    def test_trendy_procent_aktywow(self):
        days = [d for d in (datetime.date(2025, 9, 1) + datetime.timedelta(days=i) for i in range(400)) if d.weekday() < 5][-260:]
        h = [[d.isoformat(), 38.0 + 0.01 * i, 230000000 + 50000 * i + (3000000 if i % 2 else 0)] for i, d in enumerate(days)]
        h[-1] = [h[-1][0], 0.001328, h[-1][2]]
        with mock.patch.object(zd, '_now_utc', return_value=datetime.datetime.combine(days[-1], datetime.time(22, 0), tzinfo=datetime.timezone.utc)):
            ds, v, aum = zd.fund_group({'EWZ': self.mk(h)}, ('EWZ',))
        self.assertGreater(aum, 8000, 'aktywa z przedostatniego (poprawnego) wiersza — ok. 9 mld USD, nie ułamek')

    def test_ceny_bez_zlych_wierszy(self):
        days = ['2026-01-%02d' % d for d in range(1, 27)]
        spy = [[d, 100.0 + i, 5] for i, d in enumerate(days)]
        spy[22] = [days[22], 55.0, 5]                                       # odstęp ×0,47 od mediany sąsiadów — błąd pliku (iloraz 20 sesji 0,54 — dawny próg go przepuszczał)
        ief = [[d, 50.0 + i / 100, 3] for i, d in enumerate(days)]
        sb = zd.ns_sb(spy, ief, 20)
        self.assertNotIn(days[22], [r[0] for r in sb]); self.assertTrue(all(abs(r[2]) < 0.3 for r in sb), 'żaden zwrot akcji z błędnego NAV')
        self.assertEqual(zd._fund_clean(spy)[1], [days[22]])
        s = zd._td_series_ob({'in': {'d': [[d, 10.0, 1.0, 0, 0, 88.0] for d in days]}}, zd.TD_OB[0], {'INDA': {'h': [[d, 50.0 + i / 10, 1000] for i, d in enumerate(days)][:22]
                             + [[days[22], 0.01, 1000]] + [[d, 52.3 + i / 10, 1000] for i, d in enumerate(days[23:])]}})
        i22 = s['dates'].index(days[22])
        self.assertIsNone(s['ret'][i22]); self.assertIsNone(s['ret'][i22 + 1], 'NAV z błędnego wiersza nie jest ceną')
        self.assertTrue(zd._isnum(s['ret'][i22 + 2]))

    def test_notatki_tylko_swieze_i_cena_tygodniowa(self):
        zd.META['notes'] = []
        h = self.H + [['2026-10-01', 37.1, 233800000], ['2026-10-02', 38.1, 235300000], ['2026-10-05', 0.001328, 238400000]]
