# ===================== v225: KONTROLA — KURSY WALUT STRONY VS H.10 (FED) =====================
class KontrolaKursyV225(unittest.TestCase):
    """v225: migawki kursów rynki.json (now/1D/1T/…) vs H.10 Fed z tych samych dni; ⚠️ ponad 1,5% albo mediana dnia ponad 0,4%; nigdy ❌."""

    def setUp(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('kontrola_v225', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        self.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(self.k)

    CSV = ('"Series Description","Australian Dollar","Euro-Area Euro","Japanese Yen","Mexican Peso","Swiss Franc","Canadian Dollar","Venezuelan Bolivar"\n'
           '"Unit:","Currency","Currency","Currency","Currency","Currency","Currency","Currency"\n'
           '"Multiplier:","1","1","1","1","1","1","1"\n'
           '"Currency:","AUD","EUR","JPY","MXN","CHF","CAD","VEB"\n'
           '"Unique Identifier: ","H10/H10/RXI$US_N.B.AL","H10/H10/RXI$US_N.B.EU","H10/H10/RXI_N.B.JA","H10/H10/RXI_N.B.MX","H10/H10/RXI_N.B.SZ","H10/H10/RXI_N.B.CA","H10/H10/RXI_N.B.VE"\n'
           '"Time Period","RXI$US_N.B.AL","RXI$US_N.B.EU","RXI_N.B.JA","RXI_N.B.MX","RXI_N.B.SZ","RXI_N.B.CA","RXI_N.B.VE"\n'
           '2026-09-28,0.7024,1.1400,157.0000,18.1000,0.8300,1.4160,ND\n'
           '2026-10-01,ND,1.1232,157.6300,18.4001,0.8263,1.4253,0\n'
           '2026-10-02,0.6953,1.1259,157.8100,18.1920,0.8306,1.4253,850.1\n')

    @staticmethod
    def R(**m):
        return {'fx': {k: {'amount': 1.0, 'base': 'USD', 'date': d, 'rates': r} for k, (d, r) in m.items()}}

    def test_csv(self):
        H = self.k.fx_h10_csv(self.CSV)
        self.assertEqual(sorted(H), ['2026-09-28', '2026-10-01', '2026-10-02'])
        self.assertAlmostEqual(H['2026-10-02']['EUR'], 1 / 1.1259); self.assertAlmostEqual(H['2026-10-02']['AUD'], 1 / 0.6953, msg='RXI$US — USD za jednostkę: odwrotność')
        self.assertEqual(H['2026-10-02']['JPY'], 157.81); self.assertEqual(H['2026-10-02']['VEB'], 850.1)
        self.assertNotIn('AUD', H['2026-10-01'], 'ND — brak, nie zero'); self.assertNotIn('VEB', H['2026-10-01'], 'zero — pominięte')
        self.assertNotIn('VEB', H['2026-09-28'])
        self.assertEqual(self.k.fx_h10_csv(''), {}); self.assertEqual(self.k.fx_h10_csv('a,b\n2026-10-02,1'), {}, 'bez wierszy walut — nic')

    def test_porownanie(self):
        k = self.k
        H = k.fx_h10_csv(self.CSV)
        ok = {'EUR': 0.88818, 'JPY': 157.70, 'MXN': 18.33, 'CHF': 0.8290, 'CAD': 1.4250, 'AUD': 1.4390, 'GBP': 0.75}
        ok28 = {c: v * 1.001 for c, v in H['2026-09-28'].items()}          # migawka „1T” z 28.09 — kursy z tego dnia
        f = k.fx_porownanie(self.R(now=('2026-10-05', ok), **{'1D': ('2026-10-02', ok), '1T': ('2026-09-28', ok28)}), H)
        self.assertEqual([x[0] for x in f['daty']], ['2026-09-28', '2026-10-02'], 'tylko dni obecne w H.10; „now” (05.10) jeszcze nie')
        d = f['daty'][1]
        self.assertEqual((d[1], d[3]), (6, 'MXN'), '6 wspólnych walut (GBP nie ma w H.10); najwięcej peso')
        self.assertAlmostEqual(d[4], round((18.33 / 18.192 - 1) * 100, 3))
        self.assertEqual((f['zle'], f['med_zle']), ([], []))
        zly = dict(ok, JPY=157.81 * 1.06)   # v227: próg 5%
        f = k.fx_porownanie(self.R(**{'1D': ('2026-10-02', zly)}), H)
        self.assertEqual([x[:2] for x in f['zle']], [['2026-10-02', 'JPY']]); self.assertEqual(f['med_zle'], [])
        dzien = {c: v * 1.03 for c, v in ok.items()}                      # v227: wszystko o 3% obok (np. zła waluta bazowa) — mediana > 2,5%
        f = k.fx_porownanie(self.R(**{'1D': ('2026-10-02', dzien)}), H)
        self.assertEqual(f['zle'], []); self.assertEqual(len(f['med_zle']), 1)
        self.assertIsNone(k.fx_porownanie({}, H)); self.assertIsNone(k.fx_porownanie(self.R(now=('2026-10-05', ok)), {}))
        self.assertEqual(k.fx_porownanie({'fx': {'now': {'base': 'EUR', 'date': '2026-10-02', 'rates': ok}}}, H)['baza'], [['now', 'EUR']], 'v231: inna waluta bazowa — ⚠️ (dotąd cicho bez porównania)')
        f = k.fx_porownanie(self.R(now=('2026-10-02', {'EUR': True, 'JPY': -1, 'CHF': 'x'})), H)
        self.assertEqual(f['daty'], [], 'złe liczby pominięte — bez dat')
        f = k.fx_porownanie(self.R(now=('2026-10-02', ok), **{'1D': ('2026-10-02', zly)}), H)
        self.assertEqual((len(f['daty']), f['zle']), (1, []), 'ta sama data w dwóch migawkach — porównana raz (pierwsza: now)')

    def test_raport_i_wpiecie(self):
        k = self.k
        with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'), encoding='utf-8') as fh:
            src = fh.read()
        self.assertIn("f = fx_porownanie(files['rynki'], H)", src); self.assertIn('get(FX_H10, timeout=30)', src)
        base = {'at': '2026-10-07T06:20:00+00:00', 'wynik': 'OK', 'meta': {}, 'uwagi': [], 'bledy': []}
        R = dict(base, zgodnosc={'fx': {'daty': [['2026-09-28', 20, 0.097, 'MXN', -0.442], ['2026-10-02', 20, 0.091, 'MXN', 0.786]], 'zle': [], 'med_zle': []}})
        self.assertIn('- Kursy walut (strona: kurs EBC; H.10: Fed, Nowy Jork; te same dni): 2026-09-28 — 20 walut, mediana różnicy 0,10%, najwięcej MXN -0,44%; '
                      '2026-10-02 — 20 walut, mediana różnicy 0,09%, najwięcej MXN +0,79% ✅.', k.raport_md(R))
        R = dict(base, zgodnosc={'fx': {'daty': [['2026-10-02', 20, 0.6, 'JPY', 2.0]], 'zle': [['2026-10-02', 'JPY', 1, 1, 2.0]], 'med_zle': [['2026-10-02', 0.6]]}})
        self.assertIn('najwięcej JPY +2,00% ⚠️.', k.raport_md(R))
        self.assertIn('brak wspólnych dat (H.10 wychodzi raz w tygodniu) ℹ️.', k.raport_md(dict(base, zgodnosc={'fx': {'daty': [], 'zle': [], 'med_zle': []}})))
        self.assertIn('brak porównania (H.10: HTTP 503) ℹ️.', k.raport_md(dict(base, zgodnosc={'fx': {'brak': 'H.10: HTTP 503'}})))
        self.assertEqual((k.FX_PROG, k.FX_MED, k.FX_MIN_N), (5.0, 2.5, 5))   # v227: progi z 5 lat poprawnych danych


# ===================== v226: POPRAWKI PO PRZEGLĄDZIE v222–v223 =====================
class PoPrzegladzieV226(unittest.TestCase):
    """v226: próba pełnym plikiem zużyta tylko dla dni z pliku (dzień po jego końcu czeka — bez pętli); suma grupy bez drugiego wykrywania;
    kontrola: limit CoinMarketCap 15 000 i ocena końca poprzedniego miesiąca."""

    def test_plik_krotszy_niz_zestawienie(self):
        t0 = datetime.datetime(2026, 9, 25, 12, 0, tzinfo=datetime.timezone.utc)
        spy = [[d, 700.0 + i, 1000000 + i] for i, d in enumerate(['2026-09-21', '2026-09-22', '2026-09-23', '2026-09-24'])]
        days = [d for d in (datetime.date(2026, 8, 3) + datetime.timedelta(days=i) for i in range(60)) if d.weekday() < 5 and d <= datetime.date(2026, 9, 24)]
        hist = [[d.isoformat(), 50.0, 1000000] for d in days if d <= datetime.date(2026, 9, 22)]
        prev = {'scr_at': None, 'f': {t: {'iss': 'ssga', 'h': spy} for t in zd.FUND_SSGA}}
        prev['f']['EFA'] = {'iss': 'ishares', 'pid': '1', 'bf_done': True, 'h': hist}
        scr = {'1': {'localExchangeTicker': 'EFA', 'portfolioId': '1', 'navAmount': {'r': 0.001}, 'navAmountAsOf': {'r': 20260924},
                     'totalNetAssetsFund': {'r': 0.001 * 1000000}, 'totalNetAssetsFundAsOf': {'r': 20260924}}}
        doc1 = FunduszeV90.xml([(d.strftime('%b %d, %Y'), 50.0, 1000000) for d in reversed(days) if d <= datetime.date(2026, 9, 23)])   # plik do 23.09
        doc2 = FunduszeV90.xml([(d.strftime('%b %d, %Y'), 50.0, 1000000) for d in reversed(days)])                                     # plik do 24.09
        seq = [(t0, doc1), (t0 + datetime.timedelta(minutes=10), doc1), (t0 + datetime.timedelta(minutes=zd.FUND_BF_RETRY + 20), doc2)]
        wyn = []
        for now, doc in seq:
            calls = []

            def fake(url, timeout=60, headers=None, doc=doc):
                calls.append(url)
                return json.dumps(scr).encode() if 'product-screener' in url else doc
            for t in zd.FUND_SSGA:
                prev['f'][t]['at'] = (now - datetime.timedelta(minutes=5)).isoformat()
            zd.META['notes'].clear(); zd.META['errors'].clear()
            with mock.patch.object(zd, 'get_bytes', side_effect=fake), mock.patch.object(zd, '_now_utc', return_value=now), \
                    mock.patch.object(zd, 'NOW', now.isoformat()), mock.patch.object(zd, 'FUND_SLEEP', 0), mock.patch.object(zd.time, 'sleep'):
                out = zd.build_fundusze(prev)
            e = out['f']['EFA']
            wyn.append((sum('get-fund-document' in u for u in calls), e.get('bf_need'), e.get('bf_czeka'), e.get('bf_odrz'), e.get('bf_err_at'), e['h'][-1]))
            prev = out
        d = '2026-09-24'
        self.assertEqual(wyn[0][:5], (1, True, [d], None, t0.isoformat()),
                         'przebieg 1: luka — pełny plik (do 23.09); zły dzień 24.09 z zestawienia po końcu pliku — czeka, próba nie zużyta, przerwa jak po błędzie')
        self.assertEqual(wyn[0][5], [d, 0.001, 1000000])
        self.assertEqual(wyn[1][0], 0, 'przebieg 2 (10 min później): bez pobierania — bez pętli')
        self.assertEqual(wyn[2][:4], (1, None, None, [d]), 'przebieg 3 (po przerwie): plik obejmuje 24.09 — próba zużyta')
        self.assertEqual(wyn[2][5], [d, 50.0, 1000000], 'poprawny NAV z pliku zastąpił zły wiersz')

    def test_zapisz_tylko_do_konca_pliku(self):
        p = {'bf_czeka': ['2026-09-24', '2026-09-22'], 'bf_odrz': ['2026-09-01']}
        self.assertTrue(zd._fund_bf_zapisz(p, '2026-09-23'))
        self.assertEqual((p['bf_odrz'], p['bf_czeka']), (['2026-09-01', '2026-09-22'], ['2026-09-24']))
        self.assertFalse(zd._fund_bf_zapisz(p, '2026-09-24')); self.assertEqual((p['bf_odrz'], 'bf_czeka' in p), (['2026-09-01', '2026-09-22', '2026-09-24'], False))
        q = {'bf_czeka': ['2026-09-24']}
        self.assertFalse(zd._fund_bf_zapisz(q)); self.assertEqual(q['bf_odrz'], ['2026-09-24'], 'bez końca pliku — wszystkie (jak v223)')
        self.assertFalse(zd._fund_bf_zapisz({}))

    def test_grupa_bez_drugiego_wykrycia(self):
        days = [d.isoformat() for d in (datetime.date(2026, 6, 1) + datetime.timedelta(days=i) for i in range(90)) if d.weekday() < 5][:60]
        h = [[d, 50.0 + 0.01 * i, 1000000 if i < 30 else 2500000] for i, d in enumerate(days)]   # trwałe utworzenie jednostek ×2,5 (aktywa ×2,5)
        first = zd._fund_clean(h)[1]
        self.assertEqual(first, days[30:35], 'pierwsze wykrycie: 5 dni po skoku (tylko dni wcześniejsze w medianie)')
        ds, v, aum = zd.fund_group({'X': {'h': h}}, ('X',))
        self.assertEqual([d for d, x in zip(ds, v) if x is None], [days[35]],
                         'v227: jedyny brak — dzień pary przez złe wiersze z aktywami ×2,5 (nie fałszywy napływ); bez drugiego wykrycia — bez kolejnych braków')
        self.assertAlmostEqual(sum(x for x in v if x is not None), 0.0)
        self.assertNotIn(days[35], zd.fund_flows(h[:30] + h[35:], bez=()), 'v231: aktywa ×2,5 w parze dni — skok bez wyjaśnienia, nie przepływ (FUND_PARA_X)')
        fl = zd.fund_flows(h)
        self.assertTrue(all(d not in fl for d in days[30:36]), 'karta dzienna funduszu: dni ze złymi wierszami i dzień po nich — brak')

    def test_kontrola_cmc_i_poprzedni_miesiac(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('kontrola_v226', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        k = importlib.util.module_from_spec(spec); spec.loader.exec_module(k)
        self.assertEqual([x[3] for x in k.ZUZ_PLANY], [10000, 15000, 800, 250])   # v295: + FMP (250 zapytań na dobę)
        q = {'od': '2026-10-06T07:16:20+00:00', 'd': '2026-11-02', 'n': 150, 'm': '2026-11', 'nm': 300, 'mp': ['2026-10', 9700], 'dp': ['2026-11-01', 150]}
        o = k.zuzycie_ocena({'at': '2026-11-02T06:20:00+00:00', 'zuzycie': {'cg': q}})
        self.assertEqual(o['plany'][0]['znak'], '⚠️'); self.assertEqual(o['bledy'], [])
        self.assertTrue(any('w poprzednim miesiącu (2026-10) automat zużył 9 700 z 10 000 zapytań' in u for u in o['uwagi']), o['uwagi'])
        o = k.zuzycie_ocena({'at': '2026-11-09T06:20:00+00:00', 'zuzycie': {'cg': dict(q, d='2026-11-09')}})
        self.assertFalse(any('poprzednim miesiącu' in u for u in o['uwagi']), 'po 7 dniach — bez uwagi o poprzednim miesiącu')
        o = k.zuzycie_ocena({'at': '2026-11-02T06:20:00+00:00', 'zuzycie': {'cg': dict(q, mp=['2026-10', 6000])}})
        self.assertFalse(any('poprzednim miesiącu' in u for u in o['uwagi']), '60% — bez uwagi')
        o = k.zuzycie_ocena({'at': '2026-11-02T06:20:00+00:00', 'zuzycie': {'cmc': dict(q, mp=['2026-10', 13000])}})
        self.assertFalse(any('poprzednim miesiącu' in u for u in o['uwagi']), 'CoinMarketCap: 13 000 z 15 000 (87%) — bez uwagi')


# ===================== v227: POPRAWKI PO PRZEGLĄDZIE v224–v226 =====================
class PoPrzegladzieV227(unittest.TestCase):
    """v227: progi kursów z 5 lat (5% / 2,5%), H.10 z 300 obserwacji, uwagi z przecinkami; suma grupy bez fałszywego napływu przy trwałym
    skoku aktywów przez złe wiersze; dzień czekający na pełny plik znika, gdy przestaje być świeży."""

    def setUp(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('kontrola_v227', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        self.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(self.k)

    def test_kursy_progi_i_uwagi(self):
        k = self.k
        self.assertEqual((k.FX_PROG, k.FX_MED, k.FX_MIN_N), (5.0, 2.5, 5)); self.assertIn('lastobs=300&', k.FX_H10)
        u = k.fx_uwagi({'zle': [['2026-10-02', 'JPY', 167.2786, 157.81, 6.0]], 'med_zle': [['2026-10-02', 3.012]]})
        self.assertEqual(u, ['kursy walut: plik strony vs H.10 (Fed) różnią się ponad 5%: JPY 2026-10-02: 167,279 vs 157,81 (+6,00%)',
                             'kursy walut: mediana różnic z H.10 (Fed) ponad 2,5% dla 2026-10-02 (3,01%) — sprawdzić walutę bazową i datę migawki'])
        self.assertEqual(k.fx_uwagi({'zle': [], 'med_zle': []}), []); self.assertEqual(k.fx_uwagi(None), [])
        H = k.fx_h10_csv(KontrolaKursyV225.CSV)
        ok = {'EUR': 0.88818, 'JPY': 157.70, 'MXN': 18.33, 'CHF': 0.8290, 'CAD': 1.4250, 'AUD': 1.4390}
        sk = {c: v * 1.036 for c, v in ok.items()}                       # wszystko o ok. 3,6% obok (np. migawka sprzed tygodni): żadna waluta ponad 5%, mediana ponad 2,5%
        f = k.fx_porownanie(KontrolaKursyV225.R(**{'1D': ('2026-10-02', sk)}), H)
        self.assertEqual(f['zle'], []); self.assertEqual(len(f['med_zle']), 1)
        f = k.fx_porownanie(KontrolaKursyV225.R(**{'1D': ('2026-10-02', dict(ok, JPY=157.81 * 1.0365))}), H)
        self.assertEqual((f['zle'], f['med_zle']), ([], []), 'największa różnica z 5 lat (3,65%, jen) — bez ⚠️')
        f = k.fx_porownanie(KontrolaKursyV225.R(**{'1D': ('2026-10-02', dict(ok, EUR=1.1259))}), H)
        self.assertEqual([x[1] for x in f['zle']], ['EUR'], 'odwrócony kurs (USD za EUR zamiast EUR za USD) — ⚠️')

    def test_grupa_bez_falszywego_naplywu(self):
        days = [d.isoformat() for d in (datetime.date(2026, 6, 1) + datetime.timedelta(days=i) for i in range(70)) if d.weekday() < 5][:40]
        nav = lambda i: (100.0 if i < 28 else 50.0) + 0.01 * i  # noqa: E731
        h = [[d, nav(i), 1000000 if i < 20 else 2000000] for i, d in enumerate(days)]   # podział 2:1 od 20. sesji, NAV poprawiony dopiero od 28.
        ds, v, aum = zd.fund_group({'X': {'h': h}}, ('X',))
        num = [x for x in v if x is not None]
        self.assertTrue(num and max(abs(x) for x in num) < 0.5 * aum, 'żaden dzień grupy nie ma przepływu rzędu połowy aktywów (v226: +100%)')
        self.assertIn(None, v, 'nieprawdopodobna para — brak, widoczny jako brak')
        e = [[d, 38.0 + 0.01 * i, 235000000] for i, d in enumerate(days)]; e[25] = [days[25], 0.001328, 235000000]   # pojedynczy zły wiersz (jak EWZ)
        e[26] = [days[26], 38.27, 236000000]
        ds, v, _ = zd.fund_group({'E': {'h': e}}, ('E',))
        self.assertNotIn(days[25], ds); self.assertAlmostEqual(v[ds.index(days[26])], (236000000 - 235000000) * 38.27 / 1e6,
                                                                 msg='pojedynczy zły wiersz — przepływ przez dwa dni zostaje (suma dokładna)')
        self.assertEqual(zd.FUND_GR_X, 1.5)

    def test_czekajacy_dzien_wygasa(self):
        p = {'h': [['2026-10-20', 1.0, 1]], 'bf_czeka': ['2026-09-24'], 'bf_odrz': []}
        self.assertFalse(zd._fund_bf_odrz(p, ['2026-09-24'])); self.assertNotIn('bf_czeka', p, 'dzień sprzed ponad 10 sesji — nie czeka już na plik')
        q = {'h': [['2026-09-25', 1.0, 1]], 'bf_czeka': ['2026-09-24']}
        self.assertTrue(zd._fund_bf_odrz(q, ['2026-09-24'])); self.assertEqual(q['bf_czeka'], ['2026-09-24'], 'świeży — czeka dalej')


# ===================== v230: WIELORYBY — LISTA BYBIT 23.09.2026 I WERSJA LISTY W HISTORII =====================
class WielorybyListaV230(unittest.TestCase):
    """v230: Bybit 122 portfele (raport 23.09.2026), zapasowe węzły (mevblocker), wersja listy w historii sald, dzień zmiany listy w pliku."""

    def test_lista_bybit_i_zapas(self):
        import re
        g = zd.WH_GIELDY['Bybit']
        self.assertEqual((len(g['addr']), len(set(g['addr'])), g['since']), (122, 122, '2026-09-23'))
        self.assertIn('Bybit_PoR_Audit_2026_Sep_23.pdf', g['url']); self.assertIn('122 portfele', g['src'])
        self.assertTrue(all(re.fullmatch(r'0x[0-9a-f]{40}', a) for a in g['addr']), 'adresy małymi literami, bez ligatur z PDF')
        self.assertEqual(len(zd.wh_portfele()), 178); self.assertLessEqual(len(zd.wh_portfele()), zd.WH_TOPICS)
        self.assertEqual(zd.WH_RPC_ZAPAS, {'wywolania': ('https://rpc.mevblocker.io', 25), 'logi': ('https://rpc.mevblocker.io', 5)})

    def test_wersja_w_historii(self):
        prev = {'Bybit': [['2026-10-05', 't', 1.0, 2.0, 3.0]], 'Binance': [['2026-10-05', 't', 4.0, 5.0, 6.0, '2022-11']], 'Inna': [['2026-10-05', 't', 1, 1, 1]]}
        h = zd.wh_hist(prev, {'Bybit': {'eth': 9.0, 'usdt': 9.0, 'usdc': 9.0}}, '2026-10-06', 't2', wer={'Bybit': '2026-09-23', 'Binance': '2022-11'})
        self.assertEqual(h['Bybit'], [['2026-10-05', 't', 1.0, 2.0, 3.0, '2026-08-26'], ['2026-10-06', 't2', 9.0, 9.0, 9.0, '2026-09-23']],
                         'wiersz sprzed v230 — lista sprzed v230; nowy — obecna lista')
        self.assertEqual(h['Binance'], [['2026-10-05', 't', 4.0, 5.0, 6.0, '2022-11']], 'wersja już zapisana zostaje')
        self.assertEqual(h['Inna'], [['2026-10-05', 't', 1, 1, 1]], 'giełda spoza mapy — bez zgadywania wersji')
        self.assertEqual(zd.wh_hist({}, {'X': {'eth': 1, 'usdt': 1, 'usdc': 1}}, '2026-10-06', 't')['X'], [['2026-10-06', 't', 1, 1, 1]], 'bez wer — jak dotąd')
        self.assertEqual(zd.WH_WER_PRZED, {'Binance': '2022-11', 'OKX': '2026-09-08', 'Bybit': '2026-08-26', 'KuCoin': '2026-08-31', 'Bitfinex': '2022-11'})

    def test_dzien_zmiany_listy(self):
        G = zd.wh_gieldy({'Bybit': {'since': '2026-08-26'}, 'Binance': {'since': '2022-11', 'zmiana': '2026-01-01'}, 'OKX': 'x'}, '2026-10-06')
        self.assertEqual(G['Bybit']['zmiana'], '2026-10-06'); self.assertEqual(G['Bybit']['n'], 122)
        self.assertEqual(G['Binance']['zmiana'], '2026-01-01', 'ta sama lista — data zmiany z poprzedniego pliku'); self.assertNotIn('zmiana', G['OKX'])
        self.assertEqual(zd.wh_gieldy(G, '2026-10-07')['Bybit']['zmiana'], '2026-10-06', 'następny dzień — data zmiany zostaje')
        self.assertNotIn('zmiana', zd.wh_gieldy(None, '2026-10-06')['Bybit'], 'bez poprzedniego pliku — bez daty zmiany')
        import inspect
        src = inspect.getsource(zd.build_wieloryby)
        self.assertIn("'gieldy': wh_gieldy(prev.get('gieldy'), NOW[:10])", src)
        self.assertIn("wh_hist(prev.get('hist'), salda, out['blk_t'][:10], out['blk_t'], wer={g: c['since'] for g, c in WH_GIELDY.items()})", src)


