# ===================== v231: POPRAWKI PO PRZEGLĄDZIE v227–v228 =====================
class PoPrzegladzieV231(unittest.TestCase):
    """v231: para dni z aktywami ponad 1,35× (podział bez poprawki NAV) = brak; kursy walut z inną walutą bazową = ⚠️."""

    def test_podzial_bez_poprawki_nav(self):
        self.assertEqual(zd.FUND_PARA_X, 1.35)
        for k, nav in ((2.0, 0.995), (0.5, 1.005), (1.5, 1.0), (1.5, 0.99)):        # jednostki ×k, NAV prawie bez zmian (podział bez poprawki NAV)
            self.assertEqual(zd.fund_split([0, 100.0, 1_000_000], [0, 100.0 * nav, 1_000_000 * k]), 0, f'jednostki ×{k}, NAV ×{nav} — skok, nie przepływ')
        self.assertEqual(zd.fund_split([0, 100.0, 1_000_000], [0, 50.0, 2_000_000]), 2, 'prawdziwy podział 2:1 z poprawionym NAV — rozpoznany')
        self.assertEqual(zd.fund_split([0, 100.0, 1_000_000], [0, 101.0, 1_200_000]), 1, 'duży, ale możliwy napływ (+20%)')
        self.assertEqual(zd.fund_split([0, 100.0, 1_000_000], [0, 84.7, 1_000_000]), 1, 'spadek NAV o 15,3% (srebro 02.02.2026) — zwykły dzień')
        days = [d.isoformat() for d in (datetime.date(2026, 6, 1) + datetime.timedelta(days=i) for i in range(60)) if d.weekday() < 5][:30]
        h = [[d, (100.0 if i < 20 or i >= 28 else 100.0) * (0.5 if i >= 28 else 1.0) + 0.01 * i, 1_000_000 if i < 20 else 2_000_000] for i, d in enumerate(days)]
        fl = zd.fund_flows(h)
        self.assertTrue(all(abs(v) < 1 for v in fl.values()), 'podział 2:1 z NAV poprawionym dopiero po 8 sesjach — żadnego przepływu rzędu aktywów')
        self.assertNotIn(days[20], fl); self.assertNotIn(days[28], fl)
        ds, v, aum = zd.fund_group({'X': {'h': h}}, ('X',))
        self.assertTrue(all(x is None or abs(x) < 0.2 * aum for x in v), 'suma grupy bez fałszywego napływu')

    def test_kursy_inna_baza(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('kontrola_v231', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        k = importlib.util.module_from_spec(spec); spec.loader.exec_module(k)
        H = k.fx_h10_csv(KontrolaKursyV225.CSV)
        ok = {'EUR': 0.88818, 'JPY': 157.70, 'MXN': 18.33, 'CHF': 0.8290, 'CAD': 1.4250, 'AUD': 1.4390}
        R = {'fx': {'now': {'base': 'EUR', 'date': '2026-10-02', 'rates': ok}, '1D': {'base': 'USD', 'date': '2026-10-02', 'rates': ok}}}
        f = k.fx_porownanie(R, H)
        self.assertEqual(f['baza'], [['now', 'EUR']]); self.assertEqual(len(f['daty']), 1)
        u = k.fx_uwagi(f)
        self.assertTrue(any(x.startswith('kursy walut: migawki z walutą bazową inną niż USD: now (EUR)') for x in u), u)
        f = k.fx_porownanie({'fx': {'now': {'base': 'EUR', 'date': '2026-10-02', 'rates': ok}}}, H)
        self.assertEqual((f['daty'], f['baza']), ([], [['now', 'EUR']]), 'same migawki z inną bazą — ⚠️, nie „brak migawek”')
        self.assertIsNone(k.fx_porownanie({'fx': {'now': {'date': '2026-10-02', 'rates': ok}}}, H), 'bez pola base — jak dotąd: bez porównania')


# ===================== v232: ZAWIESZONA PUBLIKACJA — ZEGAR ANULUJE, KONTROLA ZGŁASZA =====================
class ZegarOdblokujV232(unittest.TestCase):
    """v232: 06.10.2026 zadanie „opublikuj” stało od 08:47 UTC w stanie waiting (środowisko github-pages bez wymogu zatwierdzenia) i trzymało
    grupę „pages”. Tryb `odblokuj` anuluje taki przebieg; zatwierdzenia przez osobę i trwającego licznika czasu nie rusza. Bez sieci (_api atrapą)."""

    @classmethod
    def setUpClass(cls):
        import importlib.util
        root = os.path.dirname(os.path.abspath(__file__))
        spec = importlib.util.spec_from_file_location('v232_zegar', os.path.join(root, 'narzedzia', 'zegar.py'))
        cls.Z = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(cls.Z)
        cls.ROOT = root
        cls.NOW = datetime.datetime(2026, 10, 6, 9, 52, tzinfo=datetime.timezone.utc)
        # prawdziwy przebieg 06.10.2026 (API, skrót) i jego oczekujące wdrożenie
        cls.RUN = {'id': 37437793511, 'name': 'Strona i dane', 'status': 'waiting', 'conclusion': None, 'event': 'push',
                   'created_at': '2026-10-06T08:41:24Z', 'run_started_at': '2026-10-06T08:41:24Z', 'updated_at': '2026-10-06T08:47:47Z'}
        cls.PEND = [{'environment': {'name': 'github-pages'}, 'wait_timer': 0, 'wait_timer_started_at': None, 'current_user_can_approve': False, 'reviewers': []}]

    def test_zawieszony(self):
        Z, R, P, N = self.Z, self.RUN, self.PEND, self.NOW
        self.assertEqual((Z.ZAWIESZONY_MIN, Z.ZAWIESZONY_PUSTY_MIN), (15, 60))
        self.assertIn('nikt nie musi zatwierdzać', Z.zawieszony(R, P, N), 'prawdziwy przypadek 06.10: 64 min, bez recenzentów, wait_timer 0')
        self.assertIn('czeka 64 min', Z.zawieszony(R, P, N))
        u = lambda m: {**R, 'updated_at': (N - datetime.timedelta(minutes=m)).strftime('%Y-%m-%dT%H:%M:%SZ')}  # noqa: E731
        self.assertIsNone(Z.zawieszony(u(14), P, N), '14 min — jeszcze nie')
        self.assertIsNotNone(Z.zawieszony(u(15), P, N), '15 min — zawieszony')
        self.assertIsNone(Z.zawieszony(u(300), [{**P[0], 'reviewers': [{'type': 'User', 'reviewer': {'login': 'x'}}]}], N), 'ktoś ma zatwierdzić — nigdy')
        self.assertIsNone(Z.zawieszony(u(300), P + [{**P[0], 'reviewers': [{'type': 'Team'}]}], N), 'jedno z wdrożeń czeka na osobę — nie ruszać')
        t = lambda m: (N - datetime.timedelta(minutes=m)).strftime('%Y-%m-%dT%H:%M:%SZ')  # noqa: E731
        self.assertIsNone(Z.zawieszony(u(40), [{**P[0], 'wait_timer': 30, 'wait_timer_started_at': t(20)}], N), 'licznik czasu środowiska biegnie')
        self.assertIsNotNone(Z.zawieszony(u(40), [{**P[0], 'wait_timer': 30, 'wait_timer_started_at': t(31)}], N), 'licznik minął, a nadal czeka')
        self.assertIsNone(Z.zawieszony(u(40), [{**P[0], 'wait_timer': 30, 'wait_timer_started_at': None}], N), 'licznik bez startu — nie ruszać')
        self.assertIsNone(Z.zawieszony(u(59), [], N), 'pusta lista — cierpliwość 60 min')
        self.assertIn('bez oczekującego wdrożenia', Z.zawieszony(u(60), [], N))
        for zly in ({**R, 'status': 'pending'}, {**R, 'status': 'in_progress'}, {**R, 'updated_at': 'zła data'}, {**R, 'updated_at': None}, None, 'x'):
            self.assertIsNone(Z.zawieszony(zly, P, N), zly)
        for zle in (None, {'x': 1}, 'x', [None], [{**P[0], 'wait_timer': 'x'}], [{**P[0], 'wait_timer': True}], [{**P[0], 'wait_timer': -1}]):
            self.assertIsNone(Z.zawieszony(u(300), zle, N), zle)

    def _run(self, odpowiedzi, env=None, token='ghs_TAJNY_TOKEN_123', now=None):
        log, out = [], io.StringIO()

        def api(path, token_, data=None):
            log.append((path, data))
            for klucz, odp in odpowiedzi:
                if klucz in path:
                    if isinstance(odp, Exception):
                        raise odp
                    return odp
            if path.endswith('/deployment_protection_rules'):   # v235: domyślnie stan 06.10.2026 (bez reguł aplikacji, sama reguła gałęzi)
                return 200, {'total_count': 0, 'custom_deployment_protection_rules': []}
            if '/environments/' in path:
                return 200, {'protection_rules': [{'type': 'branch_policy'}]}
            if path.rsplit('/', 1)[1].isdigit():                   # v235: stan przebiegu po anulowaniu
                return 200, {'status': 'completed'}
            raise AssertionError('nieoczekiwane zapytanie ' + path)
        with mock.patch.dict(os.environ, {'GH_TOKEN': token, **(env or {})}, clear=False), mock.patch.object(self.Z, '_api', api), \
                mock.patch('sys.stdout', out):
            rc = self.Z.main(['zegar.py', 'odblokuj'], now_fn=lambda: now or self.NOW, sleep=lambda s: self.fail('tryb odblokuj nie czeka'))
        self.assertNotIn('TAJNY', out.getvalue(), 'token nigdy w logu')
        return rc, log, out.getvalue()

    def test_odblokuj_06_10(self):
        import urllib.error
        base = '/repos/capitalflowai-app/capitalflowai-app.github.io/actions/'
        rc, log, out = self._run([('runs?status=waiting', (200, {'workflow_runs': [self.RUN]})), ('pending_deployments', (200, self.PEND)),
                                  ('/cancel', (202, {}))])
        self.assertEqual(rc, 0)
        r0 = '/repos/capitalflowai-app/capitalflowai-app.github.io/'
        self.assertEqual([p for p, d in log], [base + 'workflows/strona.yml/runs?status=waiting&per_page=10',
                                               base + 'runs/37437793511/pending_deployments', r0 + 'environments/github-pages',
                                               r0 + 'environments/github-pages/deployment_protection_rules', base + 'runs/37437793511/cancel',
                                               base + 'runs/37437793511'], 'v235: reguły środowiska przed anulowaniem, stan przebiegu po nim')
        self.assertEqual([d for p, d in log if p.endswith('/cancel')], [{}], 'POST (pusta treść)')
        self.assertIn('anulowany (HTTP 202)', out); self.assertIn('GitHub go zamknął', out)   # v239: osobne wiersze
        # GitHub odmawia zwykłego anulowania (409) — force-cancel
        e409 = urllib.error.HTTPError('https://api.github.com/x', 409, 'Conflict', {}, None)
        rc, log, out = self._run([('runs?status=waiting', (200, {'workflow_runs': [self.RUN]})), ('pending_deployments', (200, self.PEND)),
                                  ('/cancel', e409), ('/force-cancel', (202, {}))])
        self.assertEqual([p.rsplit('/', 1)[1] for p, d in log][-3:-1], ['cancel', 'force-cancel']); self.assertIn('anulowany (HTTP 202', out)
        # inny błąd anulowania — bez force-cancel, kod 0, w logu tylko rodzaj
        e403 = urllib.error.HTTPError('https://api.github.com/x', 403, 'Forbidden', {}, None)
        rc, log, out = self._run([('runs?status=waiting', (200, {'workflow_runs': [self.RUN]})), ('pending_deployments', (200, self.PEND)),
                                  ('/cancel', e403)])
        self.assertEqual(rc, 0); self.assertNotIn('force-cancel', ' '.join(p for p, d in log)); self.assertIn('błąd HTTPError', out)

    def test_odblokuj_bez_anulowania(self):
        rc, log, out = self._run([('runs?status=waiting', (200, {'workflow_runs': []}))])
        self.assertEqual((rc, len(log)), (0, 1)); self.assertIn('żaden przebieg nie czeka', out)
        swiezy = {**self.RUN, 'updated_at': '2026-10-06T09:45:00Z'}
        rc, log, out = self._run([('runs?status=waiting', (200, {'workflow_runs': [swiezy]})), ('pending_deployments', (200, self.PEND))])
        self.assertEqual([p for p, d in log if d is not None], [], '7 min — bez anulowania'); self.assertIn('jeszcze nie zawieszony', out)
        osoba = [{**self.PEND[0], 'reviewers': [{'type': 'User'}]}]
        rc, log, out = self._run([('runs?status=waiting', (200, {'workflow_runs': [self.RUN]})), ('pending_deployments', (200, osoba))])
        self.assertEqual([p for p, d in log if d is not None], [], 'zatwierdzenie przez osobę — nigdy')

    def test_odblokuj_bledy_i_wylaczniki(self):
        rc, log, out = self._run([('runs?status=waiting', OSError('Authorization: Bearer ghs_TAJNY_TOKEN_123 refused'))])
        self.assertEqual(rc, 0); self.assertIn('OSError', out)
        # błąd jednego przebiegu nie blokuje drugiego
        r2 = {**self.RUN, 'id': 37437793999}
        odp = [('runs?status=waiting', (200, {'workflow_runs': [self.RUN, r2]})), ('37437793511/pending_deployments', OSError('x')),
               ('37437793999/pending_deployments', (200, self.PEND)), ('37437793999/cancel', (202, {}))]
        rc, log, out = self._run(odp)
        self.assertEqual([p for p, d in log if d is not None], ['/repos/capitalflowai-app/capitalflowai-app.github.io/actions/runs/37437793999/cancel'])
        self.assertIn('przebieg 37437793511: błąd OSError', out)
        for env, tok in (({'ZEGAR_OFF': '1'}, 'ghs_TAJNY_TOKEN_123'), ({}, '')):
            rc, log, out = self._run([], env=env, token=tok)
            self.assertEqual((rc, log), (0, []), f'{env} / token {bool(tok)}: żadnego zapytania')
        with mock.patch('sys.stdout', io.StringIO()) as o:
            self.assertEqual(self.Z.main(['zegar.py', 'cos']), 2)
        self.assertIn('odblokuj', o.getvalue(), 'tryb w podpowiedzi użycia')

    def test_workflow_zegara(self):
        z = open(os.path.join(self.ROOT, '.github', 'workflows', 'zegar.yml'), encoding='utf-8').read()
        i, j, k = (z.index('python3 narzedzia/zegar.py dzienne'), z.index('python3 narzedzia/zegar.py odblokuj'),
                   z.index('python3 narzedzia/zegar.py prowadz'))
        self.assertLess(i, j); self.assertLess(j, k, 'odblokowanie przed czuwaniem (czuwanie widzi już przebieg, który ruszył po anulowaniu)')
        krok = z[z.rindex('- name:', 0, j):z.index('- name:', j)]
        for frag in ('GH_TOKEN: ${{ github.token }}', 'ZEGAR_OFF: ${{ vars.ZEGAR_OFF }}', 'zegar.py odblokuj || echo'):
            self.assertIn(frag, krok, frag)
        self.assertIn('actions: write', z); self.assertNotIn('secrets.', z)
        self.assertIn('v232', _rwc150_txt(os.path.join(self.ROOT, 'narzedzia', 'zegar.py')))


class KontrolaZawieszonaV232(unittest.TestCase):
    """v232: kontrola dzienna — przebieg „Strona i dane” w stanie waiting od ≥ 30 min = uwaga, od ≥ 120 min = błąd z podpowiedzią."""

    @classmethod
    def setUpClass(cls):
        import importlib.util, tempfile
        cls.tmp = tempfile.mkdtemp(prefix='kontrola232-')
        os.environ['KONTROLA_DIR'] = os.path.join(cls.tmp, 'kontrola'); os.environ['KONTROLA_ARCH'] = os.path.join(cls.tmp, 'archiwum')
        spec = importlib.util.spec_from_file_location('v232_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        cls.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(cls.k)
        cls.NOW = datetime.datetime(2026, 10, 6, 9, 52, tzinfo=datetime.timezone.utc)

    def _r(self, i, min_temu, status='completed', wynik='success', czeka_min=None, nazwa='Strona i dane'):
        t = (self.NOW - datetime.timedelta(minutes=min_temu)).strftime('%Y-%m-%dT%H:%M:%SZ')
        u = (self.NOW - datetime.timedelta(minutes=czeka_min)).strftime('%Y-%m-%dT%H:%M:%SZ') if czeka_min is not None else t
        return {'id': i, 'name': nazwa, 'status': status, 'conclusion': wynik, 'run_started_at': t, 'updated_at': u}

    def seria(self):
        return [self._r(2000 + j, 5 + 10 * j) for j in range(60)]

    def test_progi(self):
        k = self.k
        self.assertEqual((k.WAIT_UWAGA_MIN, k.WAIT_BLAD_MIN), (30, 120))
        A, b, u = k.przebiegi_ocena([self._r(1, 70, 'waiting', None, czeka_min=64)] + self.seria(), self.NOW)
        self.assertEqual(b, []); w = [x for x in u if x.startswith('publikacja czeka')]
        self.assertEqual(len(w), 1, u); self.assertIn('od 64 min', w[0]); self.assertIn('zegar zapasowy', w[0])
        A, b, u = k.przebiegi_ocena([self._r(1, 130, 'waiting', None, czeka_min=125)] + self.seria(), self.NOW)
        self.assertEqual(len(b), 1, b); self.assertTrue(b[0].startswith('publikacja zawieszona'), b)
        self.assertIn('2 godz.', b[0]); self.assertFalse([x for x in u if x.startswith('publikacja czeka')], 'błąd zamiast uwagi, nie oba')
        h = k.co_zrobic(b)
        self.assertEqual(len(h), 1); self.assertIn('Cancel workflow', h[0]); self.assertIn('Waiting', h[0])
        for czeka in (0, 29):
            A, b, u = k.przebiegi_ocena([self._r(1, 40, 'waiting', None, czeka_min=czeka)] + self.seria(), self.NOW)
            self.assertEqual(b, []); self.assertFalse([x for x in u if x.startswith('publikacja')], f'{czeka} min — nic')
        A, b, u = k.przebiegi_ocena([self._r(1, 300, 'waiting', None, czeka_min=290, nazwa='Kontrola strony (codziennie)')] + self.seria(), self.NOW)
        self.assertFalse([x for x in b + u if x.startswith('publikacja')], 'inne zadanie — nie ta kontrola')
        A, b, u = k.przebiegi_ocena([{**self._r(1, 300, 'waiting', None), 'updated_at': 'zła data'}] + self.seria(), self.NOW)
        self.assertFalse([x for x in b + u if x.startswith('publikacja')], 'zła data — bez zgadywania')
        # przebieg czekający dłużej niż doba (poza oknem 24 h liczników) — nadal zgłoszony
        A, b, u = k.przebiegi_ocena([self._r(1, 1600, 'waiting', None, czeka_min=1590)] + self.seria(), self.NOW)
        self.assertTrue(b and b[0].startswith('publikacja zawieszona'), b)


# ===================== v233: POPRAWKI PO PRZEGLĄDZIE v229–v231 =====================
class PoPrzegladzieV233(unittest.TestCase):
    """v233: podział jednostek — ponad 15% w dobę tylko z poprawionym NAV i jednym pasującym ułamkiem; kursy z inną bazą w kontroli."""

    def test_podzial_bez_poprawki_nav_bliskie_ulamki(self):
        self.assertEqual((zd.FUND_STALE_U, zd.FUND_STALE_N), (0.02, 0.03))   # v235: NAV ±3%
        for k in (4 / 3, 1.25, 0.75, 0.8, 1.5, 2 / 3, 2.0, 0.5):                 # jednostki ×k, NAV bez zmian (podział bez poprawki NAV)
            for nav in (1.0, 0.995, 1.005):
                self.assertEqual(zd.fund_split([0, 100.0, 1_000_000], [0, 100.0 * nav, 1_000_000 * k]), 0, f'jednostki ×{k:.3f}, NAV ×{nav} — skok')
        # przegląd: fundusz 10 mld USD, NAV dzień spóźniony — dawniej +3 333 mln USD (4:3) i −25% zwrotu następnego dnia
        h = [['2026-06-01', 100.0, 1e8], ['2026-06-02', 100.0, 1e8 * 4 / 3], ['2026-06-03', 75.0, 1e8 * 4 / 3], ['2026-06-04', 75.1, 1e8 * 4 / 3]]
        fl = zd.fund_flows(h, bez=())
        self.assertNotIn('2026-06-02', fl); self.assertNotIn('2026-06-03', fl, 'NAV poprawiony dzień później — skok NAV, brak')
        self.assertAlmostEqual(fl['2026-06-04'], 0.0)
        self.assertEqual(zd.fund_pary(h), [0, 0, 1], 'podział na dwa dni (jednostki, potem NAV) — obie pary skok (druga — wstecz)')
        d, px, ret = zd._td_fund_px(h)
        self.assertEqual(ret[:3], [None, None, None], 'bez fałszywego zwrotu −25% w dniu poprawki NAV'); self.assertAlmostEqual(ret[3], 0.1 / 75 * 100)
        h2 = [['2026-06-01', 100.0, 1e8], ['2026-06-02', 75.0, 1e8], ['2026-06-03', 75.0, 1e8 * 4 / 3], ['2026-06-04', 75.1, 1e8 * 4 / 3]]
        self.assertEqual(zd.fund_pary(h2), [1, 0, 1], 'odwrotnie (NAV, potem jednostki): v239 — pierwszy dzień nie do poznania (jak krach)')
        self.assertEqual(sorted(zd.fund_flows(h2, bez=())), ['2026-06-02', '2026-06-04'], 'przepływ 06-02 = 0 (jednostki bez zmian) — prawdziwy')
        for n in range(2, len(h) + 1):                                              # przyczynowo: para liczona z wierszy do jej końca
            self.assertEqual(zd.fund_pary(h[:n]), zd.fund_pary(h)[:n - 1], n)
        h3 = [['2026-06-01', 100.0, 1e8], ['2026-06-02', 100.0, 1e8 * 3], ['2026-06-03', 100.4, 1e8 * 3]]   # skok bez podziału (błąd liczby)
        self.assertEqual(zd.fund_pary(h3), [0, 1], 'zwykły skok — sąsiedni dzień bez zmian (dwa dni razem to nie podział)')
        import random
        rnd = random.Random(233); h4 = [['d000', 100.0, 1e6]]
        for i in range(1, 300):
            h4.append(['d%03d' % i, h4[-1][1] * (1 + rnd.gauss(0, 0.012)), h4[-1][2] * (1 + rnd.gauss(0, 0.01))])
        self.assertEqual(zd.fund_pary(h4), [zd.fund_split(a, b) for a, b in zip(h4, h4[1:])], 'zwykłe dane — jak fund_split dzień po dniu')

    def test_ulamek_jednoznaczny(self):
        F = zd.fund_split
        self.assertEqual(F([0, 100.0, 1e6], [0, 80.0, 1.25e6]), 1.25, 'czysty 5:4')
        self.assertEqual(F([0, 100.0, 1e6], [0, 75.0, 1e6 * 4 / 3]), 4 / 3, 'czysty 4:3')
        self.assertEqual(F([0, 100.0, 1e6], [0, 80.0, 1.25e6 * 1.03]), 1.25, '5:4 i napływ 3% — nadal 5:4 (dawniej 4:3)')
        self.assertEqual(F([0, 100.0, 1e6], [0, 80.0, 1.25e6 * 1.05]), 0, '5:4 i napływ 5% — 4:3 też możliwy po liczbie jednostek: skok, nie zgadywanie')
        self.assertEqual(F([0, 100.0, 1e6], [0, 76.8, 1.25e6 * 1.03]), 0, '5:4, napływ 3%, NAV −4% — pasują dwa ułamki: skok (brak), nie zły przepływ')
        self.assertEqual(F([0, 100.0, 1e6], [0, 75.0, 1e6 * 4 / 3 * 1.08]), 0, '4:3 i napływ 8% — dawniej 3:2 (zły przepływ)')
        self.assertEqual(F([0, 100.0, 1e6], [0, 75.0, 1e6 * 4 / 3 * 1.03]), 4 / 3, '4:3 i napływ 3%')
        self.assertEqual(F([0, 100.0, 1e6], [0, 50.0 * 1.02, 2e6 * 1.03]), 2, '2:1 z napływem 3% i zwrotem 2%')
        self.assertEqual(F([0, 100.0, 1e6], [0, 50.0 * 0.93, 2e6]), 2, '2:1 w dniu spadku o 7% — v235: ±10% dla ułamków nie do pomylenia')
        for nr, sr in ((1.0, 1.104), (1.0, 0.9142), (0.847, 1.0), (1.127, 1.0), (1.0306, 1.2272), (1.0087, 1.1648), (1.037, 1.1457)):   # prawdziwe dni (FXI X 2024 …)
            self.assertEqual(F([0, 100.0, 1e6], [0, 100.0 * nr, 1e6 * sr]), 1, (nr, sr))

    def test_prawdziwe_podzialy_2025_12_05(self):
        for nr, sr in ((0.4953, 2.0146), (0.498, 1.9977), (0.5038, 1.9969), (0.5027, 1.9499)):   # XLU, XLE, XLK, XLY
            self.assertEqual(zd.fund_split([0, 100.0, 1e6], [0, 100.0 * nr, 1e6 * sr]), 2, (nr, sr))

    def test_kontrola_kursy_inna_baza(self):
        import importlib.util, tempfile
        tmp = tempfile.mkdtemp(prefix='kontrola233-')
        with mock.patch.dict(os.environ, {'KONTROLA_DIR': os.path.join(tmp, 'k'), 'KONTROLA_ARCH': os.path.join(tmp, 'a')}):
            spec = importlib.util.spec_from_file_location('v233_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
            k = importlib.util.module_from_spec(spec); spec.loader.exec_module(k)
        H = {'2026-10-02': {'EUR': 0.85, 'JPY': 150.0}}
        ok = {'EUR': 0.85, 'JPY': 150.0}
        f = k.fx_porownanie({'fx': {'now': {'base': None, 'date': '2026-10-02', 'rates': ok}}}, H)
        self.assertEqual(f['baza'], [['now', 'brak']], 'pole base puste — ⚠️ (strona też odrzuca)')
        f = k.fx_porownanie({'fx': {'now': {'date': '2026-10-02', 'rates': ok}}}, H)
        self.assertIsNone(f, 'bez pola base (stary format) i bez bazy USD — bez porównania, bez ostrzeżenia (jak dotąd)')
        base = {'at': '2026-10-06T10:00:00+00:00', 'wynik': 'UWAGA', 'bledy': [], 'uwagi': ['x'], 'meta': {}, 'strona': {}, 'zrodla': []}
        r = k.raport_md(dict(base, zgodnosc={'fx': {'daty': [], 'zle': [], 'med_zle': [], 'baza': [['now', 'EUR'], ['1M', 'EUR']]}}))
        self.assertIn('- Kursy walut (plik strony vs H.10 Fed): migawki z walutą bazową inną niż USD (now (EUR), 1M (EUR)) — bez porównania ⚠️.', r)
        r = k.raport_md(dict(base, zgodnosc={'fx': {'daty': [['2026-10-02', 2, 0.1, 'JPY', 0.2]], 'zle': [], 'med_zle': [], 'baza': [['1T', 'EUR']]}}))
        self.assertIn('; migawki z inną walutą bazową: 1T (EUR) ⚠️.', r)
        r = k.raport_md(dict(base, zgodnosc={'fx': {'daty': [['2026-10-02', 2, 0.1, 'JPY', 0.2]], 'zle': [], 'med_zle': [], 'baza': []}}))
        self.assertIn('najwięcej JPY +0,20% ✅.', r)


# ===================== v235: POPRAWKI PO PRZEGLĄDZIE v232–v233 =====================
class PoPrzegladzieV235(unittest.TestCase):
    """v235: podział bez poprawki NAV także w dni ruchu ceny (±3%), lustro (NAV przed jednostkami), tolerancja NAV wg ułamka; kontrola i zegar."""

    def test_podzial_bez_poprawki_nav_w_dni_ruchu(self):
        F = zd.fund_split
        self.assertEqual((zd.FUND_STALE_U, zd.FUND_STALE_N), (0.02, 0.03))
        for k in (4 / 3, 1.25, 0.75, 0.8):
            for nav in (0.985, 1.015, 0.975, 1.025):                                 # przegląd: 4:3 przy NAV −1,5% dawał +33% aktywów
                self.assertEqual(F([0, 100.0, 1e6], [0, 100.0 * nav, 1e6 * k]), 0, f'jednostki ×{k:.3f}, NAV ×{nav}')
        self.assertEqual(F([0, 100.0, 1e6], [0, 103.06, 1.2272e6]), 1, 'FXI 04.10.2024 (NAV +3,06%) — prawdziwy napływ, nadal zwykły dzień')

    def test_lustro_nav_przed_jednostkami(self):
        F = zd.fund_split
        for k in (4 / 3, 1.25, 0.75, 0.8):
            for u in (1.0, 1.015, 0.985):   # v239: sam dzień „NAV przed jednostkami” nie do odróżnienia od krachu — zwykły dzień,
                exp = 1 if 1 / zd.FUND_PARA_X < u / k < zd.FUND_PARA_X else 0   # chyba że aktywa zmieniły się ponad 1,35× (v231)
                self.assertEqual(F([0, 100.0, 1e6], [0, 100.0 / k, 1e6 * u]), exp, f'NAV ×{1 / k:.3f} przy jednostkach ×{u}')
        self.assertEqual(F([0, 100.0, 1e6], [0, 84.7, 1e6]), 1, 'srebro −15,3% — zwykły dzień')
        self.assertEqual(F([0, 100.0, 1e6], [0, 77.0, 1e6]), 1, '−23% (np. krach) — poza ±2% od ×0,75 i ×0,8: zwykły dzień')
        h = [['2026-06-01', 100.0, 1e8], ['2026-06-02', 75.0, 1e8], ['2026-06-03', 75.0, 1e8 * 4 / 3], ['2026-06-04', 75.1, 1e8 * 4 / 3]]
        self.assertEqual(zd.fund_pary(h), [1, 0, 1], 'NAV, potem jednostki — v239: pierwszy dzień nie do poznania (jak krach), drugi skok')
        self.assertEqual(zd._td_fund_px(h)[2][2], None)
        h2 = [['2026-06-01', 100.0, 1e8], ['2026-06-02', 100.0, 1e8 * 4 / 3], ['2026-06-03', 100.3, 1e8 * 4 / 3], ['2026-06-04', 75.2, 1e8 * 4 / 3]]
        P = zd.fund_pary(h2)
        self.assertEqual((P[0], P[2]), (0, 0), 'NAV poprawiony dwa dni później — bez przepływu +33% i bez zwrotu −25%')
        self.assertNotIn(None, [zd._td_fund_px(h2)[2][2]], 'dzień między nogami — zwykły ruch')

    def test_tolerancja_nav_wg_ulamka(self):
        F = zd.fund_split
        self.assertEqual(F([0, 100.0, 1e6], [0, 50.0 * 0.93, 2e6]), 2, '2:1 w dniu spadku o 7% — rozpoznany (±10% dla ułamków nie do pomylenia)')
        self.assertEqual(F([0, 100.0, 1e6], [0, 50.0 * 1.08, 2e6 * 0.99]), 2)
        self.assertEqual(F([0, 100.0, 1e6], [0, 50.0 * 0.85, 2e6]), 0, 'NAV −15% przy 2:1 — skok')
        self.assertEqual(F([0, 100.0, 1e6], [0, 80.0, 1.25e6 * 1.03]), 1.25, '5:4 i napływ 3% — nadal jednoznaczny')
        self.assertEqual(F([0, 100.0, 1e6], [0, 75.0 * 0.93, 1e6 * 4 / 3]), 0, '4:3 przy NAV −7% — bliski ułamek: tylko ±5%')

    def test_cena_tygodniowa_fund_pary_z_calej_historii(self):
        import inspect
        src = inspect.getsource(zd)
        self.assertIn('P = fund_pary(best[1])', src); self.assertIn('reversed(P[-(len(h) - 1):])', src)

    def test_kontrola_baza_bez_h10(self):
        import importlib.util, tempfile
        tmp = tempfile.mkdtemp(prefix='kontrola235-')
        with mock.patch.dict(os.environ, {'KONTROLA_DIR': os.path.join(tmp, 'k'), 'KONTROLA_ARCH': os.path.join(tmp, 'a')}):
            spec = importlib.util.spec_from_file_location('v235_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
            k = importlib.util.module_from_spec(spec); spec.loader.exec_module(k)
        ok = {'EUR': 0.85}
        r = {'fx': {'now': {'base': 'EUR', 'date': '2026-10-02', 'rates': ok}, '1M': {'base': '', 'date': '2026-09-02', 'rates': ok},
                    '1D': {'base': 'USD', 'date': '2026-10-01', 'rates': ok}, '1T': {'date': '2026-09-25', 'rates': ok}}}
        self.assertEqual(k.fx_baza(r), [['now', 'EUR'], ['1M', 'brak']], 'pusta baza = „brak”; bez pola base (stary format) — bez uwagi')
        self.assertEqual(k.fx_baza({}), []); self.assertEqual(k.fx_baza({'fx': 'x'}), [])
        self.assertEqual(k.fx_porownanie(r, {})['baza'], [['now', 'EUR'], ['1M', 'brak']], 'H.10 puste — ostrzeżenie o bazie zostaje')
        self.assertIsNone(k.fx_porownanie({'fx': {'1T': {'date': '2026-09-25', 'rates': ok}}}, {}))
        base = {'at': '2026-10-06T10:00:00+00:00', 'wynik': 'UWAGA', 'bledy': [], 'uwagi': ['x'], 'meta': {}, 'strona': {}, 'zrodla': []}
        t = k.raport_md(dict(base, zgodnosc={'fx': {'brak': 'H.10: timed out', 'baza': [['now', 'EUR']]}}))
        self.assertIn('- Kursy walut (plik strony vs H.10 Fed): brak porównania (H.10: timed out) ℹ️; migawki z walutą bazową inną niż USD: now (EUR) ⚠️.', t)
        self.assertIn('- Kursy walut (plik strony vs H.10 Fed): brak porównania (x) ℹ️.', k.raport_md(dict(base, zgodnosc={'fx': {'brak': 'x'}})))

    def test_kontrola_recenzent(self):
        import importlib.util, tempfile
        tmp = tempfile.mkdtemp(prefix='kontrola235r-')
        with mock.patch.dict(os.environ, {'KONTROLA_DIR': os.path.join(tmp, 'k'), 'KONTROLA_ARCH': os.path.join(tmp, 'a')}):
            spec = importlib.util.spec_from_file_location('v235_kr', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
            k = importlib.util.module_from_spec(spec); spec.loader.exec_module(k)
        NOW = datetime.datetime(2026, 10, 6, 12, 0, tzinfo=datetime.timezone.utc)
        f = lambda m: (NOW - datetime.timedelta(minutes=m)).strftime('%Y-%m-%dT%H:%M:%SZ')  # noqa: E731
        runs = [{'id': 7, 'name': 'Strona i dane', 'status': 'waiting', 'conclusion': None, 'run_started_at': f(200), 'updated_at': f(190)}] + \
               [{'id': 100 + j, 'name': 'Strona i dane', 'status': 'completed', 'conclusion': 'success', 'run_started_at': f(5 + 10 * j), 'updated_at': f(3 + 10 * j)} for j in range(40)]
        A, b, u = k.przebiegi_ocena(runs, NOW, None, {7: [{'environment': {'name': 'github-pages'}, 'wait_timer': 0, 'reviewers': [{'type': 'User'}]}]})
        self.assertEqual(b, [], 'czeka na osobę — nie „zawieszona”')
        w = [x for x in u if x.startswith('publikacja czeka')]
        self.assertEqual(len(w), 1); self.assertIn('zatwierdzenie przez osobę', w[0]); self.assertIn('Review deployments', w[0])
        A, b, u = k.przebiegi_ocena(runs, NOW, None, {7: [{'wait_timer': 0, 'reviewers': []}]})
        self.assertTrue(b and b[0].startswith('publikacja zawieszona'), 'bez recenzenta — jak w v232')
        A, b, u = k.przebiegi_ocena(runs, NOW)
        self.assertTrue(b and b[0].startswith('publikacja zawieszona'), 'bez odczytu oczekujących wdrożeń — jak w v232')


class ZegarOdblokujV235(unittest.TestCase):
    """v235: reguły środowiska przed anulowaniem; po anulowaniu czekanie, aż GitHub zamknie przebieg. Bez sieci (_api atrapą)."""

    @classmethod
    def setUpClass(cls):
        import importlib.util
        root = os.path.dirname(os.path.abspath(__file__))
        spec = importlib.util.spec_from_file_location('v235_zegar', os.path.join(root, 'narzedzia', 'zegar.py'))
        cls.Z = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(cls.Z)
        cls.NOW = datetime.datetime(2026, 10, 6, 9, 52, tzinfo=datetime.timezone.utc)
        cls.RUN = {'id': 37437793511, 'name': 'Strona i dane', 'status': 'waiting', 'updated_at': '2026-10-06T08:47:47Z'}
        cls.PEND = [{'environment': {'name': 'github-pages'}, 'wait_timer': 0, 'wait_timer_started_at': None, 'reviewers': []}]

    def test_srodowisko_ok(self):
        Z = self.Z
        self.assertTrue(Z.srodowisko_ok({'protection_rules': [{'type': 'branch_policy'}]}, {'total_count': 0}), 'stan 06.10.2026')
        self.assertTrue(Z.srodowisko_ok({'protection_rules': [{'type': 'branch_policy'}, {'type': 'wait_timer', 'wait_timer': 5}]}, {'total_count': 0}))
        self.assertTrue(Z.srodowisko_ok({'protection_rules': []}, {'total_count': 0}))
        for env, wl in (({'protection_rules': [{'type': 'required_reviewers'}]}, {'total_count': 0}),
                        ({'protection_rules': [{'type': 'branch_policy'}]}, {'total_count': 1}),
                        ({'protection_rules': [{'type': 'cos_nowego'}]}, {'total_count': 0}),
                        ({}, {'total_count': 0}), (None, None), ({'protection_rules': [{'type': 'branch_policy'}]}, {'total_count': True})):
            self.assertFalse(Z.srodowisko_ok(env, wl), (env, wl))

    def _run(self, odp, sleeps):
        log, out = [], io.StringIO()

        def api(path, token_, data=None):
            log.append((path, data))
            for klucz, o in odp:
                if klucz in path:
                    if isinstance(o, Exception):
                        raise o
                    return o() if callable(o) else o
            raise AssertionError('nieoczekiwane zapytanie ' + path)
        with mock.patch.dict(os.environ, {'GH_TOKEN': 'ghs_TAJNY'}, clear=False), mock.patch.object(self.Z, '_api', api), mock.patch('sys.stdout', out):
            rc = self.Z.main(['zegar.py', 'odblokuj'], now_fn=lambda: self.NOW, sleep=sleeps.append)
        self.assertNotIn('TAJNY', out.getvalue())
        return rc, log, out.getvalue()

    def test_recenzent_albo_aplikacja_nie_anuluje(self):
        for env, wl in (({'protection_rules': [{'type': 'required_reviewers'}]}, {'total_count': 0}),
                        ({'protection_rules': [{'type': 'branch_policy'}]}, {'total_count': 2})):
            sl = []
            rc, log, out = self._run([('runs?status=waiting', (200, {'workflow_runs': [self.RUN]})), ('pending_deployments', (200, self.PEND)),
                                      ('/deployment_protection_rules', (200, wl)), ('/environments/github-pages', (200, env))], sl)
            self.assertEqual([p for p, d in log if d is not None], [], 'bez anulowania'); self.assertIn('nie anuluję', out)

    def test_czeka_az_github_zamknie(self):
        stany = iter(['in_progress', 'in_progress', 'completed'])
        sl = []
        rc, log, out = self._run([('runs?status=waiting', (200, {'workflow_runs': [self.RUN]})), ('pending_deployments', (200, self.PEND)),
                                  ('/deployment_protection_rules', (200, {'total_count': 0})), ('/environments/github-pages', (200, {'protection_rules': [{'type': 'branch_policy'}]})),
                                  ('/cancel', (202, {})), ('/actions/runs/37437793511', lambda: (200, {'status': next(stany)}))], sl)
        self.assertEqual(sl, [self.Z.ODBLOKUJ_KROK_S] * 2, 'czeka, aż przebieg będzie zakończony')
        self.assertIn('anulowany (HTTP 202)', out); self.assertIn('GitHub go zamknął', out)
        sl = []
        rc, log, out = self._run([('runs?status=waiting', (200, {'workflow_runs': [self.RUN]})), ('pending_deployments', (200, self.PEND)),
                                  ('/deployment_protection_rules', (200, {'total_count': 0})), ('/environments/github-pages', (200, {'protection_rules': [{'type': 'branch_policy'}]})),
                                  ('/cancel', (202, {})), ('/actions/runs/37437793511', (200, {'status': 'in_progress'}))], sl)
        self.assertEqual(sum(sl), self.Z.ODBLOKUJ_CZEKAJ_S, 'najwyżej 60 s'); self.assertIn('GitHub jeszcze go zamyka', out)


# ===================== v237/v242: KONTROLA — NOWE RAPORTY DOWODU REZERW GIEŁD =====================
class KontrolaNoweRaportyV237(unittest.TestCase):
    """v237/v242: OKX i Bybit — najpierw plik obecnej listy (próba kontrolna), potem pierwsze 1 024 bajty plików z datą w nazwie, od najnowszej;
    trafienie tylko z podpisem pliku; „nie ma” tylko kodem giełdy; KuCoin — data audytu z publicznego JSON; brak odpowiedzi = „nie wiadomo”.
    Bez sieci (get atrapą), bez czekania (spij atrapą)."""

    @classmethod
    def setUpClass(cls):
        import importlib.util, tempfile
        tmp = tempfile.mkdtemp(prefix='kontrola237-')
        with mock.patch.dict(os.environ, {'KONTROLA_DIR': os.path.join(tmp, 'k'), 'KONTROLA_ARCH': os.path.join(tmp, 'a')}):
            spec = importlib.util.spec_from_file_location('v237_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
            cls.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(cls.k)
        cls.BY = 'https://www.bybit.com/common-static/cht-static/por/Bybit_PoR_Audit_2026_Sep_23.pdf'
        cls.G = {'OKX': {'since': '2026-09-08'}, 'Bybit': {'since': '2026-09-23', 'url': cls.BY}, 'KuCoin': {'since': '2026-08-31', 'url': 'https://old/k.pdf'},
                 'Binance': {'since': '2022-11'}}

    def _get(self, jest=(), kucoin=None, log=None, wszystko=None):
        import urllib.error
        jest = tuple(jest) + ('por_csv_2026090800_V1', 'Bybit_PoR_Audit_2026_Sep_23.pdf', 'Bybit_PoR_Audit_2026_Sep_10.pdf')   # pliki obecnych list

        def get(url, timeout=25, headers=None, limit=None):
            if log is not None:
                log.append((url, headers, limit))
            if url == self.k.WH_NOWE_KUCOIN:
                if isinstance(kucoin, Exception):
                    raise kucoin
                return 200, json.dumps(kucoin).encode(), 5
            self.assertEqual((headers, limit), ({'Range': 'bytes=0-1023'}, 1024), 'nigdy cały plik')
            if wszystko is not None:
                return wszystko(url)
            if any(x in url for x in jest):
                return 206, (b'PK\x03\x04' if 'okx' in url else b'%PDF-1.7') + b'x' * 1000, 5
            raise urllib.error.HTTPError(url, 403 if 'bybit' in url else 404, 'x', {'Server': 'AmazonS3'} if 'bybit' in url else {}, None)
        return get

    def run_w(self, now, **kw):
        k = self.k
        with mock.patch.object(k, 'get', self._get(**kw)):
            return k.wh_nowe_raporty(self.G, now, spij=lambda s: None)

    def test_06_10_stan(self):
        k, log = self.k, []
        now = datetime.datetime(2026, 10, 6, 7, 0, tzinfo=datetime.timezone.utc)
        kuc = {'success': True, 'data': {'latestAuditDate': 1790783999000, 'auditReportUrl': None}}   # 30.09.2026 15:59 UTC
        W = self.run_w(now, kucoin=kuc, log=log)
        self.assertEqual(sorted(W), ['Bybit', 'KuCoin', 'OKX'], 'tylko giełdy z raportem miesięcznym')
        self.assertEqual((W['OKX']['nowy'], W['OKX']['prob'], W['OKX']['nie_wiadomo'], W['OKX']['kontrola']), (None, 9, 0, True))
        self.assertEqual(log[0][0], 'https://static.okx.com/cdn/okx/por/chain/por_csv_2026090800_V1.zip', 'najpierw plik obecnej listy')
        self.assertEqual(log[1][0], 'https://static.okx.com/cdn/okx/por/chain/por_csv_2026100600_V1.zip', 'potem od najnowszej daty')
        self.assertEqual((W['Bybit']['nowy'], W['Bybit']['prob'], W['Bybit']['kontrola']), (None, 0, None), 'Bybit: za wcześnie — bez zapytań')
        self.assertEqual((W['KuCoin']['nowy'], W['KuCoin']['lista']), ('2026-09-30', False), 'KuCoin: audyt 30.09, bez raportu z listą')
        w = k.wh_nowe_wiersz(W)
        self.assertIn('OKX — brak nowszego w dniach 2026-09-28–2026-10-06 ✅', w); self.assertIn('Bybit — sprawdzanie od 2026-10-13 (raport miesięczny)', w)
        self.assertIn('KuCoin — audyt z 2026-09-30, raport z listą portfeli jeszcze niedostępny ℹ️', w)

    def test_nowy_raport(self):
        k = self.k
        now = datetime.datetime(2026, 10, 25, 7, 0, tzinfo=datetime.timezone.utc)
        kuc = {'data': {'latestAuditDate': 1790783999000, 'auditReportUrl': 'https://x/y.pdf'}}
        W = self.run_w(now, jest=('por_csv_2026100800_V1', 'Bybit_PoR_Audit_2026_Oct_5.pdf'), kucoin=kuc)
        self.assertEqual((W['OKX']['nowy'], W['OKX']['lista'], W['OKX']['prob']), ('2026-10-08', True, 18))
        self.assertEqual(W['Bybit']['nowy'], None, '05.10 to mniej niż 20 dni po 23.09 — poza oknem')
        self.assertEqual((W['KuCoin']['nowy'], W['KuCoin']['lista']), ('2026-09-30', True))
        W2 = self.run_w(now, kucoin={'data': {'latestAuditDate': 1790783999000, 'auditReportUrl': 'https://old/k.pdf'}})
        self.assertEqual(W2['KuCoin']['lista'], False, 'v242: ten sam link co obecna lista — nic nowego')
        with mock.patch.object(k, 'get', self._get(jest=('Bybit_PoR_Audit_2026_Oct_5.pdf',), kucoin=kuc)):
            W3 = k.wh_nowe_raporty(dict(self.G, Bybit={'since': '2026-09-10'}), now, spij=lambda s: None)
        self.assertEqual(W3['Bybit']['nowy'], '2026-10-05', 'dzień jednocyfrowy — także zapis bez zera')
        self.assertIn('OKX — nowy raport z listą portfeli z 2026-10-08 (obecna z 2026-09-08) ⚠️', k.wh_nowe_wiersz(W))

    def test_blokada_i_strona_html(self):
        import urllib.error
        k = self.k
        now = datetime.datetime(2026, 10, 12, 7, 0, tzinfo=datetime.timezone.utc)

        def zabl(url):
            raise urllib.error.HTTPError(url, 403, 'Forbidden', {}, None)
        W = self.run_w(now, kucoin={'data': {}}, wszystko=zabl)
        self.assertEqual((W['OKX']['nowy'], W['OKX']['kontrola'], W['OKX']['prob'], W['OKX']['nie_wiadomo']), (None, 'brak', 0, 1), 'przegląd v237: 403 na wszystko')
        w = k.wh_nowe_wiersz(W)
        self.assertIn('OKX — nie wiadomo (plik obecnej listy nie odpowiada plikiem — możliwa blokada serwera) ℹ️', w)
        self.assertNotIn('brak nowszego', w, 'nigdy „brak nowszego” bez odpowiedzi plikiem')
        W = self.run_w(now, kucoin={'data': {}}, wszystko=lambda url: (200, b'<!DOCTYPE html><html>' + b'x' * 900, 5))
        self.assertEqual((W['OKX']['nowy'], W['OKX']['kontrola']), (None, 'brak'), 'strona HTML z kodem 200 to nie plik — bez fałszywego „nowa lista”')
        self.assertFalse([o for o in W.values() if o.get('nowy') and o.get('lista')])

    def test_plik_jest(self):
        import urllib.error
        k = self.k

        def odp(st=None, body=b'', kod=None):
            def get(url, timeout=25, headers=None, limit=None):
                if kod:
                    raise urllib.error.HTTPError(url, kod, 'x', {'Server': 'AmazonS3'}, None)
                return st, body, 5
            return get
        for g, kod, exp in (('OKX', 404, False), ('OKX', 403, None), ('Bybit', 403, False), ('Bybit', 404, False), ('Bybit', 429, None), ('OKX', 500, None)):
            with mock.patch.object(k, 'get', odp(kod=kod)):
                self.assertEqual(k.wh_plik_jest('u', g), exp, (g, kod))
        for g, body, exp in (('OKX', b'PK\x03\x04abc', True), ('OKX', b'%PDF', None), ('Bybit', b'%PDF-1.7', True), ('Bybit', b'<html>', None)):
            with mock.patch.object(k, 'get', odp(206, body)):
                self.assertEqual(k.wh_plik_jest('u', g), exp, (g, body))

    def test_bledy_i_limit(self):
        import urllib.error
        k = self.k
        now = datetime.datetime(2026, 10, 12, 7, 0, tzinfo=datetime.timezone.utc)

        def zly(url, timeout=25, headers=None, limit=None):
            raise urllib.error.URLError('timed out')
        with mock.patch.object(k, 'get', zly):
            W = k.wh_nowe_raporty(self.G, now, spij=lambda s: None)
        self.assertEqual((W['OKX']['nowy'], W['OKX']['nie_wiadomo'], W['OKX']['prob']), (None, 1, 0), 'brak odpowiedzi — nie wiadomo, bez dalszych prób')
        self.assertEqual(W['KuCoin']['nie_wiadomo'], 1)
        t = iter([0.0] + [1000.0] * 100)
        with mock.patch.object(k, 'get', self._get(kucoin={'data': {}})):
            W = k.wh_nowe_raporty(self.G, now, zegar=lambda: next(t), spij=lambda s: None)
        self.assertTrue(W['OKX']['przerwane'] and W['KuCoin']['przerwane'], 'limit czasu — koniec prób (także KuCoin)')
        self.assertIn('OKX — sprawdzanie przerwane (limit czasu) ℹ️', k.wh_nowe_wiersz(W))

        def stara(url, timeout=25, headers=None):   # zaślepka bez parametru limit (stare testy całej kontroli) — nie wiadomo, bez sieci
            raise AssertionError('nieoczekiwany adres ' + url)
        with mock.patch.object(k, 'get', stara):
            W = k.wh_nowe_raporty(self.G, now, spij=lambda s: None)
        self.assertTrue(all(o['nowy'] is None for o in W.values()))
        self.assertEqual(k.wh_nowe_raporty(None, now), {}); self.assertEqual(k.wh_nowe_raporty({'OKX': {'since': 'x'}}, now), {})
        pauzy = []
        with mock.patch.object(k, 'get', self._get(kucoin={'data': {}})):
            k.wh_nowe_raporty(self.G, now, spij=pauzy.append)
        self.assertTrue(pauzy and set(pauzy) == {k.WH_NOWE_PAUZA_S}, 'przerwa między zapytaniami do tej samej giełdy')

    def test_get_limit_i_podpiecie(self):
        k = self.k
        import inspect
        self.assertIn('limit=None', inspect.signature(k.get).__str__())
        src = inspect.getsource(k.kontrola)
        self.assertIn("wh_nowe_raporty((files.get('wieloryby') or {}).get('gieldy'))", src)
        self.assertIn('wh_nowe_wiersz', inspect.getsource(k.raport_md))


# ===================== v239: POPRAWKI PO PRZEGLĄDZIE v234–v236 =====================
class PoPrzegladzieV239(unittest.TestCase):
    """v239: lustro tylko wstecz po skoku jednostek (dni krachu zostają zwykłymi dniami); wąskie pasmo dokładnego ułamka; zegar i kontrola."""

    def test_dni_krachu_zostaja(self):
        F = zd.fund_split
        for nr in (0.7981, 0.7943, 0.75, 0.8, 1.25, 4 / 3):                       # XLE 09.03.2020, srebro 02.02.2026 — przy płaskich jednostkach
            for u in (1.0, 1.01, 0.99):
                self.assertEqual(F([0, 100.0, 1e6], [0, 100.0 * nr, 1e6 * u]), 1, f'NAV ×{nr}, jednostki ×{u} — zwykły dzień (krach), nie skok')
        days = ['2026-01-%02d' % d for d in range(5, 31) if datetime.date(2026, 1, d).weekday() < 5]
        h = [[d, 100.0 * (1 + 0.002 * i), 1e6 * (1 + 0.001 * i)] for i, d in enumerate(days)]
        h[10][1] = h[9][1] * 0.7943; h[10][2] = h[9][2]                          # krach jak srebro, jednostki płaskie
        for r in h[11:]:
            r[1] = h[10][1] * (1 + 0.001 * (h.index(r) - 10))
        P = zd.fund_pary(h)
        self.assertNotIn(0, P, 'dzień krachu bez skoku jednostek przed nim — żadna para nie jest skokiem')
        self.assertAlmostEqual(zd._td_fund_px(h)[2][10], (0.7943 - 1) * 100, places=6)

    def test_lustro_wstecz(self):
        mk = lambda rows: [['2026-06-%02d' % (i + 1), n, u] for i, (n, u) in enumerate(rows)]  # noqa: E731
        k = 4 / 3
        for lag in (1, 2, 3):                                                     # poprawka NAV 1–3 dni po skoku jednostek
            rows = [(100.0, 1e8), (100.0, 1e8 * k)] + [(100.0 + 0.1 * i, 1e8 * k) for i in range(1, lag)] + [(75.0, 1e8 * k), (75.1, 1e8 * k)]
            P = zd.fund_pary(mk(rows))
            self.assertEqual(P[0], 0, f'opóźnienie {lag}: skok jednostek')
            self.assertEqual(P[lag], 0, f'opóźnienie {lag}: poprawka NAV — skok (bez zwrotu −25%)')
            self.assertEqual(P[-1], 1)
        rows = [(100.0, 1e8), (100.0, 1e8 * k)] + [(100.0, 1e8 * k)] * 3 + [(100.1, 1e8 * k), (75.0, 1e8 * k)]
        self.assertEqual(zd.fund_pary(mk(rows))[-1], 1, 'poprawka po 5 dniach — poza oknem (krach od zwykłego dnia nie do odróżnienia)')
        h = mk([(100.0, 1e8), (75.0, 1e8), (75.0, 1e8 * k), (75.1, 1e8 * k)])
        self.assertEqual(zd.fund_pary(h), [1, 0, 1], 'NAV przed jednostkami: pierwszy dzień nie do poznania (jak krach) — zwykły; drugi skok')
        P = zd.fund_pary(mk([(100.0, 1e8), (100.0, 3e8), (100.3, 3e8), (80.0, 3e8)]))
        self.assertEqual(P, [0, 1, 1], 'po błędzie pliku (×3) spadek o 20% to nie poprawka podziału — zwykły dzień')
        for n in range(2, 9):                                                     # przyczynowo: para liczona z wierszy do jej końca
            rows = [(100.0, 1e8), (100.0, 1e8 * k), (100.2, 1e8 * k), (75.0, 1e8 * k), (75.1, 1e8 * k), (75.3, 1e8 * k), (75.2, 1e8 * k), (75.4, 1e8 * k)]
            self.assertEqual(zd.fund_pary(mk(rows)[:n]), zd.fund_pary(mk(rows))[:n - 1], n)

    def test_waskie_pasmo_dokladnego_ulamka(self):
        F = zd.fund_split
        self.assertEqual((zd.FUND_STALE_U2, zd.FUND_STALE_N2), (0.005, 0.06))
        self.assertEqual(F([0, 100.0, 1e6], [0, 95.0, 1e6 * 4 / 3]), 0, '4:3 bez poprawki NAV w dniu spadku o 5% — skok')
        self.assertEqual(F([0, 100.0, 1e6], [0, 104.0, 1.25e6 * 1.003]), 0)
        self.assertEqual(F([0, 100.0, 1e6], [0, 95.0, 1e6 * 4 / 3 * 1.01]), 1, 'znana luka: jednostki 1% od ułamka i ruch ceny ponad 3% — zwykły dzień')
        self.assertEqual(F([0, 100.0, 1e6], [0, 103.06, 1.2272e6]), 1, 'FXI 04.10.2024 — prawdziwy napływ')
        self.assertEqual(F([0, 100.0, 1e6], [0, 99.83, 1.2467e6]), 0, 'SPDW 14.12.2017 — jak dotąd skok')

    def test_zegar_i_kontrola(self):
        import importlib.util, tempfile
        root = os.path.dirname(os.path.abspath(__file__))
        spec = importlib.util.spec_from_file_location('v239_zegar', os.path.join(root, 'narzedzia', 'zegar.py'))
        Z = importlib.util.module_from_spec(spec); spec.loader.exec_module(Z)
        RUN = {'id': 37437793511, 'status': 'waiting', 'updated_at': '2026-10-06T08:47:47Z'}
