    def test_plik_z_nagran(self):
        o = zd.build_zloto_krypto(self.S(), None, self.NOW)
        self.assertEqual(o['ok'], {'zb': True, 'kor': True, 'tok': True, 'ryn': True}); self.assertEqual(o['notes'], [])
        self.assertEqual((o['v'], o['at'], o['part_at']['zb']), (1, self.NOW.isoformat(), self.NOW.isoformat()))
        zb = o['zb']
        self.assertEqual((zb['do'], zb['btc'], zb['d'][-1]), ('2026-10-06', 'kc', ['2026-10-06', 4156.4, 85549.93]), 'złoto z fixingu i bitcoin z zamknięcia doby UTC tego samego dnia')
        g = dict(_ZK_FX['gold']); b = dict(_ZK_FX['btc'])
        self.assertEqual([r[0] for r in zb['d']], sorted(set(g) & set(b)), 'tylko dni wspólne (złoto w dni robocze)')
        self.assertFalse(any(datetime.date.fromisoformat(r[0]).weekday() > 4 for r in zb['d']))
        # korelacja ze złotem: ostatnie 90 wspólnych dni do 06.10 = niezależne liczenie
        K = o['kor']
        self.assertEqual((K['okno'], K['kal'], K['min'], K['zl']['d']), (90, 140, 60, '2026-10-06'))
        W = zb['d'][-90:]
        xa = [_math_v125.log(W[k][1] / W[k - 1][1]) for k in range(1, len(W))]; xb = [_math_v125.log(W[k][2] / W[k - 1][2]) for k in range(1, len(W))]
        self.assertEqual((K['zl']['n'], W[0][0] > '2026-05-20'), (90, True))
        self.assertAlmostEqual(K['zl']['v'], statistics.correlation(xa, xb), places=4)
        self.assertEqual(K['zl']['s'][-1], ['2026-10-06', round(K['zl']['v'], 3)])
        # S&P 500 (dla porównania): dni wspólne z sesjami w USA, to samo okno
        Ws = zd.zk_wspolne(dict(_ZK_FX['spx']), dict(_ZK_FX['btc']))[-90:]
        xa = [_math_v125.log(Ws[k][1] / Ws[k - 1][1]) for k in range(1, len(Ws))]; xb = [_math_v125.log(Ws[k][2] / Ws[k - 1][2]) for k in range(1, len(Ws))]
        self.assertEqual((K['sp']['d'], K['sp']['n']), ('2026-10-06', 90)); self.assertAlmostEqual(K['sp']['v'], statistics.correlation(xa, xb), places=4)
        # ropa Brent: punkt „do sprawdzenia” 02.10 (+18%, niepotwierdzony) pominięty
        self.assertIn('2026-10-02', [r[0] for r in _ZK_FX['brent']])
        Wb = zd.zk_wspolne(dict(_ZK_FX['brent']), b, {r[0] for r in _ZK_FX['brent_q']})
        self.assertNotIn('2026-10-02', [r[0] for r in Wb]); self.assertEqual(K['br']['d'], '2026-10-06')
        self.assertEqual(K['br']['v'], zd.zk_kor(Wb)['v'])
        # tokeny: PAXG = podaż na łańcuchu, XAUT = w obiegu (bez rezerwy emitenta); tony = uncje ÷ 32 150,7466
        T = o['tok']
        self.assertEqual((T['PAXG']['oz'], T['PAXG']['t'], T['PAXG']['at']), (436648.2025, 13.5813, '2026-10-07T15:21:03+00:00'))
        self.assertEqual((T['XAUT']['oz'], T['XAUT']['t']), (709323.6595, round(709323.659532 / 32150.7466, 4)))
        self.assertEqual(T['razem']['t'], round((436648.20247 + 709323.659532) / 32150.7466, 4))
        # zmiany: dziennik PAXG na start z 4 dni zapisów rwa.json — 7 i 30 dni jeszcze bez dnia bazowego = None (na stronie „—”)
        self.assertEqual([r[0] for r in T['h']], ['2026-10-04', '2026-10-05', '2026-10-06', '2026-10-07'])
        self.assertEqual(T['h'][-1], ['2026-10-07', 436648.20247, 709323.659532]); self.assertIsNone(T['h'][0][2], 'XAUT bez historii w obiegu — nie z totalSupply')
        self.assertEqual((T['PAXG']['c7'], T['PAXG']['c30'], T['razem']['c7']), (None, None, None))
        # premia: cena tokenu z 20:13, notowanie złota z 20:00 (13 min) — liczba; wyrocznia z 14:01 dalej niż 1 h
        self.assertEqual((T['PAXG']['ref'], T['PAXG']['dt_min'], T['PAXG']['ref_px']), ('live', 13, 4113.0))
        self.assertEqual(T['PAXG']['prem'], round((4114.84 / 4113.0 - 1) * 100, 3)); self.assertEqual(T['PAXG']['prem_at'], '2026-10-07T20:13:00+00:00')
        self.assertEqual(T['ph'], [['2026-10-07', T['PAXG']['prem'], T['XAUT']['prem']]])
        self.assertEqual(T['gpx'], {'v': 4100.325, 'at': '2026-10-07T14:01:23+00:00', 'z': 'wyr'}, 'kwoty USD po cenie złota z wyceny tokenów')
        # wielkość rynków: złoto = szacunek (zasoby × ostatnia cena z fixingu) z datą stanu; krypto i bitcoin z cmc.json
        R = o['ryn']
        self.assertEqual(R['zloto'], {'v': round(222600 * 32150.7466 * 4156.4), 't': 222600, 't_d': '2026-06-30', 'px': 4156.4, 'px_d': '2026-10-06'})
        self.assertEqual(R['krypto'], {'v': round(_ZK_CMC['total_mcap']), 'at': _ZK_CMC['asof']})
        self.assertEqual(R['btc']['v'], round(_ZK_CMC['total_mcap'] * _ZK_CMC['btc_dom'] / 100))
        self.assertEqual(R['tok_cm'], {'v': 5031095063, 'at': '2026-10-07T15:21:03+00:00'})
        self.assertLess(len(json.dumps(o, separators=(',', ':'))), 60000, 'mały plik dla telefonu')

