    def test_prawdziwy_kalendarz_swieta_i_punkty_q_bez_dziur(self):
        """Recenzja v295c: okno 90 dni KALENDARZOWYCH miało 62–64 dni robocze — Wielkanoc (03.04, 06.04), majowe święta w Wielkiej Brytanii (04.05,
        25.05) i 2 punkty q ropy (18.03, 07.04) dawały 59 < 60 i „—” przy kompletnych danych (Brent: 36 dni). Teraz okno to 90 wspólnych dni notowań:
        na nagraniach (złoto w kalendarzu giełdy w USA, Brent w kalendarzu Wielkiej Brytanii, S&P 500) każdy wspólny dzień z pełną historią ma liczbę."""
        F = _ZK_FX
        b = dict(F['btc']); q = {r[0] for r in F['brent_q']}
        self.assertTrue({'2026-04-03', '2026-04-06', '2026-05-04', '2026-05-25'}.isdisjoint(dict(F['brent'])), 'święta w Wielkiej Brytanii — bez notowań ropy')
        self.assertTrue({'2026-03-18', '2026-04-07'} <= q, 'dwa punkty q ropy w oknie')
        for nazwa, a, sk in (('złoto', dict(F['gold']), set()), ('ropa Brent', dict(F['brent']), q), ('S&P 500', dict(F['spx']), set())):
            pts = zd.zk_wspolne(a, b, sk)
            pelne = [i for i, p in enumerate(pts) if p[0] >= '2026-02-19']   # 140 dni po początku nagrania (01.10.2025) — okno ma pełną historię
            self.assertGreater(len(pelne), 150, nazwa)
            wyn = [zd.zk_kor_okno(pts, i) for i in pelne]
            self.assertEqual([pts[i][0] for i, (r, n) in zip(pelne, wyn) if r is None], [], nazwa + ': „—” przy kompletnych danych')
            self.assertEqual({n for _r, n in wyn}, {90}, nazwa + ': zawsze 90 wspólnych dni')
            self.assertEqual([x[0] for x in zd.zk_kor(pts)['s'] if x[0] >= '2026-02-19'], [pts[i][0] for i in pelne], nazwa + ': linia na wykresie bez dziur')
        # przykład z recenzji: okno kończące się 12.05.2026 (Brent) — po staremu 90 dni kalendarzowych = 59 wspólnych dni („—”), teraz 90
        pts = zd.zk_wspolne(dict(F['brent']), b, q)
        i = [p[0] for p in pts].index('2026-05-12')
        self.assertEqual(zd.zk_kor_okno(pts, i, okno=10 ** 6, kal=90), (None, 59), 'stara reguła (okno kalendarzowe) — tu był błąd')
        r, n = zd.zk_kor_okno(pts, i)
        self.assertEqual(n, 90); self.assertIsNotNone(r)
        W = self.okno(pts, i)
        xa = [_math_v125.log(W[k][1] / W[k - 1][1]) for k in range(1, len(W))]; xb = [_math_v125.log(W[k][2] / W[k - 1][2]) for k in range(1, len(W))]
        self.assertAlmostEqual(r, statistics.correlation(xa, xb), places=4)
        self.assertNotIn('2026-04-07', [p[0] for p in W], 'punkt q pominięty'); self.assertLess(W[0][0], '2026-01-01', '90 notowań sięga dalej niż 90 dni kalendarzowych')

    def test_odczyt_starszy_niz_12_h_i_xaut_bez_potwierdzonej_rezerwy_poza_dziennikiem(self):
        # odczyt z łańcucha 07.10 15:21:03 UTC: dokładnie 12 h później — jeszcze tak; sekundę później — nie (ani dziennik, ani kafel)
        ok = zd.build_zloto_krypto(self.S(), None, datetime.datetime(2026, 10, 8, 3, 21, 3, tzinfo=datetime.timezone.utc))['tok']
        self.assertEqual((ok['PAXG']['oz'], ok['XAUT']['oz'], ok['h'][-1]), (436648.2025, 709323.6595, ['2026-10-07', 436648.20247, 709323.659532]))
        st = zd.build_zloto_krypto(self.S(), None, datetime.datetime(2026, 10, 8, 3, 21, 4, tzinfo=datetime.timezone.utc))['tok']
        self.assertEqual((st['PAXG']['oz'], st['PAXG']['at'], st['XAUT']['oz'], st['razem']['oz']), (None, None, None, None), 'odczyt starszy niż 12 h — brak, nie stara liczba jako nowa')
        self.assertEqual(st['h'][-1], ['2026-10-07', 436648.20247, None], 'dziennik: PAXG tylko z dziennych zapisów rwa.json, XAUT bez wpisu')
        # z poprzednim plikiem: poprzednia podaż z JEJ chwilą, dziennik bez nowego dnia
        p = zd.build_zloto_krypto(self.S(), None, self.NOW)
        o = zd.build_zloto_krypto(self.S(), p, self.NOW + datetime.timedelta(hours=13))['tok']
        self.assertEqual((o['PAXG']['oz'], o['PAXG']['at'], o['h']), (p['tok']['PAXG']['oz'], '2026-10-07T15:21:03+00:00', p['tok']['h']))
        # XAUT: rezerwa emitenta niepotwierdzona (ok False), brak rezerwy (None) albo blok bez pola rez — nigdy totalSupply (827 417 uncji)
        for opis, zmien in (('rez.ok False', lambda x: x['rez'].__setitem__('ok', False)), ('rez None', lambda x: x.__setitem__('rez', None)),
                            ('bez pola rez', lambda x: x.pop('rez')), ('rez.ok „true”', lambda x: x['rez'].__setitem__('ok', 'true'))):
            S = self.S(); zmien(S['rwa']['onchain']['p']['tether-gold'])
            T = zd.build_zloto_krypto(S, None, self.NOW)['tok']
            self.assertEqual((T['XAUT']['oz'], T['XAUT']['t'], T['h'][-1][2], T['razem']['oz']), (None, None, None, None), opis)
            self.assertEqual(T['PAXG']['oz'], 436648.2025, opis + ': PAXG bez zmian')
            self.assertNotIn(827417.63, [r[2] for r in T['h']], opis)

    def test_tryb_szybki_nie_nadpisuje_lepiej_dopasowanej_premii(self):
        # przebieg 1: token 20:13, złoto 20:00 (13 min) → premia; przebieg 2 (tryb szybki etf.json: ta sama cena tokenu z 20:13), złoto z 21:00
        # droższe o 0,3% (47 min) — zostaje pomiar z przebiegu 1 (z jego ceną złota, chwilą i wpisem ph)
        p = zd.build_zloto_krypto(self.S(), None, self.NOW)
        P1 = p['tok']['PAXG']
        self.assertEqual((P1['dt_min'], P1['ref_at'], P1['prem']), (13, '2026-10-07T20:00:00+00:00', round((4114.84 / 4113.0 - 1) * 100, 3)))
        o = zd.build_zloto_krypto(self.S(live_at='2026-10-07T21:00:00+00:00', live_v=4113.0 * 1.003), p, self.NOW + datetime.timedelta(hours=1))
        P2 = o['tok']['PAXG']
        self.assertEqual({f: P2[f] for f in ('prem', 'prem_at', 'ref', 'ref_px', 'ref_at', 'dt_min')}, {f: P1[f] for f in ('prem', 'prem_at', 'ref', 'ref_px', 'ref_at', 'dt_min')})
        self.assertEqual(o['tok']['ph'], p['tok']['ph'], 'historia dzienna bez gorszego pomiaru')
        self.assertIsNotNone(zd.zk_prem(4114.84, '2026-10-07T20:13:00+00:00', [('live', 4113.0 * 1.003, '2026-10-07T21:00:00+00:00')]), 'gorszy pomiar mieści się w 1 h — reguła nie „—”, tylko wybór lepszego')
        # poprzedni pomiar gorzej dopasowany (50 min) — nowy (13 min) go zastępuje; nowa cena tokenu (inna chwila) — zawsze nowy pomiar
        q = json.loads(json.dumps(p)); q['tok']['PAXG'].update(dt_min=50, ref_px=4100.0, prem=round((4114.84 / 4100.0 - 1) * 100, 3), ref_at='2026-10-07T19:23:00+00:00')   # v297c: zgodny ze sobą
        self.assertEqual(zd.build_zloto_krypto(self.S(), q, self.NOW)['tok']['PAXG']['prem'], P1['prem'])
        S = self.S(live_at='2026-10-07T21:00:00+00:00', live_v=4113.0 * 1.003); S['etf']['tok']['PAXG'] = {'p': 4127.0, 'at': '2026-10-07T21:05:00+00:00'}
        P3 = zd.build_zloto_krypto(S, p, self.NOW + datetime.timedelta(hours=1))['tok']['PAXG']
        self.assertEqual((P3['prem_at'], P3['dt_min'], P3['ref_at']), ('2026-10-07T21:05:00+00:00', 5, '2026-10-07T21:00:00+00:00'))

    def test_wejscia_uszkodzone_bez_nieskonczonosci(self):
        # chwila ceny z wyroczni nie-tekst / liczba nieskończona — cena złota do kwot z fixingu (z datą); dziennik hs nie-lista — bez wyjątku
        S = self.S(); S['rwa']['onchain']['px']['zloto']['at'] = float('inf')
        T = zd.build_zloto_krypto(S, None, self.NOW)['tok']
        self.assertEqual(T['gpx'], {'v': 4156.4, 'at': '2026-10-06', 'z': 'pm'})
        S = self.S(); S['rwa']['onchain']['hs']['paxos-gold'] = {'2026-10-04': 1.0}
        o = zd.build_zloto_krypto(S, None, self.NOW)
        self.assertEqual((o['notes'], o['ok']['tok'], [r[0] for r in o['tok']['h']]), ([], True, ['2026-10-07']))
        # cena złota spoza rozsądnego zakresu (1e308 — USD = zmiana × cena dałoby nieskończoność; 5e-324 — premia nieskończona) — pominięta
        p = zd.build_zloto_krypto(self.S(), None, self.NOW)
        p['tok']['h'] = [[(datetime.date(2026, 10, 7) - datetime.timedelta(days=i)).isoformat(), 436648.2 - 3000 * i, None] for i in range(8, 0, -1)]
        S = self.S(live_v=5e-324); S['rwa']['onchain']['px']['zloto']['v'] = 1e308
        o = zd.build_zloto_krypto(S, p, self.NOW)
        json.dumps(o, allow_nan=False)
        self.assertEqual((o['notes'], o['ok']['tok'], o['tok']['gpx']['z']), ([], True, 'pm'))
        self.assertEqual((o['tok']['PAXG']['prem'], o['tok']['PAXG']['ref_px']), (p['tok']['PAXG']['prem'], 4113.0), 'bez nowej premii z ceny spoza zakresu — poprzednia z jej chwilą')
        self.assertAlmostEqual(o['tok']['PAXG']['c7']['usd'], o['tok']['PAXG']['c7']['oz'] * 4156.4, delta=1)
        # straż pliku: liczba nieskończona albo NaN w części = błąd części (poprzednia część z jej czasem), nigdy „Infinity” w pliku
        with mock.patch.object(zd, 'zk_ryn', lambda rw, cmc, gold: {'zloto': {'v': float('nan')}}):
            o = zd.build_zloto_krypto(self.S(), p, self.NOW + datetime.timedelta(hours=1))
        json.dumps(o, allow_nan=False)
        self.assertEqual((o['ok']['ryn'], o['ryn'], o['part_at']['ryn']), (False, p['ryn'], self.NOW.isoformat())); self.assertTrue(o['notes'][0].startswith('ryn: ValueError'), o['notes'])

    def test_kontrola_stary_stan_zasobow_zlota(self):
        import importlib.util, tempfile
        tmp = tempfile.mkdtemp(prefix='kontrola-zk-')
        with mock.patch.dict(os.environ, {'KONTROLA_DIR': os.path.join(tmp, 'k'), 'KONTROLA_ARCH': os.path.join(tmp, 'a')}, clear=False):
            spec = importlib.util.spec_from_file_location('v295c_kontrola', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
            kt = importlib.util.module_from_spec(spec); spec.loader.exec_module(kt)
        o = zd.build_zloto_krypto(self.S(), None, self.NOW)
        self.assertEqual(o['ryn']['zloto']['t_d'], zd.ZK_ZLOTO['d'])
        R = {'uwagi': []}
        z = kt.zk_kontrola(o, R, now=datetime.datetime(2027, 7, 30, 6, 20, tzinfo=datetime.timezone.utc))   # v297c: 13 miesięcy po 30.06.2026 — jeszcze ✅
        self.assertEqual((z['status'], z['wiek_dni'], R['uwagi']), ('✅', 395, []))
        z = kt.zk_kontrola(o, R, now=datetime.datetime(2027, 7, 31, 6, 20, tzinfo=datetime.timezone.utc))
        self.assertEqual((z['status'], z['wiek_dni'], len(R['uwagi'])), ('⚠️', 396, 1))
        self.assertIn('ze stanu na 2026-06-30', R['uwagi'][0]); self.assertIn('ZK_ZLOTO', R['uwagi'][0]); self.assertNotIn('❌', R['uwagi'][0])
        self.assertIsNone(kt.zk_kontrola(None, R)); self.assertIsNone(kt.zk_kontrola({'ryn': {'zloto': {'t_d': '2026-02-30'}}}, R)); self.assertEqual(len(R['uwagi']), 1)
        with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'), encoding='utf-8') as f:
            k = f.read()
        self.assertIn("Z['zloto-krypto'] = zk_kontrola(files.get('zloto-krypto'), R)", k[k.index('def kontrola():'):])

    def test_zapis_w_main_i_kontrola(self):
        root = os.path.dirname(os.path.abspath(__file__))
        with open(zd.__file__, encoding='utf-8') as f:
            src = f.read()
        m = src[src.index('def main():'):]
        i, j = m.index("prev_zk = previous('zloto-krypto')"), m.index("_CR_LOG[0] = previous('krypto-dziennik')")
        self.assertLess(m.index("save('rwa', rw)"), i); self.assertLess(i, j, 'po RWA, przed TRENDAMI (wszystkie wejścia zapisane w tym przebiegu)')
        self.assertIn('build_zloto_krypto(SAVED, prev_zk)', m[i:j])
        blk = src[src.index('# ===================== v295c: ZŁOTO I SUROWCE A KRYPTO'):src.index('\ndef main():')]
        self.assertNotIn('get_json(', blk); self.assertNotIn('urllib', blk.replace('import math as _zk_math', '')); self.assertNotIn('KEY', blk)
        with open(os.path.join(root, 'narzedzia', 'kontrola.py'), encoding='utf-8') as f:
            k = f.read()
        PL = eval(zd.re.search(r'^PLIKI = (\[.*\])$', k, zd.re.M).group(1)); LM = eval(zd.re.search(r'^LIMIT_MIN = (\{[^}]*\})', k, zd.re.M).group(1))
        self.assertEqual(PL[PL.index('rwa') + 1], 'zloto-krypto'); self.assertEqual(PL[-2:], ['krypto-dzien', 'krypto-dziennik']); self.assertEqual(LM['zloto-krypto'], 90)
        # przebieg główny: plik z tego przebiegu; błąd budowy = poprzedni plik i błąd z etykietą
        saved = {}
        p = zd.build_zloto_krypto(self.S(), None, self.NOW)
        with mock.patch.object(zd, 'previous', lambda n: p if n == 'zloto-krypto' else None), mock.patch.object(zd, 'save', lambda n, o: saved.__setitem__(n, o)), \
                mock.patch.object(zd, 'build_zloto_krypto', side_effect=ValueError('test')):
            exec(compile(self._main_blok(src), 'main-zk', 'exec'), vars(zd), {})
        self.assertIs(saved['zloto-krypto'], p); self.assertIs(zd.META['ok']['zloto-krypto'], False); self.assertTrue(zd.META['errors'][-1].startswith('złoto a krypto: '))

    @staticmethod
    def _main_blok(src):
        m = src[src.index('def main():'):]
        a, b = m.index("    # v295c: CRYPTO „Złoto i surowce a krypto”"), m.index("    _CR_LOG[0] = previous('krypto-dziennik')")
        return 'def _zk_main_test():\n' + m[a:b] + '\n_zk_main_test()\n'


