        em = zd.rwe_blok(rd, {'p': {'ondo-global-markets': dict(_RWE302_PV)}}, self.NOW, oc={'v': 1, 'px': {'zloto': dict(_RWE169_GOLD)}},
                         ref={'ondo-global-markets': 965790144.95})
        o = em['p']['ondo-global-markets']
