        S = self.build(rows=rok(' '.join(['1,0,10'] * 7)))['cies']['k']['suez']
        self.assertEqual((S['r7'], S['chg']), (1.0, 4214.0), 'dokładnie 1 statek dziennie — próg włącznie')
