    def setUp(self):
        import shutil, tempfile
        self.tmp = tempfile.mkdtemp(prefix='v309-'); self.addCleanup(shutil.rmtree, self.tmp, True)
        for p in (mock.patch.object(zd, 'SUT_CSV', os.path.join(self.tmp, 'brak', 'surowce-dziennik.csv')),
                  mock.patch.object(zd.urllib.request, 'urlopen', side_effect=AssertionError('sieć w teście')),
                  mock.patch.object(zd.time, 'sleep', lambda s: None)):
            p.start(); self.addCleanup(p.stop)
        zd._SUT_LOG[0] = zd._SUT_LOG[1] = None
        self.addCleanup(zd._SUT_LOG.__setitem__, slice(None), [None, None])
        zd.META['notes'].clear(); zd.META['errors'].clear()
        self.addCleanup(zd.META['notes'].clear); self.addCleanup(zd.META['errors'].clear)

    # ---------------------------------------------------------------- pomocnicze: nagrania, kalendarz, pliki
    @staticmethod
    def iso(d):
        return datetime.datetime.strptime(d, '%m/%d/%Y').date().isoformat()

    def t(self, s):
        return datetime.datetime.fromisoformat(s).replace(tzinfo=self.UTC)

    def cal(self):
        """Kalendarz sesji: dni robocze 02.06.2025 – 20.03.2026 bez świąt NYSE (część umowna, sprzed nagrania) + 140 sesji z nagrania (DBC:
        23.03–09.10.2026, bez wierszy zastępczych) — 300 dni pliku wydawcy mieści się w pliku dziennym (jak w produkcji: kalendarz ok. 10 lat)."""
        sw = {'2025-06-19', '2025-07-04', '2025-09-01', '2025-11-27', '2025-12-25', '2026-01-01', '2026-01-19', '2026-02-16'}
        early = [d.isoformat() for d in (datetime.date(2025, 6, 2) + datetime.timedelta(days=i) for i in range(300))
                 if d.weekday() < 5 and d.isoformat() not in sw and d.isoformat() < '2026-03-23']
        return early + sorted(self.iso(r[0]) for r in self.NAG['nq']['DBC'])

    def nq_rows(self, t, extra=()):
        """Wiersze odpowiedzi Nasdaq (najnowsze pierwsze): nagranie funduszu + dni `extra` [(dzień, o, c)] na początku."""
        rows = [{'date': f'{d[5:7]}/{d[8:10]}/{d[:4]}', 'open': f'{o:.2f}', 'close': f'{c:.2f}', 'volume': '1,000', 'high': '0', 'low': '0'}
                for d, o, c in sorted(extra, reverse=True)]
        return rows + [{'date': r[0], 'open': r[1], 'close': r[2], 'volume': r[3], 'high': '0', 'low': '0'} for r in self.NAG['nq'][t]]

    def nq(self, extra=(), fail=(), empty=()):
        """Atrapa _wd_get_json (Nasdaq): 44 rynki — syntetycznie na kalendarzu cal() (+ dni extra), 7 funduszy surowcowych — z nagrania
        (+ dni extra); tylko wiersze z okna dat zapytania; zwraca (lista zapytań [(symbol, limit)], atrapa)."""
        calls, cal = [], self.cal()

        def gj(url, timeout):
            t = url.split('/quote/')[1].split('/')[0]; n = int(url.split('limit=')[1].split('&')[0])
            a, b = url.split('fromdate=')[1].split('&')[0], url.split('todate=')[1].split('&')[0]   # okno dat zapytania — jak giełda
            calls.append((t, n))
            if t in fail:
                raise RuntimeError('HTTP Error 503: Service Unavailable')
            if t in empty:
                return {'data': {'tradesTable': {'rows': []}}}
            ex = [(d, o * 1.01, c * 1.01) for d, o, c in extra]
            if t in zd.WD_SU_PX:
                rows = self.nq_rows(t, ex)
            else:
                rows = [{'date': f'{d[5:7]}/{d[8:10]}/{d[:4]}', 'open': '100.00', 'close': '100.50', 'volume': '1,000', 'high': '0', 'low': '0'}
                        for d in sorted(set(cal) | {d for d, *_ in extra}, reverse=True)]
            rows = [r for r in rows if a <= self.iso(r['date']) <= b]
            return {'data': {'tradesTable': {'rows': rows[:n]}}}
        return calls, gj

    def wd_prev(self):
        """Plik dzienny świata po serii wstępnej 44 rynków (bf px/fl/ob, ready), bez funduszy surowcowych — kalendarz cal()."""
        cal = self.cal()
        px = {t: {'d': [[d, 100.0, 100.5, None] for d in cal], 'miss': [], 'seed': True} for t in zd.TD_W_SYMS}
        fl = {t: {'iss': 'ssga' if t in zd.FUND_SSGA else 'ishares', 'd': [[d, 10.0, 1000 + i, None] for i, d in enumerate(cal)], 'seed': True}
              for t in zd.WD_SSGA + zd.WD_ISH}
        ob = {p: {'d': [[d, 1.0, None] for d in cal], 'empty': []} for p in ('tw', 'hk', 'in')}
        return {'at': '2026-10-10T05:00:00+00:00', 'v': 1, 'cal': cal, 'px': px, 'fl': fl, 'ob': ob, 'rv': {}, 'rvd': {},
                'bf': {'px': True, 'fl': True, 'ob': True}, 'try': None, 'nq': {'fails': 0, 'next': None, 'since': None}, 'ready': True}

    def ish_rows(self, t):
        """Wiersze pełnego pliku wydawcy z nagrania (parser produkcji na zbudowanym arkuszu Historical) — rosnąco."""
        return zd.parse_ishares_hist(self.ish_xml(t))

    def ish_xml(self, t, rows=None):
        """Plik wydawcy (Excel 2003 XML) z arkuszem Historical — kolumny i teksty jak w pliku z 10.10.2026."""
        cell = lambda v, typ: f'<ss:Cell><ss:Data ss:Type="{typ}">{v}</ss:Data></ss:Cell>'   # noqa: E731
        head = ['As Of', 'NAV per Share', 'Ex-Dividends', 'Shares Outstanding']
        body = ''.join('<ss:Row>' + cell(r[0], 'String') + cell(r[1], 'Number') + cell(r[2], 'String') + cell(r[3], 'Number') + '</ss:Row>'
                       for r in (rows if rows is not None else self.NAG['ish'][t]))
        x = ('<?xml version="1.0"?>\n<ss:Workbook xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><ss:Worksheet ss:Name="Holdings">'
             '<ss:Table><ss:Row>' + cell('Ticker', 'String') + '</ss:Row></ss:Table></ss:Worksheet><ss:Worksheet ss:Name="Historical"><ss:Table>'
             '<ss:Row>' + ''.join(cell(h, 'String') for h in head) + '</ss:Row>' + body + '</ss:Table></ss:Worksheet></ss:Workbook>')
        return x.encode('utf-8')

    def fu_su(self, upto=None, revise=None):
        """Część 'su' pliku fundusze: historia pełnego pliku wydawcy (ostatnie FUND_KEEP dni) do dnia `upto` włącznie; revise(t, wiersz) → wiersz."""
        out = {}
        for t in zd.FUND_ISH_SU:
            h = [r for r in self.ish_rows(t) if upto is None or r[0] <= upto][-zd.FUND_KEEP:]
            out[t] = {'iss': 'ishares', 'h': [revise(t, list(r)) if revise else r for r in h], 'pid': 'x', 'at': '2026-10-10T05:00:00+00:00'}
        return out

    def run_wd(self, now, prev, saved, gj, run_t0=None):
        with mock.patch.object(zd, '_now_utc', lambda: now), mock.patch.object(zd, '_wd_get_json', gj), \
                mock.patch.object(zd, '_wd_get_bytes', side_effect=AssertionError('plik wydawcy w tym teście')):
            return zd.build_swiat_dzien(prev, saved, run_t0=run_t0)

    # ---------------------------------------------------------------- 1. stałe i listy reguł głównych — bez zmian (asercje wartości)
    def test_stale_i_listy_regul_bez_zmian(self):
        import hashlib
        h = lambda x: hashlib.sha256(repr(x).encode()).hexdigest()[:16]   # noqa: E731
        self.assertEqual((h(zd.TR_FE), h(zd.TD_W_SYMS)), ('4dba46775e53461d', '72dbe975b6dc3a58'), 'TR_FE i TD_W_SYMS bajt w bajt jak w v300')
        self.assertEqual((len(zd.TD_W_SYMS), len(zd.TR_FE), sum(len(m) for _, m in zd.TR_FE)), (44, 27, 37))
        self.assertEqual(zd.FUND_ISH, ('IVV', 'EFA', 'IEFA', 'EZU', 'EWJ', 'EEM', 'IEMG', 'MCHI', 'FXI', 'INDA', 'EWZ', 'EWY', 'EWT',
                                       'TLT', 'IEF', 'SHY', 'AGG', 'LQD', 'HYG', 'EMB', 'IAU', 'SLV'), 'FUND_ISH (przepływy GLOBAL) bez zmian')
        self.assertEqual(zd.FUND_SSGA, ('SPY', 'XLK', 'XLF', 'XLE', 'XLV', 'XLI', 'XLY', 'XLP', 'XLU', 'SPDW', 'SPEM', 'BIL', 'JNK', 'GLD', 'GLDM'))
        self.assertEqual(zd.IX_ETF, ('SPY', 'EWC', 'ILF', 'VGK', 'KSA', 'TUR', 'EIS', 'EZA', 'INDA', 'MCHI', 'EWJ', 'EWY', 'ASEA', 'EWA', 'XLK',
                                     'XLF', 'XLE', 'XLV', 'XLI', 'XLY', 'XLP', 'XLU', 'SPDW', 'SPEM', 'BIL', 'JNK', 'GLD', 'GLDM', 'IVV', 'EFA', 'IEFA',
                                     'EZU', 'EEM', 'IEMG', 'FXI', 'EWZ', 'EWT', 'TLT', 'IEF', 'SHY', 'AGG', 'LQD', 'HYG', 'EMB', 'IAU', 'SLV'),
                         'IX_ETF (46 funduszy cen mapy GLOBAL i TRENDÓW) bez zmian — bez funduszy surowcowych')
        self.assertEqual((h(zd.IX_ETF), h(zd.FUND_ISH)), ('ad20440fe7558f2c', 'ba39c3c13a1e154c'))
        self.assertEqual((len(zd.WD_SSGA), len(zd.WD_ISH), zd.WD_SSGA + zd.WD_ISH), (14, 21, tuple(t for t in zd.FUND_SSGA + zd.FUND_ISH if t in zd.TD_W_SYMS)))
