    def setUp(self):
        for nazwa in ('post_json', 'get_bytes', 'get_json'):
            self.enterContext(mock.patch.object(zd, nazwa, side_effect=AssertionError('test nie może pytać sieci')))
        zd.META['notes'].clear()

    @staticmethod
    def _j(dd):
        return [{'date': str(int(datetime.datetime.fromisoformat(d + 'T00:00:00+00:00').timestamp())), 'totalCirculatingUSD': {'peggedUSD': v}} for d, v in dd]

    def test_pelne_cur_poziom_z_dnia_konca_okna(self):
        DD = StablecoinyPelneDobyV315.DD
        h = zd.parse_stabh(self._j(DD), now=datetime.datetime(2026, 10, 10, 7, 21, 29, tzinfo=self.U))
        self.assertEqual((h['pelne']['do'], h['pelne']['cur'], h['cur']), ('2026-10-09', 311611497263, 310982936603),
                         'poziom na koniec 09.10 (dd), a nie z chwili pobrania (cur — punkt 10.10)')
        self.assertEqual(h['pelne']['cur'] - h['pelne']['d']['7'], dict(DD)['2026-10-02'], 'poziom − zmiana 7 dób = poziom na koniec 02.10')
        self.assertEqual(h['pelne']['cur'] - h['pelne']['d']['30'], dict(DD)['2026-09-09'])
        h2 = zd.parse_stabh(self._j(DD), now=datetime.datetime(2026, 10, 11, 0, 20, tzinfo=self.U))
        self.assertEqual((h2['pelne']['do'], h2['pelne']['cur']), ('2026-10-10', 310982936603), 'po północy UTC doba 10.10 jest zamknięta')
        self.assertEqual(zd._stabh_pelne([['2026-10-08', 3.0e11], ['2026-10-09', 3.1e11]], '2026-10-10'),
                         {'do': '2026-10-09', 'cur': 310000000000, 'od': {}, 'd': {}, 'pct': {}}, 'bez okna 7 i 30 dób — sam poziom (strona: jak dotąd)')
        self.assertIsNone(zd._stabh_pelne([['2026-10-10', 3e11]], '2026-10-10'), 'bez zamkniętej doby — bez pola')

    def _tr(self, cm, now=None):
        with mock.patch.object(zd, '_now_utc', return_value=now or self.NOW):
            zd.META['notes'].clear()
            out = zd.build_trendy({'cm': {'assets': cm}})
        self.assertEqual([x for x in zd.META['notes'] if x.startswith('trendy cm')], [], 'bez wyjątku w części giełd')
        return {r['id']: r for r in out['f']}

    def test_gieldy_tylko_zamkniete_doby(self):
        cm = {k: {'d': [r[:] for r in v]} for k, v in self.CM.items()}
        R = self._tr(cm)
        self.assertEqual({k: (R[k]['date'], R[k]['sz'], R[k]['w'], R[k]['base'], R[k]['st']) for k in ('cm_btc', 'cm_eth')},
                         {'cm_btc': ('2026-10-09', 7, -16982.52, -21661.22, 'out_flat'), 'cm_eth': ('2026-10-09', 7, 122558.37, -36652.46, 'in_new')},
                         'jak trendy.json migawki m7 (7 dób do 09.10)')
        # wiersz dzisiejszej, niezamkniętej doby (dostawca go nie publikuje, warunek jest jawny) — bez wpływu na kartę
        for k in cm:
            cm[k]['d'].append(['2026-10-10', 1.0, 1.0, 900000.0, 1, 1, 9000000000, 2600000.0, 300000000000])
        R2 = self._tr(cm)
        self.assertEqual({k: (R2[k]['date'], R2[k]['w'], R2[k]['base']) for k in ('cm_btc', 'cm_eth')},
                         {'cm_btc': ('2026-10-09', -16982.52, -21661.22), 'cm_eth': ('2026-10-09', 122558.37, -36652.46)})
        # dobę później 10.10 jest już zamknięta — wchodzi do okna
        R3 = self._tr(cm, self.NOW + datetime.timedelta(days=1))
        self.assertEqual({k: R3[k]['date'] for k in ('cm_btc', 'cm_eth')}, {'cm_btc': '2026-10-10', 'cm_eth': '2026-10-10'})
        self.assertNotEqual(R3['cm_btc']['w'], -16982.52)
        # plik bez części albo bez wierszy — bez karty (jak dotąd), bez wyjątku
        for cm0 in ({}, {'btc': {}}, {'btc': {'d': None}}, {'btc': {'d': [None, 'x', [], [5]]}}):
            self.assertNotIn('cm_btc', self._tr(cm0), cm0)

    def test_kod(self):
        with open(zd.__file__, encoding='utf-8') as f:
            src = f.read()
        cm = src[src.index('    def coinmetrics():'):src.index('    def stable():')]
        self.assertIn('_d(r[0]) < today]', cm, 'giełdy: jawny warunek zamkniętej doby')
        self.assertIn("out = {'do': do, 'cur': round(M[do]),", src)


