        self.assertTrue(any('przesunięte o dzień później' in n for n in D['notes']))
        D2 = zd.build_dolar(D, now=DolarV136.NOW + datetime.timedelta(minutes=30), fetch=DolarV136('test_historia_laczenie')._fetch()[0])
