@mock.patch.object(zd, 'LEV9', ())   # v369 (F6Z2): bez nowych giełd w testach dotychczasowych części
class DzwigniaF1Z3(unittest.TestCase):
    """v343 (F1Z3): kontrakty z datą Deribit (basis, krzywa terminowa), pełniejsze opcje (zmienność ATM, skos, max pain, ściany, obrót put/call), kontrakty z datą OKX
    (do kontroli), Coinbase USA (lista kontraktów z limitem rozmiaru odpowiedzi), historia basis 3M. Zegar przypięty (NOW), sieć zablokowana — zaślepki."""
    TODAY = datetime.date(2026, 10, 11)

    def setUp(self):
        zd.META['errors'].clear(); zd.META['ok'].clear(); zd.META['notes'].clear()
        self.enterContext(mock.patch.object(zd, 'NOW', _F1Z3_T0))

    def gj(self, url, headers=None, timeout=30):
        self.assertLessEqual(timeout, 20, url)
        cur = lambda key: url.split(key)[1][:3]
        if 'kind=future' in url: return json.loads(_F1Z3_DR_FUT[cur('currency=')])
        if 'kind=option' in url: return json.loads(_F1Z3_DR_OPT[cur('currency=')])
        if 'instFamily=' in url: return json.loads(_F1Z3_OKX_MARK[cur('instFamily=')])
        if 'index-tickers' in url: return json.loads(_F1Z3_OKX_IDX[cur('instId=')])
        raise AssertionError('nieznany adres ' + url)

    # ---------- arytmetyka basis ----------
    def test_basis_arytmetyka_i_brak_zamiast_zera(self):
        self.assertEqual(zd.lev_basis(105.0, 100.0, 73.0), (5.0, 25.0), '5 % w 73 dni = 25 % rocznie (prosta annualizacja × 365 / dni)')
        self.assertEqual(zd.lev_basis(99.0, 100.0, 36.5), (-1.0, -10.0), 'kontrakt tańszy od indeksu (backwardation) — ujemny basis')
        self.assertEqual(zd.lev_basis(100.0, 100.0, 30.0), (0.0, 0.0), 'zero wyliczone z cen to prawdziwe zero, nie brak')
        for bad in ((None, 100.0, 30.0), (100.0, None, 30.0), (100.0, 100.0, None), (0.0, 100.0, 30.0), (100.0, 0.0, 30.0), (100.0, 100.0, 0.0), (100.0, 100.0, -1.0)):
            self.assertEqual(zd.lev_basis(*bad), (None, None), repr(bad))

    # ---------- Deribit: kontrakty z datą ----------
    def test_deribit_krzywa_z_nagrania(self):
        j = json.loads(_F1Z3_DR_FUT['BTC'])
        f = zd.dr_fut('BTC', j)
        self.assertEqual(f['t'], '2026-10-11T06:09:18+00:00', 'czas z odpowiedzi giełdy (creation_timestamp), nie z zegara zbieracza')
        R = {r['instrument_name']: r for r in j['result']}
        idx = R['BTC-30OCT26']['estimated_delivery_price']
        self.assertEqual(f['idx'], round(idx, 2))
        self.assertEqual([x['d'] for x in f['terms']], ['2026-10-23', '2026-10-30', '2026-11-27', '2026-12-25', '2027-03-26', '2027-06-25', '2027-09-24'],
                         'terminy od 7 dni; cotygodniowe 11–16.10 (krócej niż 7 dni) pominięte, wieczysty osobno')
        t = datetime.datetime(2026, 10, 11, 6, 9, 18, tzinfo=datetime.timezone.utc)
        for x in f['terms']:
            e = datetime.datetime.fromisoformat(x['d'] + 'T08:00:00+00:00')
            dni = (e - t).total_seconds() / 86400
            mark = R['BTC-' + e.strftime('%d%b%y').upper()]['mark_price']
            self.assertEqual(x['mark'], mark); self.assertEqual(x['dni'], round(dni, 1))
            self.assertEqual(x['b'], round((mark / idx - 1) * 100, 3)); self.assertEqual(x['y'], round((mark / idx - 1) * 365 / dni * 100, 2))
        z = [x for x in f['terms'] if x['d'] == '2026-12-25'][0]
        self.assertEqual((z['b'], z['y'], z['dni']), (1.129, 5.49, 75.1)); self.assertEqual(z['oi_usd'], 317042640.0, 'otwarte pozycje kontraktów odwrotnych Deribit są w USD')
        p = f['perp']; self.assertEqual(p['mark'], 82981.11); self.assertEqual(p['oi_usd'], 830557640.0); self.assertEqual(p['f8'], 5.21e-06)
        self.assertEqual(p['f_y'], round(5.21e-06 * 3 * 365 * 100, 3), 'stawka z 8 h × 3 × 365')
        e = zd.dr_fut('ETH', json.loads(_F1Z3_DR_FUT['ETH']))
        self.assertEqual(e['perp']['f8'], 0.0); self.assertEqual(e['perp']['f_y'], 0.0, 'stawka dokładnie zero to prawdziwa liczba z giełdy (nie brak)')
        self.assertEqual(len(e['terms']), 7)

    def test_deribit_krzywa_brak_zamiast_zera_i_bledy(self):
        base = json.loads(_F1Z3_DR_FUT['BTC'])
        with self.assertRaises(ValueError): zd.dr_fut('BTC', {'result': []})
        with self.assertRaises(ValueError): zd.dr_fut('BTC', [])
        no_idx = json.loads(_F1Z3_DR_FUT['BTC'])
        for r in no_idx['result']: r['estimated_delivery_price'] = None
        with self.assertRaises(ValueError): zd.dr_fut('BTC', no_idx)
        j = json.loads(_F1Z3_DR_FUT['BTC'])
        for r in j['result']:
            if r['instrument_name'] == 'BTC-30OCT26': r['mark_price'] = 0
            if r['instrument_name'] == 'BTC-27NOV26': r['open_interest'] = 0; r['volume_usd'] = None
            if r['instrument_name'] == 'BTC-PERPETUAL': r['funding_8h'] = 0.5   # pomyłka jednostki: 50 % za 8 h
        f = zd.dr_fut('BTC', j)
        self.assertNotIn('2026-10-30', [x['d'] for x in f['terms']], 'cena znacznikowa zero → termin pominięty, nie basis −100 %')
        n = [x for x in f['terms'] if x['d'] == '2026-11-27'][0]
        self.assertEqual((n['oi_usd'], n['vol_usd']), (None, None), 'zero pozycji i brak obrotu → brak, nie zero')
        self.assertIsNone(f['perp']['f8']); self.assertIsNone(f['perp']['f_y']); self.assertEqual(f['perp']['oi_usd'], 830557640.0)
        weekly = {'result': [dict(base['result'][0], instrument_name='BTC-12OCT26', creation_timestamp=1791698958000)]}
        with self.assertRaises(ValueError): zd.dr_fut('BTC', weekly)   # sam krótki termin, bez wieczystego — nic do pokazania
        only_perp = {'result': [r for r in base['result'] if r['instrument_name'] == 'BTC-PERPETUAL']}
        o = zd.dr_fut('BTC', only_perp); self.assertEqual(o['terms'], []); self.assertEqual(o['perp']['mark'], 82981.11)

    # ---------- Deribit: opcje wg terminu ----------
    @staticmethod
    def opt(exp, k, ty, oi, iv, fwd, vol=None, ts=1791698958000, idx=100000.0):
        return {'instrument_name': f'BTC-{exp}-{k}-{ty}', 'open_interest': oi, 'mark_iv': iv, 'underlying_price': fwd, 'volume': vol, 'creation_timestamp': ts, 'estimated_delivery_price': idx}

    def test_opcje_termin_syntetyczny_ręcznie_policzony(self):
        o = self.opt
        # termin miesięczny 30OCT26 (piątek, ostatni w miesiącu), forward 100 000; zmienność 50/54 na cenie 100 000, put 90 000 — 60, call 110 000 — 48
        R = [o('30OCT26', 90000, 'C', 1, 70, 100000.0, 10.0), o('30OCT26', 100000, 'C', 2, 50, 100000.0, 20.0), o('30OCT26', 110000, 'C', 3, 48, 100000.0, 30.0),
             o('30OCT26', 90000, 'P', 4, 60, 100000.0, 40.0), o('30OCT26', 100000, 'P', 2, 54, 100000.0, 50.0), o('30OCT26', 110000, 'P', 7, 44, 100000.0, 60.0),
             {'instrument_name': 'BTC-PERPETUAL', 'open_interest': 999}, {'instrument_name': 'BTC-31FEB26-1-P', 'open_interest': 1}]
        out = zd.dr_terms(R)
        self.assertEqual(len(out['term']), 1)
        x = out['term'][0]
        self.assertEqual((x['d'], x['mo']), ('2026-10-30', True))
        t = datetime.datetime.fromtimestamp(1791698958, datetime.timezone.utc)
        self.assertEqual(x['dni'], round((datetime.datetime(2026, 10, 30, 8, tzinfo=datetime.timezone.utc) - t).total_seconds() / 86400, 1))
        self.assertEqual(x['iv'], 52.0, 'zmienność ATM = średnia IV calla i putu na cenie wykonania najbliższej forwardowi')
        self.assertEqual(x['skew'], 12.0, 'skos = IV putu 90 % forwardu − IV calla 110 % forwardu')
        # max pain liczone niezależnie (siatka cen rozliczenia = ceny wykonania)
        oi = {(90000, 'C'): 1, (100000, 'C'): 2, (110000, 'C'): 3, (90000, 'P'): 4, (100000, 'P'): 2, (110000, 'P'): 7}
        pay = {K: sum(v * (max(0, K - k) if ty == 'C' else max(0, k - K)) for (k, ty), v in oi.items()) for K in (90000, 100000, 110000)}
        self.assertEqual(x['pain'], min(pay, key=pay.get)); self.assertEqual(x['pain'], 110000, 'ręcznie: wypłaty 160 000 / 80 000 / 40 000 dla cen rozliczenia 90 000 / 100 000 / 110 000')
        self.assertEqual(x['walls'], [[110000, 7.0, 3.0], [90000, 4.0, 1.0], [100000, 2.0, 2.0]], '3 ceny wykonania z największą liczbą otwartych opcji (put + call), malejąco')
        self.assertEqual(x['pc'], round(13 / 6, 4)); self.assertEqual(x['oi'], 19.0); self.assertEqual(x['oi_usd'], 1900000.0); self.assertEqual(x['fwd'], 100000.0)
        self.assertEqual((out['vol_p'], out['vol_c'], out['pcv']), (150.0, 60.0, 2.5), 'obrót 24 h w monetach: put 40+50+60, call 10+20+30')

    def test_opcje_pomijanie_i_braki(self):
        o = self.opt
        # skos: najbliższa cena wykonania dalej niż 4 % od celu → brak (nie liczba z dalekiej ceny); IV zero = brak wyceny
        R = [o('30OCT26', 100000, 'C', 5, 50, 100000.0), o('30OCT26', 100000, 'P', 5, 0, 100000.0), o('30OCT26', 80000, 'P', 5, 70, 100000.0), o('30OCT26', 130000, 'C', 5, 40, 100000.0)]
        x = zd.dr_terms(R)['term'][0]
        self.assertEqual(x['iv'], 50.0, 'IV putu 0 = brak wyceny — średnia tylko z calla'); self.assertIsNone(x['skew'])
        R = [o('30OCT26', 100000, 'C', 5, 0, 100000.0), o('30OCT26', 100000, 'P', 5, None, 100000.0)]
        self.assertIsNone(zd.dr_terms(R)['term'][0]['iv'], 'bez zmienności — brak, nie zero')
        # termin za mniej niż dobę, termin bez pozycji i bez forwardu — pominięte; bez woluminu — obrót brak
        R = [o('11OCT26', 100000, 'C', 5, 50, 100000.0), o('30OCT26', 100000, 'C', 0, 50, 100000.0), o('27NOV26', 100000, 'C', 5, 50, None)]
        out = zd.dr_terms(R)
        self.assertEqual(out['term'], []); self.assertEqual((out['vol_p'], out['vol_c'], out['pcv']), (None, None, None))
        # wybór terminów: wszystkie miesięczne + najwyżej 3 najbliższe tygodniowe z pozycjami ≥ 50 mln USD
        R = []
        for e in ('16OCT26', '23OCT26', '2NOV26', '9NOV26', '13NOV26'):
            R += [o(e, 100000, 'C', 1000, 50, 100000.0)]                      # 1000 × 100 000 = 100 mln USD
        R += [o('20NOV26', 100000, 'C', 100, 50, 100000.0)]                   # 10 mln USD — poniżej progu
        R += [o('30OCT26', 100000, 'C', 1, 50, 100000.0), o('27NOV26', 100000, 'C', 1, 50, 100000.0)]   # miesięczne zostają mimo małych pozycji
        sel = zd.dr_terms(R)['term']
        self.assertEqual([(x['d'], x['mo']) for x in sel], [('2026-10-16', False), ('2026-10-23', False), ('2026-10-30', True), ('2026-11-02', False), ('2026-11-27', True)],
                         '2NOV26 to poniedziałek (tygodniowy, nie miesięczny); trzy najbliższe tygodniowe + miesięczne, 20NOV26 za mało pozycji')
        self.assertEqual(zd.dr_terms([o('26MAR27', 100000, 'C', 1, 50, 100000.0)])['term'][0]['mo'], True)
        self.assertEqual(zd.dr_terms([o('25DEC26', 100000, 'C', 1, 50, 100000.0)])['term'][0]['mo'], True, 'ostatni piątek grudnia 2026 to 25.12')
        self.assertEqual(zd.dr_terms([o('18DEC26', 100000, 'C', 1000, 50, 100000.0)])['term'][0]['mo'], False)

