    # ---------- Coinbase USA ----------
    def test_cde_parse_z_nagrania(self):
        j = json.loads(_F1Z3_CDE)
        c = zd.cde_parse(j)
        self.assertEqual(c['t'], '2026-10-11T06:08:47+00:00', 'czas odpowiedzi z pola time_to_expiry_ms (rozliczenie − pozostały czas), nie z zegara'); self.assertEqual(c['f_hours'], 1)
        b = c['BTC']
        self.assertEqual(b['f_hours'], 1.0); self.assertEqual(b['f_h'], 6e-06); self.assertEqual(b['f_y'], round(6e-06 * 24 * 365 * 100, 3), 'stawka za godzinę (funding_interval 3600 s) → rok')
        self.assertEqual(b['oi'], round(169607 * 0.01, 4), 'pozycje w monetach = kontrakty × rozmiar kontraktu (0,01 BTC)'); self.assertEqual(b['px'], 82982.5, 'cena środkowa')
        self.assertEqual(b['oi_usd'], round(round(169607 * 0.01, 4) * 82982.5)); self.assertEqual(b['vol'], round(40726 * 0.01, 4)); self.assertEqual(b['vol_usd'], 33792398)
        self.assertEqual(b['idx'], 82966.59)
        self.assertEqual([x['id'] for x in b['terms']], ['BIT-30OCT26-CDE'], 'kontrakty dalszych miesięcy (pozycje < 1 mln USD, brak ceny) pominięte jako cienkie')
        x = b['terms'][0]
        self.assertEqual((x['d'], x['px'], x['b']), ('2026-10-30', 83285.0, round((83285.0 / 82966.59232 - 1) * 100, 3)))
        dni = (datetime.datetime(2026, 10, 30, 16, tzinfo=datetime.timezone.utc) - datetime.datetime(2026, 10, 11, 6, 8, 47, tzinfo=datetime.timezone.utc)).total_seconds() / 86400
        self.assertEqual(x['dni'], round(dni, 1)); self.assertEqual(x['y'], round((83285.0 / 82966.59232 - 1) * 365 / dni * 100, 2)); self.assertEqual(x['oi_usd'], round(120486 * 0.01 * 83285.0))
        e = c['ETH']; self.assertEqual(e['oi'], round(244939 * 0.1, 4)); self.assertEqual(e['terms'][0]['id'], 'ET-30OCT26-CDE'); self.assertEqual(len(e['terms']), 1)
        self.assertNotIn('GOL', json.dumps(c)); self.assertEqual(sorted(c), ['BTC', 'ETH', 'f_hours', 't'], 'produkty spoza BTC i ETH pominięte')

    def test_cde_parse_braki_wylaczone_i_bledy(self):
        j = json.loads(_F1Z3_CDE)
        for p in j['products']:
            if p['product_id'] == 'ET-30OCT26-CDE': p['trading_disabled'] = True
            if p['product_id'] == 'BIP-20DEC30-CDE': p['mid_market_price'] = '0'
        c = zd.cde_parse(j)
        self.assertEqual(c['BTC']['px'], 82975.0, 'brak ceny środkowej (0) → ostatnia cena transakcji')
        self.assertEqual(c['ETH']['terms'], [], 'kontrakt z wyłączonym handlem pominięty')
        for p in j['products']:
            if p['product_id'] == 'ETP-20DEC30-CDE': p['trading_disabled'] = True
        self.assertNotIn('ETH', zd.cde_parse(j), 'bez wieczystego nie ma wiersza monety (nie zero)')
        for p in j['products']:
            if p['product_id'] == 'BIP-20DEC30-CDE': p['is_disabled'] = True
        with self.assertRaises(ValueError): zd.cde_parse(j)
        for bad in ({}, {'products': []}, {'products': 'x'}, []):
            with self.assertRaises(ValueError): zd.cde_parse(bad)
        j2 = json.loads(_F1Z3_CDE)
        for p in j2['products']:
            if p['product_id'] == 'BIP-20DEC30-CDE': p['future_product_details']['index_price'] = ''; p['future_product_details']['funding_rate'] = ''
        b = zd.cde_parse(j2)['BTC']
        self.assertIsNone(b['idx']); self.assertEqual(b['terms'], [], 'bez indeksu nie liczymy basis (nie zero)'); self.assertIsNone(b['f_y']); self.assertIsNotNone(b['oi_usd'])

    def test_cde_get_limit_rozmiaru(self):
        class R:
            def __init__(s, b): s.b = b
            def __enter__(s): return s
            def __exit__(s, *a): return False
            def read(s, n=-1): return s.b[:n] if n >= 0 else s.b
        with mock.patch.object(zd, '_otworz', return_value=R(b'{"products":[]}')):
            self.assertEqual(zd.cde_get('https://x'), {'products': []})
        with mock.patch.object(zd, '_otworz', return_value=R(b'x' * (zd.CDE_MAXB + 1))):
            with self.assertRaises(ValueError) as cm: zd.cde_get('https://x')
        self.assertIn('większa niż', str(cm.exception))
        self.assertEqual(zd.CDE_MAXB, 2_000_000)
        src = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'zbieraj_dane.py'), encoding='utf-8').read()
        self.assertIn("CDE_URL = 'https://api.coinbase.com/api/v3/brokerage/market/products?product_type=FUTURE&limit=100'", src)
        self.assertNotIn('api_key', zd.CDE_URL); self.assertNotIn('apikey', zd.CDE_URL.lower())

    def test_lev_cde_strony_kursor_limit_stron_i_poprzednia_moneta(self):
        j = json.loads(_F1Z3_CDE)
        eth = [p for p in j['products'] if p['future_product_details']['contract_root_unit'] == 'ETH']
        btc = [p for p in j['products'] if p['future_product_details']['contract_root_unit'] != 'ETH']
        urls = []
        def get(u):
            urls.append(u)
            if len(urls) == 1: return {'products': btc, 'pagination': {'has_next': True, 'next_cursor': 'abc==', 'has_prev': False}}
            return {'products': eth, 'pagination': {'has_next': False, 'next_cursor': '', 'has_prev': True}}
        with mock.patch.object(zd, 'cde_get', side_effect=get):
            c = zd.lev_cde(None)
        self.assertEqual(urls, [zd.CDE_URL, zd.CDE_URL + '&cursor=abc%3D%3D'], 'kursor drugiej strony zakodowany'); self.assertEqual(sorted(c), ['BTC', 'ETH', 'f_hours', 't'])
        urls.clear()
        with mock.patch.object(zd, 'cde_get', side_effect=lambda u: urls.append(u) or {'products': btc, 'pagination': {'has_next': True, 'next_cursor': 'x'}}):
            c = zd.lev_cde({'ETH': {'oi_usd': 1.0, 't': 'stary'}})
