        self.assertEqual(c['ETH'], {'oi_usd': 1.0, 't': 'stary'}, 'brak wieczystego ETH → poprzedni wiersz z własnym czasem')
        self.assertTrue(any(e.startswith('Dźwignia: Coinbase USA: brak wiersza wieczystego ETH') for e in zd.META['errors']), zd.META['errors'])
        with mock.patch.object(zd, 'cde_get', return_value={'products': 'x'}):
            with self.assertRaises(ValueError): zd.lev_cde(None)
        with mock.patch.object(zd, 'cde_get', return_value=json.loads(_F1Z3_CDE)) as g:
            zd.lev_cde(None)
        g.assert_called_once_with(zd.CDE_URL)   # lista z limit=100 mieści się w jednej odpowiedzi — jedno zapytanie

