        self.assertEqual(out['s']['gvz'], prev['s']['gvz']); self.assertEqual(out['part_at']['gvz'], '2026-10-12T04:00:00+00:00', 'seria z błędem z własnym czasem')
        self.assertEqual(out['part_at']['vix'], self.NOWS)
