    ENV = {k: '' for k in ('SOSOVALUE_KEY', 'COINGECKO_KEY', 'FINNHUB_KEY', 'TWELVEDATA_KEY', 'COINMARKETCAP_KEY', 'FRED_KEY')}
    ROOT = os.path.dirname(os.path.abspath(__file__))

    def setUp(self):
        zd.META['errors'].clear(); zd.META['notes'].clear(); zd.META['ok'].clear()
        for p in (mock.patch.object(zd, 'NOW', self.NOW),):
            p.start(); self.addCleanup(p.stop)

    # ---------------- zaślepki zapytań ----------------
    def es_get(self, liab=None, ass=None):
        self.es_urls = []

        def get(url, headers=None, timeout=30):
            self.es_urls.append(url)
            sf = 'LIAB' if 'stk_flow=LIAB' in url else 'ASS'
            j = (liab if sf == 'LIAB' else ass) or (self.ES_LIAB if sf == 'LIAB' else self.ES_ASS)
            if isinstance(j, Exception):
                raise j
            return 200, json.dumps(j)
        return get

    def coh_get(self, rows=None, lm='default'):
        self.coh_urls = []

        def get(url, timeout=60):
            self.coh_urls.append(url)
            if isinstance(rows, Exception):
                raise rows
            return json.dumps(self.COH if rows is None else rows), (self.LM if lm == 'default' else lm)
        return get

    def zbuduj(self, prev=None, now=None, liab=None, ass=None, rows=None, lm='default'):
        with mock.patch.object(zd, 'get', self.es_get(liab, ass)), mock.patch.object(zd, 'pk_get_coh', self.coh_get(rows, lm)):
            return zd.build_polska_kapital(prev, now=now or self.NOW)

    def plik(self):
        return json.loads(json.dumps(self.zbuduj()))

    @staticmethod
    def kopia(o):
        return json.loads(json.dumps(o))

    def dt(self, s):
        return datetime.datetime.fromisoformat(s).astimezone(self.U)

    # ---------------- inwestycje według kraju: adres, parsowanie, składanie ----------------
    def test_adres_jedno_zapytanie_na_kierunek_bez_luznego_filtru(self):
        for sf in ('LIAB', 'ASS'):
            u = zd.PK_ES_URL.format(sf=sf, od='2024-Q1')
            self.assertIn('geo=PL', u); self.assertIn(f'stk_flow={sf}', u); self.assertIn('bop_item=FA__D__F', u); self.assertIn('sinceTimePeriod=2024-Q1', u)
            self.assertEqual(u.count('geo='), 1, 'jeden kraj sprawozdający (luźny filtr dla wielu krajów kończy się HTTP 413)'); self.assertNotIn('partner=', u, 'wszyscy partnerzy naraz')
        self.assertTrue(zd.PK_ES_URL.startswith('https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/bop_c6_q?'))
        self.assertTrue(zd.PK_COH_URL.startswith('https://cohesiondata.ec.europa.eu/resource/pbbz-hmfu.json?ms=PL'))

    def test_kwartaly_pomocnicze(self):
        self.assertEqual(zd.pk_kw_i('2026-Q2'), 2026 * 4 + 1); self.assertEqual(zd.pk_kw_lab(2026 * 4 + 1), '2026-Q2'); self.assertIsNone(zd.pk_kw_i('2026-Q5')); self.assertIsNone(zd.pk_kw_i('2026-06'))
        self.assertEqual([zd.pk_kw_koniec(q) for q in ('2026-Q1', '2026-Q2', '2026-Q3', '2026-Q4')], ['2026-03-31', '2026-06-30', '2026-09-30', '2026-12-31'])
        self.assertIsNone(zd.pk_kw_koniec('x'))

    def test_parse_eurostat_prawdziwe_wartosci_data_publikacji_i_pominiecia(self):
        upd, S = zd.pk_fdi_parse(self.ES_LIAB)
        self.assertEqual(upd, '2026-10-02T21:00:00Z', 'pole updated 23:00 czasu środkowoeuropejskiego → UTC')
        self.assertEqual(S['WRL_REST']['2026-Q2'], 4429.6); self.assertEqual(S['EU27_2020']['2026-Q2'], 2781.0); self.assertEqual(S['EXT_EU27_2020']['2026-Q2'], 1648.6)
        self.assertEqual(S['DE']['2026-Q1'], 1989.4); self.assertEqual(S['ES']['2026-Q1'], -6471.1, 'wartość ujemna (wycofanie) zostaje, nie jest zerem'); self.assertEqual(S['AT']['2026-Q1'], 7407.6)
        self.assertNotIn('2026-Q3', S['DE']); self.assertEqual(sorted(S['DE'])[0], '2024-Q1')
        self.assertNotIn('EU28', S, 'partner bez żadnej wartości nie wchodzi')
        with self.assertRaises(RuntimeError):
            zd.pk_fdi_parse({'id': ['time'], 'size': [1]})
        bad = self.kopia(self.ES_LIAB); bad['updated'] = 'wczoraj'
        with self.assertRaises(RuntimeError):
            zd.pk_fdi_parse(bad)
        big = self.kopia(self.ES_LIAB); big['value']['0'] = 9e9
        with self.assertRaises(RuntimeError):
            zd.pk_fdi_parse(big)

    def test_zloz_okno_osmiu_kwartalow_swiat_kraje_i_agregaty(self):
        F = self.plik()['fdi']
        self.assertEqual(F['q'], ['2024-Q3', '2024-Q4', '2025-Q1', '2025-Q2', '2025-Q3', '2025-Q4', '2026-Q1', '2026-Q2']); self.assertEqual(F['last'], '2026-Q2'); self.assertEqual(F['asof'], '2026-06-30')
        self.assertEqual(F['upd'], '2026-10-02T21:00:00Z'); self.assertEqual(F['upd_l'], '2026-10-02T21:00:00Z')
        I, O = F['in'], F['out']
        self.assertEqual(I['w'], [6785.7, 5809.6, 10014.8, 2413.0, 4146.5, 4709.8, 8477.9, 4429.6]); self.assertEqual(I['eu'][-1], 2781.0); self.assertEqual(I['x'][-1], 1648.6)
        self.assertEqual(O['w'][-1], 482.2); self.assertEqual(O['w'][-2], 522.1)
        for B in (I, O):
            for i in range(8):
                self.assertLessEqual(abs(B['w'][i] - (B['eu'][i] + B['x'][i])), 1.0, 'świat = UE27 + poza UE27')
            self.assertFalse(set(B['c']) & {'WRL_REST', 'EU27_2020', 'EXT_EU27_2020', 'EA21', 'EA20', 'EXT_EA21', 'EXT_EA20', 'EUI', 'PL', 'EU28'}, 'agregaty, własny kraj i instytucje UE nie są krajami')
            self.assertTrue({'DE', 'NL', 'US', 'UK', 'EL', 'CN_X_HK', 'OFFSHO', 'LU', 'IE'} <= set(B['c'])); self.assertTrue(all(len(r) == 8 for r in B['c'].values()))
        self.assertEqual(I['c']['DE'][-1], 1155.4); self.assertEqual(I['c']['ES'][-2], -6471.1); self.assertEqual(O['c']['NL'][-1], 396.0)
        self.assertEqual(I['c']['OFFSHO'][-1], 112.2); self.assertEqual(I['c']['CN_X_HK'][-1], 200.3)
        self.assertEqual(sum(1 for r in I['c'].values() if r[-1] is not None), len(I['c']) - sum(1 for r in I['c'].values() if r[-1] is None))

    def test_zloz_brak_wartosci_kraju_to_none_nigdy_zero(self):
        L = self.kopia(self.ES_LIAB)
        # usuń wartość Niemiec w 2026-Q1: indeks płaski = partner × liczba kwartałów + kwartał (okno nagrania: 10 kwartałów 2024-Q1…2026-Q2)
        P = list(L['dimension']['partner']['category']['index']); T = list(L['dimension']['time']['category']['index'])
        k = str(P.index('DE') * len(T) + T.index('2026-Q1')); self.assertIn(k, L['value']); del L['value'][k]
        F = self.zbuduj(liab=L)['fdi']; self.assertIsNone(F['in']['c']['DE'][-2]); self.assertEqual(F['in']['c']['DE'][-1], 1155.4); self.assertEqual(F['in']['c']['DE'][-3], 236.2)
        self.assertEqual(F['in']['c']['DE'].count(None), 1, 'jedna luka, reszta bez zer')

    def test_bramka_fdi(self):
        def blad(fn, fragment):
            with self.assertRaises(RuntimeError) as c:
                fn()
            self.assertIn(fragment, str(c.exception))
        upd, S = zd.pk_fdi_parse(self.ES_LIAB); upd2, A = zd.pk_fdi_parse(self.ES_ASS)
        S1 = self.kopia(S); S1['WRL_REST']['2026-Q2'] += 50.0
        blad(lambda: zd.pk_fdi_zloz((upd, S1), (upd2, A)), 'świat')
        S1b = self.kopia(S); del S1b['WRL_REST']['2026-Q2']
        F = zd.pk_fdi_zloz((upd, S1b), (upd2, A)); self.assertEqual(F['last'], '2026-Q1', 'ostatni kwartał ze światem w OBU kierunkach (brak świata w jednym cofa okno)')
        p = self.zbuduj(liab=dict(self.ES_LIAB, updated='2026-10-02T23:00:00+0200', value=dict(self.ES_LIAB['value'], **{'0': 9e9})))
        self.assertEqual(p['ok'], {'fdi': False, 'ue': True}); self.assertNotIn('fdi', p, 'zła wartość = błąd odczytu, część bez poprzedniej nie wchodzi do pliku')
        A1c = self.kopia(A); del A1c['WRL_REST']['2026-Q2']
        F = zd.pk_fdi_zloz((upd, S), (upd2, A1c)); self.assertEqual(F['last'], '2026-Q1', 'brak świata w kierunku ASS cofa okno tak samo (część wspólna kwartałów)')
        S2 = {p: v for p, v in S.items() if p != 'EU27_2020'}; blad(lambda: zd.pk_fdi_zloz((upd, S2), (upd2, A)), 'brak świata albo UE27')
        S3 = {p: v for p, v in S.items() if p in ('WRL_REST', 'EU27_2020', 'EXT_EU27_2020', 'DE', 'FR')}; blad(lambda: zd.pk_fdi_zloz((upd, S3), (upd2, A)), 'za mało krajów')
        S4 = self.kopia(S); S4['WRL_REST'] = {'2026-Q2': 1.0}; A4 = self.kopia(A); A4['WRL_REST'] = {'2026-Q2': 1.0}; blad(lambda: zd.pk_fdi_zloz((upd, S4), (upd2, A4)), 'świat nie ma kolejnych kwartałów')
        S5 = self.kopia(S); S5['WRL_REST'] = {}; blad(lambda: zd.pk_fdi_zloz((upd, S5), (upd2, A)), 'wspólnych kwartałów')

    # ---------------- rytm zapytań ----------------
    def test_fdi_rytm_jedno_zapytanie_gdy_updated_bez_zmian_i_cisza_przez_22_godziny(self):
        p1 = self.zbuduj(); self.assertEqual(len(self.es_urls), 2, 'pierwsza budowa: oba kierunki'); self.assertEqual(self.es_urls[0].count('stk_flow=LIAB'), 1)
        self.assertEqual(p1['ok'], {'fdi': True, 'ue': True}); self.assertEqual(p1['part_at'], {'fdi': self.NOW, 'ue': self.NOW})
        # 10 minut później: ani jednego zapytania
        p2 = self.zbuduj(p1, now='2026-10-13T20:10:00+00:00'); self.assertEqual(self.es_urls, [], 'odstęp 22 h jeszcze nie minął'); self.assertEqual(self.coh_urls, [], 'zbiór wypłat po 06:15 dziś już pobrany')
        self.assertEqual(p2['ok'], {'fdi': 'cached', 'ue': 'cached'}); self.assertEqual(p2['fdi'], p1['fdi']); self.assertEqual(p2['part_at'], p1['part_at'])
        # następnego dnia o 21:00 (22 h po poprzednim sprawdzeniu): updated bez zmian → tylko zapytanie o kierunek LIAB; zbiór wypłat pobrany (po 06:15 UTC)
        p3 = self.zbuduj(p2, now='2026-10-14T21:00:00+00:00')
        self.assertEqual(len(self.es_urls), 1); self.assertIn('stk_flow=LIAB', self.es_urls[0]); self.assertEqual(len(self.coh_urls), 1)
        self.assertEqual(p3['ok'], {'fdi': 'cached', 'ue': True}); self.assertEqual(p3['fdi']['at'], p1['fdi']['at'], 'część bez zmian zostaje, odstęp liczony od sprawdzenia')
        self.assertEqual(p3['part_at']['fdi'], '2026-10-14T21:00:00+00:00', 'sprawdzenie zapisane w part_at')

