    def test_ue_parse_sumy_lata_fundusze_programy_dzien_z_naglowka(self):
        U = zd.pk_ue_parse(json.dumps(self.COH), self.LM)
        self.assertEqual(U['asof'], '2026-10-13'); self.assertEqual(U['t'], '2026-10-13T05:49:39Z'); self.assertEqual(U['yr'], 2026)
        self.assertEqual(U['total'], 11146.3); self.assertEqual(U['plan'], 36777.8); self.assertEqual(U['ydr'], {'2022': 488.5, '2023': 858.1, '2024': 1997.8, '2025': 6148.3})
        F = {r[0]: r for r in U['funds']}; self.assertEqual(set(F), {'erdf', 'esf', 'cf', 'jtf', 'eafrd', 'emfaf', 'home'}, 'AMIF, BMVI i ISF razem w grupie „home”')
        self.assertAlmostEqual(F['home'][1], 89.2 + 112.5 + 18.6, delta=0.2); self.assertEqual(F['eafrd'][1], 1447.4); self.assertAlmostEqual(sum(r[1] for r in U['funds']), U['total'], delta=0.5)
        self.assertEqual(U['funds'], sorted(U['funds'], key=lambda r: -r[1])); self.assertAlmostEqual(sum(r[2] for r in U['funds']), U['plan'], delta=0.5)
        P = {r[0]: r for r in U['prog']}; self.assertEqual(U['n'], 9); self.assertEqual(P['Infrastructure, Climate, Environment'][1:], [7229.5, 24188.2]); self.assertEqual(P['Food Aid'][1:], [141.4, 525.0]); self.assertIn('Śląskie', P)
        self.assertAlmostEqual(sum(r[1] for r in U['prog']), U['total'], delta=0.5); self.assertEqual(U['prog'][0][0], 'Infrastructure, Climate, Environment')
        self.assertTrue(U['ydr']['2022'] <= U['ydr']['2023'] <= U['ydr']['2024'] <= U['ydr']['2025'] <= U['total'], 'sumy skumulowane rosną')

    def test_ue_bramki(self):
        def blad(rows, lm, fragment):
            with self.assertRaises(RuntimeError) as c:
                zd.pk_ue_parse(json.dumps(rows), lm)
            self.assertIn(fragment, str(c.exception))
        blad(self.COH, None, 'brak daty'); blad(self.COH, 'wczoraj', 'brak daty'); blad([], self.LM, 'pusta'); blad({'a': 1}, self.LM, 'pusta')
        with self.assertRaises(RuntimeError):
            zd.pk_ue_parse('<html>', self.LM)
        R = self.kopia(self.COH); R[0]['ms'] = 'DE'; blad(R, self.LM, 'spoza Polski')
        R = self.kopia(self.COH); R[3]['total_net_payments'] = '-'; blad(R, self.LM, 'bez roku, kwoty')
        R = self.kopia(self.COH)
        for r in R:
            r['is_latest_period'] = 'N'
        blad(R, self.LM, 'niejednoznaczne')
        R = self.kopia(self.COH); [r.update(year='2027') for r in R if r['is_latest_period'] == 'Y'][:1]; R[0]['year'] = '2028'; blad(R, self.LM, 'nowszy')
        R = self.kopia(self.COH)
        for r in R:
            if r['is_latest_period'] == 'Y':
                r['total_net_payments'] = str(float(r['actual_plan_eu_amt_latest_adop']) * 2)
        blad(R, self.LM, 'poza zakresem')
        R = self.kopia(self.COH)
        for r in R:
            if r['year'] == '2025':
                r['total_net_payments'] = str(float(r['total_net_payments']) * 4)
        blad(R, self.LM, 'maleje')
        R = self.kopia(self.COH)
        for r in R:
            r['actual_plan_eu_amt_latest_adop'] = '1000'
        blad(R, self.LM, 'poza zakresem')

    def test_ue_historia_dobowa_jeden_punkt_na_dzien_obciecie_i_dzien_nie_cofa_sie(self):
        p1 = self.zbuduj(); self.assertEqual(p1['ue']['hist'], [['2026-10-13', 11146.3]])
        # dzień danych pochodzi z nagłówka odpowiedzi, nie z zegara przebiegu: zbiór zmieniony w poniedziałek 12.10, przebieg 13.10
        p0 = self.zbuduj(lm='Mon, 12 Oct 2026 22:30:00 GMT'); self.assertEqual((p0['ue']['asof'], p0['ue']['t']), ('2026-10-12', '2026-10-12T22:30:00Z')); self.assertEqual(p0['ue']['hist'], [['2026-10-12', 11146.3]])
        # dzień później: zbiór zmieniony
        R2 = self.kopia(self.COH)
        for r in R2:
            if r['is_latest_period'] == 'Y':
                r['total_net_payments'] = str(float(r['total_net_payments']) + 1e6)
        p2 = self.zbuduj(p1, now='2026-10-14T06:30:00+00:00', rows=R2, lm='Wed, 14 Oct 2026 05:51:00 GMT')
        self.assertEqual([r[0] for r in p2['ue']['hist']], ['2026-10-13', '2026-10-14']); self.assertAlmostEqual(p2['ue']['hist'][1][1] - p2['ue']['hist'][0][1], 17.0, delta=0.5, msg='17 rekordów bieżącego okresu × 1 mln EUR')
        # ten sam dzień danych (zbiór nieodświeżony): punkt zastąpiony, nie dopisany
        p3 = self.zbuduj(p2, now='2026-10-15T06:30:00+00:00', rows=R2, lm='Wed, 14 Oct 2026 05:51:00 GMT'); self.assertEqual([r[0] for r in p3['ue']['hist']], ['2026-10-13', '2026-10-14'])
        # cofnięty dzień (starszy nagłówek) — zostaje poprzedni plik, notatka
        p4 = self.zbuduj(p2, now='2026-10-15T06:30:00+00:00', lm='Mon, 12 Oct 2026 05:00:00 GMT'); self.assertEqual(p4['ue']['asof'], '2026-10-14'); self.assertTrue(any('zostaje poprzedni' in n for n in zd.META['notes']))
        # obcięcie do 130 dni
        stary = self.kopia(p1); stary['ue']['hist'] = [['2026-05-01', 9000.0], ['2026-06-20', 10000.0]] + stary['ue']['hist']; stary['part_at']['ue'] = '2026-10-12T06:30:00+00:00'
        p5 = self.zbuduj(stary, now='2026-10-14T06:30:00+00:00', rows=R2, lm='Wed, 14 Oct 2026 05:51:00 GMT')
        self.assertEqual([r[0] for r in p5['ue']['hist']], ['2026-06-20', '2026-10-13', '2026-10-14'], '2026-05-01 starszy niż 130 dni')
        # spadek sumy (korekta) = notatka, plik przyjęty
        R3 = self.kopia(self.COH)
        for r in R3:
            if r['is_latest_period'] == 'Y':
                r['total_net_payments'] = str(float(r['total_net_payments']) * 0.9)
        zd.META['notes'].clear(); p6 = self.zbuduj(p1, now='2026-10-14T06:30:00+00:00', rows=R3, lm='Wed, 14 Oct 2026 05:51:00 GMT'); self.assertTrue(any('korekta' in n for n in zd.META['notes'])); self.assertLess(p6['ue']['total'], p1['ue']['total'])

