        saved = self.main_wynik({'v': 1, 'at': '2026-10-13T16:00:00+00:00'}, b)
        self.assertIs(saved['polska-kapital'], nowy); self.assertEqual({k: zd.META['ok'][k] for k in ('polska_kapital_fdi', 'polska_kapital_ue')}, {'polska_kapital_fdi': 'cached', 'polska_kapital_ue': False})
        self.assertIn('run_t0', b.call_args.kwargs); self.assertEqual(b.call_args.args[0]['at'], '2026-10-13T16:00:00+00:00')

