    def test_pobranie_zbioru_wyplat_naglowek_last_modified_i_limit_rozmiaru(self):
        class R:
            def __init__(s, body, lm):
                s.body, s.headers = body, ({'Last-Modified': lm} if lm else {})
            def read(s, n=-1):
                return s.body if n < 0 else s.body[:n]
            def __enter__(s):
                return s
            def __exit__(s, *a):
                return False
        with mock.patch.object(zd, '_otworz', lambda url, h=None, t=30: R(b'[1]', self.LM)) as o:
            self.assertEqual(zd.pk_get_coh(zd.PK_COH_URL), ('[1]', self.LM))
        with mock.patch.object(zd, '_otworz', lambda url, h=None, t=30: R(b'x' * (zd.PK_MAX_BAJTOW + 5), self.LM)):
            with self.assertRaises(RuntimeError):
                zd.pk_get_coh(zd.PK_COH_URL)

    # ---------------- kontrola dzienna ----------------
    @staticmethod
    def kt():
        import importlib.util, tempfile
        tmp = tempfile.mkdtemp(prefix='kontrola-v365-')
        with mock.patch.dict(os.environ, {'KONTROLA_DIR': os.path.join(tmp, 'k'), 'KONTROLA_ARCH': os.path.join(tmp, 'a')}, clear=False):
            spec = importlib.util.spec_from_file_location('v365_kontrola', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
            k = importlib.util.module_from_spec(spec); spec.loader.exec_module(k)
        return k

