        self.assertEqual(k.PLIKI[-2:], ['krypto-dzien', 'krypto-dziennik']); self.assertEqual(len(k.PLIKI), len(set(k.PLIKI)))
        for p in ('fdi', 'ue'):
            self.assertIn('zostaje z datą', k.AW_BEZ_BLEDU['polska_kapital_' + p])
