    def test_kontrola_swiezosc_progi(self):
        k = self.kt(); j = self.plik()
        now = datetime.datetime(2026, 10, 13, 21, 0, tzinfo=self.U)
        R = k.polska_kapital_swiezosc(j, now)
        self.assertEqual([r[0] for r in R], list(k.PK_K_ETYKIETA.values())); self.assertEqual([r[1] for r in R], ['✅', '✅']); self.assertEqual([r[3] for r in R], ['2026-06-30', '2026-10-13'])
        self.assertEqual(R[0][2], 104 * 1440 + 21 * 60, 'wiek od końca ostatniego dnia kwartału danych (30.06 24:00)'); self.assertEqual(R[1][2], 15 * 60 + 10, 'wiek od chwili aktualizacji zbioru (05:49:39 UTC)')
        # rytm kwartalny: dane za II kwartał pojawiły się 94 dni po jego końcu; tuż przed następną publikacją wiek ≈ 186 dni < próg 200
        self.assertLess(94 + 92, k.PK_K_PROG_DNI_FDI)
        R2 = k.polska_kapital_swiezosc(j, datetime.datetime(2026, 12, 31, 12, 0, tzinfo=self.U)); self.assertEqual(R2[0][1], '✅')
        R3 = k.polska_kapital_swiezosc(j, datetime.datetime(2027, 1, 20, 12, 0, tzinfo=self.U)); self.assertEqual(R3[0][1], '⚠️'); self.assertIn('najwyżej uwaga', R3[0][4]); self.assertNotIn('❌', [r[1] for r in R3])
        # wypłaty: weekend (3 dni) i święta bez uwagi, 10 dni = próg
        R4 = k.polska_kapital_swiezosc(j, datetime.datetime(2026, 10, 16, 6, 0, tzinfo=self.U)); self.assertEqual(R4[1][1], '✅')
        R5 = k.polska_kapital_swiezosc(j, datetime.datetime(2026, 10, 24, 6, 0, tzinfo=self.U)); self.assertEqual(R5[1][1], '⚠️'); self.assertIn('najwyżej uwaga', R5[1][4])
        R6 = k.polska_kapital_swiezosc(j, datetime.datetime(2027, 6, 1, tzinfo=self.U)); self.assertEqual([r[1] for r in R6], ['⚠️', '⚠️'], 'bez ❌ nawet po wielu miesiącach')
        R7 = k.polska_kapital_swiezosc(dict(j, ue=None), now); self.assertEqual(R7[1][1], '?'); self.assertEqual(R7[1][3], None)
        self.assertEqual(k.polska_kapital_swiezosc(None, now), []); self.assertEqual(k.polska_kapital_swiezosc({'v': 2}, now), [])

    def test_kontrola_spojnosc(self):
        k = self.kt(); j = self.plik()
        self.assertEqual(k.polska_kapital_spojnosc(j), [])
        z = self.kopia(j); z['fdi']['in']['w'][-1] += 40.0
        self.assertTrue(any('fdi.in' in s and 'UE27' in s for s in k.polska_kapital_spojnosc(z)))
        z = self.kopia(j); z['fdi']['q'][3] = '2025-Q4'
        self.assertTrue(any('kolejne' in s for s in k.polska_kapital_spojnosc(z)))
        z = self.kopia(j); z['fdi']['out']['c']['DE'] = z['fdi']['out']['c']['DE'][:5]
        self.assertTrue(any('fdi.out.c' in s for s in k.polska_kapital_spojnosc(z)))
        z = self.kopia(j); z['fdi']['in']['w'][-1] = None
        self.assertTrue(any('świat nie ma wartości' in s for s in k.polska_kapital_spojnosc(z)))
        z = self.kopia(j); z['fdi']['last'] = '2026-Q1'
        self.assertTrue(any('ostatni kwartał' in s for s in k.polska_kapital_spojnosc(z)))
        z = self.kopia(j); z['ue']['funds'][0][1] += 100.0
        self.assertTrue(any('ue.funds' in s and 'razem' in s for s in k.polska_kapital_spojnosc(z)))
        z = self.kopia(j); z['ue']['prog'][0][2] += 500.0
        self.assertTrue(any('ue.prog' in s and 'plan' in s for s in k.polska_kapital_spojnosc(z)))
        z = self.kopia(j); z['ue']['total'] = z['ue']['plan'] * 1.5
        self.assertTrue(any('> plan' in s for s in k.polska_kapital_spojnosc(z)))
        z = self.kopia(j); z['ue']['ydr']['2025'] = z['ue']['total'] * 2
        self.assertTrue(any('maleje' in s for s in k.polska_kapital_spojnosc(z)))
        z = self.kopia(j); z['ue']['hist'] = [['2026-10-12', 1.0], ['2026-10-13', j['ue']['total']], ['2026-10-13', j['ue']['total']]]
        self.assertTrue(any('hist' in s for s in k.polska_kapital_spojnosc(z)))
        z = self.kopia(j); z['ue']['hist'][-1][1] += 5.0
        self.assertTrue(any('ostatni punkt' in s for s in k.polska_kapital_spojnosc(z)))
        z = self.kopia(j); z['ue']['asof'] = '2026-10-12'; z['ue']['hist'][-1][0] = '2026-10-12'
        self.assertTrue(any('dzień danych' in s for s in k.polska_kapital_spojnosc(z)))

    def test_kontrola_porownanie_z_plikiem_miesiecznym_progi_z_testu_wstecznego(self):
        k = self.kt(); j = self.plik()
        ue = lambda a, b: {'rows': {'PL': {'s': {'in_d': [['2026-04', a[0]], ['2026-05', a[1]], ['2026-06', a[2]]], 'out_d': [['2026-04', b[0]], ['2026-05', b[1]], ['2026-06', b[2]]]}}}}
        # II kw. 2026: kwartalnie 4429,6 i 482,2; miesięcznie (13.10.2026) 2251,7 i −13,4 → różnica 2178 poniżej progu 5000; znak różny przy wartości kwartalnej 482 < 1000 — bez uwagi
        P = k.polska_kapital_porownania(j, {'ue': ue((900.0, 700.0, 651.7), (1.0, -4.4, -10.0))})
        self.assertEqual([w[1] for w in P['wiersze']], ['✅', '✅']); self.assertEqual(P['uwagi'], []); self.assertIn('2026-Q2 do Polski', P['wiersze'][0][0]); self.assertIn('4 430', P['wiersze'][0][0])
        P2 = k.polska_kapital_porownania(j, {'ue': ue((5000.0, 5000.0, 5000.0), (500.0, 0.0, 0.0))}); self.assertEqual([w[1] for w in P2['wiersze']], ['⚠️', '✅']); self.assertEqual(len(P2['uwagi']), 1); self.assertIn('najwyżej uwaga', P2['uwagi'][0])
