        P4 = k.polska_kapital_porownania(j, {}); self.assertEqual(P4, {'wiersze': [], 'uwagi': []})
        P5 = k.polska_kapital_porownania(j, {'ue': {'rows': {'PL': {'s': {'in_d': [['2026-06', 5.0]], 'out_d': []}}}}}); self.assertEqual([w[1] for w in P5['wiersze']], ['ℹ️', 'ℹ️'], 'brak trzech miesięcy = informacja')

