    def test_build_trzynascie_czesci_suma_bez_podwojnego_liczenia(self):
        o, V = self.build()
        self.assertEqual(o['ok'], {k: True for k in zd.LEV_PX if k != 'cz'}); self.assertEqual(len(o['ok']), 13); self.assertEqual(zd.META['errors'], [])
