        self.assertEqual(self.urls, [zd.PD_PAGE['pos'], f'https://www.gov.pl/attachment/{self.UID_POS}', zd.PD_PAGE['det'], f'https://www.gov.pl/attachment/{self.UID_DET}'], 'strona i plik każdej części, nic więcej')
