        self.assertIn('wagi 3: ', K['wiersze'][0][0])
        self.assertIsNone(k.kalendarz_kontrola({}, now)); self.assertIsNone(k.kalendarz_kontrola({'kalendarz': {'v': 2}}, now)); self.assertEqual(k.kalendarz_swiezosc({'v': 2}, now), [])

