        self.assertEqual(rows[k.KAL_K_ETYKIETA['sprz_us']][1], '?'); self.assertEqual(rows[k.KAL_K_ETYKIETA['bc_eu']][1], '✅'); self.assertIn('nieudane', rows[k.KAL_K_ETYKIETA['bc_eu']][4])
