        self.assertEqual([(e['t'][:10], e['k'], e.get('p')) for e in ev2 if e['k'] == 'pl_pkb'], [('2026-10-28', 'pl_pkb', '2026-Q3'), ('2026-11-30', 'pl_pkb', '2026-Q3')])
