        self.assertEqual((len(t2['pc']['h']), t2['pc']['h'][0][0]), (21, '2026-09-01')); self.assertEqual([r[0] for r in t2['in']['h']], ['2026-10-15', '2026-10-16'], 'pozycje dochodzą dzień po dniu')
