        self.assertLess(i0, i1); self.assertIn("kandlug_swiezosc(files.get('kanada-dlug'))", s); self.assertIn("kkd = Z.get('kanada-dlug')", s); self.assertIn("R['bledy'].append(f'kanada-dlug.json: sprzeczność w pliku — {z_}')", s)


