_V423_NOW = datetime.datetime(2026, 10, 18, 9, 0, tzinfo=datetime.timezone.utc)   # niedziela; ostatnie dane: H.8 i papiery komercyjne środa 7.10 / 14.10, stawki 15.10, ankiety kwartał 3 2026 (wydania 24.09 i 30.07)
_V423_URL = {'h8': '/h8/data/FRB_h8_xml.zip', 'cp': '/cp/data/FRB_CP_xml.zip', 'so': '/scoos/data/FRB_SCOOS_xml.zip', 'sl': '/sloos/data/FRB_SLOOS_xml.zip'}


def _v423_xml(serie, prep='2026-10-16T10:00:00', dtd=''):
    """Serie [(atrybuty, [(dzień, status, wartość)])] → bajty XML w układzie paczek wydania (przestrzenie nazw SDMX, nagłówek z datą przygotowania)."""
    p = ['<?xml version="1.0" encoding="UTF-8" standalone="no"?>\n' + dtd + '<message:MessageGroup xmlns:message="http://www.SDMX.org/resources/SDMXML/schemas/v1_0/message" '
         'xmlns:frb="http://www.federalreserve.gov/structure/compact/common" xmlns:kf="http://www.federalreserve.gov/structure/compact/X">\n  <message:Header>\n    <message:ID>X</message:ID>\n'
         '    <message:Prepared>' + prep + '</message:Prepared>\n  </message:Header>\n  <frb:DataSet id="X">\n']
    for at, obs in serie:
        p.append('    <kf:Series ' + ' '.join(f'{k}="{v}"' for k, v in sorted(at.items())) + '>\n      <frb:Annotations/>\n')
        for d, st, v in obs:
            p.append(f'      <frb:Obs OBS_STATUS="{st}" OBS_VALUE="{v}" TIME_PERIOD="{d}" />\n')
        p.append('    </kf:Series>\n')
    p.append('  </frb:DataSet>\n</message:MessageGroup>\n')
    return ''.join(p).encode('utf-8')


def _v423_zip(member, xml):
    import zipfile as _zf
    b = io.BytesIO()
    with _zf.ZipFile(b, 'w', _zf.ZIP_DEFLATED) as z:
        z.writestr('frb_common.xsd', '<xsd/>')
        z.writestr(member, xml)
    return b.getvalue()


def _v423_h8_serie():
    return [({'BG': 'CB', 'CATEGORY': 'A', 'CURRENCY': 'USD', 'FREQ': '19', 'H8_UNITS': 'LEVEL', 'SA': 'SA', 'SERIES_NAME': n, 'UNIT': 'Currency', 'UNIT_MULT': '1000000'},
             [(d, 'A', v) for d, v in _V423_FIX['h8'][n]]) for _, n in zd.FDD_H8]


def _v423_cp_serie():
    s = [({'FREQ': '19', 'SERIES_NAME': n, 'UNIT': 'Currency', 'UNIT_MULT': '1000000'}, [(d, 'A', v) for d, v in _V423_FIX['cpw'][n]]) for _, n in zd.FDD_CPW]
    s += [({'FREQ': '9', 'SERIES_NAME': n, 'UNIT': 'Percent', 'UNIT_MULT': '1'}, [(d, st, v) for d, st, v in _V423_FIX['cpr'][n]]) for _, n in zd.FDD_CPR]
    return s


def _v423_so_serie():
    return [({'FREQ': '162', 'QUEST_GRP': 'All', 'SERIES_NAME': n, 'UNIT': 'Number', 'UNIT_MULT': '1'}, [(d, 'A', v) for d, v in _V423_FIX['so'][n]]) for n in sorted(_V423_FIX['so'])]


def _v423_sl_serie():
    return [({'BANKSIZE': 'ALL', 'FREQ': '162', 'PANEL': 'DOM', 'SERIES_NAME': n, 'UNIT': 'Percentage', 'UNIT_MULT': '1'}, [(d, 'A', v) for d, v in _V423_FIX['sl'][n]]) for _, n in zd.FDD_SL]


_V423_SERIE = {'h8': _v423_h8_serie, 'cp': _v423_cp_serie, 'so': _v423_so_serie, 'sl': _v423_sl_serie}
_V423_PREP = {'h8': '2026-10-16T10:00:00', 'cp': '2026-10-16T10:00:00', 'so': '2026-09-24T18:00:00Z', 'sl': '2026-07-30T17:00:40'}


def _v423_paczka(k, edit=None, prep=None, dtd=''):
    """Paczka ZIP części k zbudowana z nagrań; edit(serie) może zmienić serie przed zapisem."""
    s = _V423_SERIE[k]()
    if edit:
        edit(s)
    return _v423_zip(zd.FDD_MEMBER[k], _v423_xml(s, _V423_PREP[k] if prep is None else prep, dtd))


def _v423_swiat(calls, **opc):
    """Zaślepka get_bytes_maks: adres → paczka (h8, cp, so, sl). opc: blad={fragment adresu: wyjątek}, h8 / cp / so / sl: własna odpowiedź (bajty)."""
    def gb(url, headers=None, timeout=60, maks=None):
        calls.append((url, headers, timeout, maks))
        for frag, e in opc.get('blad', {}).items():
            if frag in url:
                raise e
        for k, frag in _V423_URL.items():
            if frag in url:
                return opc[k] if k in opc else _v423_paczka(k)
        raise AssertionError('nieoczekiwany adres ' + url)
    return gb


def _v423_plik():
    """Plik fed-ddp.json zbudowany przez zbieracz na nagraniach (wszystkie cztery części)."""
    calls = []
    with mock.patch.object(zd, 'get_bytes_maks', _v423_swiat(calls)), mock.patch.object(zd, 'NOW', _V423_NOW.isoformat()), mock.patch.object(zd, 'FDD_SLEEP', 0), \
            mock.patch.object(zd, 'META', {'errors': [], 'notes': [], 'ok': {}}):
        return zd.build_fed_ddp(None)


class FedDdpV423(unittest.TestCase):
    """v423 (F11Z26): banki komercyjne USA, papiery komercyjne, ankieta dealerów, ankieta kredytowa banków — parsery na nagraniach (paczki ZIP z XML), bramki, bezpieczeństwo XML, rytm części, błędy części, wpięcie w main."""

    def setUp(self):
        zd.META['errors'].clear(); zd.META['ok'].clear(); zd.META['notes'].clear()
        self.p = [mock.patch.object(zd, 'NOW', _V423_NOW.isoformat()), mock.patch.object(zd, 'FDD_SLEEP', 0)]
        [p.start() for p in self.p]

    def tearDown(self):
        [p.stop() for p in self.p]
        zd._FDD_T0[0] = None

    def _build(self, prev=None, now=None, **opc):
        calls = []
        with mock.patch.object(zd, 'get_bytes_maks', _v423_swiat(calls, **opc)), mock.patch.object(zd, 'NOW', (now or _V423_NOW).isoformat()):
            return zd.build_fed_ddp(prev), calls

    # ---------------------------------------------------------------- banki komercyjne (tygodniowo)
    def test_h8_parser_liczby_i_porzadek(self):
        r = zd.parse_fdd_h8(_v423_paczka('h8'), _V423_NOW)
        self.assertEqual((r['asof'], r['pub'], len(r['h'])), ('2026-10-07', '2026-10-16', 160))
        self.assertEqual(r['h'][-1], ['2026-10-07', 26100.3, 19948.5, 5766.0, 14182.5, 2987.8, 3155.2, 1935.7, 2098.0, 19771.5, 2605.7, 2390.0, 3208.2])
        self.assertEqual(r['h'][-53][:3], ['2025-10-08', 24523.6, 18791.3])
        dni = [datetime.date.fromisoformat(x[0]) for x in r['h']]
        self.assertTrue(all(d.weekday() == 2 for d in dni) and all((b - a).days == 7 for a, b in zip(dni, dni[1:])), 'środy co 7 dni bez luk')
        self.assertEqual(round(r['h'][-1][2] / r['h'][-53][2] * 100 - 100, 1), 6.2, 'kredyt bankowy +6,2% w rok')

    def test_h8_bramki(self):
        def zle(edit, wzor, now=_V423_NOW, keep=None):
            with mock.patch.dict(zd.FDD_KEEP, {'hw': keep} if keep else {}), self.assertRaisesRegex(ValueError, wzor):
                zd.parse_fdd_h8(_v423_paczka('h8', edit), now)

        def brak(s): del s[3]
        zle(brak, 'brak wymaganych serii')
        zle(lambda s: s[0][0].update(SA='NSA'), 'atrybut SA')
        zle(lambda s: s[2][0].update(UNIT_MULT='1000'), 'atrybut UNIT_MULT')
        zle(lambda s: s[4][1].__setitem__(-1, ('2026-10-06', 'A', s[4][1][-1][2])), 'dni inne')
        zle(lambda s: [o.__setitem__(slice(None), [((datetime.date.fromisoformat(d) + datetime.timedelta(days=1)).isoformat(), st, v) for d, st, v in o]) for _, o in s], 'nie jest środą')

        def luka(s):
            for _, o in s:
                del o[100]
        zle(luka, 'luka w tygodniach', keep=150)
        zle(lambda s: s[1][1].__setitem__(-1, (s[1][1][-1][0], 'A', str(float(s[1][1][-1][2]) * 1.06))), 'nie dają sum')           # kredyt bankowy ≠ papiery + kredyty
        zle(lambda s: s[0][1].__setitem__(-1, (s[0][1][-1][0], 'A', '99999999999')), 'poza zakresem')
        zle(lambda s: s[0][1].__setitem__(-1, (s[0][1][-1][0], 'A', 'abc')), 'could not convert|nie liczba')
        zle(lambda s: s[5][1].__setitem__(-1, (s[5][1][-1][0], 'ND', '-9999')), 'brak wartości w tygodniu')
        zle(lambda s: s[4][1].__setitem__(-1, (s[4][1][-1][0], 'A', '7900000')), 'nie dają sum')                       # C&I 7900 + nieruchomości + konsumenckie + instytucje finansowe > kredyty i leasing
        zle(lambda s: [o.__setitem__(slice(None), o[-100:]) for _, o in s], 'za mało obserwacji')
        zle(None, 'źródło stoi', now=datetime.datetime(2026, 11, 20, 9, 0, tzinfo=datetime.timezone.utc))
        zle(None, 'z przyszłości', now=datetime.datetime(2026, 9, 20, 9, 0, tzinfo=datetime.timezone.utc))

    def test_xml_bezpieczenstwo_i_ksztalt_paczki(self):
        dtd = '<!DOCTYPE x [<!ENTITY a "aaaa"><!ENTITY b "&a;&a;&a;&a;">]>\n'
        with self.assertRaisesRegex(ValueError, 'DOCTYPE'):
            zd.parse_fdd_h8(_v423_paczka('h8', dtd=dtd), _V423_NOW)
        with self.assertRaisesRegex(ValueError, 'nie jest paczką ZIP'):
            zd.parse_fdd_h8(b'<html>Access denied</html>', _V423_NOW)
        with self.assertRaisesRegex(ValueError, 'brak pliku'):
            zd.parse_fdd_h8(_v423_zip('inna.xml', _v423_xml(_v423_h8_serie())), _V423_NOW)
        with mock.patch.dict(zd.FDD_MAXU, {'h8': 2000}), self.assertRaisesRegex(ValueError, 'większy niż'):
            zd.parse_fdd_h8(_v423_paczka('h8'), _V423_NOW)
        xml = _v423_xml(_v423_h8_serie())
        with self.assertRaisesRegex(ValueError, 'zły XML'):
            zd.parse_fdd_h8(_v423_zip(zd.FDD_MEMBER['h8'], xml[:len(xml) // 2]), _V423_NOW)
        with self.assertRaisesRegex(ValueError, 'powtórzona seria'):
            zd.parse_fdd_h8(_v423_paczka('h8', lambda s: s.append(s[0])), _V423_NOW)
        # strumień rozpakowywany przerywany po limicie, także gdy nagłówek paczki kłamie o rozmiarze
        with mock.patch.dict(zd.FDD_MAXU, {'h8': len(xml) - 5000}), self.assertRaisesRegex(ValueError, 'większy niż'):
            zd.fdd_xml(_v423_zip(zd.FDD_MEMBER['h8'], xml), zd.FDD_MEMBER['h8'], {'B1151NCBA': 5}, len(xml) - 5000)
        # nagłówek bez daty przygotowania: parser działa, data wydania pusta (dla h8 i cp to nie błąd)
        r = zd.parse_fdd_h8(_v423_paczka('h8', prep=''), _V423_NOW)
        self.assertIsNone(r['pub'])
        self.assertIsNone(zd.parse_fdd_h8(_v423_paczka('h8', prep='2030-01-01T00:00:00'), _V423_NOW)['pub'], 'data wydania z przyszłości nie jest pokazywana')

