def _v431_iip():
    return json.loads(json.dumps(_V431_IIP))


class IipV431(unittest.TestCase):
    """v431 (F11Z30): nagrania z 18.10.2026 (osiem gospodarek z IIP, cztery z bilansu płatniczego krajów dodatkowych). Pozycja netto = aktywa − zobowiązania; brak = brak, nigdy zero;
    kraj z kwartałem sprzed ponad czterech kwartałów albo z niezgodną arytmetyką nie wchodzi do pliku; bilans płatniczy 37 krajów (bilans.json) bez zmian."""

    def setUp(self):
        for nazwa, wartosc in (('IIP_MIN_KRAJOW', 5), ('IIP_BOP_PACZKA', 80)):   # nagranie ma 8 gospodarek; jedna paczka bilansu płatniczego (podział na paczki — osobny test)
            p = mock.patch.object(zd, nazwa, wartosc); p.start(); self.addCleanup(p.stop)

    def test_adres_i_lista_krajow(self):
        u = zd.IIP_URL
        self.assertTrue(u.startswith('https://api.imf.org/external/sdmx/3.0/data/dataflow/IMF.STA/IIP/+/USA+CAN+BRA'))
        self.assertTrue(u.endswith('.A_P+L_P+NETAL_P.IIP+P_MV+D+O+R+NIIP.USD.Q?lastNObservations=5&dimensionAtObservation=TIME_PERIOD'), 'wymiary przypięte, nigdy zestaw bez filtra')
        self.assertEqual(zd.IIP_CTY[:len(zd.BIL_CTY)], zd.BIL_CTY, 'lista z bilans.json bez zmian i na początku')
        self.assertEqual(len(zd.IIP_CTY), len(set(zd.IIP_CTY)), 'bez powtórzeń'); self.assertFalse(set(zd.IIP_EXTRA) & set(zd.BIL_CTY))
        self.assertGreaterEqual(len(zd.IIP_CTY), 100); self.assertLess(len(u), 1200)
        self.assertEqual(len(zd.BIL_CTY), 37, 'bilans.json nadal 37 gospodarek')
        for c in zd.IIP_CTY:
            self.assertRegex(c, r'^[A-Z]{3}$')
        self.assertEqual(zd.ZRODLA_META['iip'], 'imf', 'ten sam dostawca co bilans płatniczy — liczba źródeł bez zmian')

    def test_parse_wartosci_nagranie(self):
        o = zd.parse_iip(_v431_iip())
        self.assertEqual(o['asof_max'], '2026-Q2'); r = o['rows']
        self.assertEqual(r['USA'], {'q': '2026-Q2', 'a': 46968523.0, 'l': 69388842.0, 'n': -22420319.0, 'pa': 21064114.0, 'pl': 40921467.0, 'da': 15231819.0, 'dl': 15606023.0,
                                   'oa': 7131404.0, 'ol': 10639345.0, 'r': 1306544.0, 'n1': -21269088.0, 'n4': r['USA']['n4'], 'a4': r['USA']['a4'], 'l4': r['USA']['l4']})
        self.assertIsNotNone(r['USA']['n4']); self.assertAlmostEqual(r['USA']['a4'] - r['USA']['l4'], r['USA']['n4'], delta=r['USA']['a4'] * 0.01)
        self.assertEqual((r['POL']['n'], r['POL']['a'], r['POL']['l']), (-322718.0, 710582.0, 1033300.0))
        self.assertEqual(r['AUT']['q'], '2026-Q1', 'każdy kraj ze swoim ostatnim kwartałem')
        self.assertIsNone(r['DZA']['pa'], 'brak serii = None, nie zero'); self.assertIsNone(r['DZA']['pl'])
        self.assertEqual(o['order'][0], max(r, key=lambda c: r[c]['n'])); self.assertEqual(o['order'][-1], 'USA')
        self.assertEqual(sorted(o['order']), sorted(r)); self.assertTrue(all(o['rows'][a]['n'] >= o['rows'][b]['n'] for a, b in zip(o['order'], o['order'][1:])))

    def test_nieaktualny_kraj_odpada_z_powodem(self):
        o = zd.parse_iip(_v431_iip())
        self.assertNotIn('AZE', o['rows']); self.assertIn('ostatni kwartał 2008-Q4', o['pomin']['AZE'])
        self.assertIn('AZE', zd.IIP_CTY)

    def test_niezgodna_arytmetyka_kraj_pominiety(self):
        j = _v431_iip(); st = j['data']['structures'][0]['dimensions']
        ci = [v['id'] for v in st['series'][0]['values']].index('POL')
        for k, s in j['data']['dataSets'][0]['series'].items():
            p = k.split(':')
            if int(p[0]) == ci and st['series'][1]['values'][int(p[1])]['id'] == 'NETAL_P':
                for oi, ov in s['observations'].items():
                    ov[0] = str(float(ov[0]) * 1.5)
        o = zd.parse_iip(j)
        self.assertNotIn('POL', o['rows']); self.assertEqual(o['pomin']['POL'], 'aktywa − zobowiązania ≠ pozycja netto'); self.assertIn('USA', o['rows'])

    def test_straz_skali_i_za_malo_krajow(self):
        j = _v431_iip(); st = j['data']['structures'][0]['dimensions']
        ci = [v['id'] for v in st['series'][0]['values']].index('USA')
        for k, s in j['data']['dataSets'][0]['series'].items():
            if int(k.split(':')[0]) == ci:
                for ov in s['observations'].values():
                    ov[0] = str(float(ov[0]) / 1000)   # tysiące zamiast jednostek
        with self.assertRaisesRegex(RuntimeError, 'skala niezgodna'):
            zd.parse_iip(j)
        with mock.patch.object(zd, 'IIP_MIN_KRAJOW', 60):
            with self.assertRaisesRegex(RuntimeError, 'poniżej 60'):
                zd.parse_iip(_v431_iip())
        with self.assertRaises(RuntimeError):
            zd.parse_iip({'data': {'structures': [{'dimensions': {'series': [], 'observation': [{'values': []}]}}], 'dataSets': [{'series': {}}]}})

    def test_puste_i_nan_nie_sa_zerem(self):
        j = _v431_iip(); st = j['data']['structures'][0]['dimensions']
        ci = [v['id'] for v in st['series'][0]['values']].index('LUX')
        for k, s in j['data']['dataSets'][0]['series'].items():
            if int(k.split(':')[0]) == ci and st['series'][1]['values'][int(k.split(':')[1])]['id'] == 'L_P' and st['series'][2]['values'][int(k.split(':')[2])]['id'] == 'IIP':
                for ov in s['observations'].values():
                    ov[0] = 'NaN'
        r = zd.parse_iip(j)['rows']['LUX']
        self.assertIsNone(r['l']); self.assertIsNotNone(r['n']); self.assertIsNotNone(r['a'])

    def _gj(self, bop_fail=(), iip_fail=False):
        urls = []

        def gj(url, headers=None, timeout=30):
            urls.append((url, timeout))
            if '/IIP/+/' in url:
                if iip_fail:
                    raise RuntimeError('HTTP Error 503')
                return _v431_iip()
            idx = len([u for u, _ in urls if '/BOP/+/' in u]) - 1
            if idx in bop_fail:
                raise RuntimeError('HTTP Error 503')
            return json.loads(json.dumps(_V431_BOP))
        return gj, urls

    def test_budowa_pliku_iip_i_bilans_krajow_dodatkowych(self):
        gj, urls = self._gj()
        with mock.patch.object(zd, 'get_json', gj):
            o = zd.build_iip()
        self.assertEqual(len(urls), 2, 'jedno zapytanie IIP + jedna paczka bilansu płatniczego krajów dodatkowych (w teście paczka 80)')
        self.assertIn('/IIP/+/', urls[0][0]); self.assertTrue(urls[1][0].endswith(zd.BIL_URL[zd.BIL_URL.index('.L_NIL_T'):]), 'ten sam schemat wymiarów co bilans.json')
        self.assertIn('IMF.STA/BOP/+/AGO+ALB+ARM', urls[1][0]); self.assertNotIn('USA', urls[1][0].split('.L_NIL_T')[0]); self.assertTrue(all(t >= 30 for _, t in urls))
        self.assertEqual((o['v'], o['at'], o['zapytane'], o['bledy']), (1, zd.NOW, len(zd.IIP_CTY), []))
        self.assertEqual(o['bop']['CZE']['q'], '2026-Q2'); self.assertIn('ca', o['bop']['CZE']['s']); self.assertEqual(o['bop']['AUT']['q'], '2026-Q1')
        self.assertNotIn('in_p', o['bop']['DZA']['s'], 'brak serii = brak klucza, nie zero'); self.assertNotIn('USA', o['bop'])
        self.assertEqual(list(o['bop']), [c for c in zd.IIP_EXTRA if c in o['bop']], 'kolejność jak na liście')
        json.dumps(o, allow_nan=False)

    def test_podzial_na_paczki(self):
        urls = []
        with mock.patch.object(zd, 'IIP_BOP_PACZKA', 32), mock.patch.object(zd, 'IIP_MIN_KRAJOW', 5):
            with mock.patch.object(zd, 'get_json', lambda u, h=None, t=30: urls.append(u) or (_v431_iip() if '/IIP/+/' in u else {})), \
                    mock.patch.object(zd, 'parse_bilans', side_effect=lambda j, ct=None: {'rows': {c: {'q': '2026-Q2', 's': {}} for c in ct[:1]}}):
                o = zd.build_iip()
        paczki = [u.split('/BOP/+/')[1].split('.L_NIL_T')[0].split('+') for u in urls[1:]]
        self.assertEqual(len(paczki), 3, 'ok. 70 krajów dodatkowych = trzy paczki po najwyżej 32')
        self.assertEqual(sum(paczki, []), zd.IIP_EXTRA); self.assertTrue(all(len(p) <= 32 for p in paczki)); self.assertFalse(set(sum(paczki, [])) & set(zd.BIL_CTY), 'kraje z bilans.json nie są pobierane drugi raz')
        self.assertEqual(sorted(o['bop']), sorted(p[0] for p in paczki))

    def test_paczka_bez_odpowiedzi_kraje_z_poprzedniego_pliku_i_blad(self):
        gj, _ = self._gj()
        with mock.patch.object(zd, 'get_json', gj):
            pierwszy = zd.build_iip()
        gj, urls = self._gj(bop_fail=(0,))
        with mock.patch.object(zd, 'get_json', gj):
            o = zd.build_iip(pierwszy)
        self.assertEqual(len(o['bledy']), 1); self.assertIn('paczka 1', o['bledy'][0]); self.assertIn('HTTP Error 503', o['bledy'][0])
        self.assertEqual(o['bop']['CZE'], pierwszy['bop']['CZE'], 'kraj z paczki bez odpowiedzi zostaje z poprzedniego pliku')
        gj, _ = self._gj(bop_fail=(0,))
        with mock.patch.object(zd, 'get_json', gj):
            bez = zd.build_iip(None)
        self.assertEqual(len(bez['bledy']), 1); self.assertEqual(bez['bop'], {}, 'bez poprzedniego pliku — brak krajów, nie zera'); self.assertEqual(sorted(bez['rows']), sorted(zd.parse_iip(_v431_iip())['rows']))
        gj, _ = self._gj(iip_fail=True)
        with mock.patch.object(zd, 'get_json', gj):
            with self.assertRaisesRegex(RuntimeError, 'HTTP Error 503'):
                zd.build_iip(pierwszy)

    def test_dlugi_przebieg_pomija_paczki_bilansu(self):
        gj, urls = self._gj()
        with mock.patch.object(zd, 'get_json', gj):
            pierwszy = zd.build_iip()
        gj, urls = self._gj()
        with mock.patch.object(zd, 'get_json', gj), mock.patch.object(zd.time, 'monotonic', return_value=1000.0 + zd.BACK_LATE + 1):
            o = zd.build_iip(pierwszy, run_t0=1000.0)
        self.assertEqual(len(urls), 1, 'tylko IIP; paczki bilansu poza długim przebiegiem'); self.assertEqual(o['bop'], pierwszy['bop']); self.assertIn('przebieg zbyt długi', o['bledy'][0])
        gj, urls = self._gj()
        with mock.patch.object(zd, 'get_json', gj), mock.patch.object(zd.time, 'monotonic', return_value=1000.0 + zd.BACK_LATE - 1):
            o = zd.build_iip(pierwszy, run_t0=1000.0)
        self.assertEqual((len(urls), o['bledy']), (2, []))

    def test_kraj_bop_ze_starym_kwartalem_odpada(self):
        gj, _ = self._gj()
        j = json.loads(json.dumps(_V431_BOP))
        with mock.patch.object(zd, 'get_json', gj), mock.patch.object(zd, 'parse_bilans', side_effect=lambda jj, ct=None: {'rows': {'CZE': {'q': '2026-Q2', 's': {}}, 'AGO': {'q': '2024-Q4', 's': {}}, 'ALB': {'q': '2025-Q2', 's': {}}}}):
            o = zd.build_iip()
        self.assertEqual(sorted(o['bop']), ['ALB', 'CZE'], 'kwartał starszy niż IIP_STARE_Q od najnowszego odpada, 2025-Q2 zostaje')

    def test_parse_bilans_bez_zmian_dla_37_krajow(self):
        """Parametr listy krajów jest opcjonalny: bez niego bilans.json liczy się jak dotąd (37 krajów, USA, straż skali)."""
        r = zd.parse_bilans(json.loads(json.dumps(_V431_BOP)), ['CZE', 'AUT'])
        self.assertEqual(r['order'], ['CZE', 'AUT']); self.assertEqual(r['rows']['CZE']['q'], '2026-Q2')
        with self.assertRaisesRegex(RuntimeError, 'żaden kraj'):
            zd.parse_bilans(json.loads(json.dumps(_V431_BOP)))   # kraje dodatkowe nie są na liście 37
        with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'zbieraj_dane.py'), encoding='utf-8') as f:
            s = f.read()
        self.assertIn("out = parse_bilans(get_json(BIL_URL, {'Accept': 'application/json'}))", s, 'build_bilans nieruszony')

    def test_main_pobiera_raz_na_dobe_i_po_bledzie_zostaje_poprzedni(self):
        prev = {'v': 1, 'at': _iso(26 * 60), 'asof_max': '2026-Q1', 'rows': {}, 'order': [], 'bop': {}, 'bledy': []}
        for fresh_prev, oczekiwane in ((None, 'budowa'), (prev, 'budowa'), ({**prev, 'at': _iso(60)}, 'cache'), ({**prev, 'at': _iso(60), 'bledy': ['x']}, 'cache'), ({**prev, 'at': _iso(400), 'bledy': ['x']}, 'budowa')):
            saved = {}; calls = []
            offs = [mock.patch.object(zd, n, side_effect=RuntimeError('offline'), create=True) for n in dir(zd) if n.startswith('build_') and n not in ('build_iip',)]
            [p.start() for p in offs]
            try:
                with mock.patch.dict(os.environ, {'SOSOVALUE_KEY': '', 'COINGECKO_KEY': ''}, clear=False), \
                        mock.patch.object(zd, 'save', lambda name, obj: saved.__setitem__(name, obj)), \
                        mock.patch.object(zd, 'previous', lambda name, fp=fresh_prev: fp if name == 'iip' else None), \
                        mock.patch.object(zd, 'build_iip', side_effect=lambda p=None, run_t0=None: calls.append(p) or {'v': 1, 'at': zd.NOW, 'rows': {}, 'bledy': []}):
                    try:
                        zd.main()
                    except SystemExit:
                        pass
            finally:
                [p.stop() for p in offs]
            self.assertEqual(bool(calls), oczekiwane == 'budowa', (fresh_prev, oczekiwane))
            if oczekiwane == 'cache':
                self.assertIs(saved['iip'], fresh_prev); self.assertEqual(zd.META['ok']['iip'], 'cached')
            else:
                self.assertEqual(saved['iip']['at'], zd.NOW); self.assertIs(zd.META['ok']['iip'], True)
        saved = {}
        offs = [mock.patch.object(zd, n, side_effect=RuntimeError('offline'), create=True) for n in dir(zd) if n.startswith('build_') and n not in ('build_iip',)]
        [p.start() for p in offs]
        try:
            with mock.patch.dict(os.environ, {'SOSOVALUE_KEY': '', 'COINGECKO_KEY': ''}, clear=False), \
                    mock.patch.object(zd, 'save', lambda name, obj: saved.__setitem__(name, obj)), \
                    mock.patch.object(zd, 'previous', lambda name: prev if name == 'iip' else None), \
                    mock.patch.object(zd, 'build_iip', side_effect=RuntimeError('HTTP Error 503')):
                try:
                    zd.main()
                except SystemExit:
                    pass
        finally:
            [p.stop() for p in offs]
        self.assertIs(saved['iip'], prev); self.assertIs(zd.META['ok']['iip'], False); self.assertIn('MFW IIP: HTTP Error 503', zd.META['errors'])


class KontrolaIipV431(unittest.TestCase):
    """v431 (F11Z30): kontrola dzienna pliku iip.json — wiek pliku, rytm kwartalny (⚠ po 240 dniach od końca najnowszego kwartału), ❌ tylko przy sprzeczności w pliku, wpięcie w raport."""

    @classmethod
    def setUpClass(cls):
        import importlib.util, tempfile
        tmp = tempfile.mkdtemp(prefix='kontrola431-')
        with mock.patch.dict(os.environ, {'KONTROLA_DIR': os.path.join(tmp, 'k'), 'KONTROLA_ARCH': os.path.join(tmp, 'a')}):
            spec = importlib.util.spec_from_file_location('v431_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
            cls.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(cls.k)
        cls.NOW = datetime.datetime(2026, 10, 18, 13, 0, tzinfo=datetime.timezone.utc)
        with mock.patch.object(zd, 'IIP_MIN_KRAJOW', 5):
            o = zd.parse_iip(_v431_iip())
        o.update({'v': 1, 'at': '2026-10-18T03:00:00+00:00', 'bop': {'CZE': {'q': '2026-Q2', 's': {'ca': [['2026-Q2', 1.0]]}}}, 'bledy': []})
        cls.P0 = o

    def setUp(self):
        p = mock.patch.object(self.k, 'IIPK_MIN_KRAJOW', 5); p.start(); self.addCleanup(p.stop)

    def _plik(self):
        return json.loads(json.dumps(self.P0))

    def test_plik_wpiety_w_kontroli_wieku_pliku_i_stale_zgodne_ze_zbieraczem(self):
        k = self.k
        self.assertEqual(k.PLIKI[-2:], ['krypto-dzien', 'krypto-dziennik']); self.assertIn('iip', k.PLIKI); self.assertLess(k.PLIKI.index('iip'), k.PLIKI.index('krypto-dzien'))
        self.assertEqual(k.LIMIT_MIN['iip'], 48 * 60); self.assertEqual(k.PLIKI.count('iip'), 1)
        with mock.patch.object(k, 'IIPK_MIN_KRAJOW', k.IIPK_MIN_KRAJOW):
            self.assertEqual(k.IIPK_MIN_KRAJOW, 5)
        import re as _re
        with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'), encoding='utf-8') as f:
            src = f.read()
        self.assertEqual(_re.search(r'^IIPK_MIN_KRAJOW = (\d+)$', src, _re.M).group(1), '60'); self.assertEqual(zd.IIP_MIN_KRAJOW, 60, 'ten sam próg w zbieraczu i w kontroli')
        self.assertEqual(_re.search(r'^IIPK_PROG_DNI = (\d+)$', src, _re.M).group(1), '240')
        self.assertGreater(240, 92 + 110, 'kwartał cyklu + opóźnienie publikacji (110 dni 18.10.2026) + zapas')
        self.assertLess(zd.IIP_STARE_Q * 92, 240 + 92 * 2)

    def test_swiezy_plik_bez_sprzecznosci(self):
        o = self.k.iip_kontrola({'iip': self._plik()}, self.NOW)
        self.assertEqual(o['spojnosc'], []); self.assertEqual(o['uwagi'], []); self.assertEqual(o['wiersze'], [('IIP: kwartał 2026-Q2, 7 krajów', '✅')])
        self.assertIsNone(self.k.iip_kontrola({}, self.NOW)); self.assertIsNone(self.k.iip_kontrola({'iip': {'v': 2}}, self.NOW)); self.assertIsNone(self.k.iip_kontrola(None))

    def test_prog_rytmu_kwartalnego_240_dni(self):
        k = self.k
        for dni, znak in ((100, '✅'), (192, '✅'), (240, '✅'), (241, '⚠️')):
            now = datetime.datetime.combine(datetime.date(2026, 6, 30) + datetime.timedelta(days=dni), datetime.time(12, 0), tzinfo=datetime.timezone.utc)
            o = k.iip_kontrola({'iip': self._plik()}, now)
            self.assertEqual(o['wiersze'][0][1], znak, dni); self.assertEqual(bool(o['uwagi']), znak == '⚠️'); self.assertEqual(o['spojnosc'], [], 'wiek to nigdy ❌')
        self.assertEqual(str(k._iipk_koniec('2026-Q4')), '2026-12-31'); self.assertEqual(str(k._iipk_koniec('2026-Q1')), '2026-03-31'); self.assertEqual(str(k._iipk_koniec('2026-Q3')), '2026-09-30'); self.assertIsNone(k._iipk_koniec('2026-Q5'))

    def test_sprzecznosci_w_pliku(self):
        k = self.k
        def zle(mut):
            j = self._plik(); mut(j)
            return k.iip_kontrola({'iip': j}, self.NOW)['spojnosc']
        def n_x(j): j['rows']['POL']['n'] = -100000.0
        self.assertTrue(any('POL: aktywa − zobowiązania ≠ pozycja netto' in z for z in zle(n_x)))
        def kw(j): j['rows']['POL']['q'] = '2026-Q5'
        self.assertTrue(any('POL: zły kwartał' in z for z in zle(kw)))
        def ord_(j): j['order'] = list(reversed(j['order']))
        self.assertTrue(any('nie są ułożone' in z for z in zle(ord_)))
        def ord2(j): j['order'] = j['order'][:-1]
        self.assertTrue(any('lista kolejności' in z for z in zle(ord2)))
        def asof(j): j['asof_max'] = '2026-Q1'
        self.assertTrue(any('asof_max' in z for z in zle(asof)))
        def usa(j): j['rows']['USA']['a'] = 46968.5; j['rows']['USA']['n'] = j['rows']['USA']['a'] - j['rows']['USA']['l']
        self.assertTrue(any('USA' in z for z in zle(usa)))
        def bop(j): j['bop']['CZE'] = {'q': 'x'}
        self.assertTrue(any('bilans płatniczy' in z for z in zle(bop)))
        with mock.patch.object(k, 'IIPK_MIN_KRAJOW', 60):
            self.assertTrue(any('tylko 7 krajów' in z for z in k.iip_kontrola({'iip': self._plik()}, self.NOW)['spojnosc']))
        self.assertEqual(k.iip_kontrola({'iip': {'v': 1, 'rows': {}, 'order': []}}, self.NOW)['spojnosc'], ['brak krajów albo zły kształt'])
        def ujemne(j): j['rows']['LUX']['a'] = -5.0
        self.assertTrue(any('LUX' in z for z in zle(ujemne)))

    def test_paczka_bez_odpowiedzi_to_uwaga_nie_blad(self):
        j = self._plik(); j['bledy'] = ['MFW bilans płatniczy (paczka 2): HTTP Error 503']
        o = self.k.iip_kontrola({'iip': j}, self.NOW)
        self.assertEqual(o['spojnosc'], []); self.assertEqual(len(o['uwagi']), 1); self.assertIn('paczka 2', o['uwagi'][0])

    def test_wpiecie_w_raport(self):
        with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'), encoding='utf-8') as f:
            s = f.read()
        i0, i1 = s.index('# 3c-v431. Wierzyciele'), s.index('# 3d. v115: zgodność liczb')
        self.assertLess(i0, i1); self.assertIn("iip_kontrola(files)", s); self.assertIn("kip = Z.get('iip')", s); self.assertIn("R['bledy'].append(f'iip.json: sprzeczność w pliku — {z_}')", s)
        self.assertEqual(s.count("R['zgodnosc']['iip']"), 2)


class TestV437SektoryKrypto(unittest.TestCase):
    """v437 (18.10.2026, punkt 9 poleceń właściciela): każda moneta grup top 10 w jednym sektorze głównym (zbieracz) i stała kontrola przypisań w kontroli dziennej
    (tylko raportuje). Bez sieci: nagranie 27.09 z testów v140 (te same nakładające się kategorie co na żywo 18.10)."""
    NOW = datetime.datetime(2026, 10, 18, 17, 30, tzinfo=datetime.timezone.utc)

    @classmethod
    def _k(cls):
        import importlib.util
        spec = importlib.util.spec_from_file_location('kontrola_v437', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        k = importlib.util.module_from_spec(spec); spec.loader.exec_module(k)
        return k

    def _build(self, **kw):
        T = KryptoTop10V140('test_full_build_from_categories'); T.setUp()
        try:
            return T._build(**kw)
        finally:
            T.doCleanups()

    # --- zbieracz ---
    def test_konfiguracja(self):
        keys = [k for k, _ in zd.T10_CATS]
        self.assertEqual(sorted(zd.T10_PRIO), sorted(keys)); self.assertEqual(len(set(zd.T10_PRIO)), 8)
        self.assertTrue(set(zd.T10_GLOWNY.values()) <= set(keys))
        self.assertFalse(set(zd.T10_GLOWNY) & zd.T10_STABILNE, 'moneta z sektorem wprost nie jest stablecoinem')
        self.assertIn('dai', zd.T10_STABILNE); self.assertIn('gmt-token', zd.T10_BEZ['gaming']); self.assertIn('floki', zd.T10_BEZ['gaming'])
        self.assertEqual(zd.T10_PRIO.index('l1'), 7, 'L1 (najszersza) przegrywa z każdą węższą')

    def test_sektor_glowny_regula(self):
        g = zd.t10_glowny({'l1': ['near', 'stellar', 'hyperliquid', 'solana'], 'ai': ['near', 'bittensor', 'render-token'], 'rwa': ['stellar', 'chainlink', 'ondo-finance'],
                           'defi': ['hyperliquid', 'chainlink', 'ondo-finance', 'pump-fun'], 'meme': ['pump-fun', 'dogecoin'], 'depin': ['bittensor', 'render-token', 'geodnet'],
                           'gaming': ['geodnet', 'immutable-x'], 'l2': ['immutable-x', 'arbitrum']})
        self.assertEqual(g, {'near': 'l1', 'stellar': 'l1', 'hyperliquid': 'defi', 'solana': 'l1', 'bittensor': 'ai', 'render-token': 'depin', 'chainlink': 'defi', 'ondo-finance': 'rwa',
                             'pump-fun': 'meme', 'dogecoin': 'meme', 'geodnet': 'depin', 'immutable-x': 'gaming', 'arbitrum': 'l2'})
        self.assertEqual(zd.t10_glowny({'ai': ['near']}), {'near': 'ai'}, 'sektor wprost, którego nie ma wśród kandydatów monety, nie wymusza przypisania')
        self.assertEqual(zd.t10_glowny({'l1': ['near'], 'defi': ['near']}), {'near': 'l1'}); self.assertEqual(zd.t10_glowny({}), {}); self.assertEqual(zd.t10_glowny(None), {})

    def test_budowa_grupy_rozlaczne(self):
        out, _ = self._build()
        ids = {k: [r[0] for r in out['g'][k]['c']] for k, _ in zd.T10_CATS}
        wszystkie = [i for v in ids.values() for i in v]
        self.assertEqual(len(wszystkie), len(set(wszystkie)), 'każda moneta w jednym sektorze: ' + str([i for i in set(wszystkie) if wszystkie.count(i) > 1]))
        for k in ids:
            self.assertEqual(len(ids[k]), 10, k)
            mc = [r[4] for r in out['g'][k]['c']]; self.assertEqual(mc, sorted(mc, reverse=True), k)
        self.assertIn('near', ids['l1']); self.assertNotIn('near', ids['ai']); self.assertIn('bittensor', ids['ai']); self.assertNotIn('bittensor', ids['depin'])
        self.assertIn('chainlink', ids['defi']); self.assertNotIn('chainlink', ids['rwa']); self.assertIn('pump-fun', ids['meme']); self.assertNotIn('pump-fun', ids['defi'])
        self.assertNotIn('dai', wszystkie, 'stablecoin nie jest sektorem'); self.assertNotIn('gmt-token', ids['gaming'], 'GoMining to nie gra'); self.assertNotIn('floki', ids['gaming'])
        # kolejny przebieg (same ceny kandydatów, bez składu kategorii) — te same grupy, nadal rozłączne
        out2, _ = self._build(prev=out, now=T10_NOW + datetime.timedelta(minutes=60))
        ids2 = {k: [r[0] for r in out2['g'][k]['c']] for k, _ in zd.T10_CATS}
        self.assertEqual(ids2, ids, 'reguła liczona od nowa z kandydatów daje ten sam podział')

    # --- kontrola ---
    def _plik(self):
        def w(i, s, mc):
            return [i, s, i.title(), 1.0, mc, 0.5, '2026-10-18T17:00:00Z']
        g = {}
        n = 0
        for k, _ in self._k().T10_K_SEKTORY:
            g[k] = {'cat': k, 'sk': '2026-10-18T12:00:00+00:00', 'pool': [], 'c': [w(f'{k}-coin{i}', f'{k[:2].upper()}{i}', (10 - i) * 1e9) for i in range(10)]}
        return {'at': '2026-10-18T17:05:01+00:00', 'cols': list(zd.T10_COLS), 'n': 10, 'g': g, 'ok': {k: True for k in g}, 'calls': 1}

    def _logo(self, j):
        return {'at': j['at'], 'n': 0, 'logo': {r[0]: 'data:image/png;base64,AAAA' for g in j['g'].values() for r in g['c']}}

    def _mk(self, j, mnoz=1.0, bez=()):
        rows = [[r[1], r[4] * mnoz, 0, 0, 0, 0] for g in j['g'].values() for r in g['c'] if isinstance(r, list) and len(r) > 4 and isinstance(r[4], (int, float)) and r[4] > 0 and r[1] not in bez]
        return {'mk': {'asof': '2026-10-18T17:14:58', 'rows': rows + [['ZZZ', 1e6, 0, 0, 0, 0]]}}

    def test_kontrola_zdrowy_plik(self):
        k = self._k(); j = self._plik()
        o = k.t10_k_kontrola(j, self._logo(j), self._mk(j), self.NOW)
        self.assertEqual((o['uwagi'], o['spojnosc']), ([], []))
        self.assertEqual([z for _, z in o['wiersze']], ['✅'] * 6)
        self.assertEqual(k.t10_k_kontrola(None), {'uwagi': [], 'wiersze': [], 'spojnosc': []}); self.assertEqual(k.t10_k_kontrola({'g': 5}), {'uwagi': [], 'wiersze': [], 'spojnosc': []})
        self.assertEqual(len(k.t10_k_kontrola(j, None, None, self.NOW)['uwagi']), 1, 'bez pliku logo — ostrzeżenie; bez rankingu ogólnego — bez porównania')

    def test_kontrola_kazda_usterka(self):
        k = self._k()

        def zle(f, wzor, logo=True, mk=True, wiersz=None):
            j = self._plik(); f(j)
            o = k.t10_k_kontrola(j, self._logo(j) if logo else None, self._mk(j) if mk else None, self.NOW)
            self.assertTrue(any(wzor in x for x in o['spojnosc']), (wzor, o['spojnosc']))
            self.assertTrue(any(wzor in x for x in o['uwagi']) or len(o['spojnosc']) > 4, (wzor, o['uwagi']))
            return o
        o = zle(lambda j: j['g']['ai']['c'].__setitem__(0, list(j['g']['l1']['c'][0])), 'więcej niż jednym sektorze')          # ta sama moneta w L1 i AI
        self.assertIn('l1-coin0 (L1, AI)', ' '.join(o['spojnosc']))
        zle(lambda j: j['g']['l1']['c'].__setitem__(1, list(j['g']['l1']['c'][0])), 'więcej niż jednym sektorze')               # dwa razy w tym samym
        zle(lambda j: j['g'].__setitem__('nowy', {'c': []}), 'nieznany sektor')
        zle(lambda j: j['g'].pop('meme'), 'memecoiny: brak sektora')
        zle(lambda j: j['g']['rwa'].__setitem__('c', []), 'RWA: brak danych')
        zle(lambda j: j['g']['rwa']['c'].pop(), 'RWA: tylko 9 z 10')
        zle(lambda j: j['g']['defi']['c'][2].__setitem__(0, 'dai'), 'stablecoin w sektorze DeFi: dai')
        zle(lambda j: j['g']['l1']['c'][2].__setitem__(0, 'bitcoin'), 'bitcoin w sektorze L1')
        zle(lambda j: j['g']['l2']['c'][2].__setitem__(0, 'Zły Id'), 'L2: zły wiersz')
        zle(lambda j: j['g']['l2']['c'][2].__setitem__(1, ''), 'L2: zły wiersz')
        zle(lambda j: j['g']['l2']['c'][2].__setitem__(4, None), 'L2: zły wiersz')
        zle(lambda j: j['g']['l2']['c'][2].__setitem__(4, -5.0), 'L2: zły wiersz')
        zle(lambda j: j['g']['l2']['c'].__setitem__(3, 'x'), 'L2: zły wiersz')
        zle(lambda j: j['g']['gaming']['c'][5].__setitem__(4, 99e9), 'gaming: kapitalizacje nie malejąco', mk=False)
        zle(lambda j: j['g']['depin'].__setitem__('sk', '2026-10-18T02:00:00+00:00'), 'DePIN: skład z 2026-10-18 02:00 UTC (15 h temu)')
        zle(lambda j: j['g']['depin'].__setitem__('sk', None), 'DePIN: brak czasu składu')
        zle(lambda j: None, 'brak pliku z logo monet', logo=False)

    def test_kontrola_logo_i_ranking_ogolny(self):
        k = self._k(); j = self._plik(); L = self._logo(j)
        del L['logo']['ai-coin3']; L['logo']['ai-coin4'] = 'https://obcy/x.png'
        o = k.t10_k_kontrola(j, L, None, self.NOW); self.assertEqual(o['spojnosc'], ['brak logo: ai-coin3, ai-coin4'])
        w = dict(o['wiersze']); self.assertEqual((w['logo monet'], w['świeżość składu sektorów'], w['każda moneta w jednym sektorze (znane sektory, bez powtórzeń)']), ('⚠️', '✅', '✅'))
        # ranking ogólny: 3 rozbieżne = ⚠️, 1–2 = tylko ℹ️, cały ranking dwa razy mniejszy = ⚠️, plik z innego przebiegu = pominięte, symbol spoza rankingu = ℹ️
        mk = self._mk(j); wiersze = mk['mk']['rows']
        for i in (0, 1, 2):
            wiersze[i][1] *= 2
        o = k.t10_k_kontrola(j, self._logo(j), mk, self.NOW); self.assertTrue(any('ponad 15%' in x for x in o['spojnosc']), o)
        mk = self._mk(j); mk['mk']['rows'][0][1] *= 2; mk['mk']['rows'][1][1] *= 1.14
        o = k.t10_k_kontrola(j, self._logo(j), mk, self.NOW); self.assertEqual(o['spojnosc'], [], 'jedna rozbieżność i różnica 14% — bez ⚠️')
        self.assertTrue(any(z == 'ℹ️' and 'pojedyncze' in t for t, z in o['wiersze']))
        o = k.t10_k_kontrola(j, self._logo(j), self._mk(j, 0.5), self.NOW); self.assertTrue(any('ponad 15%' in x for x in o['spojnosc']))
        mk = self._mk(j); mk['mk']['asof'] = '2026-10-18T09:00:00'
        o = k.t10_k_kontrola(j, self._logo(j), mk, self.NOW); self.assertEqual(o['spojnosc'], []); self.assertTrue(any('pominięte' in t for t, _ in o['wiersze']))
        o = k.t10_k_kontrola(j, self._logo(j), self._mk(j, bez=('L10', 'L11')), self.NOW)
        self.assertEqual(o['spojnosc'], []); self.assertTrue(any(z == 'ℹ️' and 'poza rankingiem ogólnym' in t and 'L10' in t for t, z in o['wiersze']))
        j['ok']['ai'] = False; o = k.t10_k_kontrola(j, self._logo(j), self._mk(j), self.NOW); self.assertEqual(o['spojnosc'], []); self.assertTrue(any('nieudane' in t for t, _ in o['wiersze']))

    def test_kontrola_na_zywej_migawce_i_tylko_raportuje(self):
        import copy
        k = self._k(); j = self._plik(); L = self._logo(j); M = self._mk(j)
        stan = copy.deepcopy((j, L, M)); k.t10_k_kontrola(j, L, M, self.NOW); self.assertEqual((j, L, M), stan, 'kontrola niczego nie zmienia')
        with open(k.__file__, encoding='utf-8') as f:
            s = f.read()
        a = s.index('def t10_k_kontrola('); b = s.index('# --- v352: zmienność rynków')
        self.assertNotRegex(s[a:b], r'open\(|\.write\(|os\.(remove|rename)|shutil|subprocess|urlopen', 'funkcja kontroli nie zapisuje, nie kasuje i nie pyta sieci')
        self.assertNotIn("R['bledy']", s[s.index('# 3c-v437. Sektory krypto'):s.index('# 3c-v423. Fed')], 'najwyżej uwagi, nigdy błąd')
        i0, i1 = s.index('# 3c-v437. Sektory krypto'), s.index('# 3d. v115: zgodność liczb')
        self.assertLess(i0, i1); self.assertIn("t10_k_kontrola(files.get('krypto-top10'), files.get('krypto-top10-logo'), files.get('krypto'))", s)
        self.assertIn("skt_ = Z.get('krypto-top10')", s); self.assertIn("R['uwagi'] += T10K_['uwagi']", s); self.assertIn("R['zgodnosc']['krypto-top10'] = {'spojnosc': T10K_['spojnosc']", s); self.assertEqual(k.T10_K_STABILNE, zd.T10_STABILNE, 'listy stablecoinów zbieracza i kontroli zgodne')
        self.assertEqual([x for x, _ in k.T10_K_SEKTORY], [x for x, _ in zd.T10_CATS])



class TestV432DwaJezyki(unittest.TestCase):
    """v432: strona ma tylko polski i angielski. Pliki: bez narzędzia podziału słowników i plików i18n, bez kontroli plików słowników, mapa witryny i
    hreflang tylko pl / en / x-default, Service Worker bez ścieżki i18n/, krok „Złóż stronę” bez podziału. Słowniki i przełącznik sprawdza test_widoki.cjs."""
    ROOT = os.path.dirname(os.path.abspath(__file__))

    def _czytaj(self, *p):
        with open(os.path.join(self.ROOT, *p), encoding='utf-8') as f:
            return f.read()

    def test_bez_narzedzia_podzialu_i_kontroli_plikow_slownikow(self):
        self.assertFalse(os.path.exists(os.path.join(self.ROOT, 'narzedzia', 'odchudz_strone.py')), 'narzędzie podziału słowników usunięte')
        w = self._czytaj('.github', 'workflows', 'strona.yml')
        for s in ('odchudz_strone', 'i18n', 'lżejsza strona', 'rm -rf _site/i18n'):
            self.assertNotIn(s, w, s)
        self.assertIn('cp index.html _site/', w)
        k = self._czytaj('narzedzia', 'kontrola.py')
        for s in ('i18n_kontrola', 'I18N_JEZYKI', 'I18N_MAPA', 'CF_I18N', 'i18n_skrot'):
            self.assertNotIn(s, k, s)
        sw = self._czytaj('sw.js')
        self.assertNotIn('i18n', sw)
        self.assertIn('fonts|img', sw)

    def test_mapa_witryny_i_hreflang_tylko_pl_en(self):
        import xml.etree.ElementTree as ET
        xml = self._czytaj('sitemap.xml').replace('LASTMOD', '2026-10-18')
        root = ET.fromstring(xml)
        ns = {'s': 'http://www.sitemaps.org/schemas/sitemap/0.9', 'x': 'http://www.w3.org/1999/xhtml'}
        urls = root.findall('s:url', ns)
        self.assertEqual([u.find('s:loc', ns).text for u in urls], ['https://capitalflowai-app.github.io/', 'https://capitalflowai-app.github.io/?lang=en'])
        for u in urls:
            self.assertEqual([a.get('hreflang') for a in u.findall('x:link', ns)], ['pl', 'en', 'x-default'])
        h = self._czytaj('index.html')
        head = h[:h.index('</head>')]
        self.assertEqual(re.findall(r'<link rel="alternate" hreflang="([^"]+)"', head), ['pl', 'en', 'x-default'])
        self.assertNotIn('?lang=de', head); self.assertNotIn('?lang=ja', head)

    def test_slowniki_w_stronie_tylko_pl_i_en(self):
        h = self._czytaj('index.html')
        self.assertIsNone(re.search(r'(?<![\w.$-])["\']?(?:de|es|fr|it|pt|ru|zh|ja)["\']?\s*:\s*\{', h), 'żaden słownik nie ma innego języka niż pl i en')
        self.assertIn("const LANG_NAMES={pl:'Polski',en:'English'};", h)
        self.assertIn("SEO_LANGS=['pl','en'];", h)
        self.assertIn('id="lang-sw"', h)
        self.assertNotIn('cfLangReady', h); self.assertNotIn('CF_I18N', h)


class TestV440KontrolaZakladek(unittest.TestCase):
    """v440 (18.10.2026): stała kontrola zakładek GLOBAL, CRYPTO i TRENDY — podmiana pliku w kopii, serwer lokalny, oceny, raport, okablowanie.
    Bez przeglądarki i bez sieci zewnętrznej (serwer tylko na 127.0.0.1, żywa strona udawana funkcją)."""

    @classmethod
    def setUpClass(cls):
        import importlib.util
        here = os.path.dirname(os.path.abspath(__file__))
        sp = importlib.util.spec_from_file_location('kz_v440', os.path.join(here, 'narzedzia', 'kontrola_zakladki.py'))
        cls.kz = importlib.util.module_from_spec(sp)
        sp.loader.exec_module(cls.kz)
        cls.here = here

    # --- podmiana pliku -----------------------------------------------------------------
    def test_przesuniecie_dat(self):
        kz = self.kz
        self.assertEqual(kz._przesun_str('2026-03-01', 14), '2026-02-15')
        self.assertEqual(kz._przesun_str('2026-10-18T06:20:00+00:00', 14), '2026-10-04T06:20:00+00:00')
        self.assertEqual(kz._przesun_str('2026-10-18 06:20', 1), '2026-10-17 06:20')
        self.assertEqual(kz._przesun_str('jutro', 14), 'jutro')
        self.assertEqual(kz._przesun_str('2026-13-45', 14), '2026-13-45', 'nieprawdziwa data bez zmian')
        j = {'at': '2026-10-18T06:20:00+00:00', 'ts': 1792300000, 'wolumen': 1792300000, 'ok': True, 'x': [1, '2026-10-01', {'t': 1792300000000}]}
        o = kz.przesun_daty(j, 14)
        self.assertEqual(o['at'], '2026-10-04T06:20:00+00:00')
        self.assertEqual(o['ts'], 1792300000 - 14 * 86400)
        self.assertEqual(o['wolumen'], 1792300000, 'zwykła liczba (nie klucz czasu) nietknięta')
        self.assertIs(o['ok'], True)
        self.assertEqual(o['x'][1], '2026-09-17')
        self.assertEqual(o['x'][2]['t'], 1792300000000 - 14 * 86400 * 1000)

    def test_zmiany_pliku(self):
        kz = self.kz
        body = json.dumps({'at': '2026-10-18T06:00:00+00:00', 'rows': [[1, 2], [3, 4]], 'm': {'a': [1], 'b': 5}}).encode()
        self.assertEqual(kz.zmien_plik('brak', body)[0], 404)
        self.assertEqual(kz.zmien_plik('pusty', body), (200, b'{}'))
        k, b = kz.zmien_plik('ucięty', body)
        self.assertEqual(k, 200); self.assertLess(len(b), len(body))
        with self.assertRaises(ValueError):
            json.loads(b.decode())
        k, b = kz.zmien_plik('puste_listy', body)
        self.assertEqual(json.loads(b), {'at': '2026-10-18T06:00:00+00:00', 'rows': [], 'm': {'a': [], 'b': 5}})
        k, b = kz.zmien_plik('stary', body)
        self.assertEqual(json.loads(b)['at'], '2026-10-04T06:00:00+00:00')
        self.assertEqual(kz.zmien_plik('stary', b'nie json'), (200, b'nie json'), 'nie JSON — bez zmiany')
        self.assertEqual(set(kz.OPIS_ZMIAN), set(kz.ZMIANY), 'każda zmiana ma opis')
        for sc in kz.SCENARIUSZE:
            self.assertIn(sc['zmiana'], kz.ZMIANY)

    def test_wstrzykniecie_skryptu(self):
        kz = self.kz
        h = kz.wstrzyknij('<html><head><title>x</title></head><body></body></html>', {'tryb': 'pelny'}, 'var a=1;')
        self.assertTrue(h.startswith('<html><head><script>window.__KZ_CFG={"tryb": "pelny"};'))
        self.assertEqual(h.count('var a=1;'), 1)
        with self.assertRaises(AssertionError):
            kz.wstrzyknij('<head>', {}, 'x</script>y')
        js = open(os.path.join(self.here, 'narzedzia', 'kontrola_zakladki.js'), encoding='utf-8').read()
        self.assertNotIn('</script', js)

    def test_serwer_lokalny_podmienia_tylko_jeden_plik(self):
        kz = self.kz
        zapytane = []

        def zywa(sciezka):
            zapytane.append(sciezka)
            if sciezka == '/index.html':
                return 200, 'text/html', b'<html><head></head><body>const EXTRA1</body></html>'
            if sciezka == '/data/krypto.json':
                return 200, 'application/json', b'{"at": "2026-10-18T06:00:00+00:00", "a": [1]}'
            if sciezka == '/data/rynki.json':
                return 200, 'application/json', b'{"r": [1]}'
            return 404, 'text/plain', b''
        zr = kz.Zrodlo('https://example.invalid', pobierz=zywa)   # (testy bez sieci: odpowiedzi serwera sprawdzamy funkcją obsluz, bez gniazd)
        stan = kz.nowy_stan()
        sc = {'plik': 'krypto', 'zmiana': 'pusty'}

        def o(adres, metoda='GET', dane=b''):
            return kz.obsluz(zr, sc, {'tryb': 'pelny'}, 'var kz=1;', stan, metoda, adres, dane)
        k, ct, b = o('/?nc=1&sw=off'); self.assertEqual(k, 200); self.assertIn('text/html', ct)
        self.assertIn(b'window.__KZ_CFG', b); self.assertIn(b'const EXTRA1', b); self.assertIn('strona', stan['zdarzenia'])
        self.assertEqual(o('/data/krypto.json?nc=2')[::2], (200, b'{}'), 'plik scenariusza podmieniony')
        self.assertEqual(o('/data/rynki.json')[::2], (200, b'{"r": [1]}'), 'inne pliki bez zmian')
        self.assertEqual(o('/data/nie-ma.json')[0], 404)
        self.assertEqual(o('/data/krypto.json')[2], b'{}')
        self.assertEqual(zapytane.count('/data/krypto.json'), 1, 'jedno pobranie z żywej strony na ścieżkę (pamięć wspólna)')
        self.assertEqual(o('/__kz/widok_global')[0], 204); self.assertIn('widok_global', stan['zdarzenia'])
        self.assertFalse(stan['gotowe'].is_set())
        self.assertEqual(o('/__kz/wynik', 'POST', json.dumps({'koniec': True, 'tab': {}}).encode())[0], 204)
        self.assertTrue(stan['gotowe'].is_set()); self.assertTrue(stan['wynik']['koniec'])
        self.assertEqual(o('/__kz/wynik', 'POST', b'nie json')[0], 204); self.assertEqual(stan['wynik'], {'nieczytelny': True})
        k, ct, b = kz.obsluz(zr, None, {}, 'x', kz.nowy_stan(), 'GET', '/data/krypto.json')
        self.assertIn(b'"a": [1]', b, 'bez scenariusza plik bez zmian')
        k, ct, b = kz.obsluz(kz.Zrodlo('https://example.invalid', pobierz=lambda p: (503, 'text/plain', b'')), None, {}, 'x', kz.nowy_stan(), 'GET', '/')
        self.assertEqual(k, 503, 'żywa strona nie odpowiada — przeglądarka dostaje ten sam błąd')
        z = {'strona': 10.0, 'widok_global': 12.4, 'klik_crypto': 20.0, 'widok_crypto': 21.5, 'klik_trendy': 30.0}
        self.assertEqual(kz.czasy_widoku(z), {'global': 2.4, 'crypto': 1.5, 'trendy': None})

    # --- oceny -----------------------------------------------------------------
    def wynik_ok(self):
        tab = lambda nz, w, wp: {'nazwa': nz, 'przelaczenie': True, 'uwagi': [], 'wykresy': 1, 'wykresy_po': wp, 'panele': 30, 'artefakty': [], 'artefakty_po': []}
        return {'koniec': True, 'err': [], 'kons': [], 'tab': {'global': tab('GLOBAL', 1, 119), 'crypto': tab('CRYPTO', 3, 21), 'trendy': tab('TRENDY', 48, 48)},
                'powrot': {'ok': True, 'u': [], 'wykresy': 1, 'wykresy_wczesniej': 1},
                'ele': [{'z': 'GLOBAL', 't': 'przełącznik', 'n': 'Okres › 1M', 's': 'ok', 'u': []},
                        {'z': 'CRYPTO', 't': 'rozwijanie', 'n': 'DEX (blok)', 's': 'ok', 'u': []}], 'zegar': {'stale': ''}}

    def test_oceny_podstawowe_zielone(self):
        kz = self.kz
        o = kz.oceny_podstawowe(self.wynik_ok(), {'global': 2.0, 'crypto': 1.0, 'trendy': 0.3})
        self.assertEqual([x for x in o if x['p'] in ('⚠️', '❌')], [])
        n = ' | '.join(x['n'] for x in o)
        for s in ('przełączenie zakładki', 'rysowanie wykresów', 'napisy-błędy', 'czas pierwszego widoku', 'powrót do zakładki GLOBAL', 'błędy JavaScriptu', 'Okres › 1M', 'DEX (blok)'):
            self.assertIn(s, n)

    def test_oceny_podstawowe_problemy(self):
        kz = self.kz
        w = self.wynik_ok()
        w['err'] = ['TypeError: x is undefined (index.html:5)']
        w['tab']['crypto']['przelaczenie'] = False; w['tab']['crypto']['uwagi'] = ['sekcja zakładki niewidoczna']
        w['tab']['trendy']['wykresy_po'] = 0
        w['tab']['global']['artefakty_po'] = ['Kafle: „cena NaN USD”']
        w['ele'][0]['s'] = 'ostrz'; w['ele'][0]['u'] = ['przycisk nie został zaznaczony']
        w['powrot'] = {'ok': True, 'u': [], 'wykresy': 2, 'wykresy_wczesniej': 119}
        o = kz.oceny_podstawowe(w, {'global': 99.0, 'crypto': None, 'trendy': 0.1})
        zle = {(x['z'], x['n'].split(' (')[0]): x['p'] for x in o if x['p'] != '✅'}
        self.assertEqual(zle[('wszystkie', 'błędy JavaScriptu na stronie')], '❌')
        self.assertEqual(zle[('CRYPTO', 'przełączenie zakładki')], '❌')
        self.assertEqual(zle[('TRENDY', 'rysowanie wykresów')], '❌')
        self.assertEqual(zle[('GLOBAL', 'napisy-błędy')], '❌')
        self.assertEqual(zle[('GLOBAL', 'Okres › 1M')], '⚠️')
        self.assertEqual(zle[('GLOBAL', 'czas pierwszego widoku')], '⚠️', 'dłużej niż próg')
        self.assertEqual(zle[('CRYPTO', 'czas pierwszego widoku')], '⚠️', 'brak pomiaru = ostrzeżenie, nie zero')
        self.assertTrue(any(x['n'].startswith('powrót do zakładki GLOBAL') and x['p'] == '❌' for x in o))

    def test_potwierdzenie_drugim_przebiegiem(self):
        kz = self.kz
        a = [{'z': 'GLOBAL', 'p': '❌', 'n': 'X', 't': 'js', 'u': 'e'}, {'z': 'GLOBAL', 'p': '⚠️', 'n': 'Y', 't': 'js', 'u': 'f'}, {'z': 'GLOBAL', 'p': '✅', 'n': 'Z', 't': 'js', 'u': ''}]
        b = [{'z': 'GLOBAL', 'p': '❌', 'n': 'X', 't': 'js', 'u': 'e'}, {'z': 'GLOBAL', 'p': '✅', 'n': 'Y', 't': 'js', 'u': ''}, {'z': 'GLOBAL', 'p': '⚠️', 'n': 'Z', 't': 'js', 'u': 'g'}]
