        self.assertIn('✅ przełączenie zakładki', txt); self.assertIn('Okres', txt); self.assertIn('plik „krypto”: plik pusty ({})', txt)
        self.assertNotIn('⚠️', txt); self.assertNotIn('❌', txt)

