        R['depin'][60] = deep
        dup = self._x('dup-y', 3, mc=77777777.0)
        R['decentralized-finance-defi'][70] = _c439.deepcopy(dup)
        R['layer-2'][80] = _c439.deepcopy(dup)
        out = self._build(rows=R)
        tm = round(top['market_cap'])
