_V452_NOW = datetime.datetime(2026, 10, 19, 5, 0, 0, tzinfo=datetime.timezone.utc)


def _v452_ots(rows=None, extra=()):
    L = [{'MonthId': m, 'FlowTypeId': f, 'SuppressionIndex': 0, 'CommodityId': 71081200, 'CommoditySitcId': 97101, 'CountryId': c, 'PortId': 428, 'Value': float(v), 'NetMass': float(kg), 'SuppUnit': float(kg) * 1000}
         for m, f, c, v, kg in (_V452_ROWS if rows is None else rows)]
    return {'@odata.context': 'https://example.invalid/$metadata#OTS', 'value': L + list(extra)}


def _v452_kr(skip=()):
    return {'@odata.context': 'x', 'value': [{'CountryId': i, 'CountryCodeAlpha': a, 'CountryName': 'k%d' % i} for i, a in _V452_KRAJE if i not in skip]}


class ZlotoUkV452(unittest.TestCase):
    """v452: zbieracz — data/zloto-uk.json: scalanie czterech strumieni w import i eksport, miesiące pełne i luki, ranking krajów, rytm ~dobowy, błąd zostawia poprzedni plik."""

    def setUp(self):
        zd.META['errors'].clear()
        self.p = [mock.patch.object(zd, 'NOW', _V452_NOW.isoformat()), mock.patch.object(zd, 'HMRC_SLEEP', 0)]
        for p in self.p:
            p.start()
        self.kr = zd.hmrc_kraje(_v452_kr())

    def tearDown(self):
        for p in self.p:
            p.stop()
        zd.META['errors'].clear()

    def _zloz(self, j=None):
        return zd.hmrc_zloz(_v452_ots() if j is None else j, self.kr, _V452_NOW.isoformat())

    # ---------------------------------------------------------------- odczyt i scalanie
    def test_nagranie_24_miesiace_import_eksport_i_okres(self):
        o = self._zloz()
        self.assertEqual((o['v'], o['okres'], len(o['mies']), o['mies'][0], o['mies'][-1], o['pomin']), (1, '2026-08', 24, '2024-09', '2026-08', 0))
        for s in ('imp', 'exp'):
            self.assertEqual((len(o[s]['w']), len(o[s]['m'])), (24, 24))
        # sierpień 2026: import z krajów Unii (strumień 1) i spoza Unii (strumień 3) razem; masa w tonach (urząd podaje kilogramy)
        sier = [r for r in _V452_ROWS if r[0] == 202608]
        self.assertAlmostEqual(o['imp']['w'][-1], sum(r[3] for r in sier if r[1] in (1, 3)) / 1e6, places=3); self.assertEqual(o['imp']['w'][-1], 75.424)
        self.assertAlmostEqual(o['imp']['m'][-1], sum(r[4] for r in sier if r[1] in (1, 3)) / 1e3, places=3); self.assertEqual(o['imp']['m'][-1], 0.755)
        self.assertAlmostEqual(o['exp']['w'][-1], sum(r[3] for r in sier if r[1] in (2, 4)) / 1e6, places=3)
        self.assertEqual(o['exp']['w'][17], 182.293, 'luty 2026: jednorazowy duży eksport zostaje w serii (dane urzędu, nie błąd)')
        self.assertEqual(o['imp']['w'][15], 120.51); self.assertEqual(o['mies'][15], '2025-12')

    def test_ranking_krajow_posortowany_bez_kodow_zbiorczych_i_nie_wiekszy_niz_suma(self):
        o = self._zloz()
        for s, top in (('imp', 8), ('exp', 6)):
            L = o['kraje'][s]
            self.assertLessEqual(len(L), top); self.assertTrue(L)
            self.assertEqual([x['w12'] for x in L], sorted((x['w12'] for x in L), reverse=True))
            self.assertTrue(all(len(x['k']) == 2 and x['k'].isupper() and x['k'] not in zd.HMRC_ZBIORCZE for x in L))
            self.assertLessEqual(sum(x['w12'] for x in L), sum(v for v in o[s]['w'][-12:] if v is not None) + 0.01)
            self.assertTrue(all(x['wl'] <= x['w12'] + 0.01 for x in L))
        im = o['kraje']['imp']
        self.assertEqual([x['k'] for x in im[:4]], ['CH', 'ES', 'DE', 'FR'])
        self.assertEqual(im[0], {'k': 'CH', 'w12': 433.847, 'm12': 4.218, 'wp': 215.205, 'wl': 40.407, 'ml': 0.4})
        # wartość kraju z 12 miesięcy = suma wierszy tego kraju (obu strumieni) z ostatnich 12 miesięcy pliku
        ch = sum(r[3] for r in _V452_ROWS if r[2] == 39 and r[1] in (1, 3) and r[0] >= 202509) / 1e6
        self.assertAlmostEqual(im[0]['w12'], ch, places=3)

    def test_miesiac_bez_wierszy_to_brak_a_kierunek_bez_wierszy_w_pelnym_miesiacu_to_zero(self):
        bez_marca = [r for r in _V452_ROWS if r[0] != 202603]
        o = self._zloz(_v452_ots(bez_marca))
        i = o['mies'].index('2026-03')
        self.assertIsNone(o['imp']['w'][i]); self.assertIsNone(o['exp']['w'][i]); self.assertIsNone(o['imp']['m'][i]); self.assertIsNone(o['exp']['m'][i])
        self.assertEqual(sum(1 for v in o['imp']['w'] if v is None), 1)
        bez_eksp = [r for r in _V452_ROWS if not (r[0] == 202607 and r[1] in (2, 4))]
        o2 = self._zloz(_v452_ots(bez_eksp))
        self.assertEqual(o2['exp']['w'][22], 0.0); self.assertEqual(o2['exp']['m'][22], 0.0); self.assertGreater(o2['imp']['w'][22], 0)

    def test_ostatni_miesiac_niepelny_nie_jest_okresem_i_miesiac_z_przyszlosci_to_blad(self):
        czesc = [(202609, 1, 4, 1000000, 10)] * (zd.HMRC_MIN_MIES - 1)
        o = self._zloz(_v452_ots(_V452_ROWS + czesc))
        self.assertEqual(o['okres'], '2026-08', 'wrzesień z 4 wierszami to jeszcze niepełny miesiąc')
        pelny = [(202609, 1, 4, 1000000, 10)] * zd.HMRC_MIN_MIES
        self.assertEqual(self._zloz(_v452_ots(_V452_ROWS + pelny))['okres'], '2026-09')
        with self.assertRaisesRegex(RuntimeError, 'z przyszłości'):
            self._zloz(_v452_ots(_V452_ROWS + [(202611, 1, 4, 1000000, 10)] * 6))

    def test_zle_odpowiedzi_to_wyjatek_a_nie_cichy_plik(self):
        j = _v452_ots(); j['@odata.nextLink'] = 'https://example.invalid/next'
        with self.assertRaisesRegex(RuntimeError, 'podzielona na strony'):
            self._zloz(j)
        with self.assertRaisesRegex(RuntimeError, 'za mało wierszy'):
            self._zloz(_v452_ots(_V452_ROWS[:50]))
        with self.assertRaisesRegex(RuntimeError, 'brak listy'):
            self._zloz({'value': 'x'})
        zle = [{'MonthId': 'x', 'FlowTypeId': 1, 'CommodityId': 71081200, 'Value': 1.0, 'NetMass': 1.0, 'CountryId': 4}] * 30
        with self.assertRaisesRegex(RuntimeError, 'zły format'):
            self._zloz(_v452_ots(extra=zle))
        mało = [r for r in _V452_ROWS if r[0] >= 202603]   # 6 miesięcy zamiast 24
        with self.assertRaisesRegex(RuntimeError, 'za mało miesięcy'):
            self._zloz(_v452_ots(mało * 3))
        with self.assertRaisesRegex(RuntimeError, 'za mało miesięcy'):
            self._zloz(_v452_ots(_V452_ROWS[:3] * 40))
        rozrzut = [(y * 100 + m, 1, 4, 1000, 1) for y in range(2012, 2022) for m in range(1, 13)]   # 120 wierszy, w żadnym miesiącu nie ma ich dość
        with self.assertRaisesRegex(RuntimeError, 'brak pełnego miesiąca'):
            self._zloz(_v452_ots(rozrzut))

    def test_wiersze_z_liczba_tekstem_nan_ujemna_albo_znacznikiem_tajemnicy_sa_pomijane_i_liczone(self):
        extra = [{'MonthId': 202608, 'FlowTypeId': 1, 'SuppressionIndex': 0, 'CommodityId': 71081200, 'CountryId': 4, 'Value': v, 'NetMass': 10.0}
                 for v in ('123', float('nan'), -5.0, True, None)]
        extra.append({'MonthId': 202608, 'FlowTypeId': 1, 'SuppressionIndex': 1, 'CommodityId': 71081200, 'CountryId': 4, 'Value': 99999999.0, 'NetMass': 99.0})
        extra.append({'MonthId': 202608, 'FlowTypeId': 9, 'SuppressionIndex': 0, 'CommodityId': 71081200, 'CountryId': 4, 'Value': 5.0, 'NetMass': 1.0})
        extra.append({'MonthId': 202608, 'FlowTypeId': 1, 'SuppressionIndex': 0, 'CommodityId': 71082000, 'CountryId': 4, 'Value': 5.0, 'NetMass': 1.0})   # złoto monetarne: poza przedziałem
        o = self._zloz(_v452_ots(extra=extra))
        self.assertEqual(o['pomin'], len(extra)); self.assertEqual(o['imp']['w'][-1], 75.424, 'pominięte wiersze nie wchodzą do sum')

    def test_wszystkie_kody_zlota_niemonetarnego_sa_w_sumie_a_poza_przedzialem_pominiete(self):
        baza = self._zloz()
        pelny = lambda cn, f, c, v, kg: {'MonthId': 202608, 'FlowTypeId': f, 'SuppressionIndex': 0, 'CommodityId': cn, 'CountryId': c, 'Value': v, 'NetMass': kg}
        extra = [pelny(71081310, 3, 39, 9.8e9, 100000.0),   # sztabki londyńskie spoza Unii (Szwajcaria): wiersz większy niż dawny limit 5 mld £
                 pelny(71081380, 4, 4, 3e6, 50.0), pelny(71081100, 1, 4, 1e6, 1.0)]
        o = self._zloz(_v452_ots(extra=extra))
        self.assertEqual(o['pomin'], 0)
        self.assertAlmostEqual(o['imp']['w'][-1], baza['imp']['w'][-1] + 9800.0 + 1.0, places=3)
        self.assertAlmostEqual(o['imp']['m'][-1], baza['imp']['m'][-1] + 100.0 + 0.001, places=3)
        self.assertAlmostEqual(o['exp']['w'][-1], baza['exp']['w'][-1] + 3.0, places=3)
        ch0 = next(x['w12'] for x in baza['kraje']['imp'] if x['k'] == 'CH'); ch1 = next(x['w12'] for x in o['kraje']['imp'] if x['k'] == 'CH')
        self.assertAlmostEqual(ch1, ch0 + 9800.0, places=3); self.assertEqual(o['kraje']['imp'][0]['k'], 'CH', 'Szwajcaria na czele dostawców')
        poza = [pelny(cn, 1, 4, 7e6, 5.0) for cn in (71082000, 71081400, 71080000)] + [dict(pelny(71081310, 1, 4, 7e6, 5.0), CommodityId='71081310')]
        o2 = self._zloz(_v452_ots(extra=poza))
        self.assertEqual(o2['pomin'], 4); self.assertEqual(o2['imp']['w'], baza['imp']['w'], 'złoto monetarne i kody poza przedziałem nie wchodzą do sum')

    def test_przedzial_kodow_w_zapytaniu_zgodny_ze_stala_i_sztabki_to_nie_wycinek(self):
        od, do = zd.HMRC_CN
        self.assertEqual((od, do), (71081100, 71081399)); self.assertIn('CommodityId%20ge%20' + str(od) + '%20and%20CommodityId%20le%20' + str(do), zd.HMRC_URL)
        self.assertNotIn('%20eq%20', zd.HMRC_URL, 'zapytanie nie może wrócić do jednego kodu (kod 71081200 to ułamek procenta obrotu)')

    def test_slownik_krajow_tylko_kody_dwuliterowe_bez_zbiorczych_i_poufnych(self):
        self.assertEqual((self.kr[4], self.kr[39], self.kr[400]), ('DE', 'CH', 'US'))
        self.assertNotIn(977, self.kr, 'kraj poufny bez kodu nie trafia do słownika'); self.assertNotIn(951, self.kr); self.assertNotIn(1001, self.kr)
        self.assertTrue(all(len(a) == 2 and a.isupper() and a not in zd.HMRC_ZBIORCZE for a in self.kr.values()))
        self.assertEqual(self.kr[644], 'QA', 'Katar ma kod QA — to nie kod zbiorczy')
        with self.assertRaisesRegex(RuntimeError, 'za krótki'):
            zd.hmrc_kraje({'value': [{'CountryId': 4, 'CountryCodeAlpha': 'DE'}]})
        with self.assertRaisesRegex(RuntimeError, 'bez Niemiec'):
            zd.hmrc_kraje(_v452_kr(skip=(4,)))
        with self.assertRaisesRegex(RuntimeError, 'za krótki'):
            zd.hmrc_kraje(None)

    # ---------------------------------------------------------------- część przebiegu: zapytania, rytm, błąd
    def _siec(self, kolejka=None):
        wywolania = []

        def hg(url):
            wywolania.append(url)
            if kolejka:
                x = kolejka.pop(0)
                if isinstance(x, BaseException):
                    raise x
                return x
            return _v452_ots() if 'OTS' in url else _v452_kr()
        return hg, wywolania

    def test_zapytania_tylko_filtr_bez_sortowania_okno_27_miesiecy_i_dwa_zapytania(self):
        hg, got = self._siec()
        with mock.patch.object(zd, 'hmrc_get', hg):
            o = zd.build_zloto_uk(None)
        self.assertEqual(len(got), 2); self.assertEqual(got[1], 'https://api.uktradeinfo.com/Country')
        self.assertEqual(got[0], 'https://api.uktradeinfo.com/OTS?$filter=CommodityId%20ge%2071081100%20and%20CommodityId%20le%2071081399%20and%20MonthId%20ge%20202407')
        self.assertNotIn('$orderby', got[0]); self.assertNotIn('$top', got[0]); self.assertNotIn('$select', got[0])
        self.assertEqual((o['ok'], o['t'], o['try'], o['at']), (True, _V452_NOW.isoformat(), _V452_NOW.isoformat(), _V452_NOW.isoformat()))

    def test_rytm_22_godziny_po_bledzie_3_godziny_i_zapis_pliku(self):
        saved, prev = {}, {}
        hg, got = self._siec()
        with mock.patch.object(zd, 'previous', lambda n: prev.get(n)), mock.patch.object(zd, 'save', lambda n, o: saved.__setitem__(n, o)), mock.patch.object(zd, 'hmrc_get', hg):
            self.assertIs(zd.hmrc_czesc(), True); obj = saved['zloto-uk']; self.assertEqual(len(got), 2)
            prev['zloto-uk'] = obj; saved.clear()
            with mock.patch.object(zd, 'NOW', (_V452_NOW + datetime.timedelta(hours=21, minutes=59)).isoformat()):
                self.assertEqual(zd.hmrc_czesc(), 'cached'); self.assertIs(saved['zloto-uk'], obj); self.assertEqual(len(got), 2, 'rytm: bez zapytań')
            saved.clear()
            with mock.patch.object(zd, 'NOW', (_V452_NOW + datetime.timedelta(hours=22)).isoformat()):
                self.assertIs(zd.hmrc_czesc(), True); self.assertEqual(len(got), 4)
        self.assertTrue(zd.hmrc_trzeba(None, _V452_NOW.isoformat())); self.assertTrue(zd.hmrc_trzeba({'v': 1}, 'zepsute'))
        p = dict(obj); p['ok'] = False
        self.assertFalse(zd.hmrc_trzeba(p, (_V452_NOW + datetime.timedelta(hours=2, minutes=59)).isoformat()))
        self.assertTrue(zd.hmrc_trzeba(p, (_V452_NOW + datetime.timedelta(hours=3)).isoformat()))

    def test_blad_zostawia_poprzedni_plik_z_ok_false_a_403_nie_jest_obchodzone(self):
        import io, urllib.error
        saved, prev = {}, {}
        hg0, _ = self._siec()
        with mock.patch.object(zd, 'hmrc_get', hg0):
            obj = zd.build_zloto_uk(None)
        prev['zloto-uk'] = obj
        t1 = (_V452_NOW + datetime.timedelta(days=1)).isoformat()
        hg, got = self._siec([urllib.error.HTTPError('https://x/OTS', 403, 'Forbidden', {}, io.BytesIO(b'Your request has been rejected'))])
        with mock.patch.object(zd, 'NOW', t1), mock.patch.object(zd, 'previous', lambda n: prev.get(n)), mock.patch.object(zd, 'save', lambda n, o: saved.__setitem__(n, o)), mock.patch.object(zd, 'hmrc_get', hg):
            self.assertIs(zd.hmrc_czesc(), False)
        self.assertEqual(len(got), 1, 'po 403 jedna próba — bez ponawiania w tym przebiegu i bez zmiany zapytania')
        s = saved['zloto-uk']
        self.assertEqual((s['ok'], s['try'], s['t'], s['imp'], s['okres']), (False, t1, _V452_NOW.isoformat(), obj['imp'], obj['okres']), 'dane i czas ostatniego udanego sprawdzenia zostają')
        self.assertTrue(any(e.startswith('Złoto Wielkiej Brytanii: ') and '403' in e for e in zd.META['errors']))
        # bez poprzedniego pliku błąd niczego nie zapisuje
        saved.clear(); prev.clear(); zd.META['errors'].clear()
        hg2, _g2 = self._siec([OSError('brak sieci')])
        with mock.patch.object(zd, 'previous', lambda n: None), mock.patch.object(zd, 'save', lambda n, o: saved.__setitem__(n, o)), mock.patch.object(zd, 'hmrc_get', hg2):
            self.assertIs(zd.hmrc_czesc(), False)
        self.assertEqual(saved, {}); self.assertEqual(len(zd.META['errors']), 1)
        # druga odpowiedź (słownik krajów) zepsuta = błąd, plik poprzedni
        hg3, _g3 = self._siec([_v452_ots(), {'value': []}])
        with mock.patch.object(zd, 'hmrc_get', hg3):
            with self.assertRaisesRegex(RuntimeError, 'za krótki'):
                zd.build_zloto_uk(None)

    def test_hmrc_get_limit_rozmiaru_i_odstep(self):
        class R:
            def __init__(s, b): s.b = b
            def __enter__(s): return s
            def __exit__(s, *a): return False
            def read(s, n=-1): return s.b[:n]
        slept = []
        with mock.patch.object(zd, 'time', mock.Mock(sleep=lambda x: slept.append(x))), mock.patch.object(zd, 'HMRC_SLEEP', 2.0):
            with mock.patch.object(zd, '_otworz', lambda u, h=None, t=30: R(b'{"a": 1}')):
                self.assertEqual(zd.hmrc_get('https://x'), {'a': 1})
            with mock.patch.object(zd, '_otworz', lambda u, h=None, t=30: R(b'a' * 20)), mock.patch.object(zd, 'HMRC_MAX_B', 10):
                with self.assertRaisesRegex(RuntimeError, 'większa niż limit'):
                    zd.hmrc_get('https://x')
        self.assertEqual(slept, [2.0, 2.0])

    def test_przebieg_glowny_wola_czesc_zrodla_meta_i_nowe_zrodlo(self):
        import pathlib
        src = pathlib.Path(zd.__file__).read_text(encoding='utf-8')
        self.assertEqual(src.count("META['ok']['zloto_uk'] = hmrc_czesc()"), 1)
        self.assertEqual(zd.ZRODLA_META['zloto_uk'], 'hmrc')
        n0 = zd.zrodla_meta({'kalendarz_stat_eu': True})['n']
        self.assertEqual(zd.zrodla_meta({'kalendarz_stat_eu': True, 'zloto_uk': True}), {'n': n0 + 1, 'ok': n0 + 1}, 'brytyjski urząd celny to jedno nowe źródło')
        self.assertEqual(zd.zrodla_meta({'zloto_uk': 'cached'}), {'n': 1, 'ok': 1}); self.assertEqual(zd.zrodla_meta({'zloto_uk': False}), {'n': 1, 'ok': 0})
        s = pathlib.Path(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'index.html')).read_text(encoding='utf-8')
        for nazwa in ('uktradeinfo', 'HMRC', 'hmrc', 'HM Revenue'):
            self.assertNotIn(nazwa, s, 'zero nazw dostawców na stronie: ' + nazwa)


class KontrolaZlotoUkV452(unittest.TestCase):
    """v452: kontrola dzienna pliku zloto-uk.json — wiek sprawdzenia (48 h) i miesiąca danych (110 dób), spójność w pliku, cena jednostkowa tylko informacyjnie, wpięcie w raport."""

    @classmethod
    def setUpClass(cls):
        import importlib.util, tempfile
        tmp = tempfile.mkdtemp(prefix='kontrola452-')
        with mock.patch.dict(os.environ, {'KONTROLA_DIR': os.path.join(tmp, 'k'), 'KONTROLA_ARCH': os.path.join(tmp, 'a')}):
            spec = importlib.util.spec_from_file_location('v452_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
            cls.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(cls.k)
        cls.NOW = datetime.datetime(2026, 10, 19, 13, 0, tzinfo=datetime.timezone.utc)
        with mock.patch.object(zd, 'NOW', _V452_NOW.isoformat()):
            o = zd.hmrc_zloz(_v452_ots(), zd.hmrc_kraje(_v452_kr()), _V452_NOW.isoformat())
        o.update({'at': '2026-10-19T05:00:00+00:00', 't': '2026-10-19T05:00:00+00:00', 'try': '2026-10-19T05:00:00+00:00', 'ok': True})
        cls.P0 = o

    def _plik(self):
        return json.loads(json.dumps(self.P0))

    def _st(self, o, now=None):
        return {r[0]: r[1] for r in self.k.zuk_k_kontrola(o, now or self.NOW)['rows']}

    def test_plik_wpiety_w_kontroli_i_stale_zgodne_ze_zbieraczem(self):
        k = self.k
        self.assertEqual(k.PLIKI[-2:], ['krypto-dzien', 'krypto-dziennik']); self.assertEqual(k.PLIKI.count('zloto-uk'), 1); self.assertLess(k.PLIKI.index('zloto-uk'), k.PLIKI.index('krypto-dzien'))
        self.assertEqual(k.LIMIT_MIN['zloto-uk'], 36 * 60); self.assertIn('zloto_uk', k.AW_BEZ_BLEDU)
        self.assertEqual(k.ZUK_K_OKNO, zd.HMRC_OKNO)
        self.assertEqual(k.ZUK_K_PROG_MIN, 2 * zd.HMRC_CO_H * 60 + 4 * 60, 'ponad dwa pełne rytmy (22 h) — 48 h')
        import pathlib
        src = pathlib.Path(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py')).read_text(encoding='utf-8')
        for a in ("R['zgodnosc']['zloto-uk']", "Z.get('zloto-uk')", 'zuk_k_kontrola(files.get'):
            self.assertEqual(src.count(a) >= 1, True, a)
        # próg miesiąca danych: największy normalny wiek (ok. 78 dób) i po jednej opuszczonej publikacji (ok. 109) nie dają ⚠️
        self.assertGreater(k.ZUK_K_MIES_DNI, 109)

    def test_swiezy_plik_bez_uwag(self):
        o = self.k.zuk_k_kontrola(self._plik(), self.NOW)
        self.assertEqual([r[1] for r in o['rows']], ['✅', '✅']); self.assertEqual(o['uwagi'], []); self.assertEqual(o['spojnosc'], [])
        self.assertEqual(o['wiersze'], [('spójność pliku (miesiące, długości serii, zakresy, kraje wobec sumy)', '✅')], 'cena jednostkowa w przedziale — bez wiersza ℹ️ (z danych: ok. 100 tys. £ za kg)')
        self.assertEqual(self.k.zuk_k_kontrola(None, self.NOW), {'rows': [], 'uwagi': [], 'wiersze': [], 'spojnosc': []})
        self.assertEqual(self.k.zuk_k_kontrola({'v': 2}, self.NOW)['rows'], [])

    def test_skala_sztabek_londynskich_tysiace_mln_funtow_to_nie_usterka(self):
        o = self._plik()   # miesiące po kilkanaście tysięcy mln £ (19.10.2026: import do 21 tys.), 12 miesięcy z kraju ponad 50 tys. — dawne granice 5000 i 500 oznaczałyby to jako błąd
        X = 200
        for kier in ('imp', 'exp'):
            for p in ('w', 'm'):
                o[kier][p] = [None if v is None else v * X for v in o[kier][p]]
            for x in o['kraje'][kier]:
                for f in ('w12', 'm12', 'wp', 'wl', 'ml'):
                    x[f] = x[f] * X
        r = self.k.zuk_k_kontrola(o, self.NOW)
        self.assertEqual(r['spojnosc'], []); self.assertEqual(r['uwagi'], []); self.assertGreater(max(v for v in o['imp']['w'] if v is not None), 5000)
        o['imp']['w'][3] = 1e6 + 1
        self.assertTrue(any('poza zakresem' in z for z in self.k.zuk_k_kontrola(o, self.NOW)['spojnosc']), 'wartość ponad granicę 1e6 mln £ jest usterką')

    def test_wiek_sprawdzenia_48_godzin_i_miesiaca_110_dob(self):
        k = self.k
        for h, ocz in ((47, '✅'), (49, '⚠️')):
            self.assertEqual(self._st(self._plik(), self.NOW.replace(hour=5) + datetime.timedelta(hours=h))['Złoto Wielkiej Brytanii (sprawdzenie źródła)'], ocz, f'{h} h')
        # sierpień 2026 kończy się 31.08; 110 dób po jego końcu to 19.12.2026
        koniec = datetime.datetime(2026, 9, 1, tzinfo=datetime.timezone.utc)
        for d, ocz in ((109, '✅'), (111, '⚠️')):
            o = self._plik(); o['t'] = (koniec + datetime.timedelta(days=d)).isoformat()
            self.assertEqual(self._st(o, koniec + datetime.timedelta(days=d, hours=1))['Złoto Wielkiej Brytanii (ostatni miesiąc danych)'], ocz, f'{d} dób')
        o = self._plik(); o['t'] = 'zepsute'
        self.assertEqual(self._st(o)['Złoto Wielkiej Brytanii (sprawdzenie źródła)'], '?')
        o = self._plik(); o['ok'] = False
        self.assertTrue(any('nie powiodła się' in u for u in k.zuk_k_kontrola(o, self.NOW)['uwagi']))

    def test_spojnosc_wykrywa_sprzecznosci_ale_nic_nie_jest_czerwone(self):
        k = self.k
        przyp = []
        o = self._plik(); o['okres'] = '2026-07'; przyp.append((o, 'okres'))
        o = self._plik(); o['imp']['w'].pop(); przyp.append((o, 'zła długość'))
        o = self._plik(); o['exp']['m'][3] = -1.0; przyp.append((o, 'poza zakresem'))
        o = self._plik(); o['kraje']['imp'][0]['w12'] = 99999.0; przyp.append((o, 'suma krajów'))
        o = self._plik(); o['kraje']['imp'][1]['k'] = o['kraje']['imp'][0]['k']; przyp.append((o, 'powtórzony'))
        o = self._plik(); o['kraje']['exp'][0]['wl'] = o['kraje']['exp'][0]['w12'] + 5; przyp.append((o, 'ostatni miesiąc większy'))
        o = self._plik(); o['mies'] = o['mies'][::-1]; przyp.append((o, 'miesiące'))
        o = self._plik(); o['kraje']['imp'][0]['m12'] = None; przyp.append((o, 'zła liczba'))
        for o, slowo in przyp:
            r = k.zuk_k_kontrola(o, self.NOW)
            self.assertTrue(r['spojnosc'] and any(slowo in z for z in r['spojnosc']), (slowo, r['spojnosc']))
            self.assertEqual(r['wiersze'][0][1], '⚠️'); self.assertTrue(all(w[1] in ('✅', '⚠️', 'ℹ️') for w in r['wiersze']))

    def test_cena_jednostkowa_poza_przedzialem_tylko_informacja(self):
        o = self._plik(); o['imp']['m'] = [v * 1000 if v is not None else None for v in o['imp']['m']]   # masa w kg zamiast t = cena 1000 razy za niska
        o['imp']['m'] = [min(v, 500.0) if v is not None else None for v in o['imp']['m']]
        r = self.k.zuk_k_kontrola(o, self.NOW)
        self.assertTrue(any(z == 'ℹ️' and 'cena jednostkowa' in w for w, z in r['wiersze']), r['wiersze']); self.assertEqual(r['uwagi'], [])
        self.assertEqual(r['spojnosc'], [])


