        p2 = self._plik(); del p2['il']; del p2['ok']['il']; self.assertEqual([r for r in k.emk_kontrola(p2, self.NOW)['rows'] if 'Izrael' in r[0]], [], 'część, której nigdy nie było — bez wiersza')

