        st4 = _v458_kaub()[1]; st4['characteristicValues'] = []; o4 = zd.kl_re_czesc(h, st4, self.T); self.assertEqual((o4['mw'], o4['mnw'], o4['nw']), (None, None, None), 'brak wartości charakterystycznych = brak, nie zero')

